def _apply_v1_legacy_columns(conn: sqlite3.Connection) -> None:
    for table, columns in LEGACY_COLUMN_ADDITIONS.items():
        existing = {row[1] for row in conn.execute(f'PRAGMA table_info("{table}")').fetchall()}
        if not existing:
            continue
        for name, definition in columns.items():
            if name not in existing:
                conn.execute(f'ALTER TABLE "{table}" ADD COLUMN "{name}" {definition}')


def _apply_v2_tool_audit_events(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS tool_audit_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at REAL NOT NULL,
            session_id TEXT NOT NULL,
            tool_name TEXT NOT NULL,
            policy TEXT NOT NULL,
            explicit_approval INTEGER NOT NULL,
            args_sha256 TEXT NOT NULL,
            status TEXT NOT NULL,
            ok INTEGER,
            elapsed_ms INTEGER,
            output_sha256 TEXT NOT NULL DEFAULT ''
        )
        """
    )


def _apply_v3_execution_spine_tables(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS runtime_tasks (
            task_id TEXT PRIMARY KEY CHECK (length(trim(task_id)) > 0),
            parent_task_id TEXT REFERENCES runtime_tasks(task_id) ON DELETE RESTRICT,
            session_id TEXT NOT NULL DEFAULT '',
            title TEXT NOT NULL DEFAULT '',
            state TEXT NOT NULL DEFAULT 'pending'
                CHECK (state IN ('pending', 'running', 'paused', 'waiting_approval', 'blocked', 'completed', 'failed', 'cancelled')),
            current_epoch INTEGER NOT NULL DEFAULT 0 CHECK (current_epoch >= 0),
            state_version INTEGER NOT NULL DEFAULT 0 CHECK (state_version >= 0),
            workspace_dir TEXT NOT NULL DEFAULT '',
            policy TEXT NOT NULL DEFAULT 'standard',
            budget_json TEXT NOT NULL DEFAULT '{}',
            checkpoint_ref TEXT NOT NULL DEFAULT '',
            created_at REAL NOT NULL,
            updated_at REAL NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS runtime_task_epochs (
            task_id TEXT NOT NULL REFERENCES runtime_tasks(task_id) ON DELETE RESTRICT,
            epoch INTEGER NOT NULL CHECK (epoch >= 1),
            worker_id TEXT NOT NULL CHECK (length(trim(worker_id)) > 0),
            status TEXT NOT NULL DEFAULT 'active'
                CHECK (status IN ('active', 'released', 'expired', 'fenced')),
            claimed_at REAL NOT NULL,
            heartbeat_at REAL NOT NULL,
            lease_expires_at REAL NOT NULL,
            fenced_at REAL,
            fence_reason TEXT NOT NULL DEFAULT '',
            PRIMARY KEY (task_id, epoch)
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS runtime_task_transitions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            task_id TEXT NOT NULL REFERENCES runtime_tasks(task_id) ON DELETE RESTRICT,
            seq INTEGER NOT NULL CHECK (seq >= 1),
            from_state TEXT NOT NULL,
            to_state TEXT NOT NULL
                CHECK (to_state IN ('pending', 'running', 'paused', 'waiting_approval', 'blocked', 'completed', 'failed', 'cancelled')),
            epoch INTEGER NOT NULL DEFAULT 0 CHECK (epoch >= 0),
            reason TEXT NOT NULL DEFAULT '',
            evidence_json TEXT NOT NULL DEFAULT '{}',
            created_at REAL NOT NULL,
            UNIQUE (task_id, seq)
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS runtime_actions (
            action_id TEXT PRIMARY KEY CHECK (length(trim(action_id)) > 0),
            task_id TEXT REFERENCES runtime_tasks(task_id) ON DELETE RESTRICT,
            session_id TEXT NOT NULL DEFAULT '',
            epoch INTEGER NOT NULL DEFAULT 0 CHECK (epoch >= 0),
            attempt INTEGER NOT NULL DEFAULT 1 CHECK (attempt >= 1),
            action_class TEXT NOT NULL DEFAULT 'consequential'
                CHECK (action_class IN ('read_only', 'managed_edit', 'consequential', 'external')),
            replay_policy TEXT NOT NULL DEFAULT 'non_idempotent'
                CHECK (replay_policy IN ('idempotent', 'reconcilable', 'non_idempotent')),
            tool_name TEXT NOT NULL CHECK (length(trim(tool_name)) > 0),
            policy TEXT NOT NULL,
            explicit_approval INTEGER NOT NULL DEFAULT 0 CHECK (explicit_approval IN (0, 1)),
            args_sha256 TEXT NOT NULL,
            status TEXT NOT NULL
                CHECK (status IN ('never_started', 'in_flight', 'committed', 'failed', 'denied', 'uncertain')),
            ok INTEGER CHECK (ok IS NULL OR ok IN (0, 1)),
            elapsed_ms INTEGER CHECK (elapsed_ms IS NULL OR elapsed_ms >= 0),
            output_sha256 TEXT NOT NULL DEFAULT '',
            error_code TEXT NOT NULL DEFAULT '',
            created_at REAL NOT NULL,
            updated_at REAL NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS runtime_task_checkpoints (
            checkpoint_id TEXT PRIMARY KEY CHECK (length(trim(checkpoint_id)) > 0),
            task_id TEXT NOT NULL REFERENCES runtime_tasks(task_id) ON DELETE RESTRICT,
            seq INTEGER NOT NULL CHECK (seq >= 1),
            step INTEGER NOT NULL CHECK (step >= 0),
            epoch INTEGER NOT NULL DEFAULT 0 CHECK (epoch >= 0),
            milestone_id TEXT NOT NULL DEFAULT '',
            status TEXT NOT NULL DEFAULT 'committed'
                CHECK (status IN ('pending_commit', 'committed', 'interrupted', 'resumed', 'superseded')),
            payload_json TEXT NOT NULL DEFAULT '{}',
            payload_hash TEXT NOT NULL,
            evidence_refs_json TEXT NOT NULL DEFAULT '[]',
            created_at REAL NOT NULL,
            updated_at REAL NOT NULL,
            UNIQUE (task_id, seq)
        )
        """
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_runtime_tasks_session_state ON runtime_tasks(session_id, state)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_runtime_tasks_parent ON runtime_tasks(parent_task_id)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_runtime_task_epochs_active ON runtime_task_epochs(task_id, status)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_runtime_task_transitions_task ON runtime_task_transitions(task_id, seq)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_runtime_actions_task_status ON runtime_actions(task_id, status)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_runtime_actions_session ON runtime_actions(session_id, created_at)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_runtime_task_checkpoints_task ON runtime_task_checkpoints(task_id, seq)"
    )


@dataclass(frozen=True, slots=True)
class MigrationStep:
    """One additive, idempotent SQLite schema upgrade step."""

    version: int
    name: str
    apply: Callable[[sqlite3.Connection], None]


MIGRATION_STEPS: tuple[MigrationStep, ...] = (
    MigrationStep(1, "v1_legacy_additive_columns", _apply_v1_legacy_columns),
    MigrationStep(2, "v2_tool_audit_events", _apply_v2_tool_audit_events),
    MigrationStep(3, "v3_runtime_execution_spine", _apply_v3_execution_spine_tables),
)


def _ensure_migrations_table(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS schema_migrations (
            version INTEGER PRIMARY KEY,
            applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )
        """
    )


def _apply_migrations_locked(
    conn: sqlite3.Connection,
    *,
    current_version: int,
    target_version: int = RUNTIME_SCHEMA_VERSION,
    fault_hook: Callable[[int, sqlite3.Connection], None] | None = None,
) -> int:
    """Run all additive migration steps up to ``target_version`` inside an active transaction."""
    if current_version > target_version:
        raise SchemaMigrationError(
            f"Database schema version {current_version} is newer than supported version {target_version}."
        )
    # Always reconcile additive legacy columns first so partial pre-v1 tables upgrade cleanly.
    _apply_v1_legacy_columns(conn)
    _ensure_migrations_table(conn)
    for step in MIGRATION_STEPS:
        if step.version > target_version:
            continue
        step.apply(conn)
        if fault_hook is not None:
            fault_hook(step.version, conn)
        conn.execute("INSERT OR IGNORE INTO schema_migrations(version) VALUES (?)", (step.version,))
    if current_version < target_version:
        conn.execute(f"PRAGMA user_version = {int(target_version)}")
    return target_version


def apply_schema_migrations(
    conn: sqlite3.Connection,
    *,
    target_version: int = RUNTIME_SCHEMA_VERSION,
    fault_hook: Callable[[int, sqlite3.Connection], None] | None = None,
) -> int:
    """Upgrade ``conn`` transactionally under ``BEGIN IMMEDIATE``; roll back on any failure."""
    try:
        row = conn.execute("PRAGMA user_version").fetchone()
        current = int(row[0]) if row else 0
    except BaseException as exc:
        mapped = classify_persistence_error(exc)
        if mapped is exc:
            raise
        raise mapped from exc

    if current > target_version:
        raise SchemaMigrationError(
            f"Database schema version {current} is newer than supported version {target_version}."
        )

    try:
        with _write_transaction_scope():
            if not conn.in_transaction:
                conn.execute("BEGIN IMMEDIATE")
            _apply_migrations_locked(
                conn,
                current_version=current,
                target_version=target_version,
                fault_hook=fault_hook,
            )
            conn.commit()
        return target_version
    except BaseException as exc:
        with contextlib.suppress(sqlite3.Error):
            conn.rollback()
        mapped = classify_persistence_error(exc)
        if mapped is exc:
            raise
        raise mapped from exc


def _verify_sqlite_integrity(conn: sqlite3.Connection) -> None:
    row = conn.execute("PRAGMA quick_check").fetchone()
    if not row or str(row[0]).lower() != "ok":
        detail = str(row[0]) if row else "empty quick_check result"
        raise DatabaseCorruptionError(f"SQLite quick_check failed (fail closed): {detail}")


def _set_owner_only(path: Path) -> None:
    with contextlib.suppress(OSError):
        if path.exists():
            path.chmod(0o600)


def _create_online_snapshot(source_conn: sqlite3.Connection, directory: Path, prefix: str) -> Path:
    directory.mkdir(parents=True, exist_ok=True, mode=0o700)
    fd, raw_name = tempfile.mkstemp(prefix=prefix, suffix=".sqlite3.tmp", dir=directory)
    os.close(fd)
    snapshot = Path(raw_name)
    try:
        snapshot.chmod(0o600)
        with contextlib.closing(sqlite3.connect(snapshot, timeout=10.0)) as dst:
            source_conn.backup(dst, pages=256, sleep=0.01)
            dst.execute("PRAGMA journal_mode=DELETE")
            dst.commit()
            _verify_sqlite_integrity(dst)
        with snapshot.open("rb") as handle:
            os.fsync(handle.fileno())
        return snapshot
    except BaseException as exc:
        snapshot.unlink(missing_ok=True)
        mapped = classify_persistence_error(exc)
        if mapped is exc:
            raise
        raise mapped from exc


def _restore_snapshot_to_live(snapshot: Path, live_db: Path) -> None:
    fd, raw_stage = tempfile.mkstemp(prefix=f".{live_db.name}.restore-", suffix=".tmp", dir=live_db.parent)
    os.close(fd)
    staged = Path(raw_stage)
    try:
        staged.chmod(0o600)
        with (
            contextlib.closing(sqlite3.connect(snapshot, timeout=10.0)) as src,
            contextlib.closing(sqlite3.connect(staged, timeout=10.0)) as dst,
        ):
            src.backup(dst, pages=256, sleep=0.01)
            dst.execute("PRAGMA journal_mode=DELETE")
            dst.commit()
            _verify_sqlite_integrity(dst)
        with staged.open("rb") as handle:
            os.fsync(handle.fileno())
        for suffix in ("-wal", "-shm"):
            Path(f"{live_db}{suffix}").unlink(missing_ok=True)
        os.replace(staged, live_db)
        _set_owner_only(live_db)
    finally:
        staged.unlink(missing_ok=True)


def upgrade_database(
    storage: StorageProvider,
    db_path: Path,
    *,
    base_ddl: Callable[[sqlite3.Connection], None] | None = None,
    target_version: int = RUNTIME_SCHEMA_VERSION,
    backup_path: Path | None = None,
    retry_policy: BusyRetryPolicy = DEFAULT_BUSY_RETRY_POLICY,
    fault_hook: Callable[[int, sqlite3.Connection], None] | None = None,
) -> int:
    """Initialize or upgrade ``db_path`` with pre-flight checks, ``0600`` backup, and rollback/restore."""
    if backup_path is not None and backup_path.expanduser().resolve() == db_path.expanduser().resolve():
        raise SchemaMigrationError("Pre-migration backup_path must differ from db_path.")

    file_existed = False
    try:
        file_existed = db_path.is_file() and db_path.stat().st_size > 0
    except OSError:
        file_existed = False

    pre_version = 0
    pre_tables: set[str] = set()
    snapshot: Path | None = None

    if file_existed:
        conn_check: sqlite3.Connection | None = None
        try:
            conn_check = storage.connect(db_path)
            _configure_connection(conn_check, busy_timeout_ms=retry_policy.busy_timeout_ms)
            _verify_sqlite_integrity(conn_check)
            v_row = conn_check.execute("PRAGMA user_version").fetchone()
            pre_version = int(v_row[0]) if v_row else 0
            if pre_version > target_version:
                raise SchemaMigrationError(
                    f"Database schema version {pre_version} is newer than supported version {target_version}."
                )
            pre_tables = {
                str(r[0])
                for r in conn_check.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
            }
            needs_snapshot = (bool(pre_tables) and pre_version < target_version) or (backup_path is not None)
            if needs_snapshot:
                snap_dir = backup_path.parent if backup_path is not None else db_path.parent
                snapshot = _create_online_snapshot(
                    conn_check,
                    snap_dir,
                    prefix=f".{db_path.name}.pre-v{target_version}-",
                )
        except BaseException as exc:
            if snapshot is not None:
                snapshot.unlink(missing_ok=True)
            mapped = classify_persistence_error(exc)
            if mapped is exc:
                raise
            raise mapped from exc
        finally:
            if conn_check is not None:
                with contextlib.suppress(sqlite3.Error):
                    conn_check.close()

    def _upgrade_tx(conn: sqlite3.Connection) -> int:
        _verify_sqlite_integrity(conn)
        v_row = conn.execute("PRAGMA user_version").fetchone()
        current = int(v_row[0]) if v_row else 0
        if current > target_version:
            raise SchemaMigrationError(
                f"Database schema version {current} is newer than supported version {target_version}."
            )
        if base_ddl is not None:
            base_ddl(conn)
        return _apply_migrations_locked(
            conn,
            current_version=current,
            target_version=target_version,
            fault_hook=fault_hook,
        )

    try:
        # Configure WAL mode outside BEGIN IMMEDIATE once before entering the atomic DDL transaction.
        wal_conn: sqlite3.Connection | None = None
        try:
            wal_conn = storage.connect(db_path)
            _configure_connection(wal_conn, busy_timeout_ms=retry_policy.busy_timeout_ms)
            _verify_sqlite_integrity(wal_conn)
            v_row = wal_conn.execute("PRAGMA user_version").fetchone()
            current_wal = int(v_row[0]) if v_row else 0
            if current_wal > target_version:
                raise SchemaMigrationError(
                    f"Database schema version {current_wal} is newer than supported version {target_version}."
                )
            wal_conn.execute("PRAGMA journal_mode = WAL")
            wal_conn.execute("PRAGMA synchronous = NORMAL")
        except BaseException as exc:
            mapped = classify_persistence_error(exc)
            if mapped is exc:
                raise
            raise mapped from exc
        finally:
            if wal_conn is not None:
                with contextlib.suppress(sqlite3.Error):
                    wal_conn.close()

        applied_version = run_write_transaction(
            storage,
            db_path,
            _upgrade_tx,
            retry_policy=retry_policy,
        )
    except BaseException:
        if snapshot is not None:
            live_intact = False
            if db_path.is_file():
                try:
                    with contextlib.closing(sqlite3.connect(db_path, timeout=5.0)) as verify_conn:
                        _verify_sqlite_integrity(verify_conn)
                        after_v = int(verify_conn.execute("PRAGMA user_version").fetchone()[0])
                        after_tables = {
                            str(r[0])
                            for r in verify_conn.execute(
                                "SELECT name FROM sqlite_master WHERE type='table'"
                            ).fetchall()
                        }
                        live_intact = (after_v == pre_version) and (after_tables == pre_tables)
                except sqlite3.Error:
                    live_intact = False
            if not live_intact and db_path.parent.is_dir():
                with contextlib.suppress(OSError, sqlite3.Error):
                    _restore_snapshot_to_live(snapshot, db_path)
                    live_intact = True
            if backup_path is not None:
                with contextlib.suppress(OSError):
                    os.replace(snapshot, backup_path)
                    _set_owner_only(backup_path)
            elif live_intact:
                snapshot.unlink(missing_ok=True)
        raise

    for protected in (db_path, Path(f"{db_path}-wal"), Path(f"{db_path}-shm")):
        _set_owner_only(protected)

    if snapshot is not None:
        if backup_path is not None:
            backup_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
            os.replace(snapshot, backup_path)
            _set_owner_only(backup_path)
        else:
            snapshot.unlink(missing_ok=True)

    return applied_version


# ---------------------------------------------------------------------------
# Typed durable spine records and short-transaction store (M5-P1-01)
# ---------------------------------------------------------------------------


def _non_empty_text(value: str, field: str, *, max_len: int = 256) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise ValueError(f"{field} must be a non-empty string without NUL characters.")
    cleaned = value.strip()
    if len(cleaned) > max_len:
        raise ValueError(f"{field} exceeds maximum length ({max_len}).")
    return cleaned


@dataclass(frozen=True, slots=True)
class TaskRecord:
    """Durable autonomous root/child task record."""

    task_id: str
    parent_task_id: str | None
    session_id: str
    title: str
    state: str
    current_epoch: int
    state_version: int
    workspace_dir: str
    policy: str
    budget_json: str
    checkpoint_ref: str
    created_at: float
    updated_at: float


@dataclass(frozen=True, slots=True)
class TaskEpochRecord:
    """Durable worker lease and monotonic fencing epoch record."""

    task_id: str
    epoch: int
    worker_id: str
    status: str
    claimed_at: float
    heartbeat_at: float
    lease_expires_at: float
    fenced_at: float | None
    fence_reason: str


@dataclass(frozen=True, slots=True)
class TaskTransitionRecord:
    """Append-only durable state transition entry for a task."""

    id: int
    task_id: str
    seq: int
    from_state: str
    to_state: str
    epoch: int
    reason: str
    evidence_json: str
    created_at: float


@dataclass(frozen=True, slots=True)
class ActionRecord:
    """Durable consequential action intent and outcome record."""

    action_id: str
    task_id: str | None
    session_id: str
    epoch: int
    attempt: int
    action_class: str
    replay_policy: str
    tool_name: str
    policy: str
    explicit_approval: bool
    args_sha256: str
    status: str
    ok: bool | None
    elapsed_ms: int | None
    output_sha256: str
    error_code: str
    created_at: float
    updated_at: float


def _row_to_task(row: sqlite3.Row) -> TaskRecord:
    return TaskRecord(
        task_id=str(row["task_id"]),
        parent_task_id=str(row["parent_task_id"]) if row["parent_task_id"] is not None else None,
        session_id=str(row["session_id"]),
        title=str(row["title"]),
        state=str(row["state"]),
        current_epoch=int(row["current_epoch"]),
        state_version=int(row["state_version"]),
        workspace_dir=str(row["workspace_dir"]),
        policy=str(row["policy"]),
        budget_json=str(row["budget_json"]),
        checkpoint_ref=str(row["checkpoint_ref"]),
        created_at=float(row["created_at"]),
        updated_at=float(row["updated_at"]),
    )


def _row_to_epoch(row: sqlite3.Row) -> TaskEpochRecord:
    return TaskEpochRecord(
        task_id=str(row["task_id"]),
        epoch=int(row["epoch"]),
        worker_id=str(row["worker_id"]),
        status=str(row["status"]),
        claimed_at=float(row["claimed_at"]),
        heartbeat_at=float(row["heartbeat_at"]),
        lease_expires_at=float(row["lease_expires_at"]),
        fenced_at=float(row["fenced_at"]) if row["fenced_at"] is not None else None,
        fence_reason=str(row["fence_reason"]),
    )


def _row_to_transition(row: sqlite3.Row) -> TaskTransitionRecord:
    return TaskTransitionRecord(
        id=int(row["id"]),
        task_id=str(row["task_id"]),
        seq=int(row["seq"]),
        from_state=str(row["from_state"]),
        to_state=str(row["to_state"]),
        epoch=int(row["epoch"]),
        reason=str(row["reason"]),
        evidence_json=str(row["evidence_json"]),
        created_at=float(row["created_at"]),
    )


def _row_to_action(row: sqlite3.Row) -> ActionRecord:
    return ActionRecord(
        action_id=str(row["action_id"]),
        task_id=str(row["task_id"]) if row["task_id"] is not None else None,
        session_id=str(row["session_id"]),
        epoch=int(row["epoch"]),
        attempt=int(row["attempt"]),
        action_class=str(row["action_class"]),
        replay_policy=str(row["replay_policy"]),
        tool_name=str(row["tool_name"]),
        policy=str(row["policy"]),
        explicit_approval=bool(row["explicit_approval"]),
        args_sha256=str(row["args_sha256"]),
        status=str(row["status"]),
        ok=bool(row["ok"]) if row["ok"] is not None else None,
        elapsed_ms=int(row["elapsed_ms"]) if row["elapsed_ms"] is not None else None,
        output_sha256=str(row["output_sha256"]),
        error_code=str(row["error_code"]),
        created_at=float(row["created_at"]),
        updated_at=float(row["updated_at"]),
    )


class RuntimePersistenceStore:
    """Short-transaction SQLite repository for tasks, transitions, actions, and epochs."""

    def __init__(
        self,
        storage: StorageProvider,
        db_path: Path,
        *,
        retry_policy: BusyRetryPolicy = DEFAULT_BUSY_RETRY_POLICY,
    ) -> None:
        self._storage = storage
        self._db_path = db_path
        self._retry_policy = retry_policy

    def create_task(
        self,
        task_id: str,
        *,
        session_id: str = "",
        parent_task_id: str | None = None,
        title: str = "",
        state: str = "pending",
        workspace_dir: str = "",
        policy: str = "standard",
        budget_json: str = "{}",
        checkpoint_ref: str = "",
        now: float | None = None,
    ) -> TaskRecord:
        tid = _non_empty_text(task_id, "task_id", max_len=128)
        parent = _non_empty_text(parent_task_id, "parent_task_id", max_len=128) if parent_task_id else None
        if state not in TASK_STATES:
            raise ValueError(f"Unsupported task state: {state!r}")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskRecord:
            conn.row_factory = sqlite3.Row
            conn.execute(
                """
                INSERT INTO runtime_tasks (
                    task_id, parent_task_id, session_id, title, state,
                    current_epoch, state_version, workspace_dir, policy,
                    budget_json, checkpoint_ref, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, 0, 0, ?, ?, ?, ?, ?, ?)
                """,
                (
                    tid,
                    parent,
                    str(session_id)[:128],
                    str(title)[:240],
                    state,
                    str(workspace_dir),
                    str(policy)[:40],
                    str(budget_json or "{}"),
                    str(checkpoint_ref)[:256],
                    ts,
                    ts,
                ),
            )
            row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            assert row is not None
            return _row_to_task(row)

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def get_task(self, task_id: str) -> TaskRecord | None:
        tid = _non_empty_text(task_id, "task_id", max_len=128)

        def _read(conn: sqlite3.Connection) -> TaskRecord | None:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            return _row_to_task(row) if row is not None else None

        return run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def list_child_tasks(self, parent_task_id: str) -> list[TaskRecord]:
        """Return child milestone tasks under ``parent_task_id`` ordered by creation."""
        pid = _non_empty_text(parent_task_id, "parent_task_id", max_len=128)

        def _read(conn: sqlite3.Connection) -> list[TaskRecord]:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                "SELECT * FROM runtime_tasks WHERE parent_task_id = ? ORDER BY created_at ASC, task_id ASC",
                (pid,),
            ).fetchall()
            return [_row_to_task(r) for r in rows]

        return run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def list_root_tasks(self, *, states: tuple[str, ...] | None = None) -> list[TaskRecord]:
        """Return root ``runtime_tasks`` rows (``parent_task_id IS NULL``)."""
        if states is not None:
            for st in states:
                if st not in TASK_STATES:
                    raise ValueError(f"Unsupported task state filter: {st!r}")

        def _read(conn: sqlite3.Connection) -> list[TaskRecord]:
            conn.row_factory = sqlite3.Row
            if states:
                placeholders = ",".join("?" for _ in states)
                rows = conn.execute(
                    f"SELECT * FROM runtime_tasks WHERE parent_task_id IS NULL AND state IN ({placeholders}) ORDER BY created_at ASC",
                    tuple(states),
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT * FROM runtime_tasks WHERE parent_task_id IS NULL ORDER BY created_at ASC"
                ).fetchall()
            return [_row_to_task(r) for r in rows]

        return run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def ensure_task(
        self,
        task_id: str,
        *,
        session_id: str = "",
        title: str = "",
        state: str = "pending",
        workspace_dir: str = "",
        policy: str = "standard",
        now: float | None = None,
    ) -> TaskRecord:
        """Idempotently ensure an authoritative ``runtime_tasks`` row exists."""
        tid = _non_empty_text(task_id, "task_id", max_len=128)
        if state not in TASK_STATES:
            raise ValueError(f"Unsupported task state: {state!r}")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskRecord:
            conn.row_factory = sqlite3.Row
            existing = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if existing is not None:
                if workspace_dir or policy:
                    conn.execute(
                        """
                        UPDATE runtime_tasks
                        SET workspace_dir = CASE WHEN ? != '' THEN ? ELSE workspace_dir END,
                            policy = CASE WHEN ? != '' THEN ? ELSE policy END,
                            updated_at = ?
                        WHERE task_id = ?
                        """,
                        (str(workspace_dir), str(workspace_dir), str(policy)[:40], str(policy)[:40], ts, tid),
                    )
                    refreshed = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
                    assert refreshed is not None
                    return _row_to_task(refreshed)
                return _row_to_task(existing)
            conn.execute(
                """
                INSERT INTO runtime_tasks (
                    task_id, parent_task_id, session_id, title, state,
                    current_epoch, state_version, workspace_dir, policy,
                    budget_json, checkpoint_ref, created_at, updated_at
                ) VALUES (?, NULL, ?, ?, ?, 0, 0, ?, ?, '{}', '', ?, ?)
                """,
                (tid, str(session_id)[:128], str(title)[:240], state, str(workspace_dir), str(policy)[:40], ts, ts),
            )
            created = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            assert created is not None
            return _row_to_task(created)

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def claim_epoch(
        self,
        task_id: str,
        worker_id: str,
        *,
        lease_ttl_s: float = 30.0,
        fence_reason: str = "superseded_by_new_epoch",
        now: float | None = None,
    ) -> TaskEpochRecord:
        tid = _non_empty_text(task_id, "task_id", max_len=128)
        wid = _non_empty_text(worker_id, "worker_id", max_len=128)
        if lease_ttl_s <= 0:
            raise ValueError("lease_ttl_s must be positive.")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskEpochRecord:
            conn.row_factory = sqlite3.Row
            task_row = conn.execute("SELECT current_epoch FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if task_row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            next_epoch = int(task_row["current_epoch"]) + 1
            conn.execute(
                """
                UPDATE runtime_task_epochs
                SET status = 'fenced', fenced_at = ?, fence_reason = ?
                WHERE task_id = ? AND status = 'active'
                """,
                (ts, str(fence_reason)[:160], tid),
            )
            conn.execute(
                "UPDATE runtime_tasks SET current_epoch = ?, updated_at = ? WHERE task_id = ?",
                (next_epoch, ts, tid),
            )
            conn.execute(
                """
                INSERT INTO runtime_task_epochs (
                    task_id, epoch, worker_id, status, claimed_at, heartbeat_at, lease_expires_at
                ) VALUES (?, ?, ?, 'active', ?, ?, ?)
                """,
                (tid, next_epoch, wid, ts, ts, ts + lease_ttl_s),
            )
            row = conn.execute(
                "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                (tid, next_epoch),
            ).fetchone()
            assert row is not None
            return _row_to_epoch(row)

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def acquire_worker_lease(
        self,
        task_id: str,
        worker_id: str,
        *,
        lease_ttl_s: float = 30.0,
        force_takeover: bool = False,
        fence_reason: str = "lease_takeover",
        now: float | None = None,
    ) -> tuple[TaskEpochRecord, list[TaskEpochRecord]]:
        """Transactionally claim single-owner worker lease with monotonic epoch (M5-P1-04).

        Rejects concurrent acquisition with :class:`LeaseOwnershipConflictError`
        when another worker holds an unexpired active lease unless ``force_takeover=True``.
        Expired active leases transition to ``expired`` before the replacement
        epoch is minted; ``runtime_actions`` rows are never cleared by lease expiry.
        """
        tid = _non_empty_text(task_id, "task_id", max_len=128)
        wid = _non_empty_text(worker_id, "worker_id", max_len=128)
        if lease_ttl_s <= 0:
            raise ValueError("lease_ttl_s must be positive.")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> tuple[TaskEpochRecord, list[TaskEpochRecord]]:
            conn.row_factory = sqlite3.Row
            task_row = conn.execute("SELECT current_epoch FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if task_row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            active_rows = conn.execute(
                "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND status = 'active' ORDER BY epoch ASC",
                (tid,),
            ).fetchall()
            closed_epochs: list[int] = []
            for a_row in active_rows:
                a_ep = int(a_row["epoch"])
                a_owner = str(a_row["worker_id"])
                a_exp = float(a_row["lease_expires_at"])
                if a_exp <= ts:
                    conn.execute(
                        """
                        UPDATE runtime_task_epochs
                        SET status = 'expired', fenced_at = ?, fence_reason = 'lease_expired'
                        WHERE task_id = ? AND epoch = ? AND status = 'active'
                        """,
                        (ts, tid, a_ep),
                    )
                    closed_epochs.append(a_ep)
                else:
                    if not force_takeover and a_owner != wid:
                        raise LeaseOwnershipConflictError(
                            f"Task {tid!r} is actively owned by worker {a_owner!r} in epoch {a_ep} "
                            f"(lease valid for {max(0.0, a_exp - ts):.2f}s)."
                        )
                    conn.execute(
                        """
                        UPDATE runtime_task_epochs
                        SET status = 'fenced', fenced_at = ?, fence_reason = ?
                        WHERE task_id = ? AND epoch = ? AND status = 'active'
                        """,
                        (ts, str(fence_reason)[:160], tid, a_ep),
                    )
                    closed_epochs.append(a_ep)

            next_epoch = int(task_row["current_epoch"]) + 1
            conn.execute(
                "UPDATE runtime_tasks SET current_epoch = ?, updated_at = ? WHERE task_id = ?",
                (next_epoch, ts, tid),
            )
            conn.execute(
                """
                INSERT INTO runtime_task_epochs (
                    task_id, epoch, worker_id, status, claimed_at, heartbeat_at, lease_expires_at
                ) VALUES (?, ?, ?, 'active', ?, ?, ?)
                """,
                (tid, next_epoch, wid, ts, ts, ts + lease_ttl_s),
            )
            new_row = conn.execute(
                "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                (tid, next_epoch),
            ).fetchone()
            assert new_row is not None
            superseded: list[TaskEpochRecord] = []
            for c_ep in closed_epochs:
                c_row = conn.execute(
                    "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                    (tid, c_ep),
                ).fetchone()
                if c_row is not None:
                    superseded.append(_row_to_epoch(c_row))
            return _row_to_epoch(new_row), superseded

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def heartbeat_epoch(
        self,
        task_id: str,
        epoch: int,
        worker_id: str,
        *,
        lease_ttl_s: float = 30.0,
        now: float | None = None,
    ) -> TaskEpochRecord:
        """Renew an active worker lease or fail closed on stale/fenced/expired epochs."""
        tid = _non_empty_text(task_id, "task_id", max_len=128)
        wid = _non_empty_text(worker_id, "worker_id", max_len=128)
        if lease_ttl_s <= 0:
            raise ValueError("lease_ttl_s must be positive.")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> tuple[TaskEpochRecord | None, str, str]:
            conn.row_factory = sqlite3.Row
            t_row = conn.execute("SELECT current_epoch FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if t_row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            cur_ep = int(t_row["current_epoch"])
            ep_row = conn.execute(
                "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                (tid, int(epoch)),
            ).fetchone()
            if ep_row is None or int(epoch) != cur_ep:
                return (
                    None,
                    "stale",
                    f"Stale task epoch {epoch} for task {tid!r} (current_epoch={cur_ep}).",
                )
            if str(ep_row["worker_id"]) != wid:
                return (
                    None,
                    "owner",
                    f"Worker {wid!r} does not own task {tid!r} epoch {epoch} (owned by {ep_row['worker_id']!r}).",
                )
            if str(ep_row["status"]) != "active":
                return (
                    None,
                    "stale",
                    f"Task {tid!r} epoch {epoch} is not active (status={ep_row['status']!r}).",
                )
            if float(ep_row["lease_expires_at"]) <= ts:
                conn.execute(
                    """
                    UPDATE runtime_task_epochs
                    SET status = 'expired', fenced_at = ?, fence_reason = 'lease_expired_before_heartbeat'
                    WHERE task_id = ? AND epoch = ? AND status = 'active'
                    """,
                    (ts, tid, int(epoch)),
                )
                return (
                    None,
                    "expired",
                    f"Task {tid!r} epoch {epoch} lease expired at {float(ep_row['lease_expires_at']):.3f} (now={ts:.3f}).",
                )
            conn.execute(
                """
                UPDATE runtime_task_epochs
                SET heartbeat_at = ?, lease_expires_at = ?
                WHERE task_id = ? AND epoch = ?
                """,
                (ts, ts + lease_ttl_s, tid, int(epoch)),
            )
            conn.execute("UPDATE runtime_tasks SET updated_at = ? WHERE task_id = ?", (ts, tid))
            refreshed = conn.execute(
                "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                (tid, int(epoch)),
            ).fetchone()
            assert refreshed is not None
            return _row_to_epoch(refreshed), "", ""

        rec, err_kind, err_msg = run_write_transaction(
            self._storage, self._db_path, _tx, retry_policy=self._retry_policy
        )
        if err_kind == "stale":
            raise StaleEpochError(err_msg)
        if err_kind == "owner":
            raise LeaseOwnershipConflictError(err_msg)
        if err_kind == "expired":
            raise LeaseExpiredError(err_msg)
        assert rec is not None
        return rec

    def expire_stale_leases(
        self,
        *,
        task_id: str | None = None,
        now: float | None = None,
    ) -> list[TaskEpochRecord]:
        """Mark active epochs past ``lease_expires_at`` as ``expired`` without releasing unresolved actions."""
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> list[TaskEpochRecord]:
            conn.row_factory = sqlite3.Row
            clauses = ["status = 'active'", "lease_expires_at <= ?"]
            params: list[Any] = [ts]
            if task_id is not None:
                clauses.append("task_id = ?")
                params.append(_non_empty_text(task_id, "task_id", max_len=128))
            where_sql = " AND ".join(clauses)
            rows = conn.execute(
                f"SELECT task_id, epoch FROM runtime_task_epochs WHERE {where_sql} ORDER BY task_id, epoch",
                tuple(params),
            ).fetchall()
            if not rows:
                return []
            expired_records: list[TaskEpochRecord] = []
            for r in rows:
                conn.execute(
                    """
                    UPDATE runtime_task_epochs
                    SET status = 'expired', fenced_at = ?, fence_reason = 'lease_expired'
                    WHERE task_id = ? AND epoch = ? AND status = 'active'
                    """,
                    (ts, str(r["task_id"]), int(r["epoch"])),
                )
                upd = conn.execute(
                    "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                    (str(r["task_id"]), int(r["epoch"])),
                ).fetchone()
                if upd is not None:
                    expired_records.append(_row_to_epoch(upd))
            return expired_records

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def fence_active_epoch(
        self,
        task_id: str,
        *,
        reason: str = "fenced_by_operator",
        now: float | None = None,
    ) -> list[TaskEpochRecord]:
        """Fence any currently active lease epoch on ``task_id``."""
        tid = _non_empty_text(task_id, "task_id", max_len=128)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> list[TaskEpochRecord]:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                "SELECT epoch FROM runtime_task_epochs WHERE task_id = ? AND status = 'active' ORDER BY epoch ASC",
                (tid,),
            ).fetchall()
            if not rows:
                return []
            fenced: list[TaskEpochRecord] = []
            for r in rows:
                ep_num = int(r["epoch"])
                conn.execute(
                    """
                    UPDATE runtime_task_epochs
                    SET status = 'fenced', fenced_at = ?, fence_reason = ?
                    WHERE task_id = ? AND epoch = ? AND status = 'active'
                    """,
                    (ts, str(reason)[:160], tid, ep_num),
                )
                upd = conn.execute(
                    "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                    (tid, ep_num),
                ).fetchone()
                if upd is not None:
                    fenced.append(_row_to_epoch(upd))
            return fenced

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def fence_foreign_boot_leases(
        self,
        *,
        worker_prefix: str = "wrk-",
        current_boot_prefix: str,
        now: float | None = None,
    ) -> list[TaskEpochRecord]:
        """Fence active runtime worker leases created by a prior OS process boot."""
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> list[TaskEpochRecord]:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                """
                SELECT task_id, epoch FROM runtime_task_epochs
                WHERE status = 'active' AND worker_id LIKE ? AND worker_id NOT LIKE ?
                ORDER BY task_id, epoch
                """,
                (f"{worker_prefix}%", f"{current_boot_prefix}%"),
            ).fetchall()
            if not rows:
                return []
            fenced: list[TaskEpochRecord] = []
            for r in rows:
                conn.execute(
                    """
                    UPDATE runtime_task_epochs
                    SET status = 'fenced', fenced_at = ?, fence_reason = 'prior_process_restart'
                    WHERE task_id = ? AND epoch = ? AND status = 'active'
                    """,
                    (ts, str(r["task_id"]), int(r["epoch"])),
                )
                upd = conn.execute(
                    "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                    (str(r["task_id"]), int(r["epoch"])),
                ).fetchone()
                if upd is not None:
                    fenced.append(_row_to_epoch(upd))
            return fenced

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def release_epoch(
        self,
        task_id: str,
        epoch: int,
        worker_id: str,
        *,
        next_state: str | None = None,
        reason: str = "turn_completed",
        now: float | None = None,
    ) -> bool:
        """Cleanly release ``(task_id, epoch)`` iff still active and owned by ``worker_id``.

        Returns ``False`` without mutating ``runtime_tasks.state`` when the epoch
        was already fenced, expired, or superseded by a replacement worker.
        """
        tid = _non_empty_text(task_id, "task_id", max_len=128)
        wid = _non_empty_text(worker_id, "worker_id", max_len=128)
        if next_state is not None and next_state not in TASK_STATES:
            raise ValueError(f"Unsupported target task state: {next_state!r}")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> bool:
            conn.row_factory = sqlite3.Row
            t_row = conn.execute("SELECT state, current_epoch FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if t_row is None or int(t_row["current_epoch"]) != int(epoch):
                return False
            ep_row = conn.execute(
                "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                (tid, int(epoch)),
            ).fetchone()
            if ep_row is None or str(ep_row["worker_id"]) != wid or str(ep_row["status"]) != "active":
                return False
            if float(ep_row["lease_expires_at"]) <= ts:
                conn.execute(
                    """
                    UPDATE runtime_task_epochs
                    SET status = 'expired', fenced_at = ?, fence_reason = 'lease_expired_before_release'
                    WHERE task_id = ? AND epoch = ? AND status = 'active'
                    """,
                    (ts, tid, int(epoch)),
                )
                return False
            conn.execute(
                "UPDATE runtime_task_epochs SET status = 'released', heartbeat_at = ? WHERE task_id = ? AND epoch = ?",
                (ts, tid, int(epoch)),
            )
            if next_state is not None and str(t_row["state"]) != next_state:
                from_state = str(t_row["state"])
                seq_row = conn.execute(
                    "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                    (tid,),
                ).fetchone()
                next_seq = int(seq_row[0]) if seq_row else 1
                conn.execute(
                    "UPDATE runtime_tasks SET state = ?, state_version = state_version + 1, updated_at = ? WHERE task_id = ?",
                    (next_state, ts, tid),
                )
                conn.execute(
                    """
                    INSERT INTO runtime_task_transitions (
                        task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                    ) VALUES (?, ?, ?, ?, ?, ?, '{}', ?)
                    """,
                    (tid, next_seq, from_state, next_state, int(epoch), str(reason)[:240], ts),
                )
            return True

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def get_epoch(self, task_id: str, epoch: int) -> TaskEpochRecord | None:
        tid = _non_empty_text(task_id, "task_id", max_len=128)

        def _read(conn: sqlite3.Connection) -> TaskEpochRecord | None:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                (tid, int(epoch)),
            ).fetchone()
            return _row_to_epoch(row) if row is not None else None

        return run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def list_epochs(self, task_id: str) -> list[TaskEpochRecord]:
        tid = _non_empty_text(task_id, "task_id", max_len=128)

        def _read(conn: sqlite3.Connection) -> list[TaskEpochRecord]:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                "SELECT * FROM runtime_task_epochs WHERE task_id = ? ORDER BY epoch ASC",
                (tid,),
            ).fetchall()
            return [_row_to_epoch(r) for r in rows]

        return run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def record_transition(
        self,
        task_id: str,
        *,
        to_state: str,
        expected_state_version: int | None = None,
        epoch: int | None = None,
        reason: str = "",
        evidence_json: str = "{}",
        checkpoint_ref: str | None = None,
        allow_inactive_epoch: bool = False,
        now: float | None = None,
    ) -> tuple[TaskRecord, TaskTransitionRecord]:
        tid = _non_empty_text(task_id, "task_id", max_len=128)
        if to_state not in TASK_STATES:
            raise ValueError(f"Unsupported target task state: {to_state!r}")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> tuple[TaskRecord, TaskTransitionRecord]:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            current_version = int(row["state_version"])
            if expected_state_version is not None and current_version != expected_state_version:
                raise ValueError(
                    f"Task {tid!r} state_version mismatch (expected {expected_state_version}, actual {current_version})."
                )
            current_epoch = int(row["current_epoch"])
            if epoch is not None and epoch != current_epoch:
                raise StaleEpochError(
                    f"Stale task epoch {epoch} cannot transition task {tid!r} at current_epoch={current_epoch}."
                )
            if epoch is not None and epoch > 0 and not allow_inactive_epoch:
                ep_row = conn.execute(
                    "SELECT status, lease_expires_at FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                    (tid, int(epoch)),
                ).fetchone()
                if ep_row is None or str(ep_row["status"]) != "active":
                    raise StaleEpochError(
                        f"Inactive task epoch {epoch} cannot transition task {tid!r}."
                    )
                if float(ep_row["lease_expires_at"]) <= ts:
                    raise LeaseExpiredError(
                        f"Expired task epoch {epoch} cannot transition task {tid!r}."
                    )
            effective_epoch = current_epoch if epoch is None else int(epoch)
            from_state = str(row["state"])
            seq_row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                (tid,),
            ).fetchone()
            next_seq = int(seq_row[0]) if seq_row else 1
            new_checkpoint = str(row["checkpoint_ref"]) if checkpoint_ref is None else str(checkpoint_ref)[:256]
            conn.execute(
                """
                UPDATE runtime_tasks
                SET state = ?, state_version = state_version + 1, checkpoint_ref = ?, updated_at = ?
                WHERE task_id = ?
                """,
                (to_state, new_checkpoint, ts, tid),
            )
            cur = conn.execute(
                """
                INSERT INTO runtime_task_transitions (
                    task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (tid, next_seq, from_state, to_state, effective_epoch, str(reason)[:240], str(evidence_json or "{}"), ts),
            )
            updated_task = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            tr_row = conn.execute(
                "SELECT * FROM runtime_task_transitions WHERE id = ?",
                (cur.lastrowid,),
            ).fetchone()
            assert updated_task is not None and tr_row is not None
            return _row_to_task(updated_task), _row_to_transition(tr_row)

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def list_transitions(self, task_id: str) -> list[TaskTransitionRecord]:
        tid = _non_empty_text(task_id, "task_id", max_len=128)

        def _read(conn: sqlite3.Connection) -> list[TaskTransitionRecord]:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                "SELECT * FROM runtime_task_transitions WHERE task_id = ? ORDER BY seq ASC",
                (tid,),
            ).fetchall()
            return [_row_to_transition(r) for r in rows]

        return run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def record_action_intent(
        self,
        action_id: str,
        *,
        tool_name: str,
        policy: str,
        args_sha256: str,
        task_id: str | None = None,
        session_id: str = "",
        epoch: int = 0,
        attempt: int = 1,
        action_class: str = "consequential",
        replay_policy: str = "non_idempotent",
        explicit_approval: bool = False,
        status: str = "in_flight",
        now: float | None = None,
    ) -> ActionRecord:
        aid = _non_empty_text(action_id, "action_id", max_len=128)
        tid = _non_empty_text(task_id, "task_id", max_len=128) if task_id else None
        tname = _non_empty_text(tool_name, "tool_name", max_len=200)
        pol = _non_empty_text(policy, "policy", max_len=40)
        digest = _non_empty_text(args_sha256, "args_sha256", max_len=128)
        if action_class not in ACTION_CLASSES:
            raise ValueError(f"Unsupported action_class: {action_class!r}")
        if replay_policy not in REPLAY_POLICIES:
            raise ValueError(f"Unsupported replay_policy: {replay_policy!r}")
        if status not in {"never_started", "in_flight", "denied"}:
            raise ValueError(f"Invalid initial action status: {status!r}")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> ActionRecord:
            conn.row_factory = sqlite3.Row
            if tid is not None:
                task_row = conn.execute(
                    "SELECT current_epoch FROM runtime_tasks WHERE task_id = ?",
                    (tid,),
                ).fetchone()
                if task_row is None:
                    raise KeyError(f"Runtime task {tid!r} does not exist.")
                if epoch > 0 and int(task_row["current_epoch"]) != int(epoch):
                    raise PermissionError(
                        f"Stale epoch {epoch} cannot record action intent for task {tid!r} (current_epoch={task_row['current_epoch']})."
                    )
            conn.execute(
                """
                INSERT INTO runtime_actions (
                    action_id, task_id, session_id, epoch, attempt, action_class,
                    replay_policy, tool_name, policy, explicit_approval, args_sha256,
                    status, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    aid,
                    tid,
                    str(session_id)[:128],
                    int(epoch),
                    int(attempt),
                    action_class,
                    replay_policy,
                    tname,
                    pol,
                    int(bool(explicit_approval)),
                    digest,
                    status,
                    ts,
                    ts,
                ),
            )
            row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            assert row is not None
            return _row_to_action(row)

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def finalize_action(
        self,
        action_id: str,
        *,
        status: str,
        ok: bool | None,
        elapsed_ms: int | None,
        output_sha256: str = "",
        error_code: str = "",
        now: float | None = None,
    ) -> ActionRecord:
        aid = _non_empty_text(action_id, "action_id", max_len=128)
        if status not in {"committed", "failed", "denied", "uncertain"}:
            raise ValueError(f"Unsupported terminal/reconciled action status: {status!r}")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> ActionRecord:
            conn.row_factory = sqlite3.Row
            existing = conn.execute("SELECT status FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            if existing is None:
                raise KeyError(f"Runtime action {aid!r} does not exist.")
            conn.execute(
                """
                UPDATE runtime_actions
                SET status = ?, ok = ?, elapsed_ms = ?, output_sha256 = ?, error_code = ?, updated_at = ?
                WHERE action_id = ?
                """,
                (
                    status,
                    (int(bool(ok)) if ok is not None else None),
                    (max(0, int(elapsed_ms)) if elapsed_ms is not None else None),
                    str(output_sha256)[:128],
                    str(error_code)[:120],
                    ts,
                    aid,
                ),
            )
            row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            assert row is not None
            return _row_to_action(row)

        return run_write_transaction(self._storage, self._db_path, _tx, retry_policy=self._retry_policy)

    def get_action(self, action_id: str) -> ActionRecord | None:
        aid = _non_empty_text(action_id, "action_id", max_len=128)

        def _read(conn: sqlite3.Connection) -> ActionRecord | None:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            return _row_to_action(row) if row is not None else None

        return run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def list_task_actions(
        self,
        task_id: str,
        *,
        statuses: tuple[str, ...] | None = None,
    ) -> list[ActionRecord]:
        tid = _non_empty_text(task_id, "task_id", max_len=128)
        if statuses is not None:
            for st in statuses:
                if st not in ACTION_STATUSES:
                    raise ValueError(f"Unsupported action status filter: {st!r}")

        def _read(conn: sqlite3.Connection) -> list[ActionRecord]:
            conn.row_factory = sqlite3.Row
            if statuses:
                placeholders = ",".join("?" for _ in statuses)
                rows = conn.execute(
                    f"SELECT * FROM runtime_actions WHERE task_id = ? AND status IN ({placeholders}) ORDER BY created_at ASC",
                    (tid, *statuses),
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT * FROM runtime_actions WHERE task_id = ? ORDER BY created_at ASC",
                    (tid,),
                ).fetchall()
            return [_row_to_action(r) for r in rows]

        return run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

runtime_persistence = sys.modules[__name__]

"""Durable intent/result ledger and replay classification for workflow side effects (M5-P1-03).

Provides both:
1. The standalone ``SideEffectLedger`` contract (retained for narrow contract tests).
2. The authoritative M5 2.0 ``DurableActionLedger`` integrated into the served
   runtime over Schema v3 ``runtime_actions`` (``runtime_persistence``):
   - Stable ``action_id`` and monotonic ``attempt`` identities
     (``derive_action_id``, ``format_attempt_id``);
   - Explicit separation of ``never_started``, ``in_flight``, ``committed``, and
     ``uncertain`` (plus ``denied`` and confirmed ``failed``);
   - Missing results on crash/interruption are reconciled to ``uncertain``
     (never ``failed``);
   - Action-type replay classification (``idempotent``, ``reconcilable``,
     ``non_idempotent``) ensuring non-idempotent uncertain writes are never
     retried blindly.

Stdlib-only (plus ``runtime_persistence``); inlined into standalone ``studio.py``
by ``scripts/build_studio.py``.
"""


import asyncio
import hashlib
import json
import sqlite3
import time
import uuid
from collections.abc import Callable, Iterable, Mapping, Sequence
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Literal, Protocol


EffectStatus = Literal["claimed", "completed", "failed"]
_STATUSES = frozenset({"claimed", "completed", "failed"})

ReplayPolicy = Literal["idempotent", "reconcilable", "non_idempotent"]
LedgerActionStatus = Literal["never_started", "in_flight", "committed", "failed", "denied", "uncertain"]
ReconciliationVerdict = Literal["verified_committed", "verified_not_applied", "unresolved"]

_LEDGER_READ_ONLY_TOOLS: frozenset[str] = frozenset(
    {
        "list_files",
        "grep_search",
        "read_file",
        "codegraph_architecture",
        "codegraph_context",
        "codegraph_impact",
        "codegraph_path",
        "codegraph_quality",
        "oc_lint",
        "ctx_search",
        "oc_search",
        "oc_read",
        "mcp_bridge__get_current_session_data",
        "mcp_bridge__get_harness_diff",
        "mcp_bridge__oc_search",
        "mcp_bridge__oc_lint",
        "mcp_bridge__codegraph_query",
    }
)
_LEDGER_READ_ONLY_BLOCKS: frozenset[str] = frozenset({"json-peek", "csv-peek", "shortcut-debt"})

_AMBIGUOUS_EXC_NAMES: frozenset[str] = frozenset(
    {
        "McpAmbiguousOutcomeError",
        "AmbiguousSideEffectError",
        "CancelledError",
        "ReadTimeout",
        "WriteTimeout",
        "PoolTimeout",
        "RemoteProtocolError",
    }
)


class SideEffectError(ValueError):
    """Raised when a side-effect ledger request is malformed."""


class DuplicateSideEffect(RuntimeError):
    """Raised when an operation key already represents a non-retryable effect."""


class AmbiguousSideEffectError(RuntimeError):
    """Raised when a side effect was dispatched and its outcome could not be confirmed."""


class ActionIdentityConflictError(DuplicateSideEffect, PermissionError):
    """Raised when an action_id is reused for a different tool or argument digest."""


class UncertainActionReplayError(DuplicateSideEffect, PermissionError):
    """Raised when a non-idempotent or unverified uncertain action is replayed blindly."""


class CommittedActionReplayError(DuplicateSideEffect, PermissionError):
    """Raised when an already-committed consequential action is re-submitted."""


class UnresolvedEffectsHoldError(DuplicateSideEffect, PermissionError):
    """Raised when lease takeover or consequential admission is held by unresolved effects (M5-P1-04)."""

    def __init__(
        self,
        message: str,
        *,
        task_id: str = "",
        epoch: int = 0,
        unresolved_action_ids: tuple[str, ...] = (),
    ) -> None:
        super().__init__(message)
        self.task_id = task_id
        self.epoch = epoch
        self.unresolved_action_ids = unresolved_action_ids


@dataclass(frozen=True, slots=True)
class EffectRecord:
    operation_key: str
    effect_name: str
    request_hash: str
    status: EffectStatus
    result_hash: str | None
    attempts: int
    updated_at: str


def _text(value: str, field: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise SideEffectError(f"{field} must be a non-empty string without NUL characters.")
    return value.strip()


def _status(value: str) -> EffectStatus:
    if value not in _STATUSES:
        raise SideEffectError(f"unknown side-effect status: {value}")
    return value  # type: ignore[return-value]


class SideEffectLedger:
    """Claim operation keys atomically before execution and finalize exactly once."""

    def __init__(self, database: Path) -> None:
        self.database = Path(database)
        self.database.parent.mkdir(parents=True, exist_ok=True)
        with sqlite3.connect(self.database) as connection:
            connection.execute(
                """
                CREATE TABLE IF NOT EXISTS side_effects (
                    operation_key TEXT PRIMARY KEY,
                    effect_name TEXT NOT NULL,
                    request_hash TEXT NOT NULL,
                    status TEXT NOT NULL,
                    result_hash TEXT,
                    attempts INTEGER NOT NULL,
                    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    CHECK (status IN ('claimed', 'completed', 'failed')),
                    CHECK (attempts > 0)
                )
                """
            )

    @staticmethod
    def _record(row: sqlite3.Row | None) -> EffectRecord | None:
        if row is None:
            return None
        _status(row["status"])
        return EffectRecord(
            row["operation_key"],
            row["effect_name"],
            row["request_hash"],
            row["status"],
            row["result_hash"],
            row["attempts"],
            row["updated_at"],
        )

    def get(self, operation_key: str) -> EffectRecord | None:
        key = _text(operation_key, "operation_key")
        with sqlite3.connect(self.database) as connection:
            connection.row_factory = sqlite3.Row
            return self._record(
                connection.execute("SELECT * FROM side_effects WHERE operation_key = ?", (key,)).fetchone()
            )

    def claim(self, operation_key: str, effect_name: str, request_hash: str) -> EffectRecord:
        key = _text(operation_key, "operation_key")
        name = _text(effect_name, "effect_name")
        digest = _text(request_hash, "request_hash")
        with sqlite3.connect(self.database, timeout=5.0) as connection:
            connection.row_factory = sqlite3.Row
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute("SELECT * FROM side_effects WHERE operation_key = ?", (key,)).fetchone()
            existing = self._record(row)
            if existing is not None:
                if existing.request_hash != digest or existing.effect_name != name:
                    raise DuplicateSideEffect("operation key conflicts with a different request.")
                if existing.status != "failed":
                    raise DuplicateSideEffect("operation key already has a claimed or completed side effect.")
                connection.execute(
                    "UPDATE side_effects SET status = 'claimed', result_hash = NULL, attempts = attempts + 1, "
                    "updated_at = CURRENT_TIMESTAMP WHERE operation_key = ?",
                    (key,),
                )
            else:
                connection.execute(
                    "INSERT INTO side_effects(operation_key, effect_name, request_hash, status, attempts) "
                    "VALUES (?, ?, ?, 'claimed', 1)",
                    (key, name, digest),
                )
            updated = connection.execute("SELECT * FROM side_effects WHERE operation_key = ?", (key,)).fetchone()
        result = self._record(updated)
        assert result is not None
        return result

    def complete(self, operation_key: str, result_hash: str) -> EffectRecord:
        return self._finish(operation_key, "completed", result_hash)

    def fail(self, operation_key: str, result_hash: str = "failure") -> EffectRecord:
        return self._finish(operation_key, "failed", result_hash)

    def _finish(self, operation_key: str, status: EffectStatus, result_hash: str) -> EffectRecord:
        key = _text(operation_key, "operation_key")
        digest = _text(result_hash, "result_hash")
        with sqlite3.connect(self.database) as connection:
            connection.row_factory = sqlite3.Row
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute("SELECT * FROM side_effects WHERE operation_key = ?", (key,)).fetchone()
            existing = self._record(row)
            if existing is None or existing.status != "claimed":
                raise DuplicateSideEffect("only a claimed side effect can be finalized.")
            connection.execute(
                "UPDATE side_effects SET status = ?, result_hash = ?, updated_at = CURRENT_TIMESTAMP "
                "WHERE operation_key = ?",
                (status, digest, key),
            )
            updated = connection.execute("SELECT * FROM side_effects WHERE operation_key = ?", (key,)).fetchone()
        result = self._record(updated)
        assert result is not None
        return result


# ---------------------------------------------------------------------------
# Authoritative M5 2.0 Durable Intent / Result Ledger (`runtime_actions`)
# ---------------------------------------------------------------------------


def canonical_args_sha256(args: Mapping[str, Any] | None) -> str:
    """Return a deterministic SHA-256 hex digest for structured tool arguments."""
    payload = dict(args) if isinstance(args, Mapping) else {}
    serialized = json.dumps(payload, sort_keys=True, ensure_ascii=False, default=str, separators=(",", ":"))
    return hashlib.sha256(serialized.encode("utf-8", errors="replace")).hexdigest()


def canonical_result_sha256(result: Mapping[str, Any] | None) -> str:
    """Return a deterministic SHA-256 hex digest for tool output + diff material."""
    payload = result if isinstance(result, Mapping) else {}
    material = str(payload.get("output") or "") + "\n" + str(payload.get("diff") or "")
    return hashlib.sha256(material.encode("utf-8", errors="replace")).hexdigest()


def derive_action_id(
    scope_id: str,
    tool_name: str,
    args: Mapping[str, Any] | None,
    *,
    step_id: str | int | None = None,
    call_index: int | None = None,
) -> str:
    """Derive a deterministic stable ``action_id`` for a logical execution slot.

    Re-entering the same ``(scope_id, step_id, call_index, tool_name, args_sha256)``
    slot across retries or crash recovery produces the exact same ``action_id``.
    """
    clean_scope = _text(scope_id or "default", "scope_id")
    clean_tool = _text(tool_name, "tool_name")
    args_digest = canonical_args_sha256(args)
    slot_material = json.dumps(
        {
            "scope": clean_scope,
            "step": "" if step_id is None else str(step_id),
            "index": 0 if call_index is None else int(call_index),
            "tool": clean_tool,
            "args_sha256": args_digest,
        },
        sort_keys=True,
        separators=(",", ":"),
    )
    digest = hashlib.sha256(slot_material.encode("utf-8")).hexdigest()[:32]
    return f"act-{digest}"


def mint_unique_action_id(
    scope_id: str,
    tool_name: str,
    args: Mapping[str, Any] | None,
) -> str:
    """Mint a unique ``action_id`` when a caller invokes an ad-hoc unslotted action."""
    clean_scope = str(scope_id or "adhoc").strip() or "adhoc"
    clean_tool = _text(tool_name, "tool_name")
    nonce = uuid.uuid4().hex
    return derive_action_id(clean_scope, clean_tool, args, step_id=f"adhoc-{nonce}", call_index=0)


def format_attempt_id(action_id: str, attempt: int) -> str:
    """Format the canonical per-attempt identifier for a stable ``action_id``."""
    clean_aid = _text(action_id, "action_id")
    if int(attempt) < 1:
        raise SideEffectError("attempt must be >= 1.")
    return f"{clean_aid}#attempt-{int(attempt)}"


def classify_replay_policy(
    tool_name: str,
    args: Mapping[str, Any] | None = None,
    *,
    action_class: str | None = None,
) -> ReplayPolicy:
    """Classify replay safety by action type (`idempotent`, `reconcilable`, `non_idempotent`).

    - ``idempotent``: managed reads (`read_only` tools and read-only smart blocks)
      whose re-execution cannot duplicate or corrupt state.
    - ``reconcilable``: deterministic target overwrites (`write_file`, and
      `oc_save_doc` / `mcp_bridge__oc_save_doc` when an explicit ``doc_id`` is
      supplied) whose target state can be verified before deciding whether to
      mark committed or retry; still never retried blindly without verification.
    - ``non_idempotent``: shell/Python execution, skill scripts, relative
      substring edits (`edit_file`), `oc_save_doc` without `doc_id` (creates a
      new document UUID per call), subagent delegation, outbound MCP `tools/call`,
      consequential inbound bridge calls, and any unknown tool.
    """
    clean = str(tool_name or "").strip()
    safe_args = args if isinstance(args, Mapping) else {}
    if action_class == "read_only":
        return "idempotent"
    if clean in _LEDGER_READ_ONLY_TOOLS:
        return "idempotent"
    if clean == "ctx_run_block":
        block = str(safe_args.get("block") or "").strip().lower()
        if block in _LEDGER_READ_ONLY_BLOCKS:
            return "idempotent"
        return "non_idempotent"
    if clean == "write_file":
        return "reconcilable"
    if clean in ("oc_save_doc", "mcp_bridge__oc_save_doc"):
        doc_id = str(safe_args.get("doc_id") or "").strip()
        return "reconcilable" if doc_id else "non_idempotent"
    return "non_idempotent"


def is_ambiguous_exception(exc: BaseException) -> bool:
    """Return True when ``exc`` indicates an ambiguous post-dispatch outcome (`uncertain`)."""
    if isinstance(
        exc,
        (
            AmbiguousSideEffectError,
            asyncio.CancelledError,
            TimeoutError,
            ConnectionResetError,
            BrokenPipeError,
        ),
    ):
        return True
    for cls in type(exc).__mro__:
        if cls.__name__ in _AMBIGUOUS_EXC_NAMES:
            return True
    return False


class ActionReconciler(Protocol):
    """Callback probing target state for ``reconcilable`` uncertain actions before replay."""

    def __call__(
        self,
        record: runtime_persistence.ActionRecord,
        tool_name: str,
        args: Mapping[str, Any],
    ) -> ReconciliationVerdict:
        ...


@dataclass(frozen=True, slots=True)
class LedgerBeginOutcome:
    """Decision returned when registering or re-entering an action attempt."""

    proceed: bool
    action_id: str
    attempt: int
    attempt_id: str
    status: LedgerActionStatus
    replay_policy: ReplayPolicy
    record: runtime_persistence.ActionRecord | None = None
    replay_blocked: bool = False
    already_committed: bool = False
    reconciled: bool = False
    reason: str = ""
    error: Exception | None = None


def _sel_row_to_action(row: sqlite3.Row) -> runtime_persistence.ActionRecord:
    return runtime_persistence.ActionRecord(
        action_id=str(row["action_id"]),
        task_id=(str(row["task_id"]) if row["task_id"] is not None else None),
        session_id=str(row["session_id"]),
        epoch=int(row["epoch"]),
        attempt=int(row["attempt"]),
        action_class=str(row["action_class"]),
        replay_policy=str(row["replay_policy"]),
        tool_name=str(row["tool_name"]),
        policy=str(row["policy"]),
        explicit_approval=bool(row["explicit_approval"]),
        args_sha256=str(row["args_sha256"]),
        status=str(row["status"]),
        ok=(bool(row["ok"]) if row["ok"] is not None else None),
        elapsed_ms=(int(row["elapsed_ms"]) if row["elapsed_ms"] is not None else None),
        output_sha256=str(row["output_sha256"]),
        error_code=str(row["error_code"]),
        created_at=float(row["created_at"]),
        updated_at=float(row["updated_at"]),
    )


class DurableActionLedger:
    """Authoritative SQLite ``runtime_actions`` intent, outcome, and replay ledger."""

    def __init__(
        self,
        storage: runtime_persistence.StorageProvider,
        db_path: Path,
        *,
        retry_policy: runtime_persistence.BusyRetryPolicy | None = None,
        reconciler: ActionReconciler | None = None,
        on_action_resolved: Callable[[str], None] | None = None,
    ) -> None:
        self._storage = storage
        self._db_path = Path(db_path)
        self._retry_policy: runtime_persistence.BusyRetryPolicy = (
            retry_policy or runtime_persistence.DEFAULT_BUSY_RETRY_POLICY
        )
        self._reconciler = reconciler
        self._on_action_resolved = on_action_resolved

    @property
    def reconciler(self) -> ActionReconciler | None:
        return self._reconciler

    def get_action(self, action_id: str) -> runtime_persistence.ActionRecord | None:
        aid = _text(action_id, "action_id")

        def _read(conn: sqlite3.Connection) -> runtime_persistence.ActionRecord | None:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            return _sel_row_to_action(row) if row is not None else None

        return runtime_persistence.run_read(
            self._storage, self._db_path, _read, retry_policy=self._retry_policy
        )

    def stage_never_started(
        self,
        action_id: str,
        *,
        tool_name: str,
        args: Mapping[str, Any] | None,
        policy: str,
        action_class: str = "consequential",
        replay_policy: ReplayPolicy | None = None,
        task_id: str | None = None,
        session_id: str = "",
        epoch: int = 0,
        explicit_approval: bool = False,
        now: float | None = None,
    ) -> runtime_persistence.ActionRecord:
        """Persist an explicit ``never_started`` intent record prior to dispatch."""
        aid = _text(action_id, "action_id")[:128]
        tname = _text(tool_name, "tool_name")[:200]
        pol = _text(policy, "policy")[:40]
        digest = canonical_args_sha256(args)
        eff_class = action_class if action_class in runtime_persistence.ACTION_CLASSES else "consequential"
        eff_replay = replay_policy or classify_replay_policy(tname, args, action_class=eff_class)
        if eff_replay not in runtime_persistence.REPLAY_POLICIES:
            raise SideEffectError(f"Unsupported replay_policy: {eff_replay!r}")
        tid = _text(task_id, "task_id")[:128] if task_id else None
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.ActionRecord:
            conn.row_factory = sqlite3.Row
            existing = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            if existing is not None:
                rec = _sel_row_to_action(existing)
                if rec.tool_name != tname or rec.args_sha256 != digest:
                    raise ActionIdentityConflictError(
                        f"Action `{aid}` conflicts with existing `{rec.tool_name}` intent digest."
                    )
                return rec
            conn.execute(
                """
                INSERT INTO runtime_actions (
                    action_id, task_id, session_id, epoch, attempt, action_class,
                    replay_policy, tool_name, policy, explicit_approval, args_sha256,
                    status, created_at, updated_at
                ) VALUES (?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, 'never_started', ?, ?)
                """,
                (
                    aid,
                    tid,
                    str(session_id)[:128],
                    max(0, int(epoch)),
                    eff_class,
                    eff_replay,
                    tname,
                    pol,
                    int(bool(explicit_approval)),
                    digest,
                    ts,
                    ts,
                ),
            )
            row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            assert row is not None
            return _sel_row_to_action(row)

        return runtime_persistence.run_write_transaction(
            self._storage, self._db_path, _tx, retry_policy=self._retry_policy
        )

    def begin(
        self,
        *,
        action_id: str | None,
        step_id: str | int | None = None,
        call_index: int | None = None,
        tool_name: str,
        args: Mapping[str, Any] | None,
        policy: str,
        action_class: str,
        replay_policy: str | None = None,
        allowed: bool,
        explicit_approval: bool,
        session_id: str,
        task_id: str | None = None,
        epoch: int | None = None,
        worker_id: str | None = None,
        now: float | None = None,
    ) -> LedgerBeginOutcome:
        """Atomically evaluate replay safety and commit durable ``in_flight`` (or ``denied``) intent."""
        tname = _text(tool_name, "tool_name")[:200]
        pol = _text(policy or "standard", "policy")[:40]
        safe_args = args if isinstance(args, Mapping) else {}
        digest = canonical_args_sha256(safe_args)
        eff_class = action_class if action_class in runtime_persistence.ACTION_CLASSES else "consequential"
        resolved_replay: ReplayPolicy = (
            replay_policy  # type: ignore[assignment]
            if replay_policy in runtime_persistence.REPLAY_POLICIES
            else classify_replay_policy(tname, safe_args, action_class=eff_class)
        )
        scope_key = str(task_id or session_id or "default")
        if action_id is not None and str(action_id).strip():
            aid = _text(str(action_id), "action_id")[:128]
        elif step_id is not None or call_index is not None:
            aid = derive_action_id(scope_key, tname, safe_args, step_id=step_id, call_index=call_index)
        else:
            aid = mint_unique_action_id(scope_key, tname, safe_args)

        clean_tid = _text(task_id, "task_id")[:128] if task_id else None
        clean_epoch = max(0, int(epoch or 0))
        clean_wid = str(worker_id).strip()[:128] if worker_id and str(worker_id).strip() else None
        ts = time.time() if now is None else float(now)

        # Optional pre-transaction reconciliation probe for `reconcilable` actions in `uncertain` state
        # (performed strictly outside `BEGIN IMMEDIATE` so filesystem/read checks hold no write lock).
        reconcile_verdict: ReconciliationVerdict = "unresolved"
        if allowed and resolved_replay == "reconcilable" and self._reconciler is not None:
            prior = self.get_action(aid)
            if prior is not None and prior.tool_name == tname and prior.args_sha256 == digest:
                if prior.status in ("uncertain", "in_flight") or (
                    prior.status == "committed" and prior.error_code == "pre_takeover_verified_committed"
                ):
                    try:
                        reconcile_verdict = self._reconciler(prior, tname, safe_args)
                    except Exception:
                        reconcile_verdict = "unresolved"

        def _tx(conn: sqlite3.Connection) -> LedgerBeginOutcome:
            conn.row_factory = sqlite3.Row
            existing_row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            existing = _sel_row_to_action(existing_row) if existing_row is not None else None

            if existing is not None and (existing.tool_name != tname or existing.args_sha256 != digest):
                err = ActionIdentityConflictError(
                    f"Action `{aid}` already bound to `{existing.tool_name}` with a different argument digest."
                )
                return LedgerBeginOutcome(
                    proceed=False,
                    action_id=aid,
                    attempt=existing.attempt,
                    attempt_id=format_attempt_id(aid, existing.attempt),
                    status=existing.status,  # type: ignore[arg-type]
                    replay_policy=resolved_replay,
                    record=existing,
                    replay_blocked=True,
                    reason=str(err),
                    error=err,
                )

            effective_tid = clean_tid
            missing_tid_code = ""
            effective_allowed = allowed
            tx_fence_reason = ""
            tx_fence_error: Exception | None = None
            if effective_tid is not None:
                t_row = conn.execute(
                    "SELECT state, current_epoch FROM runtime_tasks WHERE task_id = ?",
                    (effective_tid,),
                ).fetchone()
                if t_row is None:
                    if not effective_allowed:
                        effective_tid = None
                        missing_tid_code = "unknown_task_id"
                    else:
                        raise KeyError(f"Runtime task {effective_tid!r} does not exist.")
                elif effective_allowed:
                    cur_ep = int(t_row["current_epoch"])
                    if cur_ep > 0:
                        ep_row = conn.execute(
                            "SELECT worker_id, status, lease_expires_at FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                            (effective_tid, clean_epoch),
                        ).fetchone()
                        if clean_epoch != cur_ep or ep_row is None:
                            effective_allowed = False
                            missing_tid_code = "stale_epoch_fenced"
                            tx_fence_reason = (
                                f"Denied: Stale or mismatched task epoch {clean_epoch} for task `{effective_tid}` "
                                f"(current epoch: {cur_ep})."
                            )
                            tx_fence_error = runtime_persistence.StaleEpochError(tx_fence_reason)
                        elif str(ep_row["status"]) != "active":
                            effective_allowed = False
                            missing_tid_code = "inactive_epoch_fenced"
                            tx_fence_reason = (
                                f"Denied: Task `{effective_tid}` epoch {clean_epoch} is not active "
                                f"(status: `{ep_row['status']}`)."
                            )
                            tx_fence_error = runtime_persistence.StaleEpochError(tx_fence_reason)
                        elif float(ep_row["lease_expires_at"]) <= ts:
                            conn.execute(
                                """
                                UPDATE runtime_task_epochs
                                SET status = 'expired', fenced_at = ?, fence_reason = 'lease_expired_at_admission'
                                WHERE task_id = ? AND epoch = ? AND status = 'active'
                                """,
                                (ts, effective_tid, clean_epoch),
                            )
                            effective_allowed = False
                            missing_tid_code = "lease_expired_fenced"
                            tx_fence_reason = f"Denied: Task `{effective_tid}` epoch {clean_epoch} lease has expired."
                            tx_fence_error = runtime_persistence.LeaseExpiredError(tx_fence_reason)
                        elif clean_wid is None or clean_wid != str(ep_row["worker_id"]):
                            effective_allowed = False
                            missing_tid_code = "worker_mismatch_fenced"
                            tx_fence_reason = (
                                f"Denied: Worker `{clean_wid or ''}` does not own task `{effective_tid}` "
                                f"epoch {clean_epoch} (owned by `{ep_row['worker_id']}`)."
                            )
                            tx_fence_error = runtime_persistence.LeaseOwnershipConflictError(tx_fence_reason)
                    if effective_allowed and eff_class != "read_only":
                        unresolved_rows = conn.execute(
                            """
                            SELECT action_id FROM runtime_actions
                            WHERE task_id = ? AND action_id != ? AND action_class != 'read_only'
                              AND (status = 'uncertain' OR (status = 'in_flight' AND epoch < ?))
                            ORDER BY created_at ASC LIMIT 3
                            """,
                            (effective_tid, aid, clean_epoch),
                        ).fetchall()
                        if unresolved_rows:
                            unres_ids = tuple(str(r["action_id"]) for r in unresolved_rows)
                            effective_allowed = False
                            missing_tid_code = "unresolved_effects_hold"
                            tx_fence_reason = (
                                f"Denied: Consequential `{eff_class}` action `{tname}` blocked because "
                                f"task `{effective_tid}` has unresolved side effects ({', '.join(unres_ids)})."
                            )
                            tx_fence_error = UnresolvedEffectsHoldError(
                                tx_fence_reason,
                                task_id=effective_tid,
                                epoch=clean_epoch,
                                unresolved_action_ids=unres_ids,
                            )

            if not effective_allowed:
                if existing is None:
                    conn.execute(
                        """
                        INSERT INTO runtime_actions (
                            action_id, task_id, session_id, epoch, attempt, action_class,
                            replay_policy, tool_name, policy, explicit_approval, args_sha256,
                            status, ok, elapsed_ms, error_code, created_at, updated_at
                        ) VALUES (?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, 'denied', 0, 1, ?, ?, ?)
                        """,
                        (
                            aid,
                            effective_tid,
                            str(session_id)[:128],
                            clean_epoch,
                            eff_class,
                            resolved_replay,
                            tname,
                            pol,
                            int(bool(explicit_approval)),
                            digest,
                            missing_tid_code or "admission_denied",
                            ts,
                            ts,
                        ),
                    )
                    denied_row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                    assert denied_row is not None
                    denied_rec = _sel_row_to_action(denied_row)
                    return LedgerBeginOutcome(
                        proceed=False,
                        action_id=aid,
                        attempt=denied_rec.attempt,
                        attempt_id=format_attempt_id(aid, denied_rec.attempt),
                        status="denied",
                        replay_policy=resolved_replay,
                        record=denied_rec,
                        replay_blocked=(tx_fence_error is not None),
                        reason=tx_fence_reason,
                        error=tx_fence_error,
                    )
                if existing.status in ("never_started", "denied", "failed"):
                    next_att = existing.attempt + 1
                    conn.execute(
                        """
                        UPDATE runtime_actions
                        SET attempt = ?, epoch = ?, policy = ?, explicit_approval = ?,
                            status = 'denied', ok = 0, elapsed_ms = 1,
                            error_code = ?, updated_at = ?
                        WHERE action_id = ?
                        """,
                        (
                            next_att,
                            clean_epoch,
                            pol,
                            int(bool(explicit_approval)),
                            missing_tid_code or "admission_denied",
                            ts,
                            aid,
                        ),
                    )
                    denied_row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                    assert denied_row is not None
                    denied_rec = _sel_row_to_action(denied_row)
                    return LedgerBeginOutcome(
                        proceed=False,
                        action_id=aid,
                        attempt=denied_rec.attempt,
                        attempt_id=format_attempt_id(aid, denied_rec.attempt),
                        status="denied",
                        replay_policy=resolved_replay,
                        record=denied_rec,
                        replay_blocked=(tx_fence_error is not None),
                        reason=tx_fence_reason,
                        error=tx_fence_error,
                    )
                # Preserve existing `committed`, `in_flight`, or `uncertain` record without clobbering it.
                return LedgerBeginOutcome(
                    proceed=False,
                    action_id=aid,
                    attempt=existing.attempt,
                    attempt_id=format_attempt_id(aid, existing.attempt),
                    status=existing.status,  # type: ignore[arg-type]
                    replay_policy=resolved_replay,
                    record=existing,
                    replay_blocked=(tx_fence_error is not None),
                    reason=tx_fence_reason,
                    error=tx_fence_error,
                )

            # `allowed` is True: commit durable `in_flight` intent or enforce replay classification!
            if existing is None:
                conn.execute(
                    """
                    INSERT INTO runtime_actions (
                        action_id, task_id, session_id, epoch, attempt, action_class,
                        replay_policy, tool_name, policy, explicit_approval, args_sha256,
                        status, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, 'in_flight', ?, ?)
                    """,
                    (
                        aid,
                        effective_tid,
                        str(session_id)[:128],
                        clean_epoch,
                        eff_class,
                        resolved_replay,
                        tname,
                        pol,
                        int(bool(explicit_approval)),
                        digest,
                        ts,
                        ts,
                    ),
                )
                ins_row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                assert ins_row is not None
                ins_rec = _sel_row_to_action(ins_row)
                return LedgerBeginOutcome(
                    proceed=True,
                    action_id=aid,
                    attempt=1,
                    attempt_id=format_attempt_id(aid, 1),
                    status="in_flight",
                    replay_policy=resolved_replay,
                    record=ins_rec,
                )

            # Existing record found on replay of `action_id`:
            if existing.status == "committed":
                if resolved_replay == "idempotent":
                    next_att = existing.attempt + 1
                    conn.execute(
                        """
                        UPDATE runtime_actions
                        SET attempt = ?, epoch = ?, policy = ?, explicit_approval = ?,
                            status = 'in_flight', ok = NULL, elapsed_ms = NULL,
                            output_sha256 = '', error_code = '', updated_at = ?
                        WHERE action_id = ?
                        """,
                        (next_att, clean_epoch, pol, int(bool(explicit_approval)), ts, aid),
                    )
                    upd = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                    assert upd is not None
                    return LedgerBeginOutcome(
                        proceed=True,
                        action_id=aid,
                        attempt=next_att,
                        attempt_id=format_attempt_id(aid, next_att),
                        status="in_flight",
                        replay_policy=resolved_replay,
                        record=_sel_row_to_action(upd),
                    )
                if (
                    resolved_replay == "reconcilable"
                    and existing.error_code == "pre_takeover_verified_committed"
                    and reconcile_verdict == "verified_committed"
                ):
                    conn.execute(
                        """
                        UPDATE runtime_actions
                        SET epoch = ?, error_code = '', updated_at = ?
                        WHERE action_id = ?
                        """,
                        (clean_epoch, ts, aid),
                    )
                    rec_upd = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                    assert rec_upd is not None
                    return LedgerBeginOutcome(
                        proceed=False,
                        action_id=aid,
                        attempt=existing.attempt,
                        attempt_id=format_attempt_id(aid, existing.attempt),
                        status="committed",
                        replay_policy=resolved_replay,
                        record=_sel_row_to_action(rec_upd),
                        already_committed=True,
                        reconciled=True,
                        reason=(
                            f"Reconciled `{tname}` (`{aid}`): target state already matches intent; "
                            "skipping duplicate side effect."
                        ),
                    )
                err_c = CommittedActionReplayError(
                    f"Replay blocked: consequential action `{aid}` (`{tname}`) is already `committed` "
                    f"(attempt {existing.attempt}) and will not be executed again."
                )
                return LedgerBeginOutcome(
                    proceed=False,
                    action_id=aid,
                    attempt=existing.attempt,
                    attempt_id=format_attempt_id(aid, existing.attempt),
                    status="committed",
                    replay_policy=resolved_replay,
                    record=existing,
                    replay_blocked=True,
                    already_committed=True,
                    reason=str(err_c),
                    error=err_c,
                )

            if existing.status in ("never_started", "denied", "failed"):
                next_att = existing.attempt + 1
                conn.execute(
                    """
                    UPDATE runtime_actions
                    SET attempt = ?, task_id = COALESCE(?, task_id), epoch = ?, policy = ?,
                        explicit_approval = ?, status = 'in_flight', ok = NULL,
                        elapsed_ms = NULL, output_sha256 = '', error_code = '', updated_at = ?
                    WHERE action_id = ?
                    """,
                    (next_att, effective_tid, clean_epoch, pol, int(bool(explicit_approval)), ts, aid),
                )
                upd = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                assert upd is not None
                return LedgerBeginOutcome(
                    proceed=True,
                    action_id=aid,
                    attempt=next_att,
                    attempt_id=format_attempt_id(aid, next_att),
                    status="in_flight",
                    replay_policy=resolved_replay,
                    record=_sel_row_to_action(upd),
                )

            # `existing.status` is `'in_flight'` (missing result!) or `'uncertain'`:
            # Missing result on an `'in_flight'` record is NEVER treated as `'failed'` —
            # transition orphaned `'in_flight'` to `'uncertain'` before applying replay rules.
            cur_record = existing
            if existing.status == "in_flight":
                conn.execute(
                    """
                    UPDATE runtime_actions
                    SET status = 'uncertain', ok = NULL,
                        error_code = CASE WHEN error_code = '' THEN 'missing_result' ELSE error_code END,
                        updated_at = ?
                    WHERE action_id = ? AND status = 'in_flight'
                    """,
                    (ts, aid),
                )
                re_row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                assert re_row is not None
                cur_record = _sel_row_to_action(re_row)

            # Now `cur_record.status == 'uncertain'`: apply action-type replay classification!
            if resolved_replay == "idempotent":
                next_att = cur_record.attempt + 1
                conn.execute(
                    """
                    UPDATE runtime_actions
                    SET attempt = ?, epoch = ?, policy = ?, explicit_approval = ?,
                        status = 'in_flight', ok = NULL, elapsed_ms = NULL,
                        output_sha256 = '', error_code = '', updated_at = ?
                    WHERE action_id = ?
                    """,
                    (next_att, clean_epoch, pol, int(bool(explicit_approval)), ts, aid),
                )
                upd = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                assert upd is not None
                return LedgerBeginOutcome(
                    proceed=True,
                    action_id=aid,
                    attempt=next_att,
                    attempt_id=format_attempt_id(aid, next_att),
                    status="in_flight",
                    replay_policy=resolved_replay,
                    record=_sel_row_to_action(upd),
                )

            if resolved_replay == "reconcilable":
                if reconcile_verdict == "verified_committed":
                    conn.execute(
                        """
                        UPDATE runtime_actions
                        SET status = 'committed', ok = 1, error_code = 'reconciled_committed', updated_at = ?
                        WHERE action_id = ? AND status = 'uncertain'
                        """,
                        (ts, aid),
                    )
                    rec_row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                    assert rec_row is not None
                    rec_obj = _sel_row_to_action(rec_row)
                    return LedgerBeginOutcome(
                        proceed=False,
                        action_id=aid,
                        attempt=rec_obj.attempt,
                        attempt_id=format_attempt_id(aid, rec_obj.attempt),
                        status="committed",
                        replay_policy=resolved_replay,
                        record=rec_obj,
                        already_committed=True,
                        reconciled=True,
                        reason=f"Reconciled `{tname}` (`{aid}`): target state already reflects the committed effect.",
                    )
                if reconcile_verdict == "verified_not_applied":
                    next_att = cur_record.attempt + 1
                    conn.execute(
                        """
                        UPDATE runtime_actions
                        SET attempt = ?, epoch = ?, policy = ?, explicit_approval = ?,
                            status = 'in_flight', ok = NULL, elapsed_ms = NULL,
                            output_sha256 = '', error_code = '', updated_at = ?
                        WHERE action_id = ?
                        """,
                        (next_att, clean_epoch, pol, int(bool(explicit_approval)), ts, aid),
                    )
                    upd = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
                    assert upd is not None
                    return LedgerBeginOutcome(
                        proceed=True,
                        action_id=aid,
                        attempt=next_att,
                        attempt_id=format_attempt_id(aid, next_att),
                        status="in_flight",
                        replay_policy=resolved_replay,
                        record=_sel_row_to_action(upd),
                        reconciled=True,
                    )

            err_u = UncertainActionReplayError(
                f"Replay blocked: `{resolved_replay}` action `{aid}` (`{tname}`, attempt {cur_record.attempt}) "
                f"is in `uncertain` state ({cur_record.error_code or 'unreconciled'}) and cannot be retried blindly."
            )
            return LedgerBeginOutcome(
                proceed=False,
                action_id=aid,
                attempt=cur_record.attempt,
                attempt_id=format_attempt_id(aid, cur_record.attempt),
                status="uncertain",
                replay_policy=resolved_replay,
                record=cur_record,
                replay_blocked=True,
                reason=str(err_u),
                error=err_u,
            )

        outcome = runtime_persistence.run_write_transaction(
            self._storage, self._db_path, _tx, retry_policy=self._retry_policy
        )
        if outcome.reconciled and self._on_action_resolved is not None:
            try:
                self._on_action_resolved(outcome.action_id)
            except Exception:
                pass
        return outcome

    def mark_never_started(
        self,
        action_id: str,
        *,
        error_code: str = "pre_execute_guard_blocked",
        now: float | None = None,
    ) -> runtime_persistence.ActionRecord:
        """Transition a pre-execution blocked attempt back to ``never_started``."""
        aid = _text(action_id, "action_id")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.ActionRecord:
            conn.row_factory = sqlite3.Row
            conn.execute(
                """
                UPDATE runtime_actions
                SET status = 'never_started', ok = NULL, elapsed_ms = 0,
                    output_sha256 = '', error_code = ?, updated_at = ?
                WHERE action_id = ?
                """,
                (str(error_code)[:120], ts, aid),
            )
            row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            if row is None:
                raise KeyError(f"Runtime action {aid!r} does not exist.")
            return _sel_row_to_action(row)

        return runtime_persistence.run_write_transaction(
            self._storage, self._db_path, _tx, retry_policy=self._retry_policy
        )

    def complete(
        self,
        action_id: str,
        result: Mapping[str, Any],
        elapsed_ms: int,
        *,
        now: float | None = None,
    ) -> runtime_persistence.ActionRecord:
        """Durably finalize a completed, deterministically failed, or uncertain tool result."""
        aid = _text(action_id, "action_id")
        out_digest = canonical_result_sha256(result)
        clean_ms = max(0, int(elapsed_ms))
        ts = time.time() if now is None else float(now)

        if bool(result.get("uncertain")):
            final_status: LedgerActionStatus = "uncertain"
            ok_val: int | None = None
            err_code = str(result.get("error_code") or "ambiguous_outcome")[:120]
        elif bool(result.get("ok")):
            final_status = "committed"
            ok_val = 1
            err_code = ""
        else:
            final_status = "failed"
            ok_val = 0
            err_code = str(result.get("error_code") or "tool_returned_false")[:120]

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.ActionRecord:
            conn.row_factory = sqlite3.Row
            conn.execute(
                """
                UPDATE runtime_actions
                SET status = ?, ok = ?, elapsed_ms = ?, output_sha256 = ?, error_code = ?, updated_at = ?
                WHERE action_id = ?
                """,
                (final_status, ok_val, clean_ms, out_digest, err_code, ts, aid),
            )
            row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            if row is None:
                raise KeyError(f"Runtime action {aid!r} does not exist.")
            return _sel_row_to_action(row)

        return runtime_persistence.run_write_transaction(
            self._storage, self._db_path, _tx, retry_policy=self._retry_policy
        )

    def record_exception(
        self,
        action_id: str,
        exc: BaseException,
        elapsed_ms: int,
        *,
        now: float | None = None,
    ) -> runtime_persistence.ActionRecord:
        """Finalize an exception raised during execution as ``uncertain`` (if ambiguous) or ``failed``."""
        aid = _text(action_id, "action_id")
        ambiguous = is_ambiguous_exception(exc)
        final_status: LedgerActionStatus = "uncertain" if ambiguous else "failed"
        ok_val: int | None = None if ambiguous else 0
        err_code = type(exc).__name__[:120]
        out_digest = canonical_result_sha256({"output": str(exc), "diff": ""})
        clean_ms = max(0, int(elapsed_ms))
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.ActionRecord:
            conn.row_factory = sqlite3.Row
            conn.execute(
                """
                UPDATE runtime_actions
                SET status = ?, ok = ?, elapsed_ms = ?, output_sha256 = ?, error_code = ?, updated_at = ?
                WHERE action_id = ?
                """,
                (final_status, ok_val, clean_ms, out_digest, err_code, ts, aid),
            )
            row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            if row is None:
                raise KeyError(f"Runtime action {aid!r} does not exist.")
            return _sel_row_to_action(row)

        return runtime_persistence.run_write_transaction(
            self._storage, self._db_path, _tx, retry_policy=self._retry_policy
        )

    def reconcile_missing_results(
        self,
        *,
        task_id: str | None = None,
        session_id: str | None = None,
        error_code: str = "missing_result",
        now: float | None = None,
    ) -> list[runtime_persistence.ActionRecord]:
        """Transition orphaned ``in_flight`` actions with missing results to ``uncertain`` (never ``failed``)."""
        ts = time.time() if now is None else float(now)
        code = str(error_code or "missing_result")[:120]

        def _tx(conn: sqlite3.Connection) -> list[runtime_persistence.ActionRecord]:
            conn.row_factory = sqlite3.Row
            clauses = ["status = 'in_flight'"]
            params: list[Any] = []
            if task_id is not None:
                clauses.append("task_id = ?")
                params.append(_text(task_id, "task_id"))
            if session_id is not None:
                clauses.append("session_id = ?")
                params.append(_text(session_id, "session_id"))
            where_sql = " AND ".join(clauses)
            rows = conn.execute(
                f"SELECT action_id FROM runtime_actions WHERE {where_sql} ORDER BY created_at ASC",
                tuple(params),
            ).fetchall()
            if not rows:
                return []
            ids = [str(r["action_id"]) for r in rows]
            placeholders = ",".join("?" for _ in ids)
            conn.execute(
                f"""
                UPDATE runtime_actions
                SET status = 'uncertain', ok = NULL, error_code = ?, updated_at = ?
                WHERE action_id IN ({placeholders}) AND status = 'in_flight'
                """,
                (code, ts, *ids),
            )
            updated_rows = conn.execute(
                f"SELECT * FROM runtime_actions WHERE action_id IN ({placeholders}) ORDER BY created_at ASC",
                tuple(ids),
            ).fetchall()
            return [_sel_row_to_action(r) for r in updated_rows]

        return runtime_persistence.run_write_transaction(
            self._storage, self._db_path, _tx, retry_policy=self._retry_policy
        )

    def resolve_uncertain_action(
        self,
        action_id: str,
        *,
        resolution: Literal["verified_committed", "verified_not_applied"],
        reason: str = "",
        now: float | None = None,
    ) -> runtime_persistence.ActionRecord:
        """Explicitly reconcile an ``uncertain`` action after verification."""
        aid = _text(action_id, "action_id")
        if resolution not in ("verified_committed", "verified_not_applied"):
            raise SideEffectError(f"Unsupported uncertain resolution: {resolution!r}")
        ts = time.time() if now is None else float(now)
        target_status = "committed" if resolution == "verified_committed" else "never_started"
        ok_val: int | None = 1 if resolution == "verified_committed" else None
        code = str(reason or resolution)[:120]

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.ActionRecord:
            conn.row_factory = sqlite3.Row
            cur = conn.execute("SELECT status FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            if cur is None:
                raise KeyError(f"Runtime action {aid!r} does not exist.")
            if str(cur["status"]) not in ("uncertain", "in_flight"):
                raise SideEffectError(
                    f"Only `uncertain` or orphaned `in_flight` actions can be reconciled (got `{cur['status']}`)."
                )
            conn.execute(
                """
                UPDATE runtime_actions
                SET status = ?, ok = ?, error_code = ?, updated_at = ?
                WHERE action_id = ?
                """,
                (target_status, ok_val, code, ts, aid),
            )
            row = conn.execute("SELECT * FROM runtime_actions WHERE action_id = ?", (aid,)).fetchone()
            assert row is not None
            return _sel_row_to_action(row)

        rec_resolved = runtime_persistence.run_write_transaction(
            self._storage, self._db_path, _tx, retry_policy=self._retry_policy
        )
        if self._on_action_resolved is not None:
            try:
                self._on_action_resolved(aid)
            except Exception:
                pass
        return rec_resolved

    def list_task_actions(
        self,
        task_id: str,
        *,
        statuses: Iterable[str] | None = None,
    ) -> list[runtime_persistence.ActionRecord]:
        """Return durable ``runtime_actions`` rows recorded against ``task_id``."""
        tid = _text(task_id, "task_id")
        status_list = [str(s) for s in statuses] if statuses is not None else []

        def _read(conn: sqlite3.Connection) -> list[runtime_persistence.ActionRecord]:
            conn.row_factory = sqlite3.Row
            if status_list:
                placeholders = ",".join("?" for _ in status_list)
                rows = conn.execute(
                    f"""
                    SELECT * FROM runtime_actions
                    WHERE task_id = ? AND status IN ({placeholders})
                    ORDER BY created_at ASC, action_id ASC
                    """,
                    (tid, *status_list),
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT * FROM runtime_actions WHERE task_id = ? ORDER BY created_at ASC, action_id ASC",
                    (tid,),
                ).fetchall()
            return [_sel_row_to_action(r) for r in rows]

        return runtime_persistence.run_read(
            self._storage, self._db_path, _read, retry_policy=self._retry_policy
        )

    def list_unresolved_consequential_actions(
        self,
        task_id: str,
        *,
        before_epoch: int | None = None,
    ) -> list[runtime_persistence.ActionRecord]:
        """Return consequential actions on ``task_id`` that are ``uncertain`` or orphaned ``in_flight``."""
        tid = _text(task_id, "task_id")

        def _read(conn: sqlite3.Connection) -> list[runtime_persistence.ActionRecord]:
            conn.row_factory = sqlite3.Row
            if before_epoch is None:
                rows = conn.execute(
                    """
                    SELECT * FROM runtime_actions
                    WHERE task_id = ? AND action_class != 'read_only'
                      AND status IN ('uncertain', 'in_flight')
                    ORDER BY created_at ASC, action_id ASC
                    """,
                    (tid,),
                ).fetchall()
            else:
                rows = conn.execute(
                    """
                    SELECT * FROM runtime_actions
                    WHERE task_id = ? AND action_class != 'read_only'
                      AND (status = 'uncertain' OR (status = 'in_flight' AND epoch < ?))
                    ORDER BY created_at ASC, action_id ASC
                    """,
                    (tid, int(before_epoch)),
                ).fetchall()
            return [_sel_row_to_action(r) for r in rows]

        return runtime_persistence.run_read(
            self._storage, self._db_path, _read, retry_policy=self._retry_policy
        )


@dataclass(frozen=True, slots=True)
class PreTakeoverReconciliationReport:
    """Summary of pre-takeover reconciliation for orphaned in-flight & uncertain effects (M5-P1-04)."""

    task_id: str
    swept_in_flight_ids: tuple[str, ...] = ()
    reconciled_committed_ids: tuple[str, ...] = ()
    reconciled_not_applied_ids: tuple[str, ...] = ()
    unresolved_action_ids: tuple[str, ...] = ()

    @property
    def has_unresolved_effects(self) -> bool:
        return bool(self.unresolved_action_ids)


@dataclass(frozen=True, slots=True)
class LeaseClaimOutcome:
    """Result of single-owner worker lease claim + pre-takeover reconciliation (M5-P1-04)."""

    task: runtime_persistence.TaskRecord
    epoch_record: runtime_persistence.TaskEpochRecord
    superseded_epochs: tuple[runtime_persistence.TaskEpochRecord, ...]
    reconciliation: PreTakeoverReconciliationReport


class WorkerLeaseCoordinator:
    """Coordinates single-owner worker leases, durable epoch fencing, and safe takeover (M5-P1-04).

    Guarantees:
    1. Only one unexpired active worker lease can own a task at a time; concurrent
       claimants fail with :class:`runtime_persistence.LeaseOwnershipConflictError`.
    2. Lease expiry marks the expired epoch ``expired`` without releasing or
       clearing unresolved ``in_flight`` / ``uncertain`` actions.
    3. Before replacement execution enters ``running`` in a new monotonic epoch,
       all orphaned ``in_flight`` actions on ``task_id`` are swept to ``uncertain``,
       any ``reconcilable`` actions with supplied candidate args are probed outside
       SQLite write locks, and if any consequential action remains ``uncertain``,
       the task is held in ``blocked`` and :class:`UnresolvedEffectsHoldError` is raised.
    """

    def __init__(
        self,
        store: runtime_persistence.RuntimePersistenceStore,
        ledger: DurableActionLedger,
        *,
        on_epochs_fenced: Callable[[str, Sequence[runtime_persistence.TaskEpochRecord], str], None] | None = None,
        resumption_blocker: Callable[[str, str], Sequence[str]] | None = None,
    ) -> None:
        self._store = store
        self._ledger = ledger
        self._on_epochs_fenced = on_epochs_fenced
        self._resumption_blocker = resumption_blocker

    @property
    def store(self) -> runtime_persistence.RuntimePersistenceStore:
        return self._store

    @property
    def ledger(self) -> DurableActionLedger:
        return self._ledger

    def reconcile_task_effects(
        self,
        task_id: str,
        *,
        known_action_args: Mapping[str, Mapping[str, Any]] | None = None,
        error_code: str = "lease_takeover_in_flight",
        now: float | None = None,
    ) -> PreTakeoverReconciliationReport:
        """Sweep orphaned ``in_flight`` rows to ``uncertain`` and probe reconcilable effects."""
        tid = _text(task_id, "task_id")
        ts = time.time() if now is None else float(now)

        swept = self._ledger.reconcile_missing_results(
            task_id=tid,
            error_code=error_code,
            now=ts,
        )
        swept_ids = tuple(r.action_id for r in swept)

        reconciled_committed: list[str] = []
        reconciled_not_applied: list[str] = []
        reconciler = self._ledger.reconciler
        if reconciler is not None and known_action_args:
            uncertain_rows = self._ledger.list_task_actions(tid, statuses=("uncertain",))
            for rec in uncertain_rows:
                if rec.replay_policy != "reconcilable":
                    continue
                cand_args = known_action_args.get(rec.action_id)
                if cand_args is None or canonical_args_sha256(cand_args) != rec.args_sha256:
                    continue
                try:
                    verdict = reconciler(rec, rec.tool_name, cand_args)
                except Exception:
                    verdict = "unresolved"
                if verdict == "verified_committed":
                    self._ledger.resolve_uncertain_action(
                        rec.action_id,
                        resolution="verified_committed",
                        reason="pre_takeover_verified_committed",
                        now=ts,
                    )
                    reconciled_committed.append(rec.action_id)
                elif verdict == "verified_not_applied":
                    self._ledger.resolve_uncertain_action(
                        rec.action_id,
                        resolution="verified_not_applied",
                        reason="pre_takeover_verified_not_applied",
                        now=ts,
                    )
                    reconciled_not_applied.append(rec.action_id)

        unresolved = self._ledger.list_unresolved_consequential_actions(tid)
        return PreTakeoverReconciliationReport(
            task_id=tid,
            swept_in_flight_ids=swept_ids,
            reconciled_committed_ids=tuple(reconciled_committed),
            reconciled_not_applied_ids=tuple(reconciled_not_applied),
            unresolved_action_ids=tuple(r.action_id for r in unresolved),
        )

    def acquire_or_takeover(
        self,
        task_id: str,
        worker_id: str,
        *,
        session_id: str = "",
        title: str = "",
        workspace_dir: str = "",
        policy: str = "standard",
        lease_ttl_s: float = 30.0,
        force_takeover: bool = False,
        fence_reason: str = "lease_takeover",
        known_action_args: Mapping[str, Mapping[str, Any]] | None = None,
        now: float | None = None,
    ) -> LeaseClaimOutcome:
        """Atomically claim a worker lease, fence prior epochs, and reconcile before ``running``."""
        tid = _text(task_id, "task_id")
        wid = _text(worker_id, "worker_id")
        ts = time.time() if now is None else float(now)

        self._store.ensure_task(
            tid,
            session_id=session_id or tid,
            title=title,
            workspace_dir=workspace_dir,
            policy=policy,
            now=ts,
        )

        # Claim the monotonic epoch FIRST so:
        # 1) live unexpired owners reject concurrent callers before touching their in-flight actions;
        # 2) expired/superseded owners are fenced before pre-takeover reconciliation begins.
        epoch_rec, superseded = self._store.acquire_worker_lease(
            tid,
            wid,
            lease_ttl_s=lease_ttl_s,
            force_takeover=force_takeover,
            fence_reason=fence_reason,
            now=ts,
        )
        if superseded and self._on_epochs_fenced is not None:
            try:
                self._on_epochs_fenced(tid, superseded, fence_reason)
            except Exception:
                pass

        report = self.reconcile_task_effects(
            tid,
            known_action_args=known_action_args,
            now=ts,
        )
        extra_blockers: tuple[str, ...] = ()
        if self._resumption_blocker is not None:
            try:
                extra_blockers = tuple(str(x) for x in self._resumption_blocker(tid, workspace_dir) if str(x))
            except Exception:
                extra_blockers = ()
        if report.has_unresolved_effects or extra_blockers:
            combined_unresolved = tuple(dict.fromkeys((*report.unresolved_action_ids, *extra_blockers)))
            self._store.release_epoch(
                tid,
                epoch_rec.epoch,
                wid,
                next_state="blocked",
                reason="unresolved_effects_hold",
                now=ts,
            )
            sample = ", ".join(combined_unresolved[:3])
            raise UnresolvedEffectsHoldError(
                f"Replacement execution on task `{tid}` held (`blocked`) at epoch {epoch_rec.epoch}: "
                f"unresolved side effects ({sample}) must be reconciled before resuming.",
                task_id=tid,
                epoch=epoch_rec.epoch,
                unresolved_action_ids=combined_unresolved,
            )

        transition_reason = (
            "lease_takeover_reconciled" if superseded else "lease_acquired"
        )
        updated_task, _ = self._store.record_transition(
            tid,
            to_state="running",
            epoch=epoch_rec.epoch,
            reason=transition_reason,
            now=ts,
        )
        return LeaseClaimOutcome(
            task=updated_task,
            epoch_record=epoch_rec,
            superseded_epochs=tuple(superseded),
            reconciliation=report,
        )

    def heartbeat(
        self,
        task_id: str,
        epoch: int,
        worker_id: str,
        *,
        lease_ttl_s: float = 30.0,
        now: float | None = None,
    ) -> runtime_persistence.TaskEpochRecord:
        return self._store.heartbeat_epoch(
            task_id, epoch, worker_id, lease_ttl_s=lease_ttl_s, now=now
        )

    def release(
        self,
        task_id: str,
        epoch: int,
        worker_id: str,
        *,
        next_state: str | None = "paused",
        reason: str = "turn_completed",
        now: float | None = None,
    ) -> bool:
        return self._store.release_epoch(
            task_id,
            epoch,
            worker_id,
            next_state=next_state,
            reason=reason,
            now=now,
        )

    def fence_and_halt(
        self,
        task_id: str,
        *,
        target_state: str = "paused",
        reason: str = "fenced_by_operator",
        sweep_in_flight: bool = False,
        now: float | None = None,
    ) -> list[runtime_persistence.TaskEpochRecord]:
        """Fence active lease epochs on ``task_id`` and record a halted lifecycle state."""
        tid = _text(task_id, "task_id")
        ts = time.time() if now is None else float(now)
        task = self._store.get_task(tid)
        if task is None:
            return []
        fenced = self._store.fence_active_epoch(tid, reason=reason, now=ts)
        if fenced and self._on_epochs_fenced is not None:
            try:
                self._on_epochs_fenced(tid, fenced, reason)
            except Exception:
                pass
        if sweep_in_flight:
            self._ledger.reconcile_missing_results(task_id=tid, error_code=reason, now=ts)
        effective_state = target_state
        if target_state != "cancelled":
            unresolved = self._ledger.list_unresolved_consequential_actions(tid)
            if unresolved:
                effective_state = "blocked"
        if task.state != effective_state:
            self._store.record_transition(
                tid,
                to_state=effective_state,
                reason=reason,
                allow_inactive_epoch=True,
                now=ts,
            )
        return fenced

side_effect_ledger = sys.modules[__name__]

"""Time, token, cost, tool, cancellation, and durable recovery execution budgets."""


import json
import sqlite3
import threading
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable



class BudgetError(ValueError):
    """Raised when a budget or usage value is invalid."""


class BudgetExceeded(RuntimeError):
    """Raised when an operation would exceed an execution or recovery budget."""


class ExecutionCancelled(RuntimeError):
    """Raised when cancellation has been requested."""


@dataclass(frozen=True, slots=True)
class BudgetLimits:
    max_seconds: float
    max_tokens: int
    max_cost: float
    max_tools: int
    max_retries: int = 0

    def __post_init__(self) -> None:
        if self.max_seconds <= 0 or self.max_tokens < 0 or self.max_cost < 0 or self.max_tools < 0 or self.max_retries < 0:
            raise BudgetError("budget limits must be non-negative, with max_seconds positive.")


@dataclass(frozen=True, slots=True)
class BudgetUsage:
    elapsed_seconds: float
    tokens: int
    cost: float
    tools: int
    retries: int


class ExecutionBudget:
    """Thread-safe budget guard with monotonic time and explicit cancellation."""

    def __init__(self, limits: BudgetLimits, *, clock: Callable[[], float] = time.monotonic) -> None:
        self.limits = limits
        self._clock = clock
        self._started = clock()
        self._tokens = 0
        self._cost = 0.0
        self._tools = 0
        self._retries = 0
        self._cancelled = False
        self._lock = threading.RLock()

    def cancel(self) -> None:
        with self._lock:
            self._cancelled = True

    def _usage(self) -> BudgetUsage:
        return BudgetUsage(self._clock() - self._started, self._tokens, self._cost, self._tools, self._retries)

    def usage(self) -> BudgetUsage:
        with self._lock:
            return self._usage()

    def check(self) -> BudgetUsage:
        with self._lock:
            usage = self._usage()
            if self._cancelled:
                raise ExecutionCancelled("execution was cancelled.")
            if usage.elapsed_seconds > self.limits.max_seconds:
                raise BudgetExceeded("time budget exceeded.")
            if usage.tokens > self.limits.max_tokens:
                raise BudgetExceeded("token budget exceeded.")
            if usage.cost > self.limits.max_cost:
                raise BudgetExceeded("cost budget exceeded.")
            if usage.tools > self.limits.max_tools:
                raise BudgetExceeded("tool budget exceeded.")
            if usage.retries > self.limits.max_retries:
                raise BudgetExceeded("retry budget exceeded.")
            return usage

    def consume(self, *, tokens: int = 0, cost: float = 0.0, tools: int = 0) -> BudgetUsage:
        if isinstance(tokens, bool) or tokens < 0 or isinstance(tools, bool) or tools < 0 or cost < 0:
            raise BudgetError("usage increments must be non-negative.")
        with self._lock:
            self._tokens += tokens
            self._cost += cost
            self._tools += tools
            return self.check()

    def retry(self) -> BudgetUsage:
        with self._lock:
            self._retries += 1
            return self.check()

    def allow_retry(self) -> bool:
        try:
            self.retry()
        except BudgetExceeded:
            return False
        return True


def _non_neg_int(value: Any, name: str, *, min_value: int = 0) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < min_value:
        raise BudgetError(f"{name} must be an integer >= {min_value}.")
    return int(value)


def _non_neg_float(value: Any, name: str, *, strictly_positive: bool = False) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise BudgetError(f"{name} must be numeric.")
    val = float(value)
    if strictly_positive and val <= 0:
        raise BudgetError(f"{name} must be positive.")
    if not strictly_positive and val < 0:
        raise BudgetError(f"{name} must be non-negative.")
    return val


@dataclass(frozen=True, slots=True)
class TaskBudgetSpec:
    """Durable root-task and crash-recovery budget bounds (M5-P1-05)."""

    max_steps: int = 25
    max_tool_calls: int = 120
    max_tokens: int = 500_000
    max_elapsed_s: float = 1_800.0
    max_recoveries: int = 3

    def __post_init__(self) -> None:
        _non_neg_int(self.max_steps, "max_steps", min_value=1)
        _non_neg_int(self.max_tool_calls, "max_tool_calls", min_value=0)
        _non_neg_int(self.max_tokens, "max_tokens", min_value=0)
        _non_neg_float(self.max_elapsed_s, "max_elapsed_s", strictly_positive=True)
        _non_neg_int(self.max_recoveries, "max_recoveries", min_value=0)

    def to_dict(self) -> dict[str, Any]:
        return {
            "max_steps": self.max_steps,
            "max_tool_calls": self.max_tool_calls,
            "max_tokens": self.max_tokens,
            "max_elapsed_s": round(self.max_elapsed_s, 4),
            "max_recoveries": self.max_recoveries,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any] | None) -> TaskBudgetSpec:
        raw = data or {}
        return cls(
            max_steps=int(raw.get("max_steps", 25)),
            max_tool_calls=int(raw.get("max_tool_calls", 120)),
            max_tokens=int(raw.get("max_tokens", 500_000)),
            max_elapsed_s=float(raw.get("max_elapsed_s", 1_800.0)),
            max_recoveries=int(raw.get("max_recoveries", 3)),
        )


@dataclass(frozen=True, slots=True)
class TaskBudgetState:
    """Persisted task + recovery budget counters and safe-boundary flags."""

    spec: TaskBudgetSpec
    steps_used: int = 0
    tool_calls_used: int = 0
    tokens_used: int = 0
    elapsed_s: float = 0.0
    recoveries_used: int = 0
    pause_requested: bool = False
    cancel_requested: bool = False
    exhausted_reason: str = ""
    verification_contract: dict[str, Any] | None = None

    def to_dict(self) -> dict[str, Any]:
        return {
            "spec": self.spec.to_dict(),
            "steps_used": self.steps_used,
            "tool_calls_used": self.tool_calls_used,
            "tokens_used": self.tokens_used,
            "elapsed_s": round(self.elapsed_s, 4),
            "recoveries_used": self.recoveries_used,
            "pause_requested": self.pause_requested,
            "cancel_requested": self.cancel_requested,
            "exhausted_reason": self.exhausted_reason,
        }

    def to_json(self) -> str:
        payload = self.to_dict()
        if self.verification_contract is not None:
            payload["verification_contract"] = self.verification_contract
        return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    @classmethod
    def from_json(
        cls,
        raw: str | None,
        *,
        default_spec: TaskBudgetSpec | None = None,
    ) -> TaskBudgetState:
        fallback = default_spec or TaskBudgetSpec()
        text = (raw or "").strip()
        if not text or text == "{}":
            return cls(spec=fallback)
        try:
            parsed = json.loads(text)
        except (TypeError, ValueError) as exc:
            raise BudgetError("persisted task budget JSON is malformed.") from exc
        if not isinstance(parsed, dict):
            raise BudgetError("persisted task budget JSON must be an object.")
        spec_raw = parsed.get("spec")
        if isinstance(spec_raw, dict):
            spec = TaskBudgetSpec.from_dict(spec_raw)
        else:
            spec = TaskBudgetSpec(
                max_steps=int(parsed.get("max_steps", fallback.max_steps)),
                max_tool_calls=int(parsed.get("max_tool_calls", fallback.max_tool_calls)),
                max_tokens=int(parsed.get("max_tokens", fallback.max_tokens)),
                max_elapsed_s=float(parsed.get("max_elapsed_s", fallback.max_elapsed_s)),
                max_recoveries=int(parsed.get("max_recoveries", fallback.max_recoveries)),
            )
        vc_raw = parsed.get("verification_contract")
        vc_dict = dict(vc_raw) if isinstance(vc_raw, dict) else None
        return cls(
            spec=spec,
            steps_used=_non_neg_int(int(parsed.get("steps_used", 0)), "steps_used"),
            tool_calls_used=_non_neg_int(int(parsed.get("tool_calls_used", 0)), "tool_calls_used"),
            tokens_used=_non_neg_int(int(parsed.get("tokens_used", 0)), "tokens_used"),
            elapsed_s=_non_neg_float(float(parsed.get("elapsed_s", 0.0)), "elapsed_s"),
            recoveries_used=_non_neg_int(int(parsed.get("recoveries_used", 0)), "recoveries_used"),
            pause_requested=bool(parsed.get("pause_requested", False)),
            cancel_requested=bool(parsed.get("cancel_requested", False)),
            exhausted_reason=str(parsed.get("exhausted_reason", "")),
            verification_contract=vc_dict,
        )

    def violation_reason(self, *, check_recovery: bool = False) -> str:
        if self.steps_used > self.spec.max_steps:
            return f"step budget exceeded ({self.steps_used}/{self.spec.max_steps})"
        if self.tool_calls_used > self.spec.max_tool_calls:
            return f"tool budget exceeded ({self.tool_calls_used}/{self.spec.max_tool_calls})"
        if self.tokens_used > self.spec.max_tokens:
            return f"token budget exceeded ({self.tokens_used}/{self.spec.max_tokens})"
        if self.elapsed_s > self.spec.max_elapsed_s:
            return f"time budget exceeded ({self.elapsed_s:.2f}s/{self.spec.max_elapsed_s:.2f}s)"
        if check_recovery and self.recoveries_used > self.spec.max_recoveries:
            return f"recovery budget exceeded ({self.recoveries_used}/{self.spec.max_recoveries})"
        return ""


class DurableTaskBudgetManager:
    """SQLite-backed task and recovery budget enforcement over ``runtime_tasks.budget_json``."""

    def __init__(
        self,
        storage: runtime_persistence.StorageProvider,
        db_path: Path,
        *,
        retry_policy: runtime_persistence.BusyRetryPolicy = runtime_persistence.DEFAULT_BUSY_RETRY_POLICY,
    ) -> None:
        self._storage = storage
        self._db_path = db_path
        self._retry_policy = retry_policy

    @staticmethod
    def _validate_task_id(task_id: str) -> str:
        if not isinstance(task_id, str) or not task_id.strip() or "\x00" in task_id:
            raise BudgetError("task_id must be a non-empty string without NUL characters.")
        return task_id.strip()

    def get_budget(
        self,
        task_id: str,
        *,
        default_spec: TaskBudgetSpec | None = None,
    ) -> TaskBudgetState:
        tid = self._validate_task_id(task_id)

        def _read(conn: sqlite3.Connection) -> TaskBudgetState:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT budget_json FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            return TaskBudgetState.from_json(str(row["budget_json"]), default_spec=default_spec)

        return runtime_persistence.run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def ensure_budget(
        self,
        task_id: str,
        *,
        spec: TaskBudgetSpec | None = None,
        override_spec: bool = False,
        now: float | None = None,
    ) -> TaskBudgetState:
        tid = self._validate_task_id(task_id)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskBudgetState:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT budget_json FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            raw = str(row["budget_json"] or "{}").strip()
            current = TaskBudgetState.from_json(raw, default_spec=spec)
            effective_spec = spec if (override_spec and spec is not None) else current.spec
            updated = TaskBudgetState(
                spec=effective_spec,
                steps_used=current.steps_used,
                tool_calls_used=current.tool_calls_used,
                tokens_used=current.tokens_used,
                elapsed_s=current.elapsed_s,
                recoveries_used=current.recoveries_used,
                pause_requested=current.pause_requested,
                cancel_requested=current.cancel_requested,
                exhausted_reason=current.exhausted_reason,
                verification_contract=current.verification_contract,
            )
            encoded = updated.to_json()
            if encoded != raw:
                conn.execute(
                    "UPDATE runtime_tasks SET budget_json = ?, updated_at = ? WHERE task_id = ?",
                    (encoded, ts, tid),
                )
            return updated

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def set_control_flags(
        self,
        task_id: str,
        *,
        pause_requested: bool | None = None,
        cancel_requested: bool | None = None,
        now: float | None = None,
    ) -> TaskBudgetState:
        tid = self._validate_task_id(task_id)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskBudgetState:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT budget_json FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            current = TaskBudgetState.from_json(str(row["budget_json"]))
            updated = TaskBudgetState(
                spec=current.spec,
                steps_used=current.steps_used,
                tool_calls_used=current.tool_calls_used,
                tokens_used=current.tokens_used,
                elapsed_s=current.elapsed_s,
                recoveries_used=current.recoveries_used,
                pause_requested=current.pause_requested if pause_requested is None else bool(pause_requested),
                cancel_requested=current.cancel_requested if cancel_requested is None else bool(cancel_requested),
                exhausted_reason=current.exhausted_reason,
                verification_contract=current.verification_contract,
            )
            conn.execute(
                "UPDATE runtime_tasks SET budget_json = ?, updated_at = ? WHERE task_id = ?",
                (updated.to_json(), ts, tid),
            )
            return updated

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def record_usage(
        self,
        task_id: str,
        *,
        epoch: int | None = None,
        steps_delta: int = 0,
        tool_calls_delta: int = 0,
        tokens_delta: int = 0,
        elapsed_delta_s: float = 0.0,
        enforce: bool = True,
        now: float | None = None,
    ) -> TaskBudgetState:
        tid = self._validate_task_id(task_id)
        _non_neg_int(steps_delta, "steps_delta")
        _non_neg_int(tool_calls_delta, "tool_calls_delta")
        _non_neg_int(tokens_delta, "tokens_delta")
        _non_neg_float(elapsed_delta_s, "elapsed_delta_s")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> tuple[TaskBudgetState, str, bool]:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                "SELECT current_epoch, budget_json FROM runtime_tasks WHERE task_id = ?",
                (tid,),
            ).fetchone()
            if row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            if epoch is not None and int(row["current_epoch"]) != int(epoch):
                raise runtime_persistence.StaleEpochError(
                    f"Stale epoch {epoch} cannot mutate budget for task {tid!r} at current_epoch={row['current_epoch']}."
                )
            current = TaskBudgetState.from_json(str(row["budget_json"]))
            candidate = TaskBudgetState(
                spec=current.spec,
                steps_used=current.steps_used + steps_delta,
                tool_calls_used=current.tool_calls_used + tool_calls_delta,
                tokens_used=current.tokens_used + tokens_delta,
                elapsed_s=round(current.elapsed_s + elapsed_delta_s, 6),
                recoveries_used=current.recoveries_used,
                pause_requested=current.pause_requested,
                cancel_requested=current.cancel_requested,
                exhausted_reason=current.exhausted_reason,
                verification_contract=current.verification_contract,
            )
            violation = candidate.violation_reason(check_recovery=False)
            final_state = (
                TaskBudgetState(
                    spec=candidate.spec,
                    steps_used=candidate.steps_used,
                    tool_calls_used=candidate.tool_calls_used,
                    tokens_used=candidate.tokens_used,
                    elapsed_s=candidate.elapsed_s,
                    recoveries_used=candidate.recoveries_used,
                    pause_requested=candidate.pause_requested,
                    cancel_requested=candidate.cancel_requested,
                    exhausted_reason=violation or candidate.exhausted_reason,
                    verification_contract=candidate.verification_contract,
                )
                if violation
                else candidate
            )
            conn.execute(
                "UPDATE runtime_tasks SET budget_json = ?, updated_at = ? WHERE task_id = ?",
                (final_state.to_json(), ts, tid),
            )
            return final_state, violation, final_state.cancel_requested

        state, violation, cancelled = runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )
        if enforce and cancelled:
            raise ExecutionCancelled("task cancellation requested.")
        if enforce and violation:
            raise BudgetExceeded(violation)
        return state

    def consume_recovery(
        self,
        task_id: str,
        *,
        now: float | None = None,
    ) -> TaskBudgetState:
        """Atomically consume 1 durable recovery attempt; commit exhaustion before raising."""
        tid = self._validate_task_id(task_id)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> tuple[TaskBudgetState, str]:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT budget_json FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            current = TaskBudgetState.from_json(str(row["budget_json"]))
            next_recoveries = current.recoveries_used + 1
            violation = ""
            if next_recoveries > current.spec.max_recoveries:
                violation = f"recovery budget exceeded ({next_recoveries}/{current.spec.max_recoveries})"
            persisted = TaskBudgetState(
                spec=current.spec,
                steps_used=current.steps_used,
                tool_calls_used=current.tool_calls_used,
                tokens_used=current.tokens_used,
                elapsed_s=current.elapsed_s,
                recoveries_used=current.recoveries_used if violation else next_recoveries,
                pause_requested=False if not violation else current.pause_requested,
                cancel_requested=current.cancel_requested,
                exhausted_reason=violation or current.exhausted_reason,
                verification_contract=current.verification_contract,
            )
            conn.execute(
                "UPDATE runtime_tasks SET budget_json = ?, updated_at = ? WHERE task_id = ?",
                (persisted.to_json(), ts, tid),
            )
            return persisted, violation

        state, violation = runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )
        if violation:
            raise BudgetExceeded(violation)
        return state

    def set_verification_contract(
        self,
        task_id: str,
        contract: dict[str, Any] | None,
        *,
        now: float | None = None,
    ) -> TaskBudgetState:
        """Persist or clear the authoritative task verification contract inside ``budget_json``."""
        tid = self._validate_task_id(task_id)
        if contract is not None and not isinstance(contract, dict):
            raise BudgetError("verification_contract must be a dict or None.")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskBudgetState:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT budget_json FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            current = TaskBudgetState.from_json(str(row["budget_json"]))
            updated = TaskBudgetState(
                spec=current.spec,
                steps_used=current.steps_used,
                tool_calls_used=current.tool_calls_used,
                tokens_used=current.tokens_used,
                elapsed_s=current.elapsed_s,
                recoveries_used=current.recoveries_used,
                pause_requested=current.pause_requested,
                cancel_requested=current.cancel_requested,
                exhausted_reason=current.exhausted_reason,
                verification_contract=dict(contract) if contract is not None else None,
            )
            conn.execute(
                "UPDATE runtime_tasks SET budget_json = ?, updated_at = ? WHERE task_id = ?",
                (updated.to_json(), ts, tid),
            )
            return updated

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

execution_budget = sys.modules[__name__]

"""Durable workflow checkpoints, evidence references, and safe resume validation."""


import hashlib
import hmac
import json
import sqlite3
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Literal, Sequence


CheckpointStatus = Literal["active", "interrupted", "resumed", "completed"]
_STATUSES = frozenset({"active", "interrupted", "resumed", "completed"})

TaskCheckpointStatus = Literal["pending_commit", "committed", "interrupted", "resumed", "superseded"]


class CheckpointError(ValueError):
    """Raised when checkpoint data is malformed or not resumable."""


class ResumeRejected(RuntimeError):
    """Raised when a checkpoint cannot be safely resumed."""


@dataclass(frozen=True, slots=True)
class Checkpoint:
    workflow_id: str
    step: int
    state: CheckpointStatus
    payload: dict[str, object]
    payload_hash: str
    updated_at: str


@dataclass(frozen=True, slots=True)
class AuditEntry:
    workflow_id: str
    step: int
    event: str
    detail: str
    created_at: str


def _workflow_id(value: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise CheckpointError("workflow_id must be a non-empty string without NUL characters.")
    return value.strip()


def _step(value: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise CheckpointError("step must be a non-negative integer.")
    return value


def _status(value: str) -> CheckpointStatus:
    if value not in _STATUSES:
        raise CheckpointError(f"unknown checkpoint state: {value}")
    return value  # type: ignore[return-value]


def _encoded_payload(payload: dict[str, object]) -> tuple[str, str]:
    try:
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    except (TypeError, ValueError) as exc:
        raise CheckpointError("checkpoint payload must be JSON serializable.") from exc
    return encoded, hashlib.sha256(encoded.encode("utf-8")).hexdigest()


class WorkflowCheckpointStore:
    """SQLite checkpoint store that only resumes intact interrupted steps."""

    def __init__(self, database: Path) -> None:
        self.database = Path(database)
        self.database.parent.mkdir(parents=True, exist_ok=True)
        with self._connect() as connection:
            connection.executescript(
                """
                CREATE TABLE IF NOT EXISTS workflow_checkpoints (
                    workflow_id TEXT PRIMARY KEY,
                    step INTEGER NOT NULL,
                    state TEXT NOT NULL,
                    payload_json TEXT NOT NULL,
                    payload_hash TEXT NOT NULL,
                    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
                );
                CREATE TABLE IF NOT EXISTS workflow_checkpoint_audit (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    workflow_id TEXT NOT NULL,
                    step INTEGER NOT NULL,
                    event TEXT NOT NULL,
                    detail TEXT NOT NULL,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
                );
                """
            )

    def _connect(self) -> sqlite3.Connection:
        connection = sqlite3.connect(self.database, timeout=5.0)
        connection.row_factory = sqlite3.Row
        return connection

    @staticmethod
    def _checkpoint(row: sqlite3.Row | None) -> Checkpoint | None:
        if row is None:
            return None
        try:
            payload = json.loads(row["payload_json"])
        except (TypeError, ValueError) as exc:
            raise ResumeRejected("checkpoint payload is not valid JSON.") from exc
        if not isinstance(payload, dict):
            raise ResumeRejected("checkpoint payload is not an object.")
        _status(row["state"])
        return Checkpoint(row["workflow_id"], row["step"], row["state"], payload, row["payload_hash"], row["updated_at"])

    def save(self, workflow_id: str, step: int, payload: dict[str, object], *, state: CheckpointStatus = "active") -> Checkpoint:
        identifier = _workflow_id(workflow_id)
        position = _step(step)
        normalized_state = _status(state)
        encoded, payload_hash = _encoded_payload(payload)
        with self._connect() as connection:
            connection.execute(
                """
                INSERT INTO workflow_checkpoints(workflow_id, step, state, payload_json, payload_hash)
                VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(workflow_id) DO UPDATE SET
                    step=excluded.step, state=excluded.state,
                    payload_json=excluded.payload_json, payload_hash=excluded.payload_hash,
                    updated_at=CURRENT_TIMESTAMP
                """,
                (identifier, position, normalized_state, encoded, payload_hash),
            )
            connection.execute(
                "INSERT INTO workflow_checkpoint_audit(workflow_id, step, event, detail) VALUES (?, ?, ?, ?)",
                (identifier, position, "checkpoint_saved", normalized_state),
            )
            row = connection.execute("SELECT * FROM workflow_checkpoints WHERE workflow_id = ?", (identifier,)).fetchone()
        result = self._checkpoint(row)
        assert result is not None
        return result

    def mark_interrupted(self, workflow_id: str) -> Checkpoint:
        identifier = _workflow_id(workflow_id)
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute("SELECT * FROM workflow_checkpoints WHERE workflow_id = ?", (identifier,)).fetchone()
            checkpoint = self._checkpoint(row)
            if checkpoint is None:
                raise CheckpointError("checkpoint does not exist.")
            connection.execute("UPDATE workflow_checkpoints SET state = 'interrupted', updated_at = CURRENT_TIMESTAMP WHERE workflow_id = ?", (identifier,))
            connection.execute(
                "INSERT INTO workflow_checkpoint_audit(workflow_id, step, event, detail) VALUES (?, ?, ?, ?)",
                (identifier, checkpoint.step, "workflow_interrupted", "safe resume available"),
            )
            updated = connection.execute("SELECT * FROM workflow_checkpoints WHERE workflow_id = ?", (identifier,)).fetchone()
        result = self._checkpoint(updated)
        assert result is not None
        return result

    def resume(self, workflow_id: str) -> Checkpoint:
        identifier = _workflow_id(workflow_id)
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute("SELECT * FROM workflow_checkpoints WHERE workflow_id = ?", (identifier,)).fetchone()
            checkpoint = self._checkpoint(row)
            if checkpoint is None:
                raise ResumeRejected("checkpoint does not exist.")
            if checkpoint.state != "interrupted":
                raise ResumeRejected("only interrupted workflows can be resumed.")
            encoded, payload_hash = _encoded_payload(checkpoint.payload)
            if not hmac_compare(payload_hash, checkpoint.payload_hash):
                raise ResumeRejected("checkpoint integrity hash does not match payload.")
            connection.execute(
                "UPDATE workflow_checkpoints SET state = 'resumed', payload_json = ?, payload_hash = ?, updated_at = CURRENT_TIMESTAMP WHERE workflow_id = ?",
                (encoded, payload_hash, identifier),
            )
            connection.execute(
                "INSERT INTO workflow_checkpoint_audit(workflow_id, step, event, detail) VALUES (?, ?, ?, ?)",
                (identifier, checkpoint.step, "workflow_resumed", "integrity verified"),
            )
            updated = connection.execute("SELECT * FROM workflow_checkpoints WHERE workflow_id = ?", (identifier,)).fetchone()
        result = self._checkpoint(updated)
        assert result is not None
        return result

    def audit(self, workflow_id: str) -> tuple[AuditEntry, ...]:
        identifier = _workflow_id(workflow_id)
        with self._connect() as connection:
            rows = connection.execute(
                "SELECT workflow_id, step, event, detail, created_at FROM workflow_checkpoint_audit WHERE workflow_id = ? ORDER BY id",
                (identifier,),
            ).fetchall()
        return tuple(AuditEntry(row["workflow_id"], row["step"], row["event"], row["detail"], row["created_at"]) for row in rows)


def hmac_compare(left: str, right: str) -> bool:
    """Constant-time comparison for checkpoint integrity digests."""
    return hmac.compare_digest(left, right)


@dataclass(frozen=True, slots=True)
class EvidenceRef:
    """Typed durable evidence pointer attached to a task checkpoint or transition."""

    kind: str
    ref_id: str
    sha256: str = ""
    summary: str = ""

    def __post_init__(self) -> None:
        if not isinstance(self.kind, str) or not self.kind.strip() or "\x00" in self.kind:
            raise CheckpointError("EvidenceRef.kind must be a non-empty string.")
        if not isinstance(self.ref_id, str) or not self.ref_id.strip() or "\x00" in self.ref_id:
            raise CheckpointError("EvidenceRef.ref_id must be a non-empty string.")

    def to_dict(self) -> dict[str, str]:
        return {
            "kind": self.kind.strip()[:64],
            "ref_id": self.ref_id.strip()[:256],
            "sha256": str(self.sha256 or "").strip()[:128],
            "summary": str(self.summary or "").strip()[:240],
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> EvidenceRef:
        if not isinstance(data, dict):
            raise CheckpointError("EvidenceRef entry must be a JSON object.")
        return cls(
            kind=str(data.get("kind", "")),
            ref_id=str(data.get("ref_id", "")),
            sha256=str(data.get("sha256", "")),
            summary=str(data.get("summary", "")),
        )


@dataclass(frozen=True, slots=True)
class TaskCheckpointRecord:
    """Authoritative checkpoint row in ``runtime_task_checkpoints`` (M5-P1-05)."""

    checkpoint_id: str
    task_id: str
    seq: int
    step: int
    epoch: int
    milestone_id: str
    status: str
    payload: dict[str, Any]
    payload_hash: str
    evidence_refs: tuple[EvidenceRef, ...]
    created_at: float
    updated_at: float

    def to_dict(self) -> dict[str, Any]:
        return {
            "checkpoint_id": self.checkpoint_id,
            "task_id": self.task_id,
            "seq": self.seq,
            "step": self.step,
            "epoch": self.epoch,
            "milestone_id": self.milestone_id,
            "status": self.status,
            "payload": self.payload,
            "payload_hash": self.payload_hash,
            "evidence_refs": [ref.to_dict() for ref in self.evidence_refs],
            "created_at": self.created_at,
            "updated_at": self.updated_at,
        }


def compute_task_checkpoint_digest(payload_json: str, evidence_refs_json: str) -> str:
    """Compute canonical SHA-256 digest covering both payload and evidence references."""
    material = f"{payload_json}\n{evidence_refs_json}".encode("utf-8")
    return hashlib.sha256(material).hexdigest()


def _encode_checkpoint_bundle(
    payload: dict[str, Any],
    evidence_refs: Sequence[EvidenceRef | dict[str, Any]],
) -> tuple[str, str, tuple[EvidenceRef, ...], str]:
    if not isinstance(payload, dict):
        raise CheckpointError("checkpoint payload must be a dict.")
    normalized_refs: list[EvidenceRef] = []
    for item in evidence_refs:
        if isinstance(item, EvidenceRef):
            normalized_refs.append(item)
        elif isinstance(item, dict):
            normalized_refs.append(EvidenceRef.from_dict(item))
        else:
            to_dict_fn = getattr(item, "to_dict", None)
            if callable(to_dict_fn):
                normalized_refs.append(EvidenceRef.from_dict(to_dict_fn()))
            else:
                raise CheckpointError("evidence_refs items must be EvidenceRef or dict.")
    try:
        payload_json = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        refs_json = json.dumps(
            [r.to_dict() for r in normalized_refs],
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        )
    except (TypeError, ValueError) as exc:
        raise CheckpointError("checkpoint payload and evidence_refs must be JSON serializable.") from exc
    digest = compute_task_checkpoint_digest(payload_json, refs_json)
    return payload_json, refs_json, tuple(normalized_refs), digest


def _decode_and_verify_checkpoint_row(
    row: sqlite3.Row,
    *,
    verify_integrity: bool = True,
) -> TaskCheckpointRecord:
    raw_payload = str(row["payload_json"])
    raw_refs = str(row["evidence_refs_json"])
    stored_hash = str(row["payload_hash"])
    try:
        payload_obj = json.loads(raw_payload)
        refs_obj = json.loads(raw_refs)
    except (TypeError, ValueError) as exc:
        raise ResumeRejected("checkpoint JSON is malformed or truncated.") from exc
    if not isinstance(payload_obj, dict):
        raise ResumeRejected("checkpoint payload_json is not a JSON object.")
    if not isinstance(refs_obj, list):
        raise ResumeRejected("checkpoint evidence_refs_json is not a JSON array.")
    try:
        refs = tuple(EvidenceRef.from_dict(item) for item in refs_obj)
    except CheckpointError as exc:
        raise ResumeRejected(f"checkpoint evidence reference invalid: {exc}") from exc
    status = str(row["status"])
    if status not in runtime_persistence.CHECKPOINT_STATUSES:
        raise ResumeRejected(f"unknown checkpoint status {status!r}.")
    if verify_integrity:
        canonical_payload = json.dumps(payload_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        canonical_refs = json.dumps(
            [r.to_dict() for r in refs],
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        )
        expected_hash = compute_task_checkpoint_digest(canonical_payload, canonical_refs)
        if not hmac_compare(expected_hash, stored_hash):
            raise ResumeRejected("checkpoint integrity hash does not match payload or evidence refs.")
    return TaskCheckpointRecord(
        checkpoint_id=str(row["checkpoint_id"]),
        task_id=str(row["task_id"]),
        seq=int(row["seq"]),
        step=int(row["step"]),
        epoch=int(row["epoch"]),
        milestone_id=str(row["milestone_id"]),
        status=status,
        payload=payload_obj,
        payload_hash=stored_hash,
        evidence_refs=refs,
        created_at=float(row["created_at"]),
        updated_at=float(row["updated_at"]),
    )


class DurableTaskCheckpointStore:
    """Authoritative SQLite store for ``runtime_task_checkpoints`` + ``runtime_tasks.checkpoint_ref``."""

    def __init__(
        self,
        storage: runtime_persistence.StorageProvider,
        db_path: Path,
        *,
        retry_policy: runtime_persistence.BusyRetryPolicy = runtime_persistence.DEFAULT_BUSY_RETRY_POLICY,
    ) -> None:
        self._storage = storage
        self._db_path = db_path
        self._retry_policy = retry_policy

    def stage_checkpoint(
        self,
        task_id: str,
        *,
        step: int,
        payload: dict[str, Any],
        evidence_refs: Sequence[EvidenceRef | dict[str, Any]] = (),
        epoch: int = 0,
        milestone_id: str = "",
        now: float | None = None,
    ) -> TaskCheckpointRecord:
        """Write a ``pending_commit`` checkpoint row without advancing ``runtime_tasks.checkpoint_ref``."""
        tid = _workflow_id(task_id)
        pos = _step(step)
        payload_json, refs_json, _, digest = _encode_checkpoint_bundle(payload, evidence_refs)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskCheckpointRecord:
            conn.row_factory = sqlite3.Row
            task_row = conn.execute("SELECT current_epoch FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if task_row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            seq_row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_checkpoints WHERE task_id = ?",
                (tid,),
            ).fetchone()
            next_seq = int(seq_row[0]) if seq_row else 1
            ckpt_id = f"ckpt-{tid[:48]}-s{next_seq}-{digest[:10]}"
            conn.execute(
                """
                INSERT INTO runtime_task_checkpoints (
                    checkpoint_id, task_id, seq, step, epoch, milestone_id, status,
                    payload_json, payload_hash, evidence_refs_json, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, 'pending_commit', ?, ?, ?, ?, ?)
                """,
                (ckpt_id, tid, next_seq, pos, int(epoch), str(milestone_id)[:128], payload_json, digest, refs_json, ts, ts),
            )
            saved = conn.execute(
                "SELECT * FROM runtime_task_checkpoints WHERE checkpoint_id = ?",
                (ckpt_id,),
            ).fetchone()
            assert saved is not None
            return _decode_and_verify_checkpoint_row(saved, verify_integrity=True)

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def save_checkpoint(
        self,
        task_id: str,
        *,
        step: int,
        payload: dict[str, Any],
        evidence_refs: Sequence[EvidenceRef | dict[str, Any]] = (),
        epoch: int | None = None,
        milestone_id: str = "",
        status: Literal["committed", "interrupted"] = "committed",
        require_active_epoch: bool = False,
        now: float | None = None,
    ) -> TaskCheckpointRecord:
        """Atomically persist checkpoint + evidence refs and advance ``runtime_tasks.checkpoint_ref``."""
        tid = _workflow_id(task_id)
        pos = _step(step)
        if status not in {"committed", "interrupted"}:
            raise CheckpointError(f"Unsupported save_checkpoint status: {status!r}")
        payload_json, refs_json, _, digest = _encode_checkpoint_bundle(payload, evidence_refs)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskCheckpointRecord:
            conn.row_factory = sqlite3.Row
            task_row = conn.execute("SELECT current_epoch FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if task_row is None:
                raise KeyError(f"Runtime task {tid!r} does not exist.")
            current_epoch = int(task_row["current_epoch"])
            if epoch is not None and int(epoch) != current_epoch:
                raise runtime_persistence.StaleEpochError(
                    f"Stale epoch {epoch} cannot checkpoint task {tid!r} at current_epoch={current_epoch}."
                )
            effective_epoch = current_epoch if epoch is None else int(epoch)
            if require_active_epoch and effective_epoch > 0:
                ep_row = conn.execute(
                    "SELECT status, lease_expires_at FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                    (tid, effective_epoch),
                ).fetchone()
                if ep_row is None or str(ep_row["status"]) != "active":
                    raise runtime_persistence.StaleEpochError(
                        f"Inactive epoch {effective_epoch} cannot checkpoint task {tid!r}."
                    )
                if float(ep_row["lease_expires_at"]) <= ts:
                    raise runtime_persistence.LeaseExpiredError(
                        f"Expired epoch {effective_epoch} cannot checkpoint task {tid!r}."
                    )
            conn.execute(
                """
                UPDATE runtime_task_checkpoints
                SET status = 'superseded', updated_at = ?
                WHERE task_id = ? AND status IN ('committed', 'interrupted', 'resumed', 'pending_commit')
                """,
                (ts, tid),
            )
            seq_row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_checkpoints WHERE task_id = ?",
                (tid,),
            ).fetchone()
            next_seq = int(seq_row[0]) if seq_row else 1
            ckpt_id = f"ckpt-{tid[:48]}-s{next_seq}-{digest[:10]}"
            conn.execute(
                """
                INSERT INTO runtime_task_checkpoints (
                    checkpoint_id, task_id, seq, step, epoch, milestone_id, status,
                    payload_json, payload_hash, evidence_refs_json, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    ckpt_id,
                    tid,
                    next_seq,
                    pos,
                    effective_epoch,
                    str(milestone_id)[:128],
                    status,
                    payload_json,
                    digest,
                    refs_json,
                    ts,
                    ts,
                ),
            )
            conn.execute(
                "UPDATE runtime_tasks SET checkpoint_ref = ?, updated_at = ? WHERE task_id = ?",
                (ckpt_id, ts, tid),
            )
            saved = conn.execute(
                "SELECT * FROM runtime_task_checkpoints WHERE checkpoint_id = ?",
                (ckpt_id,),
            ).fetchone()
            assert saved is not None
            return _decode_and_verify_checkpoint_row(saved, verify_integrity=True)

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def get_checkpoint(
        self,
        checkpoint_id: str,
        *,
        verify_integrity: bool = True,
    ) -> TaskCheckpointRecord | None:
        cid = _workflow_id(checkpoint_id)

        def _read(conn: sqlite3.Connection) -> TaskCheckpointRecord | None:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                "SELECT * FROM runtime_task_checkpoints WHERE checkpoint_id = ?",
                (cid,),
            ).fetchone()
            if row is None:
                return None
            return _decode_and_verify_checkpoint_row(row, verify_integrity=verify_integrity)

        return runtime_persistence.run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def load_latest_checkpoint(
        self,
        task_id: str,
        *,
        verify_integrity: bool = True,
    ) -> TaskCheckpointRecord | None:
        tid = _workflow_id(task_id)

        def _read(conn: sqlite3.Connection) -> TaskCheckpointRecord | None:
            conn.row_factory = sqlite3.Row
            task_row = conn.execute("SELECT checkpoint_ref FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if task_row is None:
                return None
            ckpt_ref = str(task_row["checkpoint_ref"] or "").strip()
            if ckpt_ref:
                ref_row = conn.execute(
                    "SELECT * FROM runtime_task_checkpoints WHERE checkpoint_id = ? AND task_id = ?",
                    (ckpt_ref, tid),
                ).fetchone()
                if ref_row is None:
                    raise ResumeRejected(
                        f"Task {tid!r} references missing checkpoint {ckpt_ref!r}."
                    )
                return _decode_and_verify_checkpoint_row(ref_row, verify_integrity=verify_integrity)
            latest_row = conn.execute(
                """
                SELECT * FROM runtime_task_checkpoints
                WHERE task_id = ? AND status IN ('committed', 'interrupted', 'resumed')
                ORDER BY seq DESC LIMIT 1
                """,
                (tid,),
            ).fetchone()
            if latest_row is None:
                return None
            return _decode_and_verify_checkpoint_row(latest_row, verify_integrity=verify_integrity)

        return runtime_persistence.run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def list_checkpoints(
        self,
        task_id: str,
        *,
        verify_integrity: bool = False,
    ) -> list[TaskCheckpointRecord]:
        tid = _workflow_id(task_id)

        def _read(conn: sqlite3.Connection) -> list[TaskCheckpointRecord]:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                "SELECT * FROM runtime_task_checkpoints WHERE task_id = ? ORDER BY seq ASC",
                (tid,),
            ).fetchall()
            return [_decode_and_verify_checkpoint_row(r, verify_integrity=verify_integrity) for r in rows]

        return runtime_persistence.run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def mark_latest_interrupted(
        self,
        task_id: str,
        *,
        now: float | None = None,
    ) -> TaskCheckpointRecord | None:
        tid = _workflow_id(task_id)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskCheckpointRecord | None:
            conn.row_factory = sqlite3.Row
            task_row = conn.execute("SELECT checkpoint_ref FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if task_row is None:
                return None
            ckpt_ref = str(task_row["checkpoint_ref"] or "").strip()
            row = None
            if ckpt_ref:
                row = conn.execute(
                    "SELECT * FROM runtime_task_checkpoints WHERE checkpoint_id = ? AND task_id = ?",
                    (ckpt_ref, tid),
                ).fetchone()
            if row is None:
                row = conn.execute(
                    """
                    SELECT * FROM runtime_task_checkpoints
                    WHERE task_id = ? AND status IN ('committed', 'interrupted', 'resumed')
                    ORDER BY seq DESC LIMIT 1
                    """,
                    (tid,),
                ).fetchone()
            if row is None:
                return None
            verified = _decode_and_verify_checkpoint_row(row, verify_integrity=True)
            conn.execute(
                "UPDATE runtime_task_checkpoints SET status = 'interrupted', updated_at = ? WHERE checkpoint_id = ?",
                (ts, verified.checkpoint_id),
            )
            if ckpt_ref != verified.checkpoint_id:
                conn.execute(
                    "UPDATE runtime_tasks SET checkpoint_ref = ?, updated_at = ? WHERE task_id = ?",
                    (verified.checkpoint_id, ts, tid),
                )
            refreshed = conn.execute(
                "SELECT * FROM runtime_task_checkpoints WHERE checkpoint_id = ?",
                (verified.checkpoint_id,),
            ).fetchone()
            assert refreshed is not None
            return _decode_and_verify_checkpoint_row(refreshed, verify_integrity=True)

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def validate_and_mark_resumed(
        self,
        task_id: str,
        *,
        epoch: int | None = None,
        now: float | None = None,
    ) -> TaskCheckpointRecord | None:
        """Verify latest checkpoint integrity and mark ``resumed`` inside ``BEGIN IMMEDIATE``."""
        tid = _workflow_id(task_id)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskCheckpointRecord | None:
            conn.row_factory = sqlite3.Row
            task_row = conn.execute("SELECT checkpoint_ref FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if task_row is None:
                raise ResumeRejected(f"Runtime task {tid!r} does not exist.")
            ckpt_ref = str(task_row["checkpoint_ref"] or "").strip()
            row = None
            if ckpt_ref:
                row = conn.execute(
                    "SELECT * FROM runtime_task_checkpoints WHERE checkpoint_id = ? AND task_id = ?",
                    (ckpt_ref, tid),
                ).fetchone()
                if row is None:
                    raise ResumeRejected(
                        f"Task {tid!r} references missing checkpoint {ckpt_ref!r}."
                    )
            else:
                row = conn.execute(
                    """
                    SELECT * FROM runtime_task_checkpoints
                    WHERE task_id = ? AND status IN ('interrupted', 'committed', 'resumed')
                    ORDER BY seq DESC LIMIT 1
                    """,
                    (tid,),
                ).fetchone()
            if row is None:
                return None
            verified = _decode_and_verify_checkpoint_row(row, verify_integrity=True)
            next_epoch = verified.epoch if epoch is None else int(epoch)
            conn.execute(
                """
                UPDATE runtime_task_checkpoints
                SET status = 'resumed', epoch = ?, updated_at = ?
                WHERE checkpoint_id = ?
                """,
                (next_epoch, ts, verified.checkpoint_id),
            )
            conn.execute(
                "UPDATE runtime_tasks SET checkpoint_ref = ?, updated_at = ? WHERE task_id = ?",
                (verified.checkpoint_id, ts, tid),
            )
            refreshed = conn.execute(
                "SELECT * FROM runtime_task_checkpoints WHERE checkpoint_id = ?",
                (verified.checkpoint_id,),
            ).fetchone()
            assert refreshed is not None
            return _decode_and_verify_checkpoint_row(refreshed, verify_integrity=True)

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

workflow_checkpoints = sys.modules[__name__]

"""Durable failure memory, stagnation detection and bounded recovery (M5-P2-05).

The runtime already bounds *total* work per task (steps, tool calls, tokens,
elapsed time, recovery attempts) and already refuses to complete a coding task
without authoritative evidence. What it did not do is remember **why** earlier
attempts failed. Without that memory a loop can retry the same strategy forever
within its step budget, or oscillate between two patch states, and every retry
looks like fresh work.

This module is the memory and the bound:

* every verification / recovery / rollback attempt is appended to a durable
  per-task document with an :class:`EvidenceSnapshot` — the source revision, the
  transcript hash, the failure fingerprint and the per-file digests;
* :func:`detect_stagnation` classifies a new attempt as ``first``, ``progress``,
  ``stagnant`` (identical evidence to the previous failure) or ``oscillating``
  (a previously abandoned state is revisited);
* retry / replan / rollback counters live in the same document as the history,
  so "consume a budget" and "remember the attempt" cannot diverge across a
  crash, and the counters survive restart with the failures they describe;
* :meth:`RecoveryGuard.require_progress` refuses a recovery action whose evidence
  has not changed, and an escalated verdict requests a safe pause instead of
  another attempt.

Standard library only: this module is inlined into the standalone ``studio.py``
bundle, so it must not import anything outside the standard library and must not
define a top-level name another inlined module already uses.
"""

import hashlib
import json
import os
import re
import stat
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, Sequence

RECOVERY_SCHEMA_VERSION = 1

#: Bounded history: the newest attempts are kept, the rest are pruned.
MAX_ATTEMPTS = 100
#: Bounded document: a corrupt or hostile file larger than this is refused.
MAX_DOCUMENT_BYTES = 1 << 20
#: Bound on any stored free-text field.
MAX_TEXT = 300

ATTEMPT_KINDS: tuple[str, ...] = ("verification", "recovery", "rollback", "replan")
ATTEMPT_OUTCOMES: tuple[str, ...] = ("failed", "verified", "refused")
BUDGET_KINDS: tuple[str, ...] = ("retry", "replan", "rollback")

STAGNATION_FIRST = "first"
STAGNATION_PROGRESS = "progress"
STAGNATION_STAGNANT = "stagnant"
STAGNATION_OSCILLATING = "oscillating"

_ERG_SAFE_ID = re.compile(r"^[A-Za-z0-9._-]{1,120}$")
_ERG_HEX64 = re.compile(r"^[0-9a-f]{64}$")


class RecoveryGuardError(ValueError):
    """Raised when recovery memory or a recovery budget cannot be honoured."""


class RecoveryRejected(RecoveryGuardError):
    """Raised when an action is refused because it would repeat known evidence."""


def _erg_safe_task_id(task_id: str) -> str:
    cleaned = str(task_id or "").strip()
    if not _ERG_SAFE_ID.match(cleaned):
        raise RecoveryGuardError("task_id must be 1-120 characters of [A-Za-z0-9._-].")
    return cleaned


def _erg_digest(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8", errors="surrogatepass")).hexdigest()


def _erg_bounded(text: Any, limit: int = MAX_TEXT) -> str:
    if text is None:
        return ""
    raw = str(text)
    if "\x00" in raw:
        raise RecoveryGuardError("stored text must not contain NUL.")
    return raw[:limit]


def _erg_non_neg_int(value: Any, name: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        if isinstance(value, str) and value.strip().isdigit():
            value = int(value.strip())
        else:
            raise RecoveryGuardError(f"{name} must be a non-negative integer.")
    if value < 0:
        raise RecoveryGuardError(f"{name} must be a non-negative integer.")
    return int(value)


@dataclass(frozen=True, slots=True)
class RecoveryLimits:
    """Bounds on repeated recovery work for one task."""

    max_retries: int = 3
    max_replans: int = 3
    max_rollbacks: int = 3
    #: Identical failure evidence tolerated before a safe pause is requested.
    max_identical_attempts: int = 2

    def __post_init__(self) -> None:
        for name in ("max_retries", "max_replans", "max_rollbacks", "max_identical_attempts"):
            _erg_non_neg_int(getattr(self, name), name)
        if self.max_identical_attempts < 2:
            raise RecoveryGuardError("max_identical_attempts must be at least 2.")

    def to_dict(self) -> dict[str, int]:
        return {
            "max_retries": self.max_retries,
            "max_replans": self.max_replans,
            "max_rollbacks": self.max_rollbacks,
            "max_identical_attempts": self.max_identical_attempts,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any] | None) -> RecoveryLimits:
        raw = data if isinstance(data, dict) else {}
        return cls(
            max_retries=_erg_non_neg_int(raw.get("max_retries", 3), "max_retries"),
            max_replans=_erg_non_neg_int(raw.get("max_replans", 3), "max_replans"),
            max_rollbacks=_erg_non_neg_int(raw.get("max_rollbacks", 3), "max_rollbacks"),
            max_identical_attempts=_erg_non_neg_int(
                raw.get("max_identical_attempts", 2), "max_identical_attempts"
            ),
        )


@dataclass(frozen=True, slots=True)
class EvidenceSnapshot:
    """What one attempt could observe: the conditions it ran under and what failed."""

    revision_digest: str = ""
    transcript_sha256: str = ""
    failure_fingerprint: str = ""
    failure_code: str = ""
    failure_ids: tuple[str, ...] = ()
    environment_digest: str = ""

    def __post_init__(self) -> None:
        for name in ("revision_digest", "transcript_sha256", "failure_fingerprint", "environment_digest"):
            value = getattr(self, name)
            if value and not _ERG_HEX64.match(str(value)):
                raise RecoveryGuardError(f"{name} must be a 64-character lowercase hex digest.")
        object.__setattr__(self, "failure_code", _erg_bounded(self.failure_code))
        ids = tuple(_erg_bounded(item) for item in (self.failure_ids or ()) if str(item or "").strip())
        object.__setattr__(self, "failure_ids", ids[:50])

    @property
    def conditions_digest(self) -> str:
        """Digest of the observable conditions, independent of what failed."""
        payload = json.dumps(
            {
                "revision": self.revision_digest,
                "environment": self.environment_digest,
            },
            sort_keys=True,
            separators=(",", ":"),
        )
        return _erg_digest(payload)

    @property
    def evidence_key(self) -> str:
        """Digest of the whole observation; equal keys mean nothing changed."""
        payload = json.dumps(
            {
                "conditions": self.conditions_digest,
                "transcript": self.transcript_sha256,
                "fingerprint": self.failure_fingerprint,
                "code": self.failure_code,
            },
            sort_keys=True,
            separators=(",", ":"),
        )
        return _erg_digest(payload)

    def to_dict(self) -> dict[str, Any]:
        return {
            "revision_digest": self.revision_digest,
            "transcript_sha256": self.transcript_sha256,
            "failure_fingerprint": self.failure_fingerprint,
            "failure_code": self.failure_code,
            "failure_ids": list(self.failure_ids),
            "environment_digest": self.environment_digest,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any] | None) -> EvidenceSnapshot:
        raw = data if isinstance(data, dict) else {}
        ids = raw.get("failure_ids") or ()
        if isinstance(ids, str) or not isinstance(ids, (list, tuple)):
            ids = ()
        return cls(
            revision_digest=str(raw.get("revision_digest", "")),
            transcript_sha256=str(raw.get("transcript_sha256", "")),
            failure_fingerprint=str(raw.get("failure_fingerprint", "")),
            failure_code=str(raw.get("failure_code", "")),
            failure_ids=tuple(str(item) for item in ids),
            environment_digest=str(raw.get("environment_digest", "")),
        )


@dataclass(frozen=True, slots=True)
class AttemptRecord:
    """One durable recovery-memory entry."""

    sequence: int
    kind: str
    outcome: str
    attempted_at: float
    evidence: EvidenceSnapshot

    def __post_init__(self) -> None:
        if self.kind not in ATTEMPT_KINDS:
            raise RecoveryGuardError(f"unknown attempt kind: {self.kind!r}")
        if self.outcome not in ATTEMPT_OUTCOMES:
            raise RecoveryGuardError(f"unknown attempt outcome: {self.outcome!r}")
        _erg_non_neg_int(self.sequence, "sequence")

    def to_dict(self) -> dict[str, Any]:
        return {
            "sequence": self.sequence,
            "kind": self.kind,
            "outcome": self.outcome,
            "attempted_at": round(float(self.attempted_at), 6),
            "evidence": self.evidence.to_dict(),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any] | None) -> AttemptRecord:
        raw = data if isinstance(data, dict) else {}
        return cls(
            sequence=_erg_non_neg_int(raw.get("sequence", 0), "sequence"),
            kind=str(raw.get("kind", "")),
            outcome=str(raw.get("outcome", "")),
            attempted_at=float(raw.get("attempted_at", 0.0) or 0.0),
            evidence=EvidenceSnapshot.from_dict(raw.get("evidence") if isinstance(raw.get("evidence"), dict) else None),
        )


@dataclass(frozen=True, slots=True)
class StagnationVerdict:
    """Classification of one attempt against the recorded failure memory."""

    state: str
    repeat_count: int = 0
    escalate: bool = False
    reason: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "state": self.state,
            "repeat_count": self.repeat_count,
            "escalate": self.escalate,
            "reason": self.reason,
        }


def failure_fingerprint(failure_code: str, failure_ids: Sequence[str]) -> str:
    """Canonical digest of *what* failed, independent of ordering."""
    cleaned = sorted({_erg_bounded(item) for item in (failure_ids or ()) if str(item or "").strip()})
    payload = json.dumps(
        {"code": _erg_bounded(failure_code), "failures": cleaned},
        sort_keys=True,
        separators=(",", ":"),
    )
    return _erg_digest(payload)


def evidence_delta(previous: EvidenceSnapshot, candidate: EvidenceSnapshot) -> dict[str, Any]:
    """Describe what changed between two observations (never a bare boolean)."""
    before = set(previous.failure_ids)
    after = set(candidate.failure_ids)
    return {
        "revision_changed": previous.revision_digest != candidate.revision_digest,
        "transcript_changed": previous.transcript_sha256 != candidate.transcript_sha256,
        "conditions_changed": previous.conditions_digest != candidate.conditions_digest,
        "failure_code_changed": previous.failure_code != candidate.failure_code,
        "failures_added": sorted(after - before),
        "failures_removed": sorted(before - after),
    }


def detect_stagnation(
    history: Sequence[AttemptRecord],
    candidate: EvidenceSnapshot,
    *,
    limits: RecoveryLimits | None = None,
    compare: str = "evidence",
) -> StagnationVerdict:
    """Classify ``candidate`` against the failed attempts already recorded.

    Only failed attempts are memory: a verified attempt is progress by
    definition. An attempt whose key repeats the most recent failure is
    ``stagnant``; one whose key matches an *older* abandoned state is
    ``oscillating``; anything else is ``progress``.

    ``compare="evidence"`` (the default) uses the whole observation, which is
    what a fresh verification attempt is judged by. ``compare="conditions"``
    ignores the transcript and compares only the conditions a *recovery* action
    starts from, because a recovery attempt has not produced a transcript yet —
    it is allowed when the workspace or environment changed.
    """
    if compare not in {"evidence", "conditions"}:
        raise RecoveryGuardError("compare must be 'evidence' or 'conditions'.")
    bounds = limits or RecoveryLimits()
    failed = [record for record in history if record.outcome == "failed"]
    if not failed:
        return StagnationVerdict(state=STAGNATION_FIRST, repeat_count=0, reason="no recorded failure")
    key = candidate.conditions_digest if compare == "conditions" else candidate.evidence_key
    keys = [
        record.evidence.conditions_digest if compare == "conditions" else record.evidence.evidence_key
        for record in failed
    ]
    trailing = 0
    for recorded in reversed(keys):
        if recorded != key:
            break
        trailing += 1
    if trailing:
        repeat_count = trailing + 1
        if compare == "conditions":
            reason = f"identical conditions observed {repeat_count} time(s) with no new evidence"
        else:
            reason = (
                f"identical failure evidence observed {repeat_count} time(s) "
                f"(fingerprint {candidate.failure_fingerprint[:12] or 'n/a'})"
            )
        return StagnationVerdict(
            state=STAGNATION_STAGNANT,
            repeat_count=repeat_count,
            escalate=repeat_count >= bounds.max_identical_attempts,
            reason=reason,
        )
    occurrences = keys.count(key)
    if occurrences:
        return StagnationVerdict(
            state=STAGNATION_OSCILLATING,
            repeat_count=occurrences + 1,
            escalate=True,
            reason=(
                "a previously abandoned state was revisited (patch oscillation; "
                f"{occurrences} earlier occurrence(s))"
            ),
        )
    return StagnationVerdict(state=STAGNATION_PROGRESS, repeat_count=0, reason="evidence changed")


@dataclass(frozen=True, slots=True)
class RecoveryBudgetState:
    """Persisted retry / replan / rollback counters."""

    limits: RecoveryLimits
    retries_used: int = 0
    replans_used: int = 0
    rollbacks_used: int = 0
    pause_requested: bool = False
    pause_reason: str = ""

    def used(self, kind: str) -> int:
        if kind == "retry":
            return self.retries_used
        if kind == "replan":
            return self.replans_used
        if kind == "rollback":
            return self.rollbacks_used
        raise RecoveryGuardError(f"unknown budget kind: {kind!r}")

    def limit(self, kind: str) -> int:
        if kind == "retry":
            return self.limits.max_retries
        if kind == "replan":
            return self.limits.max_replans
        if kind == "rollback":
            return self.limits.max_rollbacks
        raise RecoveryGuardError(f"unknown budget kind: {kind!r}")

    def violation_reason(self, kind: str | None = None) -> str:
        kinds = (kind,) if kind else BUDGET_KINDS
        for candidate in kinds:
            used, limit = self.used(candidate), self.limit(candidate)
            if used >= limit:
                return f"{candidate} budget exhausted ({used}/{limit})"
        return ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "limits": self.limits.to_dict(),
            "retries_used": self.retries_used,
            "replans_used": self.replans_used,
            "rollbacks_used": self.rollbacks_used,
            "pause_requested": self.pause_requested,
            "pause_reason": self.pause_reason,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any] | None) -> RecoveryBudgetState:
        raw = data if isinstance(data, dict) else {}
        return cls(
            limits=RecoveryLimits.from_dict(raw.get("limits") if isinstance(raw.get("limits"), dict) else None),
            retries_used=_erg_non_neg_int(raw.get("retries_used", 0), "retries_used"),
            replans_used=_erg_non_neg_int(raw.get("replans_used", 0), "replans_used"),
            rollbacks_used=_erg_non_neg_int(raw.get("rollbacks_used", 0), "rollbacks_used"),
            pause_requested=bool(raw.get("pause_requested", False)),
            pause_reason=_erg_bounded(raw.get("pause_reason", "")),
        )


class RecoveryGuard:
    """Durable per-task failure memory and recovery budgets.

    One atomically replaced JSON document per task at
    ``<store>/recovery/<task_id>.json`` (directory ``0700``, file ``0600``).
    Attempts are appended and counters incremented in the same write, so a crash
    cannot leave a consumed budget without the attempt that spent it (or the
    reverse), and a fresh process reads the same memory back.
    """

    def __init__(
        self,
        store_root: Path | str,
        *,
        limits: RecoveryLimits | None = None,
        clock: Callable[[], float] = time.time,
    ) -> None:
        self._root = Path(store_root)
        self._default_limits = limits or RecoveryLimits()
        self._clock = clock

    # -- paths -------------------------------------------------------------

    @property
    def directory(self) -> Path:
        return self._root / "recovery"

    def _path(self, task_id: str) -> Path:
        return self.directory / f"{_erg_safe_task_id(task_id)}.json"

    def _ensure_directory(self) -> None:
        self.directory.mkdir(parents=True, exist_ok=True, mode=0o700)
        info = self.directory.lstat()
        if not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode):
            raise RecoveryGuardError(f"recovery store {self.directory} is not a real directory.")
        with_os = getattr(os, "chmod", None)
        if with_os is not None:
            with_os(self.directory, 0o700)

    # -- documents ---------------------------------------------------------

    def _read_document(self, task_id: str) -> dict[str, Any]:
        path = self._path(task_id)
        try:
            info = path.lstat()
        except FileNotFoundError:
            return self._empty_document(task_id)
        if stat.S_ISLNK(info.st_mode):
            raise RecoveryGuardError(f"recovery record {path} must not be a symlink.")
        if not stat.S_ISREG(info.st_mode):
            raise RecoveryGuardError(f"recovery record {path} is not a regular file.")
        if info.st_size > MAX_DOCUMENT_BYTES:
            raise RecoveryGuardError(f"recovery record {path} exceeds {MAX_DOCUMENT_BYTES} bytes.")
        try:
            parsed = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise RecoveryGuardError(f"recovery record {path} is unreadable: {exc}") from exc
        if not isinstance(parsed, dict):
            raise RecoveryGuardError(f"recovery record {path} must be a JSON object.")
        if int(parsed.get("schema_version", 0)) != RECOVERY_SCHEMA_VERSION:
            raise RecoveryGuardError(f"recovery record {path} has an unsupported schema version.")
        if str(parsed.get("task_id", task_id)) != _erg_safe_task_id(task_id):
            raise RecoveryGuardError(f"recovery record {path} belongs to another task.")
        raw_attempts = parsed.get("attempts") or []
        if not isinstance(raw_attempts, list):
            raise RecoveryGuardError(f"recovery record {path} has a malformed attempts list.")
        document = self._empty_document(task_id)
        document["budget"] = RecoveryBudgetState.from_dict(
            parsed.get("budget") if isinstance(parsed.get("budget"), dict) else None
        ).to_dict()
        document["attempts"] = [
            AttemptRecord.from_dict(entry).to_dict() for entry in raw_attempts if isinstance(entry, dict)
        ]
        document["updated_at"] = float(parsed.get("updated_at", 0.0) or 0.0)
        return document

    def _empty_document(self, task_id: str) -> dict[str, Any]:
        return {
            "schema_version": RECOVERY_SCHEMA_VERSION,
            "task_id": _erg_safe_task_id(task_id),
            "budget": RecoveryBudgetState(limits=self._default_limits).to_dict(),
            "attempts": [],
            "updated_at": 0.0,
        }

    def _write_document(self, task_id: str, document: dict[str, Any]) -> None:
        self._ensure_directory()
        path = self._path(task_id)
        document["schema_version"] = RECOVERY_SCHEMA_VERSION
        document["task_id"] = _erg_safe_task_id(task_id)
        document["updated_at"] = round(float(self._clock()), 6)
        payload = json.dumps(document, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        tmp = path.with_name(f".{path.name}.{os.getpid()}.tmp")
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp, path)
        except BaseException:
            tmp.unlink(missing_ok=True)
            raise
        os.chmod(path, 0o600)

    # -- read API ----------------------------------------------------------

    def history(self, task_id: str) -> tuple[AttemptRecord, ...]:
        return tuple(AttemptRecord.from_dict(entry) for entry in self._read_document(task_id)["attempts"])

    def budget(self, task_id: str) -> RecoveryBudgetState:
        return RecoveryBudgetState.from_dict(self._read_document(task_id)["budget"])

    def summary(self, task_id: str, *, limit: int = 10) -> dict[str, Any]:
        """Read-only view for the task-state API: counters, pause flag, recent attempts."""
        document = self._read_document(task_id)
        attempts = [AttemptRecord.from_dict(entry) for entry in document["attempts"]]
        budget = RecoveryBudgetState.from_dict(document["budget"])
        recent = attempts[-max(1, min(int(limit), MAX_ATTEMPTS)) :]
        failures = [record for record in attempts if record.outcome == "failed"]
        verdict = (
            detect_stagnation(failures[:-1], failures[-1].evidence, limits=budget.limits)
            if failures
            else StagnationVerdict(state=STAGNATION_FIRST, reason="no recorded failure")
        )
        return {
            "schema_version": RECOVERY_SCHEMA_VERSION,
            "task_id": _erg_safe_task_id(task_id),
            "budget": budget.to_dict(),
            "pause_requested": budget.pause_requested,
            "pause_reason": budget.pause_reason,
            "attempt_count": len(attempts),
            "failure_count": len(failures),
            "latest_verdict": verdict.to_dict(),
            "recent_attempts": [record.to_dict() for record in recent],
            "updated_at": document["updated_at"],
        }

    # -- write API ---------------------------------------------------------

    def _load(self, task_id: str) -> tuple[dict[str, Any], list[AttemptRecord], RecoveryBudgetState]:
        document = self._read_document(task_id)
        attempts = [AttemptRecord.from_dict(entry) for entry in document["attempts"]]
        budget = RecoveryBudgetState.from_dict(document["budget"])
        return document, attempts, budget

    def _save(
        self,
        task_id: str,
        document: dict[str, Any],
        attempts: Sequence[AttemptRecord],
        budget: RecoveryBudgetState,
    ) -> None:
        document["attempts"] = [record.to_dict() for record in attempts[-MAX_ATTEMPTS:]]
        document["budget"] = budget.to_dict()
        self._write_document(task_id, document)

    def record_attempt(
        self,
        task_id: str,
        *,
        kind: str,
        outcome: str,
        evidence: EvidenceSnapshot,
        now: float | None = None,
    ) -> tuple[AttemptRecord, StagnationVerdict]:
        """Append one attempt durably and return its verdict against prior failures."""
        document, attempts, budget = self._load(task_id)
        verdict = detect_stagnation(attempts, evidence, limits=budget.limits)
        sequence = (attempts[-1].sequence + 1) if attempts else 1
        record = AttemptRecord(
            sequence=sequence,
            kind=kind,
            outcome=outcome,
            attempted_at=float(self._clock() if now is None else now),
            evidence=evidence,
        )
        if outcome == "failed" and verdict.escalate and not budget.pause_requested:
            budget = RecoveryBudgetState(
                limits=budget.limits,
                retries_used=budget.retries_used,
                replans_used=budget.replans_used,
                rollbacks_used=budget.rollbacks_used,
                pause_requested=True,
                pause_reason=verdict.reason,
            )
        self._save(task_id, document, list(attempts) + [record], budget)
        return record, verdict

    def consume(self, task_id: str, kind: str, *, now: float | None = None) -> RecoveryBudgetState:
        """Atomically consume one retry/replan/rollback; persist exhaustion before raising."""
        if kind not in BUDGET_KINDS:
            raise RecoveryGuardError(f"unknown budget kind: {kind!r}")
        document, attempts, budget = self._load(task_id)
        used, limit = budget.used(kind), budget.limit(kind)
        if used >= limit:
            exhausted = RecoveryBudgetState(
                limits=budget.limits,
                retries_used=budget.retries_used,
                replans_used=budget.replans_used,
                rollbacks_used=budget.rollbacks_used,
                pause_requested=True,
                pause_reason=budget.pause_reason or f"{kind} budget exhausted ({used}/{limit})",
            )
            self._save(task_id, document, attempts, exhausted)
            raise RecoveryRejected(f"{kind} budget exhausted ({used}/{limit}); task paused for review.")
        updated = RecoveryBudgetState(
            limits=budget.limits,
            retries_used=budget.retries_used + (1 if kind == "retry" else 0),
            replans_used=budget.replans_used + (1 if kind == "replan" else 0),
            rollbacks_used=budget.rollbacks_used + (1 if kind == "rollback" else 0),
            pause_requested=budget.pause_requested,
            pause_reason=budget.pause_reason,
        )
        self._save(task_id, document, attempts, updated)
        return updated

    def require_progress(
        self,
        task_id: str,
        evidence: EvidenceSnapshot,
        *,
        action: str = "recovery",
        compare: str = "evidence",
    ) -> StagnationVerdict:
        """Refuse ``action`` unless its evidence differs from the recorded failure.

        This is the acceptance-criterion gate: a recovery action needs changed
        evidence or changed conditions. Identical or revisited evidence raises
        :class:`RecoveryRejected` and requests a safe pause; nothing is mutated on
        behalf of the caller.
        """
        document, attempts, budget = self._load(task_id)
        verdict = detect_stagnation(attempts, evidence, limits=budget.limits, compare=compare)
        if verdict.state in (STAGNATION_STAGNANT, STAGNATION_OSCILLATING):
            paused = RecoveryBudgetState(
                limits=budget.limits,
                retries_used=budget.retries_used,
                replans_used=budget.replans_used,
                rollbacks_used=budget.rollbacks_used,
                pause_requested=True,
                pause_reason=budget.pause_reason or verdict.reason,
            )
            self._save(task_id, document, attempts, paused)
            raise RecoveryRejected(
                f"{action} refused: {verdict.reason}. Changed evidence or conditions are required "
                "before another attempt; the task is paused for review."
            )
        return verdict

    def clear(self, task_id: str) -> None:
        """Remove one task's memory (task deletion / explicit reset)."""
        self._path(task_id).unlink(missing_ok=True)

recovery_guard = sys.modules[__name__]

"""Verification evidence for coding-completion claims (M5-P2-04).

`M5-P1-06` refuses to mark a coding task complete without an authoritative patch,
protected-file and test check. A green `exit_code` on its own still says very
little: *which* revision was tested, whether the command actually ran or was
refused, and whether a failure was already there before the agent touched the
workspace. Without those answers a passing run can be attributed to the wrong
commit and a pre-existing failure can be blamed on the change.

This module produces the missing evidence, and nothing else:

1. **A source revision** — the workspace's Git ``HEAD`` (when it is a Git
   repository), the dirty path list, and the SHA-256 of every file the
   verification contract names, folded into one canonical digest. Capture it
   before and after the authoritative command: if the digest changed while the
   command ran, the result cannot be tied to one revision.
2. **A test result tied to it** — the transcript digest covers the command, the
   exit code, the bounded output *and* the revision digest, so two runs that
   agree on all four produce the same evidence hash and any difference is
   visible.
3. **An environment record** — interpreter, platform and working directory the
   command ran in, plus the execution surface.
4. **A failure classification** — every ``FAILED``/``ERROR`` line is classified as
   ``introduced``, ``pre_existing`` (a failure the caller recorded before the
   task started) or ``environmental`` (missing interpreter/package, no disk,
   network or container runtime unavailable). Unparseable output falls back to
   the global markers rather than silently calling the run clean.
5. **A denial verdict** — if the output shows the runtime *refused* to execute
   (plan policy, disabled execution, blocked bypass, missing sandbox runtime) the
   evidence is marked denied. A denied run never counts as a passing one, even
   when its exit code is 0.

The module is standard-library only, never uses a shell, sanitizes the child
environment, bounds the output it keeps, refuses to read through symlinks, and
performs no writes.
"""


import hashlib
import json
import os
import platform
import re
import stat
import subprocess
import sys
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Sequence

EVIDENCE_SCHEMA_VERSION = 1

#: Largest slice of command output kept in the evidence record.
MAX_OUTPUT_BYTES = 64 * 1024
#: Model-facing excerpt length stored alongside the digest.
MAX_EXCERPT_CHARS = 500
#: Bound on the number of failure records carried in one report.
MAX_FAILURES = 50
#: Bound on the number of dirty paths recorded from `git status --porcelain`.
MAX_DIRTY_PATHS = 50
#: Test-tool artifacts that a run creates but that never describe the revision.
#: Filtering them keeps `revision_changed` about source changes, not caches.
ARTIFACT_PATH_PREFIXES: tuple[str, ...] = (
    ".pytest_cache/",
    "__pycache__/",
    ".mypy_cache/",
    ".ruff_cache/",
    ".tox/",
    ".nox/",
    ".venv/",
    "node_modules/",
    "htmlcov/",
    ".harnesses/",
)
ARTIFACT_PATH_SUFFIXES: tuple[str, ...] = (".pyc", ".pyo", ".coverage", ".coverage.xml")

#: Bound on the size of a single file hashed into the revision.
MAX_HASH_BYTES = 8 * 1024 * 1024
#: Wall-clock bound on the `git` probes used for the revision.
GIT_TIMEOUT_S = 10.0

#: Environment variables passed to child processes; everything else is dropped so a
#: verification run cannot inherit credentials the task never needed.
SAFE_ENV_KEYS = frozenset(
    {
        "PATH",
        "HOME",
        "LANG",
        "LC_ALL",
        "LC_CTYPE",
        "TZ",
        "TMPDIR",
        "TEMP",
        "TMP",
        "SYSTEMROOT",
        "PYTHONPATH",
        "PYTHONHASHSEED",
        "PYTHONDONTWRITEBYTECODE",
        "VIRTUAL_ENV",
    }
)

#: Substrings that mean the runtime refused to execute, so there is no test result.
DENIAL_MARKERS: tuple[str, ...] = (
    "code execution is disabled",
    "denied by `plan`",
    "denied by plan",
    "direct executor bypass blocked",
    "requires an explicit approval in standard policy",
    "external mcp tools are disabled",
    "sandbox runtime unavailable",
    "container runtime unavailable",
    "cannot connect to the docker daemon",
    "cannot connect to the podman socket",
)

#: Substrings that mean the environment could not run the command at all.
ENVIRONMENT_MARKERS: tuple[str, ...] = (
    "modulenotfounderror",
    "importerror: no module named",
    "no module named pytest",
    "command not found",
    "executable file not found",
    "errno 28",
    "no space left on device",
    "connection refused",
    "temporary failure in name resolution",
    "nodename nor servname provided",
    "operation not permitted",
)

_PYTEST_FAILURE_RE = re.compile(r"^(?:FAILED|ERROR)\s+(\S+?)(?:\s+-\s+(.*))?$", re.MULTILINE)
_UNITTEST_FAILURE_RE = re.compile(r"^(?:FAIL|ERROR):\s+(\S+)(?:\s+\(([^)]+)\))?", re.MULTILINE)

CLASSIFICATION_INTRODUCED = "introduced"
CLASSIFICATION_PRE_EXISTING = "pre_existing"
CLASSIFICATION_ENVIRONMENTAL = "environmental"

RUN_PASSED = "passed"
RUN_DENIED = "denied"
RUN_INTRODUCED = "introduced"
RUN_PRE_EXISTING_ONLY = "pre_existing_only"
RUN_ENVIRONMENT_BLOCKED = "environmental"
RUN_UNCLASSIFIED = "unclassified"


class VerificationEvidenceError(ValueError):
    """Raised when evidence cannot be captured safely."""


def _bounded(text: str, limit: int = MAX_OUTPUT_BYTES) -> str:
    encoded = text.encode("utf-8", errors="replace")
    if len(encoded) <= limit:
        return text
    return encoded[:limit].decode("utf-8", errors="replace")[-limit:]


def _sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8", errors="replace")).hexdigest()


def _join_output(stdout: str | bytes | None, stderr: str | bytes | None) -> str:
    """Combine captured streams, tolerating the bytes a timeout can hand back."""
    parts: list[str] = []
    for stream in (stdout, stderr):
        if stream is None:
            continue
        parts.append(stream.decode("utf-8", errors="replace") if isinstance(stream, bytes) else str(stream))
    return "\n".join(parts).strip()


def safe_child_env() -> dict[str, str]:
    """The environment a verification command is allowed to inherit."""
    env = {key: value for key, value in os.environ.items() if key in SAFE_ENV_KEYS}
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    env["GIT_TERMINAL_PROMPT"] = "0"
    return env


# ---------------------------------------------------------------------------
# Source revision
# ---------------------------------------------------------------------------


@dataclass(frozen=True, slots=True)
class SourceRevision:
    """The exact workspace state a verification result belongs to."""

    digest: str
    git_head: str = ""
    git_dirty_paths: tuple[str, ...] = ()
    file_digests: tuple[tuple[str, str | None], ...] = ()
    captured_at: float = 0.0

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": EVIDENCE_SCHEMA_VERSION,
            "digest": self.digest,
            "git_head": self.git_head,
            "git_dirty": list(self.git_dirty_paths),
            "files": {path: digest for path, digest in self.file_digests},
            "captured_at": self.captured_at,
        }


def _normalize_rel_path(raw: str) -> str:
    text = str(raw or "").strip()
    if not text:
        raise VerificationEvidenceError("Revision file paths must be non-empty.")
    if "\x00" in text:
        raise VerificationEvidenceError("Revision file paths must not contain NUL.")
    if os.path.isabs(text) or text.startswith("~"):
        raise VerificationEvidenceError(f"Revision file path must be workspace-relative: {text!r}")
    parts = [part for part in text.replace("\\", "/").split("/") if part not in ("", ".")]
    if any(part == ".." for part in parts):
        raise VerificationEvidenceError(f"Revision file path must not traverse upward: {text!r}")
    return "/".join(parts)


def hash_workspace_file(workspace: Path, raw_rel_path: str) -> str | None:
    """SHA-256 of one confined workspace file, or ``None`` when it does not exist.

    Symlinked directories and leaves are refused instead of followed, so the
    revision never hashes bytes from outside the workspace.
    """
    root = Path(workspace).expanduser().resolve(strict=True)
    rel_parts = _normalize_rel_path(raw_rel_path).split("/")
    current = root
    for part in rel_parts[:-1]:
        current = current / part
        if current.is_symlink():
            raise VerificationEvidenceError(f"Refusing to hash through symlinked directory {str(current)!r}.")
        if not current.is_dir():
            return None
    leaf = root.joinpath(*rel_parts)
    try:
        entry = os.lstat(leaf)
    except FileNotFoundError:
        return None
    if stat.S_ISLNK(entry.st_mode):
        raise VerificationEvidenceError(f"Refusing to hash symlink {str(leaf)!r}.")
    if not stat.S_ISREG(entry.st_mode):
        return None
    if entry.st_size > MAX_HASH_BYTES:
        raise VerificationEvidenceError(f"{str(leaf)!r} is larger than the {MAX_HASH_BYTES}-byte revision limit.")
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0)
    fd = os.open(leaf, flags)
    try:
        digest = hashlib.sha256()
        while True:
            chunk = os.read(fd, 1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
        return digest.hexdigest()
    finally:
        os.close(fd)


def _is_artifact_path(rel_path: str) -> bool:
    """True for cache/coverage artifacts a test run creates rather than author."""
    normalized = rel_path.replace("\\", "/").strip()
    if normalized.startswith("./"):
        normalized = normalized[2:]
    if any(normalized.startswith(prefix) or f"/{prefix}" in f"/{normalized}" for prefix in ARTIFACT_PATH_PREFIXES):
        return True
    return any(normalized.endswith(suffix) for suffix in ARTIFACT_PATH_SUFFIXES)


def _git_probe(workspace: Path, *args: str) -> tuple[int, str]:
    try:
        proc = subprocess.run(
            ["git", "-C", str(workspace), *args],
            capture_output=True,
            text=True,
            timeout=GIT_TIMEOUT_S,
            check=False,
            env=safe_child_env(),
        )
    except (OSError, subprocess.TimeoutExpired):
        return 1, ""
    return int(proc.returncode), (proc.stdout or "").strip()


def capture_source_revision(workspace: Path, files: Sequence[str] = ()) -> SourceRevision:
    """Capture the workspace revision a verification result is tied to."""
    root = Path(workspace).expanduser().resolve(strict=True)
    git_head = ""
    dirty: tuple[str, ...] = ()
    if (root / ".git").exists():
        code, head = _git_probe(root, "rev-parse", "HEAD")
        if code == 0 and re.fullmatch(r"[0-9a-f]{40}", head or ""):
            git_head = head
            status_code, status_out = _git_probe(root, "status", "--porcelain=v1", "--untracked-files=all")
            if status_code == 0:
                paths = []
                for line in status_out.splitlines():
                    entry = line[3:].strip() if len(line) > 3 else line.strip()
                    if not entry or _is_artifact_path(entry):
                        continue
                    paths.append(entry[:200])
                dirty = tuple(sorted(set(paths))[:MAX_DIRTY_PATHS])
    normalized = [_normalize_rel_path(rel) for rel in files]
    file_digests = tuple((rel, hash_workspace_file(root, rel)) for rel in sorted(set(normalized)))
    payload = json.dumps(
        {
            "schema_version": EVIDENCE_SCHEMA_VERSION,
            "git_head": git_head,
            "git_dirty": list(dirty),
            "files": [[rel, digest] for rel, digest in file_digests],
        },
        sort_keys=True,
        separators=(",", ":"),
    )
    return SourceRevision(
        digest=hashlib.sha256(payload.encode("utf-8")).hexdigest(),
        git_head=git_head,
        git_dirty_paths=dirty,
        file_digests=file_digests,
        captured_at=round(time.time(), 6),
    )


def environment_snapshot(workspace: Path) -> dict[str, Any]:
    """Record the environment the authoritative command ran in."""
    return {
        "python": platform.python_version(),
        "implementation": platform.python_implementation(),
        "platform": platform.system() or sys.platform,
        "machine": platform.machine(),
        "cwd": str(Path(workspace).expanduser().resolve()),
        "execution_surface": "subprocess",
    }


# ---------------------------------------------------------------------------
# Failure and denial classification
# ---------------------------------------------------------------------------


@dataclass(frozen=True, slots=True)
class FailureRecord:
    """One classified failure reported by a verification command."""

    test_id: str
    kind: str
    detail: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {"test_id": self.test_id, "kind": self.kind, "detail": self.detail[:240]}


def detect_denial(output: str) -> str:
    """Return the denial marker an output matched, or ``""`` when it did not."""
    lowered = (output or "").lower()
    for marker in DENIAL_MARKERS:
        if marker in lowered:
            return marker
    return ""


def _parse_failure_lines(output: str) -> list[tuple[str, str]]:
    """``(test_id, detail)`` pairs from pytest and unittest failure lines."""
    found: list[tuple[str, str]] = []
    for match in _PYTEST_FAILURE_RE.finditer(output or ""):
        test_id = match.group(1).strip().rstrip(":")
        if test_id:
            found.append((test_id[:300], (match.group(2) or "").strip()[:300]))
    for match in _UNITTEST_FAILURE_RE.finditer(output or ""):
        test_id = match.group(1).strip()
        where = (match.group(2) or "").strip()
        if test_id:
            found.append((f"{where}::{test_id}" if where else test_id, ""))
    seen: set[str] = set()
    unique: list[tuple[str, str]] = []
    for test_id, detail in found:
        if test_id in seen:
            continue
        seen.add(test_id)
        unique.append((test_id, detail))
        if len(unique) >= MAX_FAILURES:
            break
    return unique


def _matches_pre_existing(test_id: str, pre_existing: Sequence[str]) -> bool:
    for base in pre_existing:
        candidate = str(base or "").strip()
        if not candidate:
            continue
        if test_id == candidate or test_id.startswith(candidate) or candidate.startswith(test_id):
            return True
    return False


def classify_test_output(
    output: str,
    *,
    exit_code: int | None,
    pre_existing: Sequence[str] = (),
) -> tuple[FailureRecord, ...]:
    """Classify the failures in a verification command's output.

    A failure is ``pre_existing`` when the caller recorded the same test id
    before the task started, ``environmental`` when the line (or, for output we
    cannot parse, the whole output) carries an environment marker, and
    ``introduced`` otherwise. Output with no failure lines and a non-zero exit is
    returned as one unclassified record so it is never mistaken for a clean run.
    """
    parsed = _parse_failure_lines(output)
    lowered = (output or "").lower()
    records: list[FailureRecord] = []
    for test_id, detail in parsed:
        haystack = f"{test_id} {detail}".lower()
        env_marker = next((marker for marker in ENVIRONMENT_MARKERS if marker in haystack), "")
        if env_marker:
            records.append(FailureRecord(test_id=test_id, kind=CLASSIFICATION_ENVIRONMENTAL, detail=env_marker))
        elif _matches_pre_existing(test_id, pre_existing):
            records.append(FailureRecord(test_id=test_id, kind=CLASSIFICATION_PRE_EXISTING, detail=detail))
        else:
            records.append(FailureRecord(test_id=test_id, kind=CLASSIFICATION_INTRODUCED, detail=detail))
    if records:
        return tuple(records)
    if exit_code == 0:
        return ()
    env_marker = next((marker for marker in ENVIRONMENT_MARKERS if marker in lowered), "")
    if env_marker:
        return (FailureRecord(test_id="", kind=CLASSIFICATION_ENVIRONMENTAL, detail=env_marker),)
    if _matches_pre_existing(output, pre_existing):  # pragma: no cover - defensive
        return (FailureRecord(test_id="", kind=CLASSIFICATION_PRE_EXISTING, detail=output[:240]),)
    return (FailureRecord(test_id="", kind=CLASSIFICATION_INTRODUCED, detail=output[:240]),)


# ---------------------------------------------------------------------------
# Evidence record
# ---------------------------------------------------------------------------


@dataclass(frozen=True, slots=True)
class TestEvidence:
    """Auditable result of one authoritative verification command."""

    command: tuple[str, ...]
    exit_code: int | None
    output_sha256: str
    output_excerpt: str
    revision_before: SourceRevision | None = None
    revision_after: SourceRevision | None = None
    denied: str = ""
    failures: tuple[FailureRecord, ...] = ()
    classification: str = RUN_UNCLASSIFIED
    environment: dict[str, Any] = field(default_factory=dict)
    #: The bounded transcript itself. Kept in memory for coverage matching and
    #: never serialised (``output_sha256`` + ``output_excerpt`` are the record).
    output_text: str = field(default="", repr=False, compare=False)

    @property
    def revision_changed(self) -> bool:
        if self.revision_before is None or self.revision_after is None:
            return False
        return self.revision_before.digest != self.revision_after.digest

    @property
    def introduced_failures(self) -> tuple[FailureRecord, ...]:
        return tuple(record for record in self.failures if record.kind == CLASSIFICATION_INTRODUCED)

    @property
    def pre_existing_failures(self) -> tuple[FailureRecord, ...]:
        return tuple(record for record in self.failures if record.kind == CLASSIFICATION_PRE_EXISTING)

    @property
    def environment_failures(self) -> tuple[FailureRecord, ...]:
        return tuple(record for record in self.failures if record.kind == CLASSIFICATION_ENVIRONMENTAL)

    @property
    def passed(self) -> bool:
        return self.classification == RUN_PASSED and not self.denied

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": EVIDENCE_SCHEMA_VERSION,
            "command": list(self.command),
            "exit_code": self.exit_code,
            "output_sha256": self.output_sha256,
            "output_excerpt": self.output_excerpt,
            "revision_before": self.revision_before.to_dict() if self.revision_before else None,
            "revision_after": self.revision_after.to_dict() if self.revision_after else None,
            "revision_changed": self.revision_changed,
            "denied": self.denied,
            "failures": [record.to_dict() for record in self.failures],
            "classification": self.classification,
            "environment": dict(self.environment),
        }


def build_test_evidence(
    command: Sequence[str],
    *,
    exit_code: int | None,
    output: str,
    revision_before: SourceRevision | None = None,
    revision_after: SourceRevision | None = None,
    pre_existing: Sequence[str] = (),
    environment: dict[str, Any] | None = None,
) -> TestEvidence:
    """Assemble the evidence record, tying the transcript hash to the revision."""
    bounded = _bounded(output or "")
    command_tuple = tuple(str(token) for token in command)
    denial = detect_denial(bounded)
    failures = () if denial else classify_test_output(bounded, exit_code=exit_code, pre_existing=pre_existing)
    if denial:
        classification = RUN_DENIED
    elif exit_code is None:
        classification = RUN_UNCLASSIFIED
    elif exit_code == 0 and not failures:
        classification = RUN_PASSED
    elif exit_code == 0:
        classification = RUN_UNCLASSIFIED
    elif failures and all(record.kind == CLASSIFICATION_ENVIRONMENTAL for record in failures):
        classification = RUN_ENVIRONMENT_BLOCKED
    elif failures and all(record.kind == CLASSIFICATION_PRE_EXISTING for record in failures):
        classification = RUN_PRE_EXISTING_ONLY
    elif failures and any(record.kind == CLASSIFICATION_INTRODUCED for record in failures):
        classification = RUN_INTRODUCED
    else:  # pragma: no cover - covered by the classifier's fallback record
        classification = RUN_UNCLASSIFIED
    revision_digest = revision_before.digest if revision_before is not None else ""
    transcript = json.dumps(
        {
            "command": list(command_tuple),
            "exit_code": exit_code,
            "output": bounded,
            "revision_digest": revision_digest,
            "revision_after": revision_after.digest if revision_after is not None else "",
        },
        sort_keys=True,
        separators=(",", ":"),
    )
    return TestEvidence(
        command=command_tuple,
        exit_code=exit_code,
        output_sha256=hashlib.sha256(transcript.encode("utf-8")).hexdigest(),
        output_excerpt=bounded[:MAX_EXCERPT_CHARS],
        revision_before=revision_before,
        revision_after=revision_after,
        denied=denial,
        failures=failures,
        classification=classification,
        environment=dict(environment or {}),
        output_text=bounded,
    )


def evaluate_acceptance_coverage(
    declared: Sequence[tuple[str, Sequence[str]]],
    *,
    output: str,
    failures: Sequence[FailureRecord] = (),
) -> tuple[dict[str, Any], ...]:
    """Map declared acceptance criteria to the tests observed in one transcript.

    A declared test id counts as covered only when it appears verbatim in the
    transcript and is not among the classified failures. This records what the
    run actually printed; it does not assert that the test exercises the
    criterion, so an uncovered criterion fails closed instead of being assumed.
    """
    haystack = output or ""
    failing = {record.test_id for record in failures if record.test_id}
    entries: list[dict[str, Any]] = []
    for criterion, test_ids in declared:
        ids = [str(t).strip() for t in test_ids if str(t).strip()]
        missing = [test_id for test_id in ids if test_id not in haystack or test_id in failing]
        entries.append(
            {
                "criterion": str(criterion)[:300],
                "test_ids": ids,
                "covered": bool(ids) and not missing,
                "missing_test_ids": missing,
            }
        )
    return tuple(entries)


def run_verification_command(
    command: Sequence[str],
    *,
    workspace: Path,
    timeout_s: float,
    files: Sequence[str] = (),
    pre_existing: Sequence[str] = (),
) -> TestEvidence:
    """Run one authoritative verification command and capture its evidence.

    The command is executed without a shell, with a sanitized environment, under a
    timeout, and the workspace revision is captured before and after so a result
    that spanned a change cannot be tied to one revision.
    """
    if not command:
        raise VerificationEvidenceError("A verification command is required.")
    if any((not str(token) or "\x00" in str(token)) for token in command):
        raise VerificationEvidenceError("Verification command tokens must be non-empty and NUL-free.")
    root = Path(workspace).expanduser().resolve(strict=True)
    env = safe_child_env()
    revision_before = capture_source_revision(root, files)
    exit_code: int | None = None
    output = ""
    failure_detail = ""
    try:
        proc = subprocess.run(
            [str(token) for token in command],
            cwd=root,
            capture_output=True,
            text=True,
            timeout=float(timeout_s),
            check=False,
            env=env,
        )
        exit_code = int(proc.returncode)
        output = _join_output(proc.stdout, proc.stderr)
    except subprocess.TimeoutExpired as exc:
        exit_code = None
        output = _join_output(exc.stdout, exc.stderr)
        failure_detail = f"verification command timed out after {timeout_s}s"
    except OSError as exc:
        exit_code = None
        output = f"verification command failed to start: {exc}"
        failure_detail = str(exc)
    revision_after = capture_source_revision(root, files)
    evidence = build_test_evidence(
        command,
        exit_code=exit_code,
        output=output,
        revision_before=revision_before,
        revision_after=revision_after,
        pre_existing=pre_existing,
        environment=environment_snapshot(root),
    )
    if failure_detail and not evidence.denied:
        # A command that never produced an exit code is an execution failure, not a
        # test verdict; keep the reason on the record via an environment failure.
        evidence = TestEvidence(
            command=evidence.command,
            exit_code=evidence.exit_code,
            output_sha256=evidence.output_sha256,
            output_excerpt=evidence.output_excerpt,
            revision_before=evidence.revision_before,
            revision_after=evidence.revision_after,
            denied=evidence.denied,
            failures=(
                FailureRecord(test_id="", kind=CLASSIFICATION_ENVIRONMENTAL, detail=failure_detail[:240]),
            )
            + evidence.failures,
            classification=RUN_ENVIRONMENT_BLOCKED,
            environment=evidence.environment,
            output_text=evidence.output_text,
        )
    return evidence

verification_evidence = sys.modules[__name__]

"""Process supervision, bounded tree/detached-child termination, and durable containment (M5-P3-03).

Stdlib-only module (inlined into ``studio.py`` by ``scripts/build_studio.py``; private
globals use the ``_ps_`` / ``_PS_`` prefix to avoid namespace collisions).

Guarantees:
1. Subprocess identities (``pid``, ``pgid``, ``uid``, OS ``start_fingerprint``,
   ``container_name``, ``supervision_id``) and authoritative ownership metadata
   (``session_id``, ``task_id``, ``epoch``, ``worker_id``, ``boot_id``, ``action_id``,
   acquired ``barriers``) are tracked in memory and durably recorded before execution
   completes.
2. Cancellation, abort, ownership loss (lease fencing / takeover), timeout, crash
   recovery, and security incidents execute a bounded 3-stage containment pipeline:
   origin fencing -> cooperative ``SIGTERM`` -> bounded grace wait -> ``SIGKILL`` across
   process groups AND ``os.setsid()`` detached descendants (tracked via
   ``M5_SUPERVISION_ID`` and transitive ``ppid`` chains), never signaling PID <= 1,
   Studio's own PID/PGID, or a recycled OS PID whose ``start_fingerprint`` changed.
3. Unresolved side effects and unverified/lingering process barriers are persisted
   atomically in ``<store_dir>/containment/state.json`` (``0700`` dir, ``0600`` file),
   surviving process crashes and restarts, blocking conflicting actions and conflicting
   task/workspace resumption until reconciled.
4. Stale / fenced workers, superseded epochs, revoked supervision scopes, and foreign
   process boots are durably fenced and cannot admit new actions across any tool class.
"""


import asyncio
from collections.abc import Awaitable, Callable, Mapping, Sequence
import contextlib
import contextvars
from dataclasses import dataclass
import json
import os
from pathlib import Path
import re
import signal
import stat
import subprocess
import threading
import time
from typing import Any
import uuid

PS_CONTAINMENT_SCHEMA_VERSION = "m5-process-containment-v1"
CONTAINMENT_SCHEMA_VERSION = PS_CONTAINMENT_SCHEMA_VERSION
SUPERVISION_ENV_VAR = "M5_SUPERVISION_ID"
SUPERVISION_ENV_KEY = SUPERVISION_ENV_VAR

DEFAULT_COOPERATIVE_GRACE_S = 0.25
DEFAULT_FORCE_KILL_WAIT_S = 0.50
MAX_FENCED_ORIGINS = 500
MAX_INCIDENT_HISTORY = 200

_PS_SUPERVISION_ID_RE = re.compile(r"^sup-[0-9a-f]{12,32}$")
_PS_SAFE_ID_RE = re.compile(r"^[A-Za-z0-9_.:/-]{1,200}$")
_PS_ACTIVE_SUPERVISION_ID: contextvars.ContextVar[str] = contextvars.ContextVar(
    "m5_active_supervision_id",
    default="",
)


def current_supervision_id() -> str:
    """Return the active ``supervision_id`` in the current execution context or OS env, if any."""
    ctx_val = _PS_ACTIVE_SUPERVISION_ID.get()
    if ctx_val:
        return ctx_val
    return (os.environ.get(SUPERVISION_ENV_KEY) or "").strip()


class ProcessSupervisionError(RuntimeError):
    """Base error for process supervision and containment failures."""


class ContainmentIntegrityError(ProcessSupervisionError):
    """Raised when durable containment state is corrupt, tampered, or a symlink."""


class ContainmentHoldActiveError(ProcessSupervisionError):
    """Raised when attempting to clear a hold or resume while a barrier/process remains active."""


class StaleOriginFencedError(PermissionError):
    """Raised when a stale or fenced worker/epoch/process attempts to spawn or admit actions."""


@dataclass(frozen=True, slots=True)
class ProcessProbe:
    """Point-in-time OS liveness and identity measurement for one PID."""

    pid: int
    uid: int
    ppid: int
    pgid: int
    state: str
    start_fingerprint: str
    alive: bool


@dataclass(frozen=True, slots=True)
class SupervisedProcessRecord:
    """Authoritative identity, ownership, and barrier record for a supervised subprocess."""

    supervision_id: str
    pid: int
    pgid: int
    uid: int
    start_fingerprint: str
    container_name: str | None
    tool_name: str
    session_id: str
    task_id: str | None
    epoch: int | None
    worker_id: str | None
    boot_id: str
    action_id: str
    workspace_root: str
    barriers: tuple[tuple[str, str], ...]
    started_at: float
    status: str = "running"
    containment_reason: str = ""

    def to_mapping(self) -> dict[str, Any]:
        return {
            "supervision_id": self.supervision_id,
            "pid": self.pid,
            "pgid": self.pgid,
            "uid": self.uid,
            "start_fingerprint": self.start_fingerprint,
            "container_name": self.container_name,
            "tool_name": self.tool_name,
            "session_id": self.session_id,
            "task_id": self.task_id,
            "epoch": self.epoch,
            "worker_id": self.worker_id,
            "boot_id": self.boot_id,
            "action_id": self.action_id,
            "workspace_root": self.workspace_root,
            "barriers": [[t, m] for t, m in self.barriers],
            "started_at": self.started_at,
            "status": self.status,
            "containment_reason": self.containment_reason,
        }

    @classmethod
    def from_mapping(cls, raw: Mapping[str, Any]) -> SupervisedProcessRecord:
        raw_barriers = raw.get("barriers")
        if not isinstance(raw_barriers, list):
            raise ContainmentIntegrityError("SupervisedProcessRecord.barriers must be a list.")
        parsed_barriers: list[tuple[str, str]] = []
        for item in raw_barriers:
            if not isinstance(item, list) or len(item) != 2:
                raise ContainmentIntegrityError("Malformed barrier pair in SupervisedProcessRecord.")
            parsed_barriers.append((str(item[0]), str(item[1])))
        epoch_raw = raw.get("epoch")
        return cls(
            supervision_id=str(raw["supervision_id"]),
            pid=int(raw["pid"]),
            pgid=int(raw["pgid"]),
            uid=int(raw.get("uid", -1)),
            start_fingerprint=str(raw.get("start_fingerprint") or ""),
            container_name=str(raw["container_name"]) if raw.get("container_name") else None,
            tool_name=str(raw.get("tool_name") or ""),
            session_id=str(raw.get("session_id") or ""),
            task_id=str(raw["task_id"]) if raw.get("task_id") is not None else None,
            epoch=int(epoch_raw) if epoch_raw is not None else None,
            worker_id=str(raw["worker_id"]) if raw.get("worker_id") is not None else None,
            boot_id=str(raw.get("boot_id") or ""),
            action_id=str(raw.get("action_id") or ""),
            workspace_root=str(raw.get("workspace_root") or ""),
            barriers=tuple(parsed_barriers),
            started_at=float(raw.get("started_at") or 0.0),
            status=str(raw.get("status") or "running"),
            containment_reason=str(raw.get("containment_reason") or ""),
        )


@dataclass(frozen=True, slots=True)
class TerminationOutcome:
    """Measured outcome of bounded cooperative cancel -> force kill -> reap verification."""

    supervision_id: str
    reason: str
    cooperative_sent: bool
    escalated_kill: bool
    signaled_pids: tuple[int, ...] = ()
    detached_pids: tuple[int, ...] = ()
    lingering_pids: tuple[tuple[int, str], ...] = ()
    cleanly_reaped: bool = True
    elapsed_ms: int = 0

    def to_mapping(self) -> dict[str, Any]:
        return {
            "supervision_id": self.supervision_id,
            "reason": self.reason,
            "cooperative_sent": self.cooperative_sent,
            "escalated_kill": self.escalated_kill,
            "signaled_pids": list(self.signaled_pids),
            "detached_pids": list(self.detached_pids),
            "lingering_pids": [[pid, fp] for pid, fp in self.lingering_pids],
            "cleanly_reaped": self.cleanly_reaped,
            "elapsed_ms": self.elapsed_ms,
        }


@dataclass(frozen=True, slots=True)
class PersistedBarrierHold:
    """Durable barrier hold representing an unresolved side effect or lingering process."""

    hold_id: str
    session_id: str = ""
    task_id: str | None = None
    epoch: int | None = None
    worker_id: str | None = None
    action_id: str = ""
    supervision_id: str = ""
    tool_name: str = ""
    footprint_scope: str = ""
    workspace_root: str = ""
    barriers: tuple[tuple[str, str], ...] = ()
    reason: str = "unresolved_side_effect"
    lingering_pids: tuple[tuple[int, str], ...] = ()
    created_at: float = 0.0
    updated_at: float = 0.0

    def to_mapping(self) -> dict[str, Any]:
        return {
            "hold_id": self.hold_id,
            "session_id": self.session_id,
            "task_id": self.task_id,
            "epoch": self.epoch,
            "worker_id": self.worker_id,
            "action_id": self.action_id,
            "supervision_id": self.supervision_id,
            "tool_name": self.tool_name,
            "footprint_scope": self.footprint_scope,
            "workspace_root": self.workspace_root,
            "barriers": [[t, m] for t, m in self.barriers],
            "reason": self.reason,
            "lingering_pids": [[pid, fp] for pid, fp in self.lingering_pids],
            "created_at": self.created_at,
            "updated_at": self.updated_at,
        }

    @classmethod
    def from_mapping(cls, raw: Mapping[str, Any]) -> PersistedBarrierHold:
        raw_barriers = raw.get("barriers")
        raw_lingering = raw.get("lingering_pids") or []
        if not isinstance(raw_barriers, list) or not isinstance(raw_lingering, list):
            raise ContainmentIntegrityError("Malformed barriers/lingering_pids in PersistedBarrierHold.")
        barriers = tuple(
            (str(b[0]), str(b[1]))
            for b in raw_barriers
            if isinstance(b, list) and len(b) == 2
        )
        lingering = tuple(
            (int(item[0]), str(item[1]))
            for item in raw_lingering
            if isinstance(item, list) and len(item) == 2
        )
        epoch_raw = raw.get("epoch")
        return cls(
            hold_id=str(raw["hold_id"]),
            session_id=str(raw.get("session_id") or ""),
            task_id=str(raw["task_id"]) if raw.get("task_id") is not None else None,
            epoch=int(epoch_raw) if epoch_raw is not None else None,
            worker_id=str(raw["worker_id"]) if raw.get("worker_id") is not None else None,
            action_id=str(raw.get("action_id") or ""),
            supervision_id=str(raw.get("supervision_id") or ""),
            tool_name=str(raw.get("tool_name") or ""),
            footprint_scope=str(raw.get("footprint_scope") or ""),
            workspace_root=str(raw.get("workspace_root") or ""),
            barriers=barriers,
            reason=str(raw.get("reason") or "unresolved_side_effect"),
            lingering_pids=lingering,
            created_at=float(raw.get("created_at") or 0.0),
            updated_at=float(raw.get("updated_at") or 0.0),
        )


@dataclass(frozen=True, slots=True)
class FencedOriginRecord:
    """Durable record of a fenced worker, epoch, supervision scope, or quarantined session."""

    origin_key: str
    reason: str
    session_id: str = ""
    task_id: str | None = None
    epoch: int | None = None
    worker_id: str | None = None
