"""Persisted workflow and durable root-task/milestone state machine (M5-P1-05)."""


import contextlib
import hashlib
import json
import os
import sqlite3
import subprocess
import time
from dataclasses import dataclass, field, replace
from pathlib import Path
from typing import Any, Literal, Sequence


WorkflowStatus = Literal["pending", "running", "paused", "completed", "failed", "cancelled"]
_STATUSES = frozenset({"pending", "running", "paused", "completed", "failed", "cancelled"})
_TRANSITIONS: dict[str, frozenset[str]] = {
    "pending": frozenset({"running", "cancelled"}),
    "running": frozenset({"paused", "completed", "failed", "cancelled"}),
    "paused": frozenset({"running", "cancelled"}),
    "completed": frozenset(),
    "failed": frozenset({"running", "cancelled"}),
    "cancelled": frozenset(),
}

# Authoritative M5-P1-05 task/milestone transition matrix.
# Note: 'paused', 'blocked', 'failed', and 'waiting_approval' CANNOT transition
# directly to 'completed' — only an active 'running' task with zero pending
# pause/cancel requests, zero incomplete milestones, and zero unresolved side
# effects may enter 'completed'.
TASK_STATE_TRANSITIONS: dict[str, frozenset[str]] = {
    "pending": frozenset({"running", "paused", "blocked", "cancelled"}),
    "running": frozenset({"running", "paused", "waiting_approval", "blocked", "completed", "failed", "cancelled"}),
    "waiting_approval": frozenset({"running", "paused", "blocked", "failed", "cancelled"}),
    "paused": frozenset({"running", "blocked", "cancelled"}),
    "blocked": frozenset({"running", "paused", "failed", "cancelled"}),
    "failed": frozenset({"running", "paused", "blocked", "cancelled"}),
    "completed": frozenset(),
    "cancelled": frozenset(),
}


class WorkflowStateError(ValueError):
    """Raised when workflow state or transition input is invalid."""


class WorkflowTransitionRejected(RuntimeError):
    """Raised when a requested transition is not legal for current state."""


class FalseCompletionRejected(WorkflowTransitionRejected):
    """Raised when a task claims completion without verified patch/test/ledger evidence."""


_SAFE_VERIFY_ENV_KEYS: frozenset[str] = frozenset(
    {"PATH", "HOME", "TMPDIR", "TEMP", "TMP", "LANG", "LC_ALL", "PYTHONPATH", "VIRTUAL_ENV", "SYSTEMROOT"}
)


def _normalize_workspace_rel_path(raw_path: str, field_name: str = "path") -> str:
    if not isinstance(raw_path, str) or not raw_path.strip() or "\x00" in raw_path:
        raise WorkflowStateError(f"{field_name} must be a non-empty relative path without NUL characters.")
    cleaned = raw_path.strip().replace("\\", "/")
    p = Path(cleaned)
    if p.is_absolute():
        raise WorkflowStateError(f"{field_name} must be relative to workspace_dir: {raw_path!r}")
    parts = [pt for pt in p.parts if pt not in ("", ".")]
    if not parts or any(pt == ".." for pt in parts):
        raise WorkflowStateError(f"{field_name} must stay within workspace_dir without '..': {raw_path!r}")
    return "/".join(parts)


def _resolve_safe_workspace_target(workspace_dir: Path, rel_path: str) -> Path:
    ws_root = workspace_dir.resolve()
    norm = _normalize_workspace_rel_path(rel_path)
    cursor = ws_root
    for part in Path(norm).parts:
        cursor = cursor / part
        if cursor.is_symlink():
            raise WorkflowStateError(f"Symlink escape rejected in verification path: {rel_path!r}")
    resolved = cursor.resolve()
    if resolved != ws_root and ws_root not in resolved.parents:
        raise WorkflowStateError(f"Verification path escapes workspace_dir: {rel_path!r}")
    return resolved


def compute_workspace_file_sha256(workspace_dir: Path, rel_path: str) -> str | None:
    """Return SHA-256 hex digest of ``workspace_dir / rel_path`` or ``None`` if absent."""
    target = _resolve_safe_workspace_target(workspace_dir, rel_path)
    if not target.exists():
        return None
    if not target.is_file():
        raise WorkflowStateError(f"Verification target is not a regular file: {rel_path!r}")
    return hashlib.sha256(target.read_bytes()).hexdigest()


@dataclass(frozen=True, slots=True)
class TaskVerificationSpec:
    """Authoritative patch, protected-file, ledger, and test verification contract (M5-P1-06)."""

    require_managed_edit: bool = True
    require_git_diff: bool = False
    required_modified_files: tuple[str, ...] = ()
    required_files: tuple[str, ...] = ()
    protected_files: dict[str, str] = field(default_factory=dict)
    baseline_file_digests: dict[str, str | None] = field(default_factory=dict)
    require_agent_test_action: bool = False
    test_command: tuple[str, ...] = ()
    expected_test_output_contains: tuple[str, ...] = ()
    timeout_s: float = 30.0
    #: Test ids known to fail before this task ran (M5-P2-04). A failure that
    #: matches one of these is reported as pre-existing rather than introduced.
    pre_existing_failures: tuple[str, ...] = ()
    #: When true, a run whose only failures are pre-existing may still verify.
    #: Default false: pre-existing failures are classified honestly but completion
    #: still needs a clean run.
    allow_pre_existing_failures: bool = False
    #: Require the workspace revision to be identical before and after the
    #: authoritative test command, so the result is tied to one revision.
    require_revision_stability: bool = True
    #: Cheapest check that must pass before the broader command runs (M5-P2-04
    #: staged verification). A failing first stage stops the broader run.
    targeted_test_command: tuple[str, ...] = ()
    #: ``(criterion, test_ids)`` pairs declared by the caller. Coverage is
    #: recorded from the observed transcript, and an uncovered criterion fails
    #: completion instead of being assumed covered.
    acceptance_coverage: tuple[tuple[str, tuple[str, ...]], ...] = ()

    def __post_init__(self) -> None:
        norm_mod = tuple(_normalize_workspace_rel_path(p, "required_modified_files") for p in self.required_modified_files)
        norm_req = tuple(_normalize_workspace_rel_path(p, "required_files") for p in self.required_files)
        norm_prot: dict[str, str] = {}
        for k, v in self.protected_files.items():
            nk = _normalize_workspace_rel_path(k, "protected_files")
            if not isinstance(v, str) or len(v.strip()) != 64:
                raise WorkflowStateError(f"protected_files[{nk!r}] must be a 64-char SHA-256 hex digest.")
            norm_prot[nk] = v.strip().lower()
        norm_base: dict[str, str | None] = {}
        for k, bval in self.baseline_file_digests.items():
            nk = _normalize_workspace_rel_path(k, "baseline_file_digests")
            if bval is not None:
                if not isinstance(bval, str) or len(bval.strip()) != 64:
                    raise WorkflowStateError(f"baseline_file_digests[{nk!r}] must be None or a 64-char SHA-256 hex digest.")
                norm_base[nk] = bval.strip().lower()
            else:
                norm_base[nk] = None
        cmd_tuple = tuple(str(tok) for tok in self.test_command)
        if any((not tok or "\x00" in tok) for tok in cmd_tuple):
            raise WorkflowStateError("test_command tokens must be non-empty strings without NUL.")
        exp_sub = tuple(str(s) for s in self.expected_test_output_contains if str(s))
        if isinstance(self.timeout_s, bool) or not isinstance(self.timeout_s, (int, float)) or self.timeout_s <= 0 or self.timeout_s > 120.0:
            raise WorkflowStateError("timeout_s must be in (0, 120].")
        norm_pre: list[str] = []
        for raw_fail in self.pre_existing_failures:
            cleaned = str(raw_fail or "").strip()
            if not cleaned:
                continue
            if "\x00" in cleaned:
                raise WorkflowStateError("pre_existing_failures entries must be NUL-free strings.")
            if cleaned not in norm_pre:
                norm_pre.append(cleaned[:300])
        targeted_cmd = tuple(str(tok) for tok in self.targeted_test_command)
        if any((not tok or "\x00" in tok) for tok in targeted_cmd):
            raise WorkflowStateError("targeted_test_command tokens must be non-empty strings without NUL.")
        norm_cov: list[tuple[str, tuple[str, ...]]] = []
        seen_criteria: set[str] = set()
        for entry in self.acceptance_coverage:
            if not isinstance(entry, (tuple, list)) or len(entry) != 2:
                raise WorkflowStateError("acceptance_coverage entries must be (criterion, test_ids) pairs.")
            criterion = str(entry[0] or "").strip()
            raw_ids = entry[1] if entry[1] is not None else ()
            if not criterion or "\x00" in criterion:
                raise WorkflowStateError("acceptance_coverage criteria must be non-empty, NUL-free strings.")
            if isinstance(raw_ids, str) or not isinstance(raw_ids, (list, tuple)):
                raise WorkflowStateError("acceptance_coverage test ids must be a list/tuple of strings.")
            ids = tuple(dict.fromkeys(str(t).strip()[:300] for t in raw_ids if str(t).strip()))
            if not ids:
                raise WorkflowStateError(f"acceptance_coverage[{criterion!r}] needs at least one test id.")
            if criterion[:300] in seen_criteria:
                continue
            seen_criteria.add(criterion[:300])
            norm_cov.append((criterion[:300], ids))
        object.__setattr__(self, "targeted_test_command", targeted_cmd)
        object.__setattr__(self, "acceptance_coverage", tuple(norm_cov[:100]))
        object.__setattr__(self, "pre_existing_failures", tuple(norm_pre[:200]))
        object.__setattr__(self, "required_modified_files", norm_mod)
        object.__setattr__(self, "required_files", norm_req)
        object.__setattr__(self, "protected_files", norm_prot)
        object.__setattr__(self, "baseline_file_digests", norm_base)
        object.__setattr__(self, "test_command", cmd_tuple)
        object.__setattr__(self, "expected_test_output_contains", exp_sub)
        object.__setattr__(self, "timeout_s", float(self.timeout_s))

    def to_dict(self) -> dict[str, Any]:
        return {
            "require_managed_edit": self.require_managed_edit,
            "require_git_diff": self.require_git_diff,
            "required_modified_files": list(self.required_modified_files),
            "required_files": list(self.required_files),
            "protected_files": dict(sorted(self.protected_files.items())),
            "baseline_file_digests": dict(sorted(self.baseline_file_digests.items())),
            "require_agent_test_action": self.require_agent_test_action,
            "test_command": list(self.test_command),
            "expected_test_output_contains": list(self.expected_test_output_contains),
            "timeout_s": round(self.timeout_s, 4),
            "pre_existing_failures": list(self.pre_existing_failures),
            "allow_pre_existing_failures": self.allow_pre_existing_failures,
            "require_revision_stability": self.require_revision_stability,
            "targeted_test_command": list(self.targeted_test_command),
            "acceptance_coverage": [
                {"criterion": criterion, "test_ids": list(ids)}
                for criterion, ids in self.acceptance_coverage
            ],
        }

    def sha256(self) -> str:
        canonical = json.dumps(self.to_dict(), sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> TaskVerificationSpec:
        if not isinstance(data, dict):
            raise WorkflowStateError("TaskVerificationSpec data must be a dict.")
        raw_mod = data.get("required_modified_files") or ()
        raw_req = data.get("required_files") or ()
        raw_prot = data.get("protected_files") or {}
        raw_base = data.get("baseline_file_digests") or {}
        raw_cmd = data.get("test_command") or ()
        raw_exp = data.get("expected_test_output_contains") or ()
        if not isinstance(raw_mod, (list, tuple)) or not isinstance(raw_req, (list, tuple)):
            raise WorkflowStateError("required_modified_files and required_files must be sequences.")
        if not isinstance(raw_prot, dict) or not isinstance(raw_base, dict):
            raise WorkflowStateError("protected_files and baseline_file_digests must be dicts.")
        if isinstance(raw_cmd, str) or not isinstance(raw_cmd, (list, tuple)):
            raise WorkflowStateError("test_command must be an argv list/tuple of strings.")
        if isinstance(raw_exp, str) or not isinstance(raw_exp, (list, tuple)):
            raise WorkflowStateError("expected_test_output_contains must be a list/tuple of strings.")
        return cls(
            require_managed_edit=bool(data.get("require_managed_edit", True)),
            require_git_diff=bool(data.get("require_git_diff", False)),
            required_modified_files=tuple(str(x) for x in raw_mod),
            required_files=tuple(str(x) for x in raw_req),
            protected_files={str(k): str(v) for k, v in raw_prot.items()},
            baseline_file_digests={str(k): (None if v is None else str(v)) for k, v in raw_base.items()},
            require_agent_test_action=bool(data.get("require_agent_test_action", False)),
            test_command=tuple(str(x) for x in raw_cmd),
            expected_test_output_contains=tuple(str(x) for x in raw_exp),
            timeout_s=float(data.get("timeout_s", 30.0)),
            pre_existing_failures=tuple(str(x) for x in (data.get("pre_existing_failures") or ())),
            allow_pre_existing_failures=bool(data.get("allow_pre_existing_failures", False)),
            require_revision_stability=bool(data.get("require_revision_stability", True)),
            targeted_test_command=tuple(str(x) for x in (data.get("targeted_test_command") or ())),
            acceptance_coverage=tuple(
                (str(entry.get("criterion", "")), tuple(str(t) for t in (entry.get("test_ids") or ())))
                for entry in (data.get("acceptance_coverage") or ())
                if isinstance(entry, dict)
            ),
        )


@dataclass(frozen=True, slots=True)
class TaskVerificationReport:
    """Auditable outcome of authoritative patch + test + ledger completion verification."""

    verified: bool
    spec_sha256: str = ""
    failure_code: str = ""
    failure_detail: str = ""
    modified_files: tuple[str, ...] = ()
    patch_sha256: str = ""
    test_exit_code: int | None = None
    test_output_excerpt: str = ""
    test_sha256: str = ""
    committed_edit_action_ids: tuple[str, ...] = ()
    committed_test_action_ids: tuple[str, ...] = ()
    evidence_refs: tuple[workflow_checkpoints.EvidenceRef, ...] = ()
    #: Digest of the workspace revision the result is tied to (M5-P2-04).
    source_revision: str = ""
    revision: dict[str, Any] = field(default_factory=dict)
    test_evidence: dict[str, Any] = field(default_factory=dict)
    environment: dict[str, Any] = field(default_factory=dict)
    staged_test_evidence: dict[str, Any] = field(default_factory=dict)
    acceptance_coverage: tuple[dict[str, Any], ...] = ()
    failure_classification: str = ""
    denied: bool = False
    #: Recovery-memory verdict for this attempt (M5-P2-05): state, repeat count,
    #: escalation, and whether a safe pause was requested.
    stagnation: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "verified": self.verified,
            "spec_sha256": self.spec_sha256,
            "failure_code": self.failure_code,
            "failure_detail": self.failure_detail,
            "modified_files": list(self.modified_files),
            "patch_sha256": self.patch_sha256,
            "test_exit_code": self.test_exit_code,
            "test_output_excerpt": self.test_output_excerpt,
            "test_sha256": self.test_sha256,
            "committed_edit_action_ids": list(self.committed_edit_action_ids),
            "committed_test_action_ids": list(self.committed_test_action_ids),
            "evidence_refs": [ref.to_dict() for ref in self.evidence_refs],
            "source_revision": self.source_revision,
            "revision": dict(self.revision),
            "test_evidence": dict(self.test_evidence),
            "environment": dict(self.environment),
            "staged_test_evidence": dict(self.staged_test_evidence),
            "acceptance_coverage": [dict(entry) for entry in self.acceptance_coverage],
            "failure_classification": self.failure_classification,
            "denied": self.denied,
            "stagnation": dict(self.stagnation),
        }


@dataclass(frozen=True, slots=True)
class WorkflowRecord:
    workflow_id: str
    state: WorkflowStatus
    version: int
    updated_at: str


class PersistedWorkflowState:
    """SQLite state store whose transitions are validated inside transactions."""

    def __init__(self, database: Path) -> None:
        self.database = Path(database)
        if "\x00" in str(self.database):
            raise WorkflowStateError("database path must not contain NUL characters.")
        self.database.parent.mkdir(parents=True, exist_ok=True)
        self._initialize()

    def _connect(self) -> sqlite3.Connection:
        connection = sqlite3.connect(self.database, timeout=5.0)
        connection.row_factory = sqlite3.Row
        return connection

    def _initialize(self) -> None:
        with self._connect() as connection:
            connection.execute(
                """
                CREATE TABLE IF NOT EXISTS workflow_state (
                    workflow_id TEXT PRIMARY KEY,
                    state TEXT NOT NULL,
                    version INTEGER NOT NULL,
                    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    CHECK (state IN ('pending', 'running', 'paused', 'completed', 'failed', 'cancelled')),
                    CHECK (version >= 0)
                )
                """
            )

    @staticmethod
    def _workflow_id(workflow_id: str) -> str:
        if not isinstance(workflow_id, str) or not workflow_id.strip() or "\x00" in workflow_id:
            raise WorkflowStateError("workflow_id must be a non-empty string without NUL characters.")
        return workflow_id.strip()

    @staticmethod
    def _status(status: str) -> WorkflowStatus:
        if status not in _STATUSES:
            raise WorkflowStateError(f"unknown workflow state: {status}")
        return status  # type: ignore[return-value]

    @staticmethod
    def _record(row: sqlite3.Row | None) -> WorkflowRecord | None:
        if row is None:
            return None
        return WorkflowRecord(row["workflow_id"], row["state"], row["version"], row["updated_at"])

    def create(self, workflow_id: str, *, state: WorkflowStatus = "pending") -> WorkflowRecord:
        identifier = self._workflow_id(workflow_id)
        normalized = self._status(state)
        try:
            with self._connect() as connection:
                connection.execute(
                    "INSERT INTO workflow_state(workflow_id, state, version) VALUES (?, ?, 0)",
                    (identifier, normalized),
                )
                row = connection.execute("SELECT * FROM workflow_state WHERE workflow_id = ?", (identifier,)).fetchone()
        except sqlite3.IntegrityError as exc:
            raise WorkflowStateError("workflow already exists.") from exc
        record = self._record(row)
        assert record is not None
        return record

    def get(self, workflow_id: str) -> WorkflowRecord | None:
        identifier = self._workflow_id(workflow_id)
        with self._connect() as connection:
            return self._record(connection.execute("SELECT * FROM workflow_state WHERE workflow_id = ?", (identifier,)).fetchone())

    def transition(self, workflow_id: str, target: WorkflowStatus, *, expected_version: int | None = None) -> WorkflowRecord:
        identifier = self._workflow_id(workflow_id)
        next_state = self._status(target)
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute("SELECT * FROM workflow_state WHERE workflow_id = ?", (identifier,)).fetchone()
            current = self._record(row)
            if current is None:
                raise WorkflowStateError("workflow does not exist.")
            if expected_version is not None and current.version != expected_version:
                raise WorkflowTransitionRejected("workflow version changed; refresh before transitioning.")
            if next_state not in _TRANSITIONS[current.state]:
                raise WorkflowTransitionRejected(f"transition {current.state} -> {next_state} is not allowed.")
            connection.execute(
                "UPDATE workflow_state SET state = ?, version = version + 1, updated_at = CURRENT_TIMESTAMP WHERE workflow_id = ?",
                (next_state, identifier),
            )
            updated = connection.execute("SELECT * FROM workflow_state WHERE workflow_id = ?", (identifier,)).fetchone()
        result = self._record(updated)
        assert result is not None
        return result


@dataclass(frozen=True, slots=True)
class TaskControlResult:
    """Outcome of a safe-boundary pause or cancel command."""

    task: runtime_persistence.TaskRecord
    budget: execution_budget.TaskBudgetState
    deferred_to_safe_boundary: bool
    unresolved_action_ids: tuple[str, ...] = ()


@dataclass(frozen=True, slots=True)
class ResumedTaskPlan:
    """Validated recovery plan produced before resuming an interrupted task."""

    task: runtime_persistence.TaskRecord
    budget: execution_budget.TaskBudgetState
    checkpoint: workflow_checkpoints.TaskCheckpointRecord | None
    milestones: tuple[runtime_persistence.TaskRecord, ...]
    next_step: int
    completed_milestone_ids: tuple[str, ...]


@dataclass(frozen=True, slots=True)
class RecoverySweepReport:
    """Summary of incomplete transitions and staged checkpoints reconciled on recovery."""

    recovered_task_ids: tuple[str, ...]
    blocked_task_ids: tuple[str, ...]
    cancelled_task_ids: tuple[str, ...]
    reconciled_checkpoint_ids: tuple[str, ...]
    reconciled_milestone_ids: tuple[str, ...]


def _validate_identifier(value: str, label: str = "task_id") -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise WorkflowStateError(f"{label} must be a non-empty string without NUL characters.")
    cleaned = value.strip()
    if len(cleaned) > 128:
        raise WorkflowStateError(f"{label} exceeds maximum length 128.")
    return cleaned


def milestone_task_id(root_task_id: str, milestone_key: str) -> str:
    """Build deterministic child ``runtime_tasks.task_id`` for a milestone."""
    root = _validate_identifier(root_task_id, "root_task_id")
    key = _validate_identifier(milestone_key, "milestone_key")
    candidate = f"{root}::ms:{key}"
    if len(candidate) <= 128:
        return candidate
    import hashlib

    digest = hashlib.sha256(key.encode("utf-8")).hexdigest()[:16]
    return f"{root[:96]}::ms:{digest}"


def _encode_evidence_json(
    *,
    checkpoint_id: str = "",
    evidence_refs: Sequence[workflow_checkpoints.EvidenceRef | dict[str, Any]] = (),
    extra: dict[str, Any] | None = None,
) -> str:
    refs_out: list[dict[str, str]] = []
    for item in evidence_refs:
        if isinstance(item, workflow_checkpoints.EvidenceRef):
            refs_out.append(item.to_dict())
        elif isinstance(item, dict):
            refs_out.append(workflow_checkpoints.EvidenceRef.from_dict(item).to_dict())
        else:
            to_dict_fn = getattr(item, "to_dict", None)
            if callable(to_dict_fn):
                refs_out.append(workflow_checkpoints.EvidenceRef.from_dict(to_dict_fn()).to_dict())
    payload: dict[str, Any] = {}
    if checkpoint_id:
        payload["checkpoint_id"] = checkpoint_id
    if refs_out:
        payload["evidence_refs"] = refs_out
    if extra:
        payload.update(extra)
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


class DurableTaskStateMachine:
    """Authoritative SQLite state machine for root tasks, child milestones, and checkpoints."""

    def __init__(
        self,
        storage: runtime_persistence.StorageProvider,
        db_path: Path,
        *,
        retry_policy: runtime_persistence.BusyRetryPolicy = runtime_persistence.DEFAULT_BUSY_RETRY_POLICY,
        recovery_memory: recovery_guard.RecoveryGuard | None = None,
        containment_store: process_supervision.ContainmentStore | None = None,
    ) -> None:
        self._storage = storage
        self._db_path = db_path
        self._retry_policy = retry_policy
        self._containment_store = containment_store
        self.store = runtime_persistence.RuntimePersistenceStore(storage, db_path, retry_policy=retry_policy)
        self.budgets = execution_budget.DurableTaskBudgetManager(storage, db_path, retry_policy=retry_policy)
        self.checkpoints = workflow_checkpoints.DurableTaskCheckpointStore(
            storage,
            db_path,
            retry_policy=retry_policy,
        )
        self.recovery = recovery_memory if recovery_memory is not None else recovery_guard.RecoveryGuard(
            db_path.parent / "recovery"
        )

    def ensure_root_task(
        self,
        task_id: str,
        *,
        session_id: str = "",
        title: str = "",
        workspace_dir: str = "",
        policy: str = "standard",
        budget_spec: execution_budget.TaskBudgetSpec | None = None,
        override_budget_spec: bool = False,
        now: float | None = None,
    ) -> tuple[runtime_persistence.TaskRecord, execution_budget.TaskBudgetState]:
        tid = _validate_identifier(task_id, "task_id")
        self.store.ensure_task(
            tid,
            session_id=session_id or tid,
            title=title,
            state="pending",
            workspace_dir=workspace_dir,
            policy=policy,
            now=now,
        )
        budget = self.budgets.ensure_budget(
            tid,
            spec=budget_spec,
            override_spec=override_budget_spec,
            now=now,
        )
        refreshed = self.store.get_task(tid)
        assert refreshed is not None
        return refreshed, budget

    def ensure_milestone(
        self,
        root_task_id: str,
        milestone_key: str,
        *,
        title: str = "",
        now: float | None = None,
    ) -> runtime_persistence.TaskRecord:
        root_id = _validate_identifier(root_task_id, "root_task_id")
        ms_id = milestone_task_id(root_id, milestone_key)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.TaskRecord:
            conn.row_factory = sqlite3.Row
            parent_row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (root_id,)).fetchone()
            if parent_row is None:
                raise WorkflowStateError(f"Root task {root_id!r} does not exist.")
            existing = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (ms_id,)).fetchone()
            if existing is not None:
                return runtime_persistence._row_to_task(existing)
            conn.execute(
                """
                INSERT INTO runtime_tasks (
                    task_id, parent_task_id, session_id, title, state,
                    current_epoch, state_version, workspace_dir, policy,
                    budget_json, checkpoint_ref, created_at, updated_at
                ) VALUES (?, ?, ?, ?, 'pending', 0, 0, ?, ?, '{}', '', ?, ?)
                """,
                (
                    ms_id,
                    root_id,
                    str(parent_row["session_id"]),
                    str(title or milestone_key)[:240],
                    str(parent_row["workspace_dir"]),
                    str(parent_row["policy"]),
                    ts,
                    ts,
                ),
            )
            created = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (ms_id,)).fetchone()
            assert created is not None
            return runtime_persistence._row_to_task(created)

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def list_milestones(self, root_task_id: str) -> list[runtime_persistence.TaskRecord]:
        return self.store.list_child_tasks(_validate_identifier(root_task_id, "root_task_id"))

    def transition_milestone(
        self,
        root_task_id: str,
        milestone_key: str,
        to_state: str,
        *,
        epoch: int | None = None,
        expected_state_version: int | None = None,
        reason: str = "",
        checkpoint_id: str = "",
        evidence_refs: Sequence[workflow_checkpoints.EvidenceRef | dict[str, Any]] = (),
        now: float | None = None,
    ) -> runtime_persistence.TaskRecord:
        root_id = _validate_identifier(root_task_id, "root_task_id")
        ms_id = milestone_task_id(root_id, milestone_key)
        if to_state not in runtime_persistence.TASK_STATES:
            raise WorkflowStateError(f"unknown milestone state: {to_state}")
        evidence_json = _encode_evidence_json(checkpoint_id=checkpoint_id, evidence_refs=evidence_refs)
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.TaskRecord:
            conn.row_factory = sqlite3.Row
            parent_row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (root_id,)).fetchone()
            if parent_row is None:
                raise WorkflowStateError(f"Root task {root_id!r} does not exist.")
            if epoch is not None and int(parent_row["current_epoch"]) != int(epoch):
                raise runtime_persistence.StaleEpochError(
                    f"Stale epoch {epoch} cannot transition milestone {ms_id!r} (root epoch={parent_row['current_epoch']})."
                )
            parent_budget = execution_budget.TaskBudgetState.from_json(str(parent_row["budget_json"]))
            if to_state == "completed" and (
                parent_budget.pause_requested
                or parent_budget.cancel_requested
                or str(parent_row["state"]) in {"paused", "cancelled"}
            ):
                raise WorkflowTransitionRejected(
                    f"Milestone {ms_id!r} cannot claim completion while root task pause/cancel is active."
                )
            ms_row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (ms_id,)).fetchone()
            if ms_row is None:
                raise WorkflowStateError(f"Milestone {ms_id!r} does not exist.")
            from_state = str(ms_row["state"])
            if expected_state_version is not None and int(ms_row["state_version"]) != expected_state_version:
                raise WorkflowTransitionRejected("milestone state_version changed; refresh before transitioning.")
            if from_state == to_state and to_state in {"running", "paused", "cancelled"}:
                return runtime_persistence._row_to_task(ms_row)
            allowed = TASK_STATE_TRANSITIONS.get(from_state, frozenset())
            if to_state not in allowed:
                raise WorkflowTransitionRejected(
                    f"milestone transition {from_state} -> {to_state} is not allowed."
                )
            eff_epoch = int(parent_row["current_epoch"]) if epoch is None else int(epoch)
            new_ckpt = checkpoint_id if checkpoint_id else str(ms_row["checkpoint_ref"])
            seq_row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                (ms_id,),
            ).fetchone()
            next_seq = int(seq_row[0]) if seq_row else 1
            conn.execute(
                """
                UPDATE runtime_tasks
                SET state = ?, current_epoch = ?, state_version = state_version + 1,
                    checkpoint_ref = ?, updated_at = ?
                WHERE task_id = ?
                """,
                (to_state, eff_epoch, new_ckpt[:256], ts, ms_id),
            )
            conn.execute(
                """
                INSERT INTO runtime_task_transitions (
                    task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (ms_id, next_seq, from_state, to_state, eff_epoch, str(reason)[:240], evidence_json, ts),
            )
            updated = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (ms_id,)).fetchone()
            assert updated is not None
            return runtime_persistence._row_to_task(updated)

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def transition_task(
        self,
        task_id: str,
        to_state: str,
        *,
        expected_state_version: int | None = None,
        epoch: int | None = None,
        allow_new_turn_from_completed: bool = False,
        allow_inactive_epoch: bool = False,
        reason: str = "",
        checkpoint_id: str | None = None,
        evidence_refs: Sequence[workflow_checkpoints.EvidenceRef | dict[str, Any]] = (),
        extra_evidence: dict[str, Any] | None = None,
        now: float | None = None,
    ) -> runtime_persistence.TaskRecord:
        tid = _validate_identifier(task_id, "task_id")
        if to_state not in runtime_persistence.TASK_STATES:
            raise WorkflowStateError(f"unknown task state: {to_state}")
        if to_state == "completed":
            raise WorkflowTransitionRejected(
                "Use complete_task() to transition a root task to 'completed' with milestone and boundary verification."
            )
        evidence_json = _encode_evidence_json(
            checkpoint_id=checkpoint_id or "",
            evidence_refs=evidence_refs,
            extra=extra_evidence,
        )
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.TaskRecord:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise WorkflowStateError(f"Task {tid!r} does not exist.")
            from_state = str(row["state"])
            if expected_state_version is not None and int(row["state_version"]) != expected_state_version:
                raise WorkflowTransitionRejected("task state_version changed; refresh before transitioning.")
            current_epoch = int(row["current_epoch"])
            if epoch is not None and current_epoch != int(epoch):
                raise runtime_persistence.StaleEpochError(
                    f"Stale task epoch {epoch} cannot transition task {tid!r} at current_epoch={current_epoch}."
                )
            if epoch is not None and int(epoch) > 0 and not allow_inactive_epoch:
                ep_row = conn.execute(
                    "SELECT status, lease_expires_at FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                    (tid, int(epoch)),
                ).fetchone()
                if ep_row is None or str(ep_row["status"]) != "active":
                    raise runtime_persistence.StaleEpochError(
                        f"Inactive task epoch {epoch} cannot transition task {tid!r}."
                    )
                if float(ep_row["lease_expires_at"]) <= ts:
                    raise runtime_persistence.LeaseExpiredError(
                        f"Expired task epoch {epoch} cannot transition task {tid!r}."
                    )
            allowed = TASK_STATE_TRANSITIONS.get(from_state, frozenset())
            if from_state == "completed" and to_state == "running" and allow_new_turn_from_completed:
                pass
            elif to_state not in allowed:
                raise WorkflowTransitionRejected(
                    f"task transition {from_state} -> {to_state} is not allowed."
                )
            eff_epoch = current_epoch if epoch is None else int(epoch)
            new_ckpt = str(row["checkpoint_ref"]) if checkpoint_ref_is_none(checkpoint_id) else str(checkpoint_id)[:256]
            seq_row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                (tid,),
            ).fetchone()
            next_seq = int(seq_row[0]) if seq_row else 1
            conn.execute(
                """
                UPDATE runtime_tasks
                SET state = ?, state_version = state_version + 1, checkpoint_ref = ?, updated_at = ?
                WHERE task_id = ?
                """,
                (to_state, new_ckpt, ts, tid),
            )
            conn.execute(
                """
                INSERT INTO runtime_task_transitions (
                    task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (tid, next_seq, from_state, to_state, eff_epoch, str(reason)[:240], evidence_json, ts),
            )
            updated = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            assert updated is not None
            return runtime_persistence._row_to_task(updated)

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def check_safe_boundary(
        self,
        task_id: str,
        *,
        epoch: int | None = None,
        abort_requested: bool = False,
    ) -> Literal["continue", "pause", "cancel"]:
        tid = _validate_identifier(task_id, "task_id")

        def _read(conn: sqlite3.Connection) -> Literal["continue", "pause", "cancel"]:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                "SELECT state, current_epoch, budget_json FROM runtime_tasks WHERE task_id = ?",
                (tid,),
            ).fetchone()
            if row is None:
                raise WorkflowStateError(f"Task {tid!r} does not exist.")
            state = str(row["state"])
            budget = execution_budget.TaskBudgetState.from_json(str(row["budget_json"]))
            if state == "cancelled" or budget.cancel_requested:
                return "cancel"
            if epoch is not None and int(row["current_epoch"]) != int(epoch):
                raise runtime_persistence.StaleEpochError(
                    f"Epoch {epoch} was superseded on task {tid!r} (current_epoch={row['current_epoch']})."
                )
            if state == "paused" or budget.pause_requested or abort_requested:
                return "pause"
            return "continue"

        return runtime_persistence.run_read(self._storage, self._db_path, _read, retry_policy=self._retry_policy)

    def request_pause(
        self,
        task_id: str,
        *,
        reason: str = "operator_pause_requested",
        now: float | None = None,
    ) -> TaskControlResult:
        """Pause an idle/orphaned task immediately or flag ``pause_requested`` for safe-boundary stop."""
        tid = _validate_identifier(task_id, "task_id")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskControlResult:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise WorkflowStateError(f"Task {tid!r} does not exist.")
            state = str(row["state"])
            budget = execution_budget.TaskBudgetState.from_json(str(row["budget_json"]))
            if state in {"completed", "cancelled"} or budget.cancel_requested:
                raise WorkflowTransitionRejected(
                    f"Cannot pause task {tid!r} in state {state!r}."
                )
            if state == "paused":
                return TaskControlResult(
                    task=runtime_persistence._row_to_task(row),
                    budget=budget,
                    deferred_to_safe_boundary=False,
                )
            current_epoch = int(row["current_epoch"])
            has_live_lease = False
            if current_epoch > 0:
                ep_row = conn.execute(
                    "SELECT status, lease_expires_at FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                    (tid, current_epoch),
                ).fetchone()
                if ep_row is not None and str(ep_row["status"]) == "active" and float(ep_row["lease_expires_at"]) > ts:
                    has_live_lease = True
            if has_live_lease and state in {"running", "waiting_approval"}:
                deferred_budget = execution_budget.TaskBudgetState(
                    spec=budget.spec,
                    steps_used=budget.steps_used,
                    tool_calls_used=budget.tool_calls_used,
                    tokens_used=budget.tokens_used,
                    elapsed_s=budget.elapsed_s,
                    recoveries_used=budget.recoveries_used,
                    pause_requested=True,
                    cancel_requested=budget.cancel_requested,
                    exhausted_reason=budget.exhausted_reason,
                    verification_contract=budget.verification_contract,
                )
                conn.execute(
                    "UPDATE runtime_tasks SET budget_json = ?, updated_at = ? WHERE task_id = ?",
                    (deferred_budget.to_json(), ts, tid),
                )
                refreshed = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
                assert refreshed is not None
                return TaskControlResult(
                    task=runtime_persistence._row_to_task(refreshed),
                    budget=deferred_budget,
                    deferred_to_safe_boundary=True,
                )

            unresolved_rows = conn.execute(
                """
                SELECT action_id FROM runtime_actions
                WHERE task_id = ? AND status IN ('in_flight', 'uncertain') AND action_class != 'read_only'
                ORDER BY created_at ASC
                """,
                (tid,),
            ).fetchall()
            if unresolved_rows:
                raise WorkflowTransitionRejected(
                    f"Cannot pause task {tid!r} directly while consequential actions remain unresolved."
                )

            cleared_budget = execution_budget.TaskBudgetState(
                spec=budget.spec,
                steps_used=budget.steps_used,
                tool_calls_used=budget.tool_calls_used,
                tokens_used=budget.tokens_used,
                elapsed_s=budget.elapsed_s,
                recoveries_used=budget.recoveries_used,
                pause_requested=False,
                cancel_requested=False,
                exhausted_reason=budget.exhausted_reason,
                verification_contract=budget.verification_contract,
            )
            ckpt_ref = str(row["checkpoint_ref"] or "").strip()
            if ckpt_ref:
                conn.execute(
                    "UPDATE runtime_task_checkpoints SET status = 'interrupted', updated_at = ? WHERE checkpoint_id = ?",
                    (ts, ckpt_ref),
                )
            seq_row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                (tid,),
            ).fetchone()
            next_seq = int(seq_row[0]) if seq_row else 1
            conn.execute(
                """
                UPDATE runtime_tasks
                SET state = 'paused', state_version = state_version + 1, budget_json = ?, updated_at = ?
                WHERE task_id = ?
                """,
                (cleared_budget.to_json(), ts, tid),
            )
            conn.execute(
                """
                INSERT INTO runtime_task_transitions (
                    task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                ) VALUES (?, ?, ?, 'paused', ?, ?, ?, ?)
                """,
                (
                    tid,
                    next_seq,
                    state,
                    current_epoch,
                    str(reason)[:240],
                    _encode_evidence_json(checkpoint_id=ckpt_ref),
                    ts,
                ),
            )
            conn.execute(
                """
                UPDATE runtime_tasks
                SET state = 'paused', state_version = state_version + 1, updated_at = ?
                WHERE parent_task_id = ? AND state IN ('running', 'waiting_approval')
                """,
                (ts, tid),
            )
            paused_row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            assert paused_row is not None
            return TaskControlResult(
                task=runtime_persistence._row_to_task(paused_row),
                budget=cleared_budget,
                deferred_to_safe_boundary=False,
            )

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def pause_at_safe_boundary(
        self,
        task_id: str,
        *,
        worker_id: str,
        epoch: int,
        step: int,
        checkpoint_payload: dict[str, Any] | None = None,
        evidence_refs: Sequence[workflow_checkpoints.EvidenceRef | dict[str, Any]] = (),
        milestone_id: str = "",
        reason: str = "paused_at_safe_boundary",
        now: float | None = None,
    ) -> runtime_persistence.TaskRecord:
        """Persist an ``interrupted`` checkpoint, pause running milestones, and release lease into ``paused``."""
        tid = _validate_identifier(task_id, "task_id")
        wid = _validate_identifier(worker_id, "worker_id")
        ckpt: workflow_checkpoints.TaskCheckpointRecord | None = None
        if checkpoint_payload is not None:
            ckpt = self.checkpoints.save_checkpoint(
                tid,
                step=step,
                payload=checkpoint_payload,
                evidence_refs=evidence_refs,
                epoch=epoch,
                milestone_id=milestone_id,
                status="interrupted",
                require_active_epoch=True,
                now=now,
            )
        else:
            ckpt = self.checkpoints.mark_latest_interrupted(tid, now=now)

        ts = time.time() if now is None else float(now)
        evidence_json = _encode_evidence_json(
            checkpoint_id=ckpt.checkpoint_id if ckpt else "",
            evidence_refs=evidence_refs,
        )

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.TaskRecord:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise WorkflowStateError(f"Task {tid!r} does not exist.")
            if int(row["current_epoch"]) != int(epoch):
                raise runtime_persistence.StaleEpochError(
                    f"Stale epoch {epoch} cannot pause task {tid!r} at current_epoch={row['current_epoch']}."
                )
            budget = execution_budget.TaskBudgetState.from_json(str(row["budget_json"]))
            if str(row["state"]) == "cancelled" or budget.cancel_requested:
                raise WorkflowTransitionRejected(f"Task {tid!r} was cancelled before pause boundary completed.")
            ep_row = conn.execute(
                "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                (tid, int(epoch)),
            ).fetchone()
            if ep_row is None or str(ep_row["worker_id"]) != wid or str(ep_row["status"]) != "active":
                raise runtime_persistence.StaleEpochError(
                    f"Epoch {epoch} on task {tid!r} is no longer actively owned by {wid!r}."
                )
            conn.execute(
                "UPDATE runtime_task_epochs SET status = 'released', heartbeat_at = ? WHERE task_id = ? AND epoch = ?",
                (ts, tid, int(epoch)),
            )
            cleared_budget = execution_budget.TaskBudgetState(
                spec=budget.spec,
                steps_used=budget.steps_used,
                tool_calls_used=budget.tool_calls_used,
                tokens_used=budget.tokens_used,
                elapsed_s=budget.elapsed_s,
                recoveries_used=budget.recoveries_used,
                pause_requested=False,
                cancel_requested=False,
                exhausted_reason=budget.exhausted_reason,
                verification_contract=budget.verification_contract,
            )
            from_state = str(row["state"])
            seq_row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                (tid,),
            ).fetchone()
            next_seq = int(seq_row[0]) if seq_row else 1
            conn.execute(
                """
                UPDATE runtime_tasks
                SET state = 'paused', state_version = state_version + 1, budget_json = ?, updated_at = ?
                WHERE task_id = ?
                """,
                (cleared_budget.to_json(), ts, tid),
            )
            conn.execute(
                """
                INSERT INTO runtime_task_transitions (
                    task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                ) VALUES (?, ?, ?, 'paused', ?, ?, ?, ?)
                """,
                (tid, next_seq, from_state, int(epoch), str(reason)[:240], evidence_json, ts),
            )
            ms_rows = conn.execute(
                "SELECT task_id, state FROM runtime_tasks WHERE parent_task_id = ? AND state IN ('running', 'waiting_approval')",
                (tid,),
            ).fetchall()
            for ms_row in ms_rows:
                ms_tid = str(ms_row["task_id"])
                ms_from = str(ms_row["state"])
                ms_seq_row = conn.execute(
                    "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                    (ms_tid,),
                ).fetchone()
                ms_seq = int(ms_seq_row[0]) if ms_seq_row else 1
                conn.execute(
                    "UPDATE runtime_tasks SET state = 'paused', state_version = state_version + 1, updated_at = ? WHERE task_id = ?",
                    (ts, ms_tid),
                )
                conn.execute(
                    """
                    INSERT INTO runtime_task_transitions (
                        task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                    ) VALUES (?, ?, ?, 'paused', ?, ?, ?, ?)
                    """,
                    (ms_tid, ms_seq, ms_from, int(epoch), str(reason)[:240], evidence_json, ts),
                )
            updated = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            assert updated is not None
            return runtime_persistence._row_to_task(updated)

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def cancel_task(
        self,
        task_id: str,
        *,
        reason: str = "operator_cancelled",
        evidence_refs: Sequence[workflow_checkpoints.EvidenceRef | dict[str, Any]] = (),
        now: float | None = None,
    ) -> TaskControlResult:
        """Fence active epochs, preserve unresolved side-effect records, and transition to ``cancelled``."""
        tid = _validate_identifier(task_id, "task_id")
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> TaskControlResult:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise WorkflowStateError(f"Task {tid!r} does not exist.")
            from_state = str(row["state"])
            budget = execution_budget.TaskBudgetState.from_json(str(row["budget_json"]))
            if from_state == "completed":
                raise WorkflowTransitionRejected(f"Cannot cancel completed task {tid!r}.")
            if from_state == "cancelled":
                return TaskControlResult(
                    task=runtime_persistence._row_to_task(row),
                    budget=budget,
                    deferred_to_safe_boundary=False,
                )
            current_epoch = int(row["current_epoch"])
            conn.execute(
                """
                UPDATE runtime_task_epochs
                SET status = 'fenced', fenced_at = ?, fence_reason = 'task_cancelled'
                WHERE task_id = ? AND status = 'active'
                """,
                (ts, tid),
            )
            conn.execute(
                """
                UPDATE runtime_actions
                SET status = 'uncertain', error_code = 'cancelled_in_flight', updated_at = ?
                WHERE task_id = ? AND status = 'in_flight' AND action_class != 'read_only'
                """,
                (ts, tid),
            )
            conn.execute(
                """
                UPDATE runtime_actions
                SET status = 'failed', ok = 0, error_code = 'cancelled_in_flight', updated_at = ?
                WHERE task_id = ? AND status = 'in_flight' AND action_class = 'read_only'
                """,
                (ts, tid),
            )
            unresolved_rows = conn.execute(
                """
                SELECT action_id FROM runtime_actions
                WHERE task_id = ? AND status IN ('in_flight', 'uncertain') AND action_class != 'read_only'
                ORDER BY created_at ASC
                """,
                (tid,),
            ).fetchall()
            unresolved_ids = tuple(str(r["action_id"]) for r in unresolved_rows)

            ckpt_ref = str(row["checkpoint_ref"] or "").strip()
            if ckpt_ref:
                conn.execute(
                    "UPDATE runtime_task_checkpoints SET status = 'interrupted', updated_at = ? WHERE checkpoint_id = ?",
                    (ts, ckpt_ref),
                )
            cancelled_budget = execution_budget.TaskBudgetState(
                spec=budget.spec,
                steps_used=budget.steps_used,
                tool_calls_used=budget.tool_calls_used,
                tokens_used=budget.tokens_used,
                elapsed_s=budget.elapsed_s,
                recoveries_used=budget.recoveries_used,
                pause_requested=False,
                cancel_requested=True,
                exhausted_reason=budget.exhausted_reason,
                verification_contract=budget.verification_contract,
            )
            evidence_json = _encode_evidence_json(
                checkpoint_id=ckpt_ref,
                evidence_refs=evidence_refs,
                extra={"unresolved_action_ids": list(unresolved_ids)} if unresolved_ids else None,
            )
            seq_row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                (tid,),
            ).fetchone()
            next_seq = int(seq_row[0]) if seq_row else 1
            conn.execute(
                """
                UPDATE runtime_tasks
                SET state = 'cancelled', state_version = state_version + 1, budget_json = ?, updated_at = ?
                WHERE task_id = ?
                """,
                (cancelled_budget.to_json(), ts, tid),
            )
            conn.execute(
                """
                INSERT INTO runtime_task_transitions (
                    task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                ) VALUES (?, ?, ?, 'cancelled', ?, ?, ?, ?)
                """,
                (tid, next_seq, from_state, current_epoch, str(reason)[:240], evidence_json, ts),
            )
            ms_rows = conn.execute(
                """
                SELECT task_id, state FROM runtime_tasks
                WHERE parent_task_id = ? AND state NOT IN ('completed', 'cancelled')
                """,
                (tid,),
            ).fetchall()
            for ms_row in ms_rows:
                ms_tid = str(ms_row["task_id"])
                ms_from = str(ms_row["state"])
                ms_seq_row = conn.execute(
                    "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                    (ms_tid,),
                ).fetchone()
                ms_seq = int(ms_seq_row[0]) if ms_seq_row else 1
                conn.execute(
                    "UPDATE runtime_tasks SET state = 'cancelled', state_version = state_version + 1, updated_at = ? WHERE task_id = ?",
                    (ts, ms_tid),
                )
                conn.execute(
                    """
                    INSERT INTO runtime_task_transitions (
                        task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                    ) VALUES (?, ?, ?, 'cancelled', ?, ?, ?, ?)
                    """,
                    (ms_tid, ms_seq, ms_from, current_epoch, str(reason)[:240], evidence_json, ts),
                )
            updated = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            assert updated is not None
            return TaskControlResult(
                task=runtime_persistence._row_to_task(updated),
                budget=cancelled_budget,
                deferred_to_safe_boundary=False,
                unresolved_action_ids=unresolved_ids,
            )

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def _recovery_conditions(self, task: Any) -> recovery_guard.EvidenceSnapshot:
        """Observable conditions a recovery attempt would start from (M5-P2-05)."""
        workspace = str(getattr(task, "workspace_dir", "") or "").strip()
        if not workspace:
            return recovery_guard.EvidenceSnapshot()
        root = Path(workspace)
        files: tuple[str, ...] = ()
        try:
            contract = self.budgets.get_budget(task.task_id).verification_contract or {}
            raw_files = contract.get("required_modified_files") or ()
            if isinstance(raw_files, (list, tuple)):
                files = tuple(str(item) for item in raw_files)
        except (KeyError, execution_budget.BudgetError, runtime_persistence.PersistenceError):
            files = ()
        try:
            revision = verification_evidence.capture_source_revision(root, files)
            environment = verification_evidence.environment_snapshot(root)
        except (verification_evidence.VerificationEvidenceError, OSError):
            return recovery_guard.EvidenceSnapshot()
        return recovery_guard.EvidenceSnapshot(
            revision_digest=revision.digest,
            environment_digest=hashlib.sha256(
                json.dumps(environment, sort_keys=True, separators=(",", ":")).encode("utf-8")
            ).hexdigest(),
        )

    def prepare_resume(
        self,
        task_id: str,
        *,
        consume_recovery_budget: bool = True,
        now: float | None = None,
    ) -> ResumedTaskPlan:
        """Validate resumability, checkpoint integrity, unresolved side effects, and recovery budget."""
        tid = _validate_identifier(task_id, "task_id")
        task = self.store.get_task(tid)
        if task is None:
            raise WorkflowStateError(f"Task {tid!r} does not exist.")
        if task.state == "cancelled":
            raise WorkflowTransitionRejected(f"Cancelled task {tid!r} cannot be resumed.")
        if task.state == "completed":
            raise WorkflowTransitionRejected(f"Completed task {tid!r} does not require resume.")
        if task.state == "blocked":
            raise workflow_checkpoints.ResumeRejected(
                f"Blocked task {tid!r} has unresolved side effects or integrity violations and cannot resume automatically."
            )
        if task.state not in {"paused", "failed"}:
            raise WorkflowTransitionRejected(
                f"Task {tid!r} in state {task.state!r} must be paused or failed before resume."
            )
        unresolved = [
            act.action_id
            for act in self.store.list_task_actions(tid, statuses=("in_flight", "uncertain"))
            if act.action_class != "read_only"
        ]
        if unresolved:
            raise workflow_checkpoints.ResumeRejected(
                f"Task {tid!r} has unresolved consequential action(s): {', '.join(unresolved)}."
            )
        if self._containment_store is not None:
            holds = self._containment_store.find_resumption_holds(
                task_id=tid,
                workspace_root=task.workspace_dir,
            )
            if holds:
                hold_labels = [h.action_id or h.hold_id for h in holds]
                raise workflow_checkpoints.ResumeRejected(
                    f"Task {tid!r} has conflicting containment hold(s) blocking resumption: "
                    f"{', '.join(hold_labels)}."
                )
        # Verify checkpoint integrity BEFORE consuming recovery budget.
        ckpt = self.checkpoints.load_latest_checkpoint(tid, verify_integrity=True)
        existing_budget = self.budgets.get_budget(tid)
        if existing_budget.cancel_requested:
            raise WorkflowTransitionRejected(f"Task {tid!r} has cancellation requested and cannot resume.")
        violation = existing_budget.violation_reason(check_recovery=False)
        if violation:
            raise execution_budget.BudgetExceeded(violation)

        # A recovery action needs changed evidence or changed conditions: refusing
        # here is what stops an unchanged workspace from being retried forever.
        conditions = self._recovery_conditions(task)
        if conditions.revision_digest or conditions.environment_digest:
            try:
                self.recovery.require_progress(tid, conditions, action="resume", compare="conditions")
            except recovery_guard.RecoveryRejected as exc:
                with contextlib.suppress(
                    KeyError, runtime_persistence.PersistenceError, execution_budget.BudgetError
                ):
                    self.budgets.set_control_flags(tid, pause_requested=True, now=now)
                if task.state != "paused":
                    with contextlib.suppress(WorkflowTransitionRejected):
                        self.transition_task(
                            tid,
                            "paused",
                            allow_inactive_epoch=True,
                            reason="recovery_requires_new_evidence",
                            checkpoint_id=ckpt.checkpoint_id if ckpt else None,
                            extra_evidence={"error": str(exc)},
                            now=now,
                        )
                raise WorkflowTransitionRejected(str(exc)) from exc
            except (recovery_guard.RecoveryGuardError, OSError):
                # Unreadable memory cannot prove progress, but it also cannot prove
                # repetition; the recovery budget remains the bound.
                pass

        if consume_recovery_budget:
            try:
                budget = self.budgets.consume_recovery(tid, now=now)
            except execution_budget.BudgetExceeded as exc:
                self.transition_task(
                    tid,
                    "blocked",
                    allow_inactive_epoch=True,
                    reason="recovery_budget_exceeded",
                    checkpoint_id=ckpt.checkpoint_id if ckpt else None,
                    extra_evidence={"error": str(exc)},
                    now=now,
                )
                raise
        else:
            budget = self.budgets.set_control_flags(tid, pause_requested=False, now=now)

        resumed_ckpt = self.checkpoints.validate_and_mark_resumed(
            tid,
            epoch=task.current_epoch,
            now=now,
        )
        milestones = tuple(self.list_milestones(tid))
        completed_ms = tuple(ms.task_id for ms in milestones if ms.state == "completed")
        refreshed_task = self.store.get_task(tid)
        assert refreshed_task is not None
        next_step = (resumed_ckpt.step + 1) if resumed_ckpt is not None else 0
        return ResumedTaskPlan(
            task=refreshed_task,
            budget=budget,
            checkpoint=resumed_ckpt,
            milestones=milestones,
            next_step=next_step,
            completed_milestone_ids=completed_ms,
        )

    def set_verification_spec(
        self,
        task_id: str,
        spec: TaskVerificationSpec | None,
        *,
        now: float | None = None,
    ) -> None:
        """Durably bind or clear a ``TaskVerificationSpec`` for ``task_id``."""
        tid = _validate_identifier(task_id, "task_id")
        self.budgets.set_verification_contract(
            tid,
            spec.to_dict() if spec is not None else None,
            now=now,
        )

    def get_verification_spec(self, task_id: str) -> TaskVerificationSpec | None:
        """Return the persisted ``TaskVerificationSpec`` for ``task_id``, if configured."""
        tid = _validate_identifier(task_id, "task_id")
        budget = self.budgets.get_budget(tid)
        if budget.verification_contract is None:
            return None
        return TaskVerificationSpec.from_dict(budget.verification_contract)

    def verify_task_completion(
        self,
        task_id: str,
        *,
        workspace_dir: Path,
        spec: TaskVerificationSpec | None = None,
    ) -> TaskVerificationReport:
        """Verify completion, then record the attempt in durable failure memory.

        The report is unchanged when the attempt made progress. When the same
        failure evidence repeats (or an abandoned state is revisited), the verdict
        is attached and a safe pause is requested instead of letting the loop try
        the same strategy again (M5-P2-05).
        """
        report = self._verify_task_completion_impl(task_id, workspace_dir=workspace_dir, spec=spec)
        return self._record_verification_attempt(_validate_identifier(task_id, "task_id"), report)

    def _record_verification_attempt(self, task_id: str, report: TaskVerificationReport) -> TaskVerificationReport:
        """Persist this attempt's evidence and attach the stagnation verdict."""
        failure_ids = tuple(
            str(record.get("test_id", ""))
            for record in (report.test_evidence.get("failures") or ())
            if isinstance(record, dict)
        )
        environment_digest = ""
        if report.environment:
            environment_digest = hashlib.sha256(
                json.dumps(report.environment, sort_keys=True, separators=(",", ":")).encode("utf-8")
            ).hexdigest()
        evidence = recovery_guard.EvidenceSnapshot(
            revision_digest=report.source_revision if len(report.source_revision) == 64 else "",
            transcript_sha256=report.test_sha256 if len(report.test_sha256) == 64 else "",
            failure_fingerprint=recovery_guard.failure_fingerprint(report.failure_code, failure_ids),
            failure_code=report.failure_code,
            failure_ids=failure_ids,
            environment_digest=environment_digest,
        )
        outcome = "verified" if report.verified else "failed"
        try:
            record, verdict = self.recovery.record_attempt(
                task_id, kind="verification", outcome=outcome, evidence=evidence
            )
        except (recovery_guard.RecoveryGuardError, OSError) as exc:
            if report.verified:
                return report
            # Fail closed: without memory there is no stagnation bound, so stop.
            return replace(
                report,
                failure_detail=f"{report.failure_detail} [recovery memory unavailable: {exc}]".strip()[:600],
                stagnation={"state": "unavailable", "escalate": True, "reason": str(exc)[:240], "pause_requested": True},
            )
        stagnation = dict(verdict.to_dict())
        stagnation["sequence"] = record.sequence
        stagnation["pause_requested"] = False
        if not report.verified and verdict.escalate:
            try:
                self.budgets.set_control_flags(task_id, pause_requested=True)
                stagnation["pause_requested"] = True
            except (KeyError, runtime_persistence.PersistenceError, execution_budget.BudgetError):
                stagnation["pause_requested"] = self.recovery.budget(task_id).pause_requested
        return replace(report, stagnation=stagnation)

    def _verify_task_completion_impl(
        self,
        task_id: str,
        *,
        workspace_dir: Path,
        spec: TaskVerificationSpec | None = None,
    ) -> TaskVerificationReport:
        """Authoritatively verify ledger, patch, protected-file, and test evidence outside write locks."""
        runtime_persistence.assert_no_active_write_transaction("task_verification")
        tid = _validate_identifier(task_id, "task_id")
        ws_root = Path(workspace_dir).resolve()
        effective_spec = spec if spec is not None else self.get_verification_spec(tid)
        spec_digest = effective_spec.sha256() if effective_spec is not None else ""

        actions = sorted(
            self.store.list_task_actions(tid),
            key=lambda a: (a.updated_at, a.created_at),
        )
        unresolved = [
            a.action_id
            for a in actions
            if a.status in ("in_flight", "uncertain") and a.action_class != "read_only"
        ]
        if unresolved:
            return TaskVerificationReport(
                verified=False,
                spec_sha256=spec_digest,
                failure_code="unresolved_consequential_actions",
                failure_detail=f"Unresolved consequential actions prevent completion: {', '.join(unresolved)}.",
            )

        committed_edits = [
            a for a in actions if a.action_class == "managed_edit" and a.status == "committed" and a.ok == 1
        ]
        shell_actions = [
            a for a in actions if a.tool_name == "run_bash" and a.status in ("committed", "failed")
        ]
        committed_tests = [a for a in shell_actions if a.status == "committed" and a.ok == 1]

        # Universal false-completion guard: if the latest shell/test action failed (`ok == 0`) with no
        # subsequent passing shell/test run, reject false completion even without an explicit contract.
        if shell_actions and shell_actions[-1].status == "failed":
            last_failed = shell_actions[-1]
            return TaskVerificationReport(
                verified=False,
                spec_sha256=spec_digest,
                failure_code="latest_shell_or_test_failed",
                failure_detail=(
                    f"Latest `run_bash` action `{last_failed.action_id}` failed (`ok=0`); "
                    "cannot claim completion without a subsequent passing verification run."
                ),
                committed_edit_action_ids=tuple(a.action_id for a in committed_edits),
                committed_test_action_ids=tuple(a.action_id for a in committed_tests),
            )

        if effective_spec is None:
            return TaskVerificationReport(
                verified=True,
                spec_sha256="",
                committed_edit_action_ids=tuple(a.action_id for a in committed_edits),
                committed_test_action_ids=tuple(a.action_id for a in committed_tests),
            )

        # 1. Protected user files must remain untouched (`sha256` identical to baseline).
        for prot_rel, expected_sha in sorted(effective_spec.protected_files.items()):
            try:
                actual_sha = compute_workspace_file_sha256(ws_root, prot_rel)
            except WorkflowStateError as exc:
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="protected_file_invalid",
                    failure_detail=str(exc),
                )
            if actual_sha is None:
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="protected_file_missing",
                    failure_detail=f"Protected user file `{prot_rel}` was deleted during task execution.",
                )
            if actual_sha != expected_sha:
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="protected_file_modified",
                    failure_detail=(
                        f"Protected user file `{prot_rel}` was modified "
                        f"(expected sha256={expected_sha[:12]}..., got {actual_sha[:12]}...)."
                    ),
                )

        # 2. Managed-edit provenance in durable `runtime_actions`.
        if effective_spec.require_managed_edit and not committed_edits:
            return TaskVerificationReport(
                verified=False,
                spec_sha256=spec_digest,
                failure_code="missing_managed_edit",
                failure_detail="Completion rejected: zero committed `managed_edit` actions exist in `runtime_actions`.",
            )

        # 3. Required modified files must exist and differ from pre-task baseline digest.
        patch_entries: list[dict[str, str]] = []
        modified_paths: list[str] = []
        for mod_rel in effective_spec.required_modified_files:
            try:
                cur_sha = compute_workspace_file_sha256(ws_root, mod_rel)
            except WorkflowStateError as exc:
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="invalid_modified_file_path",
                    failure_detail=str(exc),
                )
            if cur_sha is None:
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="missing_required_file",
                    failure_detail=f"Required modified file `{mod_rel}` does not exist in workspace.",
                )
            if mod_rel in effective_spec.baseline_file_digests:
                base_sha = effective_spec.baseline_file_digests[mod_rel]
                if base_sha is not None and cur_sha == base_sha:
                    return TaskVerificationReport(
                        verified=False,
                        spec_sha256=spec_digest,
                        failure_code="unmodified_required_file",
                        failure_detail=f"Required target file `{mod_rel}` is unchanged from its pre-task digest.",
                    )
            modified_paths.append(mod_rel)
            patch_entries.append({"path": mod_rel, "sha256": cur_sha})

        for req_rel in effective_spec.required_files:
            try:
                target_fp = _resolve_safe_workspace_target(ws_root, req_rel)
            except WorkflowStateError as exc:
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="invalid_required_file_path",
                    failure_detail=str(exc),
                )
            if not target_fp.is_file() or target_fp.stat().st_size == 0:
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="missing_required_file",
                    failure_detail=f"Required artifact file `{req_rel}` is missing or empty.",
                )
            req_sha = hashlib.sha256(target_fp.read_bytes()).hexdigest()
            if req_rel not in modified_paths:
                modified_paths.append(req_rel)
                patch_entries.append({"path": req_rel, "sha256": req_sha})

        # 4. Optional Git diff verification.
        git_diff_text = ""
        if effective_spec.require_git_diff:
            if not (ws_root / ".git").exists():
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="missing_git_repository",
                    failure_detail="require_git_diff=True but workspace is not a Git repository.",
                )
            git_env = {k: v for k, v in os.environ.items() if k in _SAFE_VERIFY_ENV_KEYS}
            git_env["GIT_TERMINAL_PROMPT"] = "0"
            st_proc = subprocess.run(
                ["git", "status", "--porcelain"],
                cwd=ws_root,
                capture_output=True,
                text=True,
                timeout=10.0,
                check=False,
                env=git_env,
            )
            diff_proc = subprocess.run(
                ["git", "diff", "HEAD"],
                cwd=ws_root,
                capture_output=True,
                text=True,
                timeout=10.0,
                check=False,
                env=git_env,
            )
            git_status_out = (st_proc.stdout or "").strip()
            git_diff_text = (diff_proc.stdout or "").strip()
            if st_proc.returncode != 0 or (not git_status_out and not git_diff_text):
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="missing_git_diff",
                    failure_detail="Completion rejected: Git working tree shows zero diff against HEAD.",
                )

        # 5. Post-edit agent test action ordering in `runtime_actions`.
        if effective_spec.require_agent_test_action:
            if not committed_tests:
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="missing_agent_test_execution",
                    failure_detail="Completion rejected: agent never committed a passing `run_bash` test execution.",
                )
            if committed_edits and committed_tests[-1].updated_at < committed_edits[-1].updated_at:
                return TaskVerificationReport(
                    verified=False,
                    spec_sha256=spec_digest,
                    failure_code="stale_test_before_latest_edit",
                    failure_detail=(
                        "Completion rejected: managed file edit occurred AFTER the last passing test action; "
                        "tests were not re-run on the final workspace state."
                    ),
                )

        patch_payload = json.dumps(
            {
                "files": patch_entries,
                "git_diff_sha256": hashlib.sha256(git_diff_text.encode("utf-8")).hexdigest() if git_diff_text else "",
                "edit_actions": [a.action_id for a in committed_edits],
            },
            sort_keys=True,
            separators=(",", ":"),
        )
        patch_sha = hashlib.sha256(patch_payload.encode("utf-8")).hexdigest()
        refs: list[workflow_checkpoints.EvidenceRef] = [
            workflow_checkpoints.EvidenceRef(
                kind="patch_verification",
                ref_id=",".join(modified_paths)[:120] or "workspace_patch",
                sha256=patch_sha,
                summary=f"verified {len(modified_paths)} file(s), {len(committed_edits)} edit action(s)"[:240],
            )
        ]

        # 6. Authoritative independent test command execution, tied to one revision.
        try:
            base_revision = verification_evidence.capture_source_revision(ws_root, tuple(modified_paths))
        except (verification_evidence.VerificationEvidenceError, OSError) as exc:
            return TaskVerificationReport(
                verified=False,
                spec_sha256=spec_digest,
                failure_code="revision_capture_failed",
                failure_detail=f"Cannot tie the verification result to a source revision: {exc}",
            )
        revision_files = tuple(modified_paths)
        environment = verification_evidence.environment_snapshot(ws_root)
        test_exit: int | None = None
        test_excerpt = ""
        test_sha = ""
        evidence: verification_evidence.TestEvidence | None = None
        evidence_kwargs: dict[str, Any] = {
            "spec_sha256": spec_digest,
            "modified_files": tuple(modified_paths),
            "patch_sha256": patch_sha,
            "committed_edit_action_ids": tuple(a.action_id for a in committed_edits),
            "committed_test_action_ids": tuple(a.action_id for a in committed_tests),
            "source_revision": base_revision.digest,
            "revision": base_revision.to_dict(),
            "environment": dict(environment),
        }
        if effective_spec.targeted_test_command:
            # Stage 1: the cheapest check that proves the change forwards.
            try:
                targeted = verification_evidence.run_verification_command(
                    effective_spec.targeted_test_command,
                    workspace=ws_root,
                    timeout_s=effective_spec.timeout_s,
                    files=revision_files,
                    pre_existing=effective_spec.pre_existing_failures,
                )
            except (verification_evidence.VerificationEvidenceError, OSError) as exc:
                return TaskVerificationReport(
                    verified=False,
                    failure_code="verification_targeted_test_exec_error",
                    failure_detail=f"Targeted verification command could not be recorded: {exc}",
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )
            evidence_kwargs["staged_test_evidence"] = {"targeted": targeted.to_dict()}
            evidence_kwargs["failure_classification"] = targeted.classification
            evidence_kwargs["denied"] = bool(targeted.denied)
            targeted_label = " ".join(effective_spec.targeted_test_command)[:100]
            refs.append(
                workflow_checkpoints.EvidenceRef(
                    kind="targeted_test_verification",
                    ref_id=targeted_label or "targeted_test_command",
                    sha256=targeted.output_sha256,
                    summary=(
                        f"exit_code={targeted.exit_code}; classification={targeted.classification}; "
                        f"revision={targeted.revision_before.digest[:12] if targeted.revision_before else '?'}"
                    )[:240],
                )
            )
            if targeted.denied:
                return TaskVerificationReport(
                    verified=False,
                    failure_code="verification_test_denied",
                    failure_detail=(
                        f"Targeted verification command was refused, not run (`{targeted.denied}`); "
                        "a denied run is never a passing test result."
                    ),
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )
            if targeted.exit_code is None:
                target_detail = targeted.failures[0].detail if targeted.failures else "no exit code"
                return TaskVerificationReport(
                    verified=False,
                    failure_code=(
                        "verification_test_timeout"
                        if "timed out" in target_detail
                        else "verification_targeted_test_exec_error"
                    ),
                    failure_detail=f"Targeted verification command did not complete: {target_detail}",
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )
            if effective_spec.require_revision_stability and targeted.revision_changed:
                return TaskVerificationReport(
                    verified=False,
                    failure_code="workspace_changed_during_verification",
                    failure_detail=(
                        "The workspace revision changed while the targeted verification command ran; "
                        "the result cannot be tied to the revision it claims to verify."
                    ),
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )
            targeted_tolerated = (
                effective_spec.allow_pre_existing_failures
                and targeted.classification == verification_evidence.RUN_PRE_EXISTING_ONLY
            )
            if targeted.exit_code != 0 and not targeted_tolerated:
                targeted_failing = ", ".join(
                    record.test_id or (record.detail[:60] or "<unparsed>") for record in targeted.failures[:5]
                )
                return TaskVerificationReport(
                    verified=False,
                    failure_code="verification_targeted_test_failed",
                    failure_detail=(
                        f"Targeted verification command exited with code {targeted.exit_code} "
                        f"(classification={targeted.classification}; failures: {targeted_failing or 'unparsed'}); "
                        "the broader verification stage was not run."
                    ),
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )

        if effective_spec.test_command:
            try:
                evidence = verification_evidence.run_verification_command(
                    effective_spec.test_command,
                    workspace=ws_root,
                    timeout_s=effective_spec.timeout_s,
                    files=revision_files,
                    pre_existing=effective_spec.pre_existing_failures,
                )
            except (verification_evidence.VerificationEvidenceError, OSError) as exc:
                return TaskVerificationReport(
                    verified=False,
                    failure_code="verification_test_exec_error",
                    failure_detail=f"Authoritative verification command could not be recorded: {exc}",
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )
            test_exit = evidence.exit_code
            test_excerpt = evidence.output_excerpt
            test_sha = evidence.output_sha256
            evidence_kwargs.update(
                {
                    "test_exit_code": evidence.exit_code,
                    "test_output_excerpt": test_excerpt,
                    "test_sha256": test_sha,
                    "source_revision": evidence.revision_before.digest if evidence.revision_before else base_revision.digest,
                    "revision": evidence.revision_before.to_dict() if evidence.revision_before else base_revision.to_dict(),
                    "test_evidence": evidence.to_dict(),
                    "failure_classification": evidence.classification,
                    "denied": bool(evidence.denied),
                }
            )

            if evidence.denied:
                return TaskVerificationReport(
                    verified=False,
                    failure_code="verification_test_denied",
                    failure_detail=(
                        "Authoritative verification command was refused, not run "
                        f"(`{evidence.denied}`); a denied run is never a passing test result."
                    ),
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )
            if evidence.exit_code is None:
                first_detail = evidence.failures[0].detail if evidence.failures else "no exit code"
                timed_out = "timed out" in first_detail
                return TaskVerificationReport(
                    verified=False,
                    failure_code="verification_test_timeout" if timed_out else "verification_test_exec_error",
                    failure_detail=(
                        f"Authoritative verification command timed out after {effective_spec.timeout_s}s."
                        if timed_out
                        else f"Authoritative verification command failed to start: {first_detail}"
                    ),
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )
            if effective_spec.require_revision_stability and evidence.revision_changed:
                return TaskVerificationReport(
                    verified=False,
                    failure_code="workspace_changed_during_verification",
                    failure_detail=(
                        "The workspace revision changed while the verification command ran "
                        f"({evidence.revision_before.digest[:12] if evidence.revision_before else '?'} -> "
                        f"{evidence.revision_after.digest[:12] if evidence.revision_after else '?'}); "
                        "the result cannot be tied to the revision it claims to verify."
                    ),
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )

            tolerates_pre_existing = (
                effective_spec.allow_pre_existing_failures
                and evidence.classification == verification_evidence.RUN_PRE_EXISTING_ONLY
            )
            if evidence.exit_code != 0 and not tolerates_pre_existing:
                if evidence.classification == verification_evidence.RUN_ENVIRONMENT_BLOCKED:
                    failure_code = "verification_test_environment_blocked"
                elif evidence.classification == verification_evidence.RUN_PRE_EXISTING_ONLY:
                    failure_code = "verification_test_failed_pre_existing"
                elif evidence.classification == verification_evidence.RUN_INTRODUCED:
                    failure_code = "verification_test_failed_introduced"
                else:
                    failure_code = "verification_test_failed"
                failing = ", ".join(
                    record.test_id or (record.detail[:60] or "<unparsed>") for record in evidence.failures[:5]
                )
                return TaskVerificationReport(
                    verified=False,
                    failure_code=failure_code,
                    failure_detail=(
                        f"Authoritative test command exited with code {evidence.exit_code} "
                        f"(classification={evidence.classification}; failures: {failing or 'unparsed'}): "
                        f"{test_excerpt[:200]}"
                    ),
                    evidence_refs=tuple(refs),
                    **evidence_kwargs,
                )
            coverage = verification_evidence.evaluate_acceptance_coverage(
                effective_spec.acceptance_coverage,
                output=evidence.output_text,
                failures=evidence.failures,
            )
            if coverage:
                evidence_kwargs["acceptance_coverage"] = coverage
                uncovered = [entry for entry in coverage if not entry["covered"]]
                if uncovered:
                    missing_detail = "; ".join(
                        f"{entry['criterion'][:80]} (missing: {', '.join(entry['missing_test_ids'])[:120]})"
                        for entry in uncovered[:5]
                    )
                    return TaskVerificationReport(
                        verified=False,
                        failure_code="verification_acceptance_coverage_missing",
                        failure_detail=(
                            "Declared acceptance criteria were not demonstrated by the authoritative run: "
                            f"{missing_detail}"
                        ),
                        **evidence_kwargs,
                    )
            for needle in effective_spec.expected_test_output_contains:
                if needle not in (test_excerpt if evidence.exit_code == 0 else ""):
                    return TaskVerificationReport(
                        verified=False,
                        failure_code="verification_test_output_mismatch",
                        failure_detail=f"Authoritative test output did not contain required marker {needle!r}.",
                        **evidence_kwargs,
                    )
            cmd_label = " ".join(effective_spec.test_command)[:100]
            refs.append(
                workflow_checkpoints.EvidenceRef(
                    kind="test_verification",
                    ref_id=cmd_label or "test_command",
                    sha256=test_sha,
                    summary=(
                        f"exit_code={evidence.exit_code}; classification={evidence.classification}; "
                        f"revision={evidence_kwargs['source_revision'][:12]}"
                    )[:240],
                )
            )

        return TaskVerificationReport(
            verified=True,
            spec_sha256=spec_digest,
            modified_files=tuple(modified_paths),
            patch_sha256=patch_sha,
            test_exit_code=test_exit,
            test_output_excerpt=test_excerpt,
            test_sha256=test_sha,
            committed_edit_action_ids=tuple(a.action_id for a in committed_edits),
            committed_test_action_ids=tuple(a.action_id for a in committed_tests),
            evidence_refs=tuple(refs),
            source_revision=evidence_kwargs["source_revision"],
            revision=evidence_kwargs["revision"],
            test_evidence=evidence_kwargs.get("test_evidence", {}),
            staged_test_evidence=evidence_kwargs.get("staged_test_evidence", {}),
            acceptance_coverage=tuple(evidence_kwargs.get("acceptance_coverage", ())),
            failure_classification=evidence_kwargs.get("failure_classification", ""),
            denied=bool(evidence_kwargs.get("denied", False)),
        )

    def complete_task(
        self,
        task_id: str,
        *,
        worker_id: str | None = None,
        epoch: int | None = None,
        step: int = 0,
        checkpoint_payload: dict[str, Any] | None = None,
        evidence_refs: Sequence[workflow_checkpoints.EvidenceRef | dict[str, Any]] = (),
        verification_report: TaskVerificationReport | Any | None = None,
        abort_requested: bool = False,
        reason: str = "task_completed",
        now: float | None = None,
    ) -> runtime_persistence.TaskRecord:
        """Complete a running root task only when all milestones, boundaries, actions, and verifications pass."""
        tid = _validate_identifier(task_id, "task_id")
        if abort_requested:
            raise WorkflowTransitionRejected(
                f"Task {tid!r} cannot claim completion when abort/pause was requested."
            )
        ts = time.time() if now is None else float(now)

        # Pre-check state, control flags, milestones, unresolved actions, and verification contract.
        current_task = self.store.get_task(tid)
        if current_task is None:
            raise WorkflowStateError(f"Task {tid!r} does not exist.")
        if current_task.state != "running":
            raise WorkflowTransitionRejected(
                f"Task {tid!r} in state {current_task.state!r} cannot transition to 'completed'."
            )
        current_budget = self.budgets.get_budget(tid)
        if current_budget.pause_requested or current_budget.cancel_requested:
            raise WorkflowTransitionRejected(
                f"Task {tid!r} cannot claim completion while pause_requested={current_budget.pause_requested} "
                f"or cancel_requested={current_budget.cancel_requested}."
            )
        milestones = self.list_milestones(tid)
        incomplete_ms = [ms.task_id for ms in milestones if ms.state != "completed"]
        if incomplete_ms:
            raise WorkflowTransitionRejected(
                f"Task {tid!r} cannot complete while milestone(s) remain incomplete: {', '.join(incomplete_ms)}."
            )
        all_actions = sorted(
            self.store.list_task_actions(tid),
            key=lambda a: (a.updated_at, a.created_at),
        )
        unresolved = [
            act.action_id
            for act in all_actions
            if act.status in ("in_flight", "uncertain") and act.action_class != "read_only"
        ]
        if unresolved:
            raise WorkflowTransitionRejected(
                f"Task {tid!r} cannot complete with unresolved consequential action(s): {', '.join(unresolved)}."
            )
        shell_actions = [
            act for act in all_actions if act.tool_name == "run_bash" and act.status in ("committed", "failed")
        ]
        if shell_actions and shell_actions[-1].status == "failed":
            raise FalseCompletionRejected(
                f"Task {tid!r} cannot claim completion: latest `run_bash` action "
                f"`{shell_actions[-1].action_id}` failed (`ok=0`)."
            )

        persisted_spec = (
            TaskVerificationSpec.from_dict(current_budget.verification_contract)
            if current_budget.verification_contract is not None
            else None
        )
        merged_refs: list[workflow_checkpoints.EvidenceRef | dict[str, Any]] = list(evidence_refs)
        verification_extra: dict[str, Any] | None = None
        if persisted_spec is not None:
            if verification_report is None:
                raise FalseCompletionRejected(
                    f"Task {tid!r} has an active verification contract and cannot complete without a verification_report."
                )
            if not bool(getattr(verification_report, "verified", False)):
                detail = str(getattr(verification_report, "failure_detail", "") or "verification failed")
                raise FalseCompletionRejected(f"Task {tid!r} false completion rejected: {detail}")
            rep_spec_sha = str(getattr(verification_report, "spec_sha256", ""))
            if rep_spec_sha != persisted_spec.sha256():
                raise FalseCompletionRejected(
                    f"Task {tid!r} verification_report spec_sha256 mismatch against persisted contract."
                )
            for vref in getattr(verification_report, "evidence_refs", ()):
                merged_refs.append(vref)
            if hasattr(verification_report, "to_dict"):
                verification_extra = {"verification": verification_report.to_dict()}
        elif verification_report is not None:
            if not bool(getattr(verification_report, "verified", False)):
                detail = str(getattr(verification_report, "failure_detail", "") or "verification failed")
                raise FalseCompletionRejected(f"Task {tid!r} false completion rejected: {detail}")
            for vref in getattr(verification_report, "evidence_refs", ()):
                merged_refs.append(vref)

        ckpt: workflow_checkpoints.TaskCheckpointRecord | None = None
        if checkpoint_payload is not None:
            ckpt = self.checkpoints.save_checkpoint(
                tid,
                step=step,
                payload=checkpoint_payload,
                evidence_refs=merged_refs,
                epoch=epoch,
                status="committed",
                require_active_epoch=epoch is not None and epoch > 0,
                now=ts,
            )

        evidence_json = _encode_evidence_json(
            checkpoint_id=ckpt.checkpoint_id if ckpt else current_task.checkpoint_ref,
            evidence_refs=merged_refs,
            extra=verification_extra,
        )

        def _tx(conn: sqlite3.Connection) -> runtime_persistence.TaskRecord:
            conn.row_factory = sqlite3.Row
            row = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            if row is None:
                raise WorkflowStateError(f"Task {tid!r} does not exist.")
            if str(row["state"]) != "running":
                raise WorkflowTransitionRejected(
                    f"Task {tid!r} left 'running' state ({row['state']!r}) before completion committed."
                )
            budget = execution_budget.TaskBudgetState.from_json(str(row["budget_json"]))
            if budget.pause_requested or budget.cancel_requested:
                raise WorkflowTransitionRejected(
                    f"Task {tid!r} received pause/cancel before completion committed."
                )
            if budget.verification_contract is not None:
                tx_spec = TaskVerificationSpec.from_dict(budget.verification_contract)
                if verification_report is None or not bool(getattr(verification_report, "verified", False)):
                    raise FalseCompletionRejected(
                        f"Task {tid!r} cannot commit completion without a verified report."
                    )
                if str(getattr(verification_report, "spec_sha256", "")) != tx_spec.sha256():
                    raise FalseCompletionRejected(
                        f"Task {tid!r} verification contract changed before completion committed."
                    )
            current_epoch = int(row["current_epoch"])
            if epoch is not None and current_epoch != int(epoch):
                raise runtime_persistence.StaleEpochError(
                    f"Stale epoch {epoch} cannot complete task {tid!r} at current_epoch={current_epoch}."
                )
            if epoch is not None and int(epoch) > 0:
                ep_row = conn.execute(
                    "SELECT * FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                    (tid, int(epoch)),
                ).fetchone()
                if ep_row is None or str(ep_row["status"]) != "active":
                    raise runtime_persistence.StaleEpochError(
                        f"Inactive epoch {epoch} cannot complete task {tid!r}."
                    )
                if worker_id is not None and str(ep_row["worker_id"]) != worker_id:
                    raise runtime_persistence.StaleEpochError(
                        f"Epoch {epoch} on task {tid!r} is not owned by {worker_id!r}."
                    )
                if float(ep_row["lease_expires_at"]) <= ts:
                    raise runtime_persistence.LeaseExpiredError(
                        f"Expired epoch {epoch} cannot complete task {tid!r}."
                    )
                conn.execute(
                    "UPDATE runtime_task_epochs SET status = 'released', heartbeat_at = ? WHERE task_id = ? AND epoch = ?",
                    (ts, tid, int(epoch)),
                )
            bad_ms = conn.execute(
                "SELECT task_id FROM runtime_tasks WHERE parent_task_id = ? AND state != 'completed'",
                (tid,),
            ).fetchall()
            if bad_ms:
                raise WorkflowTransitionRejected(
                    f"Task {tid!r} has incomplete milestone(s) inside completion commit."
                )
            bad_actions = conn.execute(
                """
                SELECT action_id FROM runtime_actions
                WHERE task_id = ? AND status IN ('in_flight', 'uncertain') AND action_class != 'read_only'
                """,
                (tid,),
            ).fetchall()
            if bad_actions:
                raise WorkflowTransitionRejected(
                    f"Task {tid!r} has unresolved action(s) inside completion commit."
                )
            seq_row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                (tid,),
            ).fetchone()
            next_seq = int(seq_row[0]) if seq_row else 1
            eff_epoch = current_epoch if epoch is None else int(epoch)
            conn.execute(
                """
                UPDATE runtime_tasks
                SET state = 'completed', state_version = state_version + 1, updated_at = ?
                WHERE task_id = ?
                """,
                (ts, tid),
            )
            conn.execute(
                """
                INSERT INTO runtime_task_transitions (
                    task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                ) VALUES (?, ?, 'running', 'completed', ?, ?, ?, ?)
                """,
                (tid, next_seq, eff_epoch, str(reason)[:240], evidence_json, ts),
            )
            updated = conn.execute("SELECT * FROM runtime_tasks WHERE task_id = ?", (tid,)).fetchone()
            assert updated is not None
            return runtime_persistence._row_to_task(updated)

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )

    def recover_incomplete_transitions(
        self,
        *,
        now: float | None = None,
    ) -> RecoverySweepReport:
        """Reconcile staged checkpoints, interrupted root transitions, and milestone skew on startup/recovery."""
        ts = time.time() if now is None else float(now)

        def _tx(conn: sqlite3.Connection) -> RecoverySweepReport:
            conn.row_factory = sqlite3.Row
            reconciled_ckpts: list[str] = []
            recovered_tasks: list[str] = []
            blocked_tasks: list[str] = []
            cancelled_tasks: list[str] = []
            reconciled_milestones: list[str] = []

            # 1. Reconcile staged 'pending_commit' checkpoints left by mid-transition crashes.
            pending_ckpts = conn.execute(
                "SELECT * FROM runtime_task_checkpoints WHERE status = 'pending_commit' ORDER BY created_at ASC, seq ASC"
            ).fetchall()
            for ck_row in pending_ckpts:
                ck_id = str(ck_row["checkpoint_id"])
                ck_tid = str(ck_row["task_id"])
                try:
                    verified = workflow_checkpoints._decode_and_verify_checkpoint_row(ck_row, verify_integrity=True)
                except workflow_checkpoints.ResumeRejected:
                    conn.execute(
                        "UPDATE runtime_task_checkpoints SET status = 'superseded', updated_at = ? WHERE checkpoint_id = ?",
                        (ts, ck_id),
                    )
                    reconciled_ckpts.append(ck_id)
                    continue
                conn.execute(
                    """
                    UPDATE runtime_task_checkpoints
                    SET status = 'superseded', updated_at = ?
                    WHERE task_id = ? AND seq < ? AND status IN ('committed', 'interrupted', 'resumed')
                    """,
                    (ts, ck_tid, verified.seq),
                )
                conn.execute(
                    "UPDATE runtime_task_checkpoints SET status = 'interrupted', updated_at = ? WHERE checkpoint_id = ?",
                    (ts, ck_id),
                )
                conn.execute(
                    "UPDATE runtime_tasks SET checkpoint_ref = ?, updated_at = ? WHERE task_id = ?",
                    (ck_id, ts, ck_tid),
                )
                reconciled_ckpts.append(ck_id)

            # 2. Reconcile orphaned non-terminal root tasks without an active unexpired lease.
            root_rows = conn.execute(
                """
                SELECT * FROM runtime_tasks
                WHERE parent_task_id IS NULL
                  AND state IN ('running', 'waiting_approval', 'pending', 'paused', 'blocked', 'failed', 'cancelled')
                ORDER BY created_at ASC
                """
            ).fetchall()
            for t_row in root_rows:
                tid = str(t_row["task_id"])
                state = str(t_row["state"])
                current_epoch = int(t_row["current_epoch"])
                has_live_lease = False
                if current_epoch > 0:
                    ep_row = conn.execute(
                        "SELECT status, lease_expires_at FROM runtime_task_epochs WHERE task_id = ? AND epoch = ?",
                        (tid, current_epoch),
                    ).fetchone()
                    if ep_row is not None and str(ep_row["status"]) == "active":
                        if float(ep_row["lease_expires_at"]) > ts:
                            has_live_lease = True
                        else:
                            conn.execute(
                                """
                                UPDATE runtime_task_epochs
                                SET status = 'expired', fenced_at = ?, fence_reason = 'lease_expired_on_recovery'
                                WHERE task_id = ? AND epoch = ? AND status = 'active'
                                """,
                                (ts, tid, current_epoch),
                            )

                if has_live_lease:
                    continue

                # Sweep any orphaned in-flight actions on inactive epochs before deciding task state.
                conn.execute(
                    """
                    UPDATE runtime_actions
                    SET status = 'uncertain', error_code = 'orphaned_in_flight_on_recovery', updated_at = ?
                    WHERE task_id = ? AND status = 'in_flight' AND action_class != 'read_only'
                    """,
                    (ts, tid),
                )
                conn.execute(
                    """
                    UPDATE runtime_actions
                    SET status = 'failed', ok = 0, error_code = 'orphaned_in_flight_on_recovery', updated_at = ?
                    WHERE task_id = ? AND status = 'in_flight' AND action_class = 'read_only'
                    """,
                    (ts, tid),
                )

                try:
                    budget = execution_budget.TaskBudgetState.from_json(str(t_row["budget_json"]))
                except execution_budget.BudgetError:
                    budget = execution_budget.TaskBudgetState(spec=execution_budget.TaskBudgetSpec())

                if state in {"running", "waiting_approval"} or (
                    budget.cancel_requested and state not in {"cancelled", "completed"}
                ):
                    unresolved_rows = conn.execute(
                        """
                        SELECT action_id FROM runtime_actions
                        WHERE task_id = ? AND status IN ('in_flight', 'uncertain') AND action_class != 'read_only'
                        ORDER BY created_at ASC
                        """,
                        (tid,),
                    ).fetchall()
                    unresolved_ids = [str(r["action_id"]) for r in unresolved_rows]
                    ckpt_ref = str(t_row["checkpoint_ref"] or "").strip()
                    ckpt_corrupt = False
                    if ckpt_ref:
                        ck_check = conn.execute(
                            "SELECT * FROM runtime_task_checkpoints WHERE checkpoint_id = ? AND task_id = ?",
                            (ckpt_ref, tid),
                        ).fetchone()
                        if ck_check is None:
                            ckpt_corrupt = True
                        else:
                            try:
                                workflow_checkpoints._decode_and_verify_checkpoint_row(ck_check, verify_integrity=True)
                                conn.execute(
                                    """
                                    UPDATE runtime_task_checkpoints
                                    SET status = 'interrupted', updated_at = ?
                                    WHERE checkpoint_id = ? AND status IN ('committed', 'resumed')
                                    """,
                                    (ts, ckpt_ref),
                                )
                            except workflow_checkpoints.ResumeRejected:
                                ckpt_corrupt = True

                    if unresolved_ids or ckpt_corrupt:
                        target_state = "blocked"
                        reason = (
                            "corrupt_checkpoint_on_recovery"
                            if ckpt_corrupt
                            else "recovered_incomplete_with_unresolved_effects"
                        )
                        blocked_tasks.append(tid)
                    elif budget.cancel_requested:
                        target_state = "cancelled"
                        reason = "recovered_incomplete_cancel"
                        cancelled_tasks.append(tid)
                    else:
                        target_state = "paused"
                        reason = "recovered_incomplete_transition"
                        recovered_tasks.append(tid)

                    reconciled_budget = execution_budget.TaskBudgetState(
                        spec=budget.spec,
                        steps_used=budget.steps_used,
                        tool_calls_used=budget.tool_calls_used,
                        tokens_used=budget.tokens_used,
                        elapsed_s=budget.elapsed_s,
                        recoveries_used=budget.recoveries_used,
                        pause_requested=False,
                        cancel_requested=(target_state == "cancelled"),
                        exhausted_reason=budget.exhausted_reason,
                        verification_contract=budget.verification_contract,
                    )
                    seq_row = conn.execute(
                        "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                        (tid,),
                    ).fetchone()
                    next_seq = int(seq_row[0]) if seq_row else 1
                    conn.execute(
                        """
                        UPDATE runtime_tasks
                        SET state = ?, state_version = state_version + 1, budget_json = ?, updated_at = ?
                        WHERE task_id = ?
                        """,
                        (target_state, reconciled_budget.to_json(), ts, tid),
                    )
                    conn.execute(
                        """
                        INSERT INTO runtime_task_transitions (
                            task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            tid,
                            next_seq,
                            state,
                            target_state,
                            current_epoch,
                            reason,
                            _encode_evidence_json(
                                checkpoint_id=ckpt_ref,
                                extra={"unresolved_action_ids": unresolved_ids} if unresolved_ids else None,
                            ),
                            ts,
                        ),
                    )
                    state = target_state

                # 3. Reconcile child milestone skew when parent has no live worker lease.
                if state in {"paused", "blocked", "failed", "cancelled"}:
                    ms_target = "cancelled" if state == "cancelled" else ("blocked" if state == "blocked" else "paused")
                    ms_filter = (
                        "state NOT IN ('completed', 'cancelled')"
                        if state == "cancelled"
                        else "state IN ('running', 'waiting_approval')"
                    )
                    skewed_ms = conn.execute(
                        f"SELECT task_id, state FROM runtime_tasks WHERE parent_task_id = ? AND {ms_filter}",
                        (tid,),
                    ).fetchall()
                    for ms_row in skewed_ms:
                        ms_tid = str(ms_row["task_id"])
                        ms_from = str(ms_row["state"])
                        ms_seq_row = conn.execute(
                            "SELECT COALESCE(MAX(seq), 0) + 1 FROM runtime_task_transitions WHERE task_id = ?",
                            (ms_tid,),
                        ).fetchone()
                        ms_seq = int(ms_seq_row[0]) if ms_seq_row else 1
                        conn.execute(
                            """
                            UPDATE runtime_tasks
                            SET state = ?, state_version = state_version + 1, updated_at = ?
                            WHERE task_id = ?
                            """,
                            (ms_target, ts, ms_tid),
                        )
                        conn.execute(
                            """
                            INSERT INTO runtime_task_transitions (
                                task_id, seq, from_state, to_state, epoch, reason, evidence_json, created_at
                            ) VALUES (?, ?, ?, ?, ?, 'recovered_milestone_skew', '{}', ?)
                            """,
                            (ms_tid, ms_seq, ms_from, ms_target, current_epoch, ts),
                        )
                        reconciled_milestones.append(ms_tid)

            return RecoverySweepReport(
                recovered_task_ids=tuple(recovered_tasks),
                blocked_task_ids=tuple(blocked_tasks),
                cancelled_task_ids=tuple(cancelled_tasks),
                reconciled_checkpoint_ids=tuple(reconciled_ckpts),
                reconciled_milestone_ids=tuple(reconciled_milestones),
            )

        return runtime_persistence.run_write_transaction(
            self._storage,
            self._db_path,
            _tx,
            retry_policy=self._retry_policy,
        )


def checkpoint_ref_is_none(value: str | None) -> bool:
    return value is None

workflow_state = sys.modules[__name__]

"""MCP wire-protocol boundary: adaptive HTTP transport, parser, and session state.

AS-012 boundary extraction. This module owns everything protocol-level about
talking to a Streamable-HTTP MCP server:

1. Fast-path: Stateless ``2026-07-28`` (``MCP-Protocol-Version`` + ``_meta`` +
   ``Mcp-Method`` headers) or a cached ``2025`` ``Mcp-Session-Id``.
2. Automatic fallback: ``2025-06-18`` ``initialize`` + ``Mcp-Session-Id`` +
   ``notifications/initialized`` handshake (plus an ``/sse`` -> ``/mcp`` URL
   retry on HTTP 405).

The transport is injected as a single ``post(url, headers, body, timeout)``
callable returning a :class:`TransportResponse`, so the negotiation state
machine can be exercised with scripted mock transports (no sockets, no DNS)
while the application keeps its own validating, redirect-rejecting transport.

URL validation, redirect rejection, and network I/O stay in the application:
this module never opens a connection.
"""

import json
import re
from collections.abc import Awaitable, Callable, Mapping
from dataclasses import dataclass
from typing import Any

CLIENT_NAME = "m5-studio"
STATELESS_PROTOCOL_VERSION = "2026-07-28"
STATEFUL_PROTOCOL_VERSION = "2025-06-18"


class McpTransportError(RuntimeError):
    """Raised for MCP protocol/transport failures (subset of RuntimeError for compatibility)."""


class McpRpcError(McpTransportError):
    """Raised when an MCP server returns an explicit JSON-RPC ``error`` object."""


class McpAmbiguousOutcomeError(McpTransportError):
    """Raised when an outbound ``tools/call`` outcome is ambiguous (HTTP 5xx or garbled 200)."""


@dataclass(frozen=True)
class TransportResponse:
    """Transport-agnostic response view; the application adapts its HTTP client to this."""

    status_code: int
    text: str
    content_type: str
    headers: Mapping[str, str]

    @classmethod
    def from_httpx(cls, resp: Any) -> "TransportResponse":
        return cls(
            status_code=int(resp.status_code),
            text=resp.text,
            content_type=(resp.headers.get("content-type") or "").lower(),
            headers={str(k): str(v) for k, v in resp.headers.items()},
        )


Post = Callable[[str, Mapping[str, str], dict[str, Any], float], Awaitable[TransportResponse]]


class SessionStore:
    """Explicit per-alias session-id cache; replaces the previous module global."""

    def __init__(self, backing: dict[str, str] | None = None) -> None:
        self._sessions: dict[str, str] = backing if backing is not None else {}

    def get(self, alias: str) -> str:
        return self._sessions.get(alias, "")

    def set(self, alias: str, session_id: str) -> None:
        self._sessions[alias] = session_id

    def clear(self, alias: str) -> None:
        self._sessions.pop(alias, None)


# ---------------------------------------------------------------------------
# Pure protocol pieces
# ---------------------------------------------------------------------------


def parse_mcp_payload(text: str, content_type: str, status_code: int, expected_id: int) -> dict[str, Any]:
    """Parse a JSON or SSE JSON-RPC response body and return its ``result`` object."""
    ctype = (content_type or "").lower()
    raw_text = (text or "").strip()
    if "text/event-stream" in ctype or raw_text.startswith("event:") or raw_text.startswith("data:"):
        chosen: dict[str, Any] | None = None
        for line in raw_text.splitlines():
            s = line.strip()
            if not s.startswith("data:"):
                continue
            d_str = s[5:].strip()
            if not d_str or d_str == "[DONE]":
                continue
            try:
                pkt = json.loads(d_str)
            except json.JSONDecodeError:
                continue
            if isinstance(pkt, dict):
                if pkt.get("id") == expected_id:
                    chosen = pkt
                    break
                if "result" in pkt or "error" in pkt:
                    chosen = pkt
        if chosen is None:
            raise McpTransportError(f"MCP SSE stream contained no JSON-RPC result: {raw_text[:240]}")
        obj = chosen
    else:
        try:
            obj = json.loads(raw_text)
        except Exception as exc:
            raise McpTransportError(f"Invalid MCP JSON response (HTTP {status_code}): {raw_text[:240]}") from exc

    if not isinstance(obj, dict):
        raise McpTransportError(f"Invalid MCP JSON-RPC envelope (HTTP {status_code}): {raw_text[:240]}")
    if obj.get("error"):
        err = obj["error"]
        msg = err.get("message") if isinstance(err, dict) else str(err)
        code = err.get("code") if isinstance(err, dict) else ""
        raise McpRpcError(f"MCP RPC error ({code}): {msg}")
    if "result" not in obj:
        raise McpTransportError(f"MCP JSON-RPC envelope missing result (HTTP {status_code}): {raw_text[:240]}")
    return obj.get("result") or {}


def build_headers(
    server: Mapping[str, Any],
    method: str,
    tool_name: str = "",
    client_version: str = "",
    action_id: str = "",
) -> dict[str, str]:
    headers: dict[str, str] = {
        "Accept": "application/json, text/event-stream",
        "Content-Type": "application/json",
        "Mcp-Method": method,
    }
    if tool_name:
        headers["Mcp-Name"] = tool_name
    if action_id and method == "tools/call":
        headers["Idempotency-Key"] = action_id
    for k, v in (server.get("headers") or {}).items():
        headers[str(k)] = str(v)
    tok = (server.get("effective_token") or "").strip()
    ah = (server.get("auth_header") or "Authorization").strip()
    if tok and ah.lower() != "none":
        if ah.lower() == "authorization" and not tok.lower().startswith(("bearer ", "basic ", "token ")):
            headers["Authorization"] = f"Bearer {tok}"
        else:
            headers[ah] = tok
    return headers


def build_stateless_body(method: str, params: Mapping[str, Any] | None, request_id: int, client_version: str) -> dict[str, Any]:
    meta_params = {
        **(dict(params) if params else {}),
        "_meta": {
            "io.modelcontextprotocol/protocolVersion": STATELESS_PROTOCOL_VERSION,
            "io.modelcontextprotocol/clientInfo": {"name": CLIENT_NAME, "version": client_version},
            "io.modelcontextprotocol/clientCapabilities": {},
        },
    }
    return {"jsonrpc": "2.0", "id": request_id, "method": method, "params": meta_params}


def build_initialize_body(client_version: str) -> dict[str, Any]:
    return {
        "jsonrpc": "2.0",
        "id": 1,
        "method": "initialize",
        "params": {
            "protocolVersion": STATEFUL_PROTOCOL_VERSION,
            "capabilities": {},
            "clientInfo": {"name": CLIENT_NAME, "version": client_version},
        },
    }


def extract_session_id(headers: Mapping[str, str]) -> str:
    lowered = {str(k).lower(): str(v) for k, v in headers.items()}
    return lowered.get("mcp-session-id", "")


def retry_url_after_405(url: str) -> str | None:
    """Legacy ``/sse`` endpoints answer 405; retry once against ``/mcp``."""
    if url.rstrip("/").endswith("/sse"):
        return re.sub(r"/sse/?$", "/mcp", url)
    return None


# ---------------------------------------------------------------------------
# Adaptive negotiation state machine
# ---------------------------------------------------------------------------


def _raise_for_auth(resp: TransportResponse, url: str) -> None:
    if resp.status_code in (401, 403):
        raise McpTransportError(f"MCP HTTP {resp.status_code} Unauthorized at `{url}` — check API token / Authorization header.")


def _looks_like_session_error(detail: str) -> bool:
    lowered = detail.lower()
    return any(k in lowered for k in ("init", "session", "protocol", "version", "-32600", "-32602"))


async def adaptive_call(
    post: Post,
    *,
    url: str,
    server: Mapping[str, Any],
    method: str,
    params: Mapping[str, Any] | None = None,
    timeout: float = 25.0,
    sessions: SessionStore | None = None,
    client_version: str = "",
    action_id: str = "",
) -> dict[str, Any]:
    """Execute one MCP RPC through the adaptive stateless/stateful transport.

    ``post`` must apply the application's outbound URL validation and redirect
    rejection for every request (including retries issued from here).
    For ``method == 'tools/call'``, HTTP 5xx or malformed HTTP 200 responses raise
    :class:`McpAmbiguousOutcomeError` immediately rather than re-dispatching a
    second ``tools/call`` after handshake.
    """
    sessions = sessions or SessionStore()
    alias = str(server.get("alias") or "")
    is_tool_call = method == "tools/call"
    tool_name = str((params or {}).get("name") or "") if is_tool_call else ""
    base_headers = build_headers(
        server, method, tool_name=tool_name, client_version=client_version, action_id=action_id
    )
    cached_sid = sessions.get(alias)

    req_id = 2
    if cached_sid:
        h1 = {**base_headers, "Mcp-Session-Id": cached_sid}
        body1: dict[str, Any] = {"jsonrpc": "2.0", "id": req_id, "method": method, "params": dict(params) if params else {}}
    else:
        h1 = {**base_headers, "MCP-Protocol-Version": STATELESS_PROTOCOL_VERSION}
        body1 = build_stateless_body(method, params, req_id, client_version)

    resp1 = await post(url, h1, body1, timeout)
    retry_target = retry_url_after_405(url) if resp1.status_code == 405 else None
    if retry_target:
        url = retry_target
        resp1 = await post(url, h1, body1, timeout)

    if resp1.status_code == 200:
        try:
            return parse_mcp_payload(resp1.text, resp1.content_type, resp1.status_code, req_id)
        except McpRpcError as rpc_err:
            if not _looks_like_session_error(str(rpc_err)):
                raise
        except McpTransportError as parse_err:
            if is_tool_call:
                raise McpAmbiguousOutcomeError(str(parse_err)) from parse_err
            raise
    _raise_for_auth(resp1, url)
    if is_tool_call and resp1.status_code >= 500:
        raise McpAmbiguousOutcomeError(
            f"MCP HTTP {resp1.status_code} on `{method}` (`{tool_name}`): remote outcome is uncertain ({resp1.text[:200]})"
        )

    # Fallback to the 2025 stateful `initialize` + `Mcp-Session-Id` handshake.
    sessions.clear(alias)
    init_headers = build_headers(server, "initialize", client_version=client_version)
    init_resp = await post(url, init_headers, build_initialize_body(client_version), timeout)
    if init_resp.status_code >= 400:
        raise McpTransportError(f"MCP HTTP {init_resp.status_code} from `{url}`: {init_resp.text[:260]}")
    parse_mcp_payload(init_resp.text, init_resp.content_type, init_resp.status_code, 1)

    sid = extract_session_id(init_resp.headers)
    req_headers = build_headers(
        server, method, tool_name=tool_name, client_version=client_version, action_id=action_id
    )
    notif_headers = build_headers(server, "notifications/initialized", client_version=client_version)
    if sid:
        sessions.set(alias, sid)
        req_headers["Mcp-Session-Id"] = sid
        notif_headers["Mcp-Session-Id"] = sid

    try:
        await post(url, notif_headers, {"jsonrpc": "2.0", "method": "notifications/initialized"}, 10.0)
    except Exception:
        pass

    final_resp = await post(
        url,
        req_headers,
        {"jsonrpc": "2.0", "id": 3, "method": method, "params": dict(params) if params else {}},
        timeout,
    )
    if final_resp.status_code >= 400:
        if is_tool_call and final_resp.status_code >= 500:
            raise McpAmbiguousOutcomeError(
                f"MCP HTTP {final_resp.status_code} on `{method}` (`{tool_name}`): remote outcome is uncertain ({final_resp.text[:200]})"
            )
        raise McpTransportError(f"MCP HTTP {final_resp.status_code} on `{method}`: {final_resp.text[:260]}")
    try:
        return parse_mcp_payload(final_resp.text, final_resp.content_type, final_resp.status_code, 3)
    except McpRpcError:
        raise
    except McpTransportError as parse_err:
        if is_tool_call:
            raise McpAmbiguousOutcomeError(str(parse_err)) from parse_err
        raise

mcp_client = sys.modules[__name__]

"""OpenContext personal-memory store: CRUD, FTS5 search, and vault linting.

AS-012 boundary extraction. The OpenContext vault (`oc://doc/<id>`) is the
agent's persistent memory layer: a SQLite table mirrored into an FTS5 index.
This module owns that boundary and nothing else — every function receives its
storage handle and database path explicitly, so tests can run against a
temporary database (or a fake storage double) without touching application
state. Prompt assembly (`build_pinned_opencontext_prompt`) stays in the
application: it is presentation, not storage.
"""

import re
import sqlite3
import time
import uuid
from pathlib import Path
from typing import Any, Protocol



class StorageLike(Protocol):
    """Minimal storage seam (structurally compatible with app.SQLiteStorage)."""

    def connect(self, database: Path, *, timeout: float = 5.0) -> sqlite3.Connection: ...


def doc_uri(doc_id: str) -> str:
    return f"oc://doc/{doc_id}"


def sanitize_fts5_query(raw_query: str) -> str:
    """Reduce free text to a safe OR-of-quoted-tokens FTS5 MATCH expression."""
    tokens = re.findall(r"[A-Za-z0-9_]{2,}", raw_query or "")
    if not tokens:
        return ""
    return " OR ".join(f'"{t}"' for t in tokens[:14])


def _row_to_doc(row: sqlite3.Row) -> dict[str, Any]:
    d = dict(row)
    d["pinned"] = bool(d.get("pinned", 0))
    d["uri"] = doc_uri(str(d["id"]))
    return d


def list_docs(storage: StorageLike, db_path: Path, folder: str = "") -> list[dict[str, Any]]:
    def _read(conn: sqlite3.Connection) -> list[sqlite3.Row]:
        conn.row_factory = sqlite3.Row
        if folder:
            return conn.execute(
                "SELECT * FROM opencontext_docs WHERE folder = ? ORDER BY pinned DESC, updated_at DESC",
                (folder,),
            ).fetchall()
        return conn.execute(
            "SELECT * FROM opencontext_docs ORDER BY pinned DESC, updated_at DESC"
        ).fetchall()

    rows = runtime_persistence.run_read(storage, db_path, _read)
    return [_row_to_doc(r) for r in rows]


def get_doc(storage: StorageLike, db_path: Path, doc_id_or_uri: str) -> dict[str, Any]:
    clean_id = (doc_id_or_uri or "").strip().replace("oc://doc/", "").strip("/")

    def _read(conn: sqlite3.Connection) -> sqlite3.Row | None:
        conn.row_factory = sqlite3.Row
        row: sqlite3.Row | None = conn.execute(
            "SELECT * FROM opencontext_docs WHERE id = ?",
            (clean_id,),
        ).fetchone()
        return row

    row = runtime_persistence.run_read(storage, db_path, _read)
    if not row:
        raise KeyError(f"OpenContext doc `{clean_id}` not found.")
    return _row_to_doc(row)


def upsert_doc(
    storage: StorageLike,
    db_path: Path,
    title: str,
    content: str,
    folder: str = "decisions",
    description: str = "",
    pinned: bool = False,
    doc_id: str = "",
) -> dict[str, Any]:
    clean_title = (title or "").strip()[:140]
    if not clean_title:
        raise ValueError("Document `title` is required.")
    clean_folder = re.sub(r"[^a-z0-9_/-]+", "-", (folder or "decisions").strip().lower()).strip("-") or "decisions"
    did = (doc_id or "").strip().replace("oc://doc/", "") or f"oc-{uuid.uuid4().hex[:8]}"
    desc = (description or content.splitlines()[0] if content else "").strip()[:240]
    now = time.time()

    def _write(conn: sqlite3.Connection) -> None:
        conn.execute(
            """
            INSERT INTO opencontext_docs (id, folder, title, description, content, pinned, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
              folder=excluded.folder, title=excluded.title, description=excluded.description,
              content=excluded.content, pinned=excluded.pinned, updated_at=excluded.updated_at
            """,
            (did, clean_folder, clean_title, desc, content, 1 if pinned else 0, now),
        )
        conn.execute("DELETE FROM opencontext_fts WHERE doc_id = ?", (did,))
        conn.execute(
            "INSERT INTO opencontext_fts (doc_id, folder, title, description, content) VALUES (?, ?, ?, ?, ?)",
            (did, clean_folder, clean_title, desc, content),
        )

    runtime_persistence.run_write_transaction(storage, db_path, _write)
    return get_doc(storage, db_path, did)


def delete_doc(storage: StorageLike, db_path: Path, doc_id: str) -> None:
    clean_id = (doc_id or "").strip().replace("oc://doc/", "")

    def _write(conn: sqlite3.Connection) -> None:
        conn.execute("DELETE FROM opencontext_docs WHERE id = ?", (clean_id,))
        conn.execute("DELETE FROM opencontext_fts WHERE doc_id = ?", (clean_id,))

    runtime_persistence.run_write_transaction(storage, db_path, _write)


def search_docs(storage: StorageLike, db_path: Path, query: str, limit: int = 8) -> list[dict[str, Any]]:
    fts_q = sanitize_fts5_query(query)
    if not fts_q:
        return list_docs(storage, db_path)[:limit]

    def _read(conn: sqlite3.Connection) -> list[sqlite3.Row]:
        conn.row_factory = sqlite3.Row
        return conn.execute(
            """
            SELECT d.*, bm25(opencontext_fts) AS rank_score
            FROM opencontext_fts
            JOIN opencontext_docs d ON d.id = opencontext_fts.doc_id
            WHERE opencontext_fts MATCH ?
            ORDER BY rank_score ASC
            LIMIT ?
            """,
            (fts_q, limit),
        ).fetchall()

    rows = runtime_persistence.run_read(storage, db_path, _read)
    return [_row_to_doc(r) for r in rows]


def lint_vault(storage: StorageLike, db_path: Path) -> dict[str, Any]:
    """
    Deterministic Knowledge Hygiene (`lint`):
      Checks `oc://doc/<id>` citation resolution, orphan unlinked notes, stale notes (>30d), and empty bodies.
    """
    docs = list_docs(storage, db_path)
    valid_ids = {d["id"] for d in docs}
    inbound_refs: dict[str, int] = {d["id"]: 0 for d in docs}
    dangling_links: list[dict[str, str]] = []
    stale_docs: list[str] = []
    thin_docs: list[str] = []
    now = time.time()

    link_rx = re.compile(r"oc://doc/([A-Za-z0-9_-]+)")
    for d in docs:
        body = d.get("content") or ""
        if len(body.strip()) < 30:
            thin_docs.append(d["uri"])
        if now - float(d.get("updated_at") or now) > 30 * 86400:
            stale_docs.append(d["uri"])
        for ref_id in link_rx.findall(body):
            if ref_id not in valid_ids:
                dangling_links.append({"from": d["uri"], "missing_target": f"oc://doc/{ref_id}"})
            elif ref_id != d["id"]:
                inbound_refs[ref_id] = inbound_refs.get(ref_id, 0) + 1

    orphans = [d["uri"] for d in docs if not d["pinned"] and inbound_refs.get(d["id"], 0) == 0 and len(docs) > 1]
    score = max(0, 100 - len(dangling_links) * 15 - len(thin_docs) * 10 - min(20, len(orphans) * 4))
    return {
        "total_docs": len(docs),
        "pinned_docs": sum(1 for d in docs if d["pinned"]),
        "health_score": score,
        "dangling_links": dangling_links,
        "orphan_docs": orphans,
        "stale_docs": stale_docs,
        "thin_docs": thin_docs,
    }

context_store = sys.modules[__name__]

"""Deterministic first-run preflight for guided onboarding (AS-039).

The acceptance criterion is *"a new user completes a guided first task without
editing code"*. That needs an honest answer to one question before the first
task: what is missing, and what is the single next click?

Design decisions:

* **Pure and offline.** :func:`build_report` is a pure function over
  :class:`PreflightInputs`. It never resolves DNS, probes a provider, reads the
  keyring, or opens a database. The app adapter collects the snapshot from local
  state only, so rendering onboarding can never leak a credential or phone home
  (repository principle 1: local-first privacy).
* **Fail explicit, never optimistic.** Anything unknown degrades to
  ``action-required``; a step reports ``ready`` only from positive local
  evidence. A missing model list is *not* treated as "probably fine".
* **No secrets, no shell.** The report carries booleans, counts, aliases and
  UI action tokens only. Guidance is phrased as something to click, never as a
  command the user must paste, and the guided task itself reuses the existing
  ``/api/chat/stream`` path instead of introducing a second executor.
* **Capability, not platform.** The sandbox step checks whether a configured
  container CLI is present; it never assumes macOS, a chip, or a runtime name.

Execution is optional by design: the first task is a plain chat turn, so the
sandbox step can be ``optional`` without blocking onboarding.
"""


from dataclasses import dataclass, field
from typing import Any, Literal

StepStatus = Literal["ready", "optional", "action-required", "blocked"]
ExecutionMode = Literal["disabled", "sandbox", "host"]

STEP_ORDER = ("auth", "model-source", "model-available", "workspace", "execution", "first-task")
READY_STATUSES = frozenset({"ready", "optional"})
FIRST_TASK_PROMPT = (
    "Reply with the single word READY. This confirms Studio can reach the selected "
    "model, so we can start the real task next."
)
FIRST_TASK_TITLE = "Ask a model to say READY"


@dataclass(frozen=True)
class ProviderState:
    """Credential-free view of one configured provider; never carries the key itself."""

    alias: str
    enabled: bool
    has_credential: bool
    model_count: int

    def usable_models(self) -> int:
        return self.model_count if self.enabled and self.has_credential else 0


@dataclass(frozen=True)
class PreflightInputs:
    """Local-only snapshot of everything the preflight is allowed to consider."""

    auth_ready: bool
    local_runtime_configured: bool
    providers: tuple[ProviderState, ...] = ()
    # Combo aliases are routing presets, not models: a seeded combo can exist on a
    # fresh install while nothing behind it is reachable, so it never counts here.
    combo_count: int = 0
    local_models_available: int = 0
    local_probe: Literal["not-run", "ran", "unavailable"] = "not-run"
    execution_mode: ExecutionMode = "disabled"
    sandbox_runtime_available: bool = False
    workspace_writable: bool = False
    workspace_detail: str = ""

    @property
    def usable_provider_models(self) -> int:
        return sum(provider.usable_models() for provider in self.providers)

    @property
    def known_model_count(self) -> int:
        return self.usable_provider_models + max(self.local_models_available, 0)


@dataclass(frozen=True)
class Step:
    """One onboarding step plus the single action that advances it."""

    id: str
    title: str
    status: StepStatus
    detail: str
    action_label: str = ""
    action: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "title": self.title,
            "status": self.status,
            "detail": self.detail,
            "action_label": self.action_label,
            "action": self.action,
        }


@dataclass(frozen=True)
class PreflightReport:
    """Ordered onboarding plan with one explicit next action."""

    steps: tuple[Step, ...]
    first_task_prompt: str = FIRST_TASK_PROMPT
    notes: tuple[str, ...] = field(default_factory=tuple)

    @property
    def blocked(self) -> bool:
        return any(step.status == "blocked" for step in self.steps)

    @property
    def ready(self) -> bool:
        return all(step.status in READY_STATUSES for step in self.steps)

    @property
    def next_step(self) -> Step | None:
        """The first step that needs the user; None once everything is ready."""
        for step in self.steps:
            if step.status not in READY_STATUSES:
                return step
        return None

    @property
    def completed_count(self) -> int:
        return sum(1 for step in self.steps if step.status in READY_STATUSES)

    def to_dict(self) -> dict[str, Any]:
        next_step = self.next_step
        return {
            "ready": self.ready,
            "blocked": self.blocked,
            "completed_count": self.completed_count,
            "total_count": len(self.steps),
            "summary": f"{self.completed_count} of {len(self.steps)} steps ready",
            "next_step": next_step.to_dict() if next_step else None,
            "steps": [step.to_dict() for step in self.steps],
            "first_task": {"title": FIRST_TASK_TITLE, "prompt": self.first_task_prompt},
            "notes": list(self.notes),
        }


def _auth_step(inputs: PreflightInputs) -> Step:
    if inputs.auth_ready:
        return Step(
            id="auth",
            title="Studio is running and protected",
            status="ready",
            detail="The server is answering on loopback with its bearer token in place.",
        )
    return Step(
        id="auth",
        title="Studio has no API token",
        status="blocked",
        detail=(
            "Protected routes will fail closed until a token exists. Restart Studio on "
            "loopback so it can generate one, or set a token in the environment."
        ),
        action_label="Restart Studio",
        action="restart-server",
    )


def _model_source_step(inputs: PreflightInputs) -> Step:
    usable = [provider for provider in inputs.providers if provider.enabled and provider.has_credential]
    if usable:
        aliases = ", ".join(sorted(provider.alias for provider in usable))
        return Step(
            id="model-source",
            title="A model source is configured",
            status="ready",
            detail=f"Enabled provider(s) with stored credentials: {aliases}.",
        )
    if inputs.local_models_available > 0 and inputs.local_probe == "ran":
        return Step(
            id="model-source",
            title="The local runtime is serving models",
            status="ready",
            detail=(
                f"The configured local runtime listed {inputs.local_models_available} model(s) "
                "when asked; no cloud provider is required."
            ),
        )
    disabled = [provider.alias for provider in inputs.providers if not provider.enabled]
    no_key = [provider.alias for provider in inputs.providers if provider.enabled and not provider.has_credential]
    hints: list[str] = []
    if no_key:
        hints.append("enabled but missing a credential: " + ", ".join(sorted(no_key)))
    if disabled:
        hints.append("disabled: " + ", ".join(sorted(disabled)))
    if inputs.local_runtime_configured:
        hints.append("a local runtime URL is configured but has not answered yet")
    suffix = f" ({'; '.join(hints)})" if hints else ""
    return Step(
        id="model-source",
        title="Connect a model source",
        status="action-required",
        detail=(
            "Add a cloud provider with an API key, or start a local runtime such as oMLX, "
            "Ollama, or llama.cpp on its loopback port" + suffix + "."
        ),
        action_label="Open providers",
        action="open-providers",
    )


def _model_available_step(inputs: PreflightInputs) -> Step:
    known = inputs.known_model_count
    if known > 0:
        return Step(
            id="model-available",
            title="Models are available",
            status="ready",
            detail=f"{known} model(s) or combo(s) are configured and selectable.",
        )
    if any(provider.enabled and provider.has_credential for provider in inputs.providers):
        return Step(
            id="model-available",
            title="Fetch the model list",
            status="action-required",
            detail=(
                "A provider is configured but no models are listed yet. Use Fetch models on "
                "the provider so Studio knows what it can call."
            ),
            action_label="Fetch models",
            action="open-providers",
        )
    if inputs.local_runtime_configured and inputs.local_probe == "ran":
        return Step(
            id="model-available",
            title="The local runtime reported no models",
            status="action-required",
            detail=(
                "The runtime answered but listed no models. Load a model in the runtime, or "
                "connect a cloud provider."
            ),
            action_label="Check again",
            action="probe-local-models",
        )
    if inputs.local_runtime_configured and inputs.local_probe == "unavailable":
        return Step(
            id="model-available",
            title="The local runtime did not answer",
            status="action-required",
            detail=(
                "Studio could not reach the configured local runtime URL. Start it, then "
                "check again; nothing is contacted until you press the button."
            ),
            action_label="Check local models",
            action="probe-local-models",
        )
    if inputs.local_runtime_configured:
        return Step(
            id="model-available",
            title="Confirm which models exist",
            status="action-required",
            detail=(
                "A local runtime URL is configured, but listing models means contacting it. "
                "Press the button to ask it once, or add a cloud provider instead. Routing "
                "combos do not count: a preset can exist while its targets are unreachable."
            ),
            action_label="Check local models",
            action="probe-local-models",
        )
    return Step(
        id="model-available",
        title="Choose a model",
        status="action-required",
        detail=(
            "Once a source is connected, pick a model (or an auto-fallback combo) in the "
            "Chat header. No model has been discovered yet."
        ),
        action_label="Open Chat",
        action="open-chat",
    )


def _workspace_step(inputs: PreflightInputs) -> Step:
    if inputs.workspace_writable:
        return Step(
            id="workspace",
            title="Workspace is writable",
            status="ready",
            detail=inputs.workspace_detail or "The configured workspace directory is present and writable.",
        )
    return Step(
        id="workspace",
        title="Fix the workspace directory",
        status="action-required",
        detail=inputs.workspace_detail
        or "The configured workspace directory is missing or read-only; file tools will refuse to write.",
        action_label="Check workspace",
        action="fix-workspace",
    )


def _execution_step(inputs: PreflightInputs) -> Step:
    if inputs.execution_mode == "disabled":
        return Step(
            id="execution",
            title="Code execution is off (fine for a first chat)",
            status="optional",
            detail=(
                "Shell/Python tools stay disabled, which is the safe default. Enable the "
                "container sandbox later if you want the agent to run commands."
            ),
        )
    if inputs.execution_mode == "host":
        return Step(
            id="execution",
            title="Host execution is enabled (unsandboxed)",
            status="optional",
            detail=(
                "Commands run as your OS user with no sandbox. Keep this only on a machine "
                "and workspace you trust; the container sandbox is the safer opt-in."
            ),
        )
    if inputs.sandbox_runtime_available:
        return Step(
            id="execution",
            title="Container sandbox is ready",
            status="ready",
            detail="A container runtime is on PATH; sandboxed execution is available.",
        )
    return Step(
        id="execution",
        title="Container runtime not found",
        status="action-required",
        detail=(
            "Sandbox mode is selected but no container CLI is on PATH. Install/start the "
            "runtime, or switch execution mode to disabled to continue onboarding."
        ),
        action_label="Review execution mode",
        action="review-execution",
    )


def _first_task_step(inputs: PreflightInputs) -> Step:
    if inputs.known_model_count > 0:
        return Step(
            id="first-task",
            title=FIRST_TASK_TITLE,
            status="ready",
            detail="Send the guided first prompt from Chat; it makes exactly one model call you trigger.",
            action_label="Run first task",
            action="run-first-task",
        )
    return Step(
        id="first-task",
        title=FIRST_TASK_TITLE,
        status="action-required",
        detail="Available once a model is selectable, so the guided prompt has somewhere to go.",
    )


def build_report(inputs: PreflightInputs) -> PreflightReport:
    """Build the ordered onboarding plan from a local-only snapshot."""
    builders = {
        "auth": _auth_step,
        "model-source": _model_source_step,
        "model-available": _model_available_step,
        "workspace": _workspace_step,
        "execution": _execution_step,
        "first-task": _first_task_step,
    }
    steps = tuple(builders[step_id](inputs) for step_id in STEP_ORDER)
    notes = [
        "This preflight reads local configuration only; it makes no network calls unless you "
        "press Check local models.",
        "Nothing here requires editing a config file or pasting a shell command.",
    ]
    if inputs.combo_count:
        notes.append(
            f"{inputs.combo_count} routing combo(s) are configured. They are presets, so they "
            "are not counted as available models."
        )
    if inputs.local_probe == "ran":
        notes.append(f"The local runtime listed {inputs.local_models_available} model(s) when asked.")
    elif inputs.local_probe == "unavailable":
        notes.append("The local runtime URL did not answer the model listing request.")
    return PreflightReport(steps=steps, notes=tuple(notes))

onboarding_preflight = sys.modules[__name__]

"""Deterministic failure-injection harness for workflow and action-boundary resilience tests."""


import asyncio
from collections.abc import Awaitable, Callable, Sequence
from dataclasses import dataclass
import threading
import time
import uuid
from typing import Literal

FailureKind = Literal["crash", "timeout", "provider_loss", "disconnect"]
_KINDS = frozenset({"crash", "timeout", "provider_loss", "disconnect"})

ActionBoundary = Literal[
    "before_intent",
    "after_intent_before_effect",
    "after_effect_before_result_commit",
    "before_task_completion",
]
ACTION_BOUNDARIES: frozenset[str] = frozenset(
    {
        "before_intent",
        "after_intent_before_effect",
        "after_effect_before_result_commit",
        "before_task_completion",
    }
)


class FailureInjectionError(ValueError):
    """Raised when a failure scenario or boundary fault specification is malformed."""


class InjectedBoundaryCrashError(RuntimeError):
    """Hard-crash fault injected at a deterministic execution boundary.

    Explicitly re-raised past ``except Exception:`` soft-failure handlers in
    ``execution_spine`` and ``app.py`` so durable ``in_flight`` ledger rows and
    active worker leases remain in authentic post-SIGKILL state while ASGI test
    portals remain healthy.
    """

    def __init__(
        self,
        detail: str,
        *,
        boundary: ActionBoundary,
        tool_name: str = "",
        action_id: str = "",
        task_id: str = "",
        step_id: str = "",
    ) -> None:
        super().__init__(detail)
        self.detail = detail
        self.boundary: ActionBoundary = boundary
        self.tool_name = tool_name
        self.action_id = action_id
        self.task_id = task_id
        self.step_id = step_id


@dataclass(frozen=True, slots=True)
class ActionBoundaryFaultSpec:
    """Deterministic specification for injecting crashes at an action boundary."""

    boundary: ActionBoundary
    tool_name: str = ""
    task_id: str = ""
    step_id: str | int | None = None
    max_fires: int = 1
    detail: str = "injected action-boundary crash"

    def __post_init__(self) -> None:
        if self.boundary not in ACTION_BOUNDARIES:
            raise FailureInjectionError(f"unknown action boundary: {self.boundary!r}")
        if "\x00" in self.tool_name or "\x00" in self.task_id or "\x00" in self.detail:
            raise FailureInjectionError("boundary fault text fields must not contain NUL.")
        if isinstance(self.max_fires, bool) or not isinstance(self.max_fires, int) or self.max_fires < 1:
            raise FailureInjectionError("max_fires must be an integer >= 1.")


@dataclass(frozen=True, slots=True)
class ActionBoundaryTriggerEvent:
    """Auditable record of a fired action-boundary fault."""

    rule_id: str
    boundary: ActionBoundary
    tool_name: str
    action_id: str
    task_id: str
    step_id: str
    fired_at: float
    detail: str


class _ArmedBoundaryRule:
    __slots__ = ("rule_id", "spec", "fires_count")

    def __init__(self, rule_id: str, spec: ActionBoundaryFaultSpec) -> None:
        self.rule_id = rule_id
        self.spec = spec
        self.fires_count = 0


class ActionBoundaryFaultInjector:
    """Thread-safe deterministic injector for execution-spine and completion boundaries."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._rules: list[_ArmedBoundaryRule] = []
        self._events: list[ActionBoundaryTriggerEvent] = []

    @property
    def is_armed(self) -> bool:
        return bool(self._rules)

    def arm(self, spec: ActionBoundaryFaultSpec) -> str:
        rule_id = f"fault-{uuid.uuid4().hex[:10]}"
        with self._lock:
            self._rules.append(_ArmedBoundaryRule(rule_id, spec))
        return rule_id

    def disarm(self, rule_id: str) -> bool:
        with self._lock:
            before = len(self._rules)
            self._rules = [r for r in self._rules if r.rule_id != rule_id]
            return len(self._rules) < before

    def clear(self) -> None:
        with self._lock:
            self._rules.clear()
            self._events.clear()

    def events(self) -> tuple[ActionBoundaryTriggerEvent, ...]:
        with self._lock:
            return tuple(self._events)

    def check_boundary(
        self,
        boundary: ActionBoundary,
        *,
        tool_name: str = "",
        action_id: str = "",
        task_id: str = "",
        step_id: str | int | None = None,
    ) -> None:
        if not self._rules:
            return
        step_str = "" if step_id is None else str(step_id)
        matched_spec: ActionBoundaryFaultSpec | None = None
        with self._lock:
            for idx, rule in enumerate(self._rules):
                spec = rule.spec
                if spec.boundary != boundary:
                    continue
                if spec.tool_name and spec.tool_name != tool_name:
                    continue
                if spec.task_id and spec.task_id != task_id:
                    continue
                if spec.step_id is not None and str(spec.step_id) != step_str:
                    continue
                rule.fires_count += 1
                matched_spec = spec
                event = ActionBoundaryTriggerEvent(
                    rule_id=rule.rule_id,
                    boundary=boundary,
                    tool_name=tool_name,
                    action_id=action_id,
                    task_id=task_id,
                    step_id=step_str,
                    fired_at=time.time(),
                    detail=spec.detail,
                )
                self._events.append(event)
                if rule.fires_count >= spec.max_fires:
                    self._rules.pop(idx)
                break
        if matched_spec is not None:
            raise InjectedBoundaryCrashError(
                matched_spec.detail,
                boundary=boundary,
                tool_name=tool_name,
                action_id=action_id,
                task_id=task_id,
                step_id=step_str,
            )


DEFAULT_BOUNDARY_INJECTOR = ActionBoundaryFaultInjector()


def check_action_boundary(
    boundary: ActionBoundary,
    *,
    tool_name: str = "",
    action_id: str = "",
    task_id: str = "",
    step_id: str | int | None = None,
    injector: ActionBoundaryFaultInjector | None = None,
) -> None:
    """Trigger any matching armed crash fault on ``injector`` or ``DEFAULT_BOUNDARY_INJECTOR``."""
    target = DEFAULT_BOUNDARY_INJECTOR if injector is None else injector
    if not target.is_armed:
        return
    target.check_boundary(
        boundary,
        tool_name=tool_name,
        action_id=action_id,
        task_id=task_id,
        step_id=step_id,
    )


@dataclass(frozen=True, slots=True)
class FailureScenario:
    name: str
    kind: FailureKind
    timeout_seconds: float = 0.05

    def __post_init__(self) -> None:
        if not isinstance(self.name, str) or not self.name.strip() or "\x00" in self.name:
            raise FailureInjectionError("scenario name must be non-empty and contain no NUL.")
        if self.kind not in _KINDS:
            raise FailureInjectionError(f"unknown failure kind: {self.kind}")
        if self.timeout_seconds <= 0:
            raise FailureInjectionError("timeout_seconds must be positive.")


@dataclass(frozen=True, slots=True)
class FailureOutcome:
    name: str
    kind: FailureKind
    observed: bool
    recovered: bool
    detail: str


AsyncOperation = Callable[[FailureScenario], Awaitable[None]]


async def run_failure_scenario(scenario: FailureScenario, operation: AsyncOperation) -> FailureOutcome:
    """Run one injected scenario and classify only expected failure boundaries."""
    try:
        await asyncio.wait_for(operation(scenario), timeout=scenario.timeout_seconds)
    except TimeoutError:
        if scenario.kind != "timeout":
            return FailureOutcome(scenario.name, scenario.kind, False, False, "unexpected timeout")
        return FailureOutcome(scenario.name, scenario.kind, True, True, "operation cancelled at timeout boundary")
    except asyncio.CancelledError:
        if scenario.kind != "disconnect":
            raise
        return FailureOutcome(scenario.name, scenario.kind, True, True, "disconnect cancellation propagated")
    except ConnectionError:
        if scenario.kind != "provider_loss":
            return FailureOutcome(scenario.name, scenario.kind, False, False, "unexpected provider loss")
        return FailureOutcome(scenario.name, scenario.kind, True, True, "provider loss classified for retry/recovery")
    except RuntimeError:
        if scenario.kind != "crash":
            return FailureOutcome(scenario.name, scenario.kind, False, False, "unexpected runtime failure")
        return FailureOutcome(scenario.name, scenario.kind, True, True, "crash isolated without process termination")
    else:
        return FailureOutcome(scenario.name, scenario.kind, False, False, "failure was not observed")


async def run_failure_suite(scenarios: Sequence[FailureScenario], operation: AsyncOperation) -> tuple[FailureOutcome, ...]:
    """Run an ordered suite and return one auditable outcome per scenario."""
    if not scenarios:
        raise FailureInjectionError("scenarios must not be empty.")
    outcomes = [await run_failure_scenario(scenario, operation) for scenario in scenarios]
    return tuple(outcomes)

failure_injection = sys.modules[__name__]

"""Authoritative execution-spine admission gate, action classes, and anti-bypass scope (M5-P0-06 / M5-P1-02).

This stdlib-only module defines the authoritative admission boundary between the
runtime and every consequential tool, skill script, smart block, and MCP
operation:

- ``ActionClass`` / ``classify_action`` -- deterministic separation between
  managed reads (``read_only``) and consequential effects (``managed_edit``,
  ``consequential``, ``external``);
- ``TaskAdmissionSnapshot`` / ``TaskContextResolver`` -- authoritative task
  lifecycle state and lease-epoch fencing checks;
- ``Policy`` -- deny-by-default authorization decision for one invocation;
- ``ActionLedger`` -- durable intent (start) before execution and durable
  outcome (finish) after;
- ``ActiveAdmissionScope`` / ``require_active_admission`` -- unforgeable
  ``ContextVar`` capability token minted exclusively inside
  ``DurableActionBoundary.admit_and_execute`` so direct inner-executor bypass
  fails closed at runtime;
- ``DurableActionBoundary`` -- classify -> check grant provenance -> check task
  state & epoch -> authorize policy -> durably record intent -> execute inside
  scoped admission token -> durably record outcome.

This module is inlined into the standalone artifact by
``scripts/build_studio.py`` (``INLINED_MODULES``); keep its imports strictly to
the Python standard library and free of references to ``app``.
"""

import asyncio
import contextvars
import time
from collections.abc import Awaitable, Callable, Mapping
from dataclasses import dataclass
from typing import Any, Literal, Protocol


ActionClass = Literal["read_only", "managed_edit", "consequential", "external"]

ACTION_CLASSES: frozenset[str] = frozenset({"read_only", "managed_edit", "consequential", "external"})
CONSEQUENTIAL_ACTION_CLASSES: frozenset[str] = frozenset({"managed_edit", "consequential", "external"})

MANAGED_READ_TOOLS: frozenset[str] = frozenset(
    {
        "list_files",
        "grep_search",
        "read_file",
        "codegraph_architecture",
        "codegraph_context",
        "codegraph_impact",
        "codegraph_path",
        "codegraph_quality",
        "oc_lint",
        "ctx_search",
        "oc_search",
        "oc_read",
        "list_edit_batches",
        "reconcile_task_actions",
        "mcp_bridge__get_current_session_data",
        "mcp_bridge__get_harness_diff",
        "mcp_bridge__oc_search",
        "mcp_bridge__oc_lint",
        "mcp_bridge__codegraph_query",
    }
)

MANAGED_READ_BLOCKS: frozenset[str] = frozenset({"json-peek", "csv-peek", "shortcut-debt"})
CONSEQUENTIAL_BLOCKS: frozenset[str] = frozenset({"test-summary", "first-error"})
ALL_REUSABLE_BLOCKS: frozenset[str] = MANAGED_READ_BLOCKS | CONSEQUENTIAL_BLOCKS

MANAGED_EDIT_TOOLS: frozenset[str] = frozenset({"write_file", "edit_file", "rollback_edits", "oc_save_doc"})

CONSEQUENTIAL_TOOLS: frozenset[str] = frozenset(
    {
        "run_bash",
        "ctx_execute_python",
        "delegate_subagent",
        "skill_execute_script",
        "mcp_bridge__start_council",
        "mcp_bridge__send_response",
        "mcp_bridge__summon_omlx_agent",
        "mcp_bridge__close_council",
        "mcp_bridge__create_harness_worktree",
        "mcp_bridge__oc_save_doc",
    }
)

GRANT_SOURCES: frozenset[str] = frozenset(
    {
        "unspecified",
        "none",
        "policy",
        "operator_approval",
        "operator_one_call",
        "skill_opt_in",
        "model_output",
    }
)

# Grant sources permitted to carry an explicit one-call or human approval (`approved=True`).
# `"unspecified"` preserves compatibility for narrow contract callers that supply
# `ActionRequest(..., approved=True)` directly; `"model_output"`, `"none"`, and `"policy"`
# can never confer an explicit approval grant.
EXPLICIT_APPROVAL_GRANT_SOURCES: frozenset[str] = frozenset(
    {"unspecified", "operator_approval", "operator_one_call", "skill_opt_in"}
)

# Keys inside model-emitted tool arguments that are untrusted data and are never
# consulted by admission, grant, policy, task-state, or epoch checks.
MODEL_UNTRUSTED_AUTHORITY_KEYS: frozenset[str] = frozenset(
    {
        "approved",
        "user_approved",
        "auto_approve",
        "grant",
        "grant_source",
        "approval_id",
        "policy",
        "harness_policy",
        "action_class",
        "task_id",
        "task_state",
        "epoch",
        "current_epoch",
        "worker_id",
        "bypass_admission",
    }
)

ADMISSIBLE_CONSEQUENTIAL_TASK_STATES: frozenset[str] = frozenset({"running"})
ADMISSIBLE_MANAGED_READ_TASK_STATES: frozenset[str] = frozenset(
    {"running", "waiting_approval", "awaiting_approval"}
)


class DirectExecutorBypassError(PermissionError):
    """Raised when an inner consequential executor is called outside DurableActionBoundary."""


def normalize_reusable_block_name(raw_block: Any) -> str:
    """Normalize a smart-block selector so case/whitespace never bypasses policy."""
    return str(raw_block or "").strip().lower()


def classify_action(tool_name: str, args: Mapping[str, Any] | None = None) -> ActionClass:
    """Deterministically classify an action into managed read vs consequential effect.

    Unknown or malformed tool names always classify as ``"consequential"`` (never
    ``"read_only"``) so unregistered operations fail closed under consequential
    scrutiny. Model-supplied metadata inside ``args`` (such as ``args["action_class"]``)
    is ignored; only structural dispatch selectors are inspected.
    """
    clean = str(tool_name or "").strip()
    if not clean:
        return "consequential"
    if clean == "ctx_run_block":
        block = normalize_reusable_block_name(args.get("block") if isinstance(args, Mapping) else "")
        if block in MANAGED_READ_BLOCKS:
            return "read_only"
        return "consequential"
    if clean in MANAGED_READ_TOOLS:
        return "read_only"
    if clean in MANAGED_EDIT_TOOLS:
        return "managed_edit"
    if clean.startswith("mcp__"):
        return "external"
    if clean in CONSEQUENTIAL_TOOLS:
        return "consequential"
    return "consequential"


def is_consequential_action_class(action_class: str) -> bool:
    """Return True for every non-read-only (or unrecognized) action class."""
    if action_class not in ACTION_CLASSES:
        return True
    return action_class != "read_only"


@dataclass(frozen=True, slots=True)
class AdmissionDecision:
    """Outcome of a policy check for one tool invocation."""

    allowed: bool
    reason: str = ""
    requires_approval: bool = False
    action_class: ActionClass = "consequential"
    error_code: str | None = None

    @property
    def is_consequential(self) -> bool:
        return is_consequential_action_class(self.action_class)


@dataclass(frozen=True, slots=True)
class TaskAdmissionSnapshot:
    """Authoritative server-side snapshot of task lifecycle state and lease epoch."""

    task_id: str
    state: str
    current_epoch: int = 0
    epoch_status: str | None = None
    epoch_worker_id: str | None = None
    lease_expired: bool = False
    unresolved_effect_ids: tuple[str, ...] = ()


@dataclass(frozen=True, slots=True)
class ActionRequest:
    """One action submitted to the authoritative admission boundary."""

    tool_name: str
    args: dict[str, Any]
    policy: str
    approved: bool
    session_id: str
    additional_denial: str | None = None
    denial_as_exception: bool = False
    action_class: ActionClass | None = None
    grant_source: str = "unspecified"
    approval_id: str | None = None
    task_id: str | None = None
    task_state: str | None = None
    epoch: int | None = None
    worker_id: str | None = None
    action_id: str | None = None
    step_id: str | int | None = None
    call_index: int | None = None
    replay_policy: str | None = None


@dataclass(frozen=True, slots=True)
class ActiveAdmissionScope:
    """Unforgeable capability scope active only while an admitted executor runs."""

    tool_name: str
    action_class: ActionClass
    policy: str
    session_id: str
    event_id: int
    grant_source: str
    task_id: str | None = None
    epoch: int | None = None
    worker_id: str | None = None
    action_id: str = ""
    attempt: int = 1
    attempt_id: str = ""
    replay_policy: str = "non_idempotent"
    lease_id: str | None = None
    footprint_scope: str = ""
    barriers: tuple[tuple[str, str], ...] = ()


_ACTIVE_ADMISSION_SCOPE: contextvars.ContextVar[ActiveAdmissionScope | None] = contextvars.ContextVar(
    "m5_active_admission_scope",
    default=None,
)


def current_admission_scope() -> ActiveAdmissionScope | None:
    """Return the active admission scope for the current async/call context, if any."""
    return _ACTIVE_ADMISSION_SCOPE.get()


def require_active_admission(
    *,
    expected_tool: str | None = None,
    expected_action_classes: frozenset[str] | set[str] | None = None,
) -> ActiveAdmissionScope:
    """Assert that execution is inside an admitted ``DurableActionBoundary`` scope.

    Raises ``DirectExecutorBypassError`` (a ``PermissionError`` subclass) when
    an inner consequential executor is called directly without crossing the
    admission gate, or when an admitted lower-privilege scope attempts to
    invoke an executor of another action class or tool identity.
    """
    scope = _ACTIVE_ADMISSION_SCOPE.get()
    if scope is None:
        target = f" for `{expected_tool}`" if expected_tool else ""
        raise DirectExecutorBypassError(
            f"Direct executor bypass blocked{target}: consequential execution must cross DurableActionBoundary."
        )
    if expected_tool is not None and scope.tool_name != expected_tool:
        raise DirectExecutorBypassError(
            f"Direct executor bypass blocked: active admission for `{scope.tool_name}` cannot execute `{expected_tool}`."
        )
    if expected_action_classes is not None and scope.action_class not in expected_action_classes:
        allowed_str = ", ".join(sorted(expected_action_classes))
        raise DirectExecutorBypassError(
            f"Direct executor bypass blocked: active admission class `{scope.action_class}` "
            f"for `{scope.tool_name}` is not permitted for `{allowed_str}` executor."
        )
    return scope


class Policy(Protocol):
    """Authorization seam: decide whether an action may execute."""

    def effective_policy(self, requested: str) -> str:
        """Resolve the requested policy name to a known effective policy."""
        ...

    def authorize(
        self, tool_name: str, args: dict[str, Any], policy: str, *, approved: bool
    ) -> AdmissionDecision:
        """Return a deny-by-default decision for one invocation."""
        ...


class ActionLedger(Protocol):
    """Persistence seam: durable intent before execution, durable outcome after."""

    def start(
        self, session_id: str, tool_name: str, policy: str, explicit_approval: bool, args: dict[str, Any]
    ) -> int:
        """Durably record the action attempt; returns the ledger event id."""
        ...

    def finish(
        self, event_id: int, result: dict[str, Any], elapsed_ms: int, *, status: str = "completed"
    ) -> None:
        """Durably record the outcome for a previously started action."""
        ...


@dataclass(frozen=True, slots=True)
class IntentBeginDecision:
    """Authoritative pre-execution intent & replay decision from ``IntentLedger``."""

    proceed: bool
    action_id: str
    attempt: int
    attempt_id: str
    status: str
    replay_policy: str
    replay_blocked: bool = False
    already_committed: bool = False
    reconciled: bool = False
    reason: str = ""
    error: Exception | None = None


class IntentLedger(Protocol):
    """Durable M5 2.0 intent/result ledger seam over ``runtime_actions`` (M5-P1-03)."""

    def begin(
        self,
        request: ActionRequest,
        *,
        effective_policy: str,
        action_class: ActionClass,
        allowed: bool,
        explicit_approval: bool,
    ) -> IntentBeginDecision:
        """Atomically evaluate replay policy and commit durable ``in_flight`` (or ``denied``) intent."""
        ...

    def mark_never_started(self, action_id: str, *, error_code: str) -> str:
        """Record that execution was blocked prior to entering ``executor``."""
        ...

    def complete(self, action_id: str, result: Mapping[str, Any], elapsed_ms: int) -> str:
        """Finalize a normal tool return as ``committed``, ``failed``, or ``uncertain``."""
        ...

    def record_exception(self, action_id: str, exc: BaseException, elapsed_ms: int) -> str:
        """Finalize an exception raised inside ``executor`` as ``uncertain`` or ``failed``."""
        ...


class TaskContextResolver(Protocol):
    """Authoritative resolver for task lifecycle state and lease-epoch metadata."""

    def resolve_task_context(self, request: ActionRequest) -> TaskAdmissionSnapshot | None:
        """Return the authoritative snapshot for ``request``, or ``None`` if unbound/missing."""
        ...


@dataclass(frozen=True, slots=True)
class ProfileAdmissionOutcome:
    """Outcome of unified capability, policy, and resource-barrier admission (M5-P3-02)."""

    allowed: bool
    reason: str = ""
    error_code: str | None = None
    lease_id: str | None = None
    footprint_scope: str = ""
    conflict_denied: bool = False
    conflicting_barriers: tuple[str, ...] = ()
    exhausted_resources: tuple[str, ...] = ()
    barriers: tuple[tuple[str, str], ...] = ()
    profile: dict[str, Any] | None = None
    handle: Any = None


class ExecutionProfileCoordinator(Protocol):
    """Unified execution-profile, resource-barrier, and footprint-reconciliation seam (M5-P3-02)."""

    def admit_profile(
        self,
        request: ActionRequest,
        *,
        effective_policy: str,
        action_class: ActionClass,
    ) -> ProfileAdmissionOutcome:
        """Verify capability descriptor & unified policy, acquire resource barriers, and snapshot pre-state."""
        ...

    def reconcile_and_release(
        self,
        handle: Any,
        result: dict[str, Any] | None,
        *,
        action_id: str = "",
        exc: BaseException | None = None,
    ) -> dict[str, Any] | None:
        """Observe post-execution footprint expansion, reconcile/quarantine violations, and release barriers."""
        ...

    def release_only(self, handle: Any) -> None:
        """Release acquired resource barriers when execution aborts before entering ``executor``."""
        ...


Executor = Callable[[], Awaitable[dict[str, Any]]]


def _validate_grant_and_action_class(
    request: ActionRequest,
) -> tuple[ActionClass, bool, str | None]:
    """Validate action class and grant provenance; return ``(action_class, effective_approved, denial_reason)``."""
    inferred_class = classify_action(request.tool_name, request.args)
    resolved_class: ActionClass = inferred_class
    if request.action_class is not None:
        if request.action_class not in ACTION_CLASSES:
            return (
                "consequential",
                False,
                f"Unrecognized action class `{request.action_class}`; invocation denied.",
            )
        if is_consequential_action_class(inferred_class) and request.action_class == "read_only":
            return (
                inferred_class,
                False,
                f"Action class downgrade from `{inferred_class}` to `read_only` for `{request.tool_name}` is forbidden.",
            )
        resolved_class = request.action_class

    grant_source = str(request.grant_source or "").strip() or "unspecified"
    if grant_source not in GRANT_SOURCES:
        return (
            resolved_class,
            False,
            f"Unrecognized grant provenance `{grant_source}`; invocation denied.",
        )
    if grant_source == "model_output":
        if request.approved:
            return (
                resolved_class,
                False,
                "Permission or approval cannot be inferred from model output.",
            )
        effective_approved = False
    elif request.approved and grant_source not in EXPLICIT_APPROVAL_GRANT_SOURCES:
        return (
            resolved_class,
            False,
            f"Explicit approval cannot originate from grant source `{grant_source}`.",
        )
    else:
        effective_approved = bool(request.approved)

    if request.tool_name == "skill_execute_script" and grant_source != "skill_opt_in":
        return (
            resolved_class,
            False,
            "Skill script execution requires server `skill_opt_in` provenance and cannot be invoked by model tool calls.",
        )

    return resolved_class, effective_approved, None


def _validate_task_state_and_epoch(
    request: ActionRequest,
    action_class: ActionClass,
    snapshot: TaskAdmissionSnapshot | None,
) -> str | None:
    """Validate task lifecycle state and durable epoch fencing; return denial reason or ``None``."""
    if request.task_id is not None and snapshot is None:
        return f"Authoritative task `{request.task_id}` does not exist."

    if snapshot is None:
        if request.epoch is not None:
            return "Task epoch supplied without an authoritative task context."
        if request.task_state is not None:
            snapshot = TaskAdmissionSnapshot(
                task_id=request.session_id or "transient",
                state=request.task_state,
                current_epoch=0,
            )
        else:
            return None

    normalized_state = str(snapshot.state or "").strip().lower()
    if not normalized_state:
        return f"Task `{snapshot.task_id}` has an empty or invalid lifecycle state."

    if is_consequential_action_class(action_class):
        if normalized_state not in ADMISSIBLE_CONSEQUENTIAL_TASK_STATES:
            return (
                f"Consequential `{action_class}` action `{request.tool_name}` requires task state "
                f"`running` (current state: `{normalized_state}`)."
            )
    else:
        if normalized_state not in ADMISSIBLE_MANAGED_READ_TASK_STATES:
            return (
                f"Managed read `{request.tool_name}` is not permitted when task `{snapshot.task_id}` "
                f"is in state `{normalized_state}`."
            )

    if request.epoch is not None and request.epoch <= 0:
        return f"Invalid non-positive task epoch `{request.epoch}`."
    if snapshot.current_epoch < 0:
        return f"Task `{snapshot.task_id}` has invalid negative epoch `{snapshot.current_epoch}`."

    if snapshot.current_epoch > 0:
        if request.epoch is None:
            return (
                f"Missing required task epoch for task `{snapshot.task_id}` "
                f"(current epoch: {snapshot.current_epoch})."
            )
        if request.epoch != snapshot.current_epoch:
            return (
                f"Stale or mismatched task epoch {request.epoch} for task `{snapshot.task_id}` "
                f"(current epoch: {snapshot.current_epoch})."
            )
        if snapshot.lease_expired or snapshot.epoch_status == "expired":
            return f"Task `{snapshot.task_id}` epoch {request.epoch} lease has expired."
        if snapshot.epoch_status != "active":
            return (
                f"Task `{snapshot.task_id}` epoch {request.epoch} is not active "
                f"(status: `{snapshot.epoch_status or 'missing'}`)."
            )
        if snapshot.epoch_worker_id is not None:
            if request.worker_id is None:
                return (
                    f"Missing required worker_id for task `{snapshot.task_id}` epoch "
                    f"{request.epoch} (owned by `{snapshot.epoch_worker_id}`)."
                )
            if request.worker_id != snapshot.epoch_worker_id:
                return (
                    f"Worker `{request.worker_id}` does not own task `{snapshot.task_id}` epoch "
                    f"{request.epoch} (owned by `{snapshot.epoch_worker_id}`)."
                )
    elif request.epoch is not None:
        return (
            f"Unexpected task epoch {request.epoch} supplied for task `{snapshot.task_id}` "
            "with no active epoch."
        )

    if is_consequential_action_class(action_class) and snapshot.unresolved_effect_ids:
        can_self_reconcile = (
            len(snapshot.unresolved_effect_ids) == 1
            and request.action_id is not None
            and request.action_id == snapshot.unresolved_effect_ids[0]
            and (
                request.replay_policy == "reconcilable"
                or request.tool_name in {"write_file", "oc_save_doc"}
            )
        )
        if not can_self_reconcile:
            sample = ", ".join(snapshot.unresolved_effect_ids[:3])
            return (
                f"Consequential `{action_class}` action `{request.tool_name}` blocked: "
                f"task `{snapshot.task_id}` has unresolved side effects ({sample}) "
                "requiring reconciliation before replacement execution."
            )

    return None


class DurableActionBoundary:
    """Authorize -> durably record intent -> execute -> durably record outcome.

    Guarantees pinned by ``tests/test_execution_spine.py`` and
    ``tests/test_action_admission_gate.py``:

    1. Action classification deterministically separates managed reads
       (``read_only``) from consequential effects (``managed_edit``,
       ``consequential``, ``external``) and forbids class downgrades.
    2. Grant provenance, task lifecycle state, durable epoch fencing, and policy
       errors all fail closed; no permission is ever inferred from model text
       or untrusted tool arguments.
    3. An action whose intent record cannot be persisted is never executed.
    4. Denials and failures are recorded durably when the ledger allows; a
       ledger failure while finalizing surfaces as an ``audit_warning`` on the
       result instead of silently dropping the record, and the durable
       ``started`` row still proves the attempt.
    5. Executor exceptions re-raise only after the durable attempt record
       exists (a failed finalization is swallowed for the failure path only).
    6. Execution runs inside a ``ContextVar`` ``ActiveAdmissionScope`` so inner
       executors enforce ``require_active_admission`` and reject direct bypass.
    7. Optional ``pre_execute_guard`` (e.g. asserting no active SQLite write
       transaction spans tool dispatch, M5-P1-01) fails closed before
       ``executor`` runs, finalizing the attempt as ``failed`` and re-raising.
    """

    def __init__(
        self,
        policy: Policy,
        ledger: ActionLedger,
        *,
        pre_execute_guard: Callable[[], None] | None = None,
        task_context_resolver: TaskContextResolver | None = None,
        intent_ledger: IntentLedger | None = None,
        boundary_injector: failure_injection.ActionBoundaryFaultInjector | None = None,
        profile_coordinator: ExecutionProfileCoordinator | None = None,
    ) -> None:
        self._policy = policy
        self._ledger = ledger
        self._pre_execute_guard = pre_execute_guard
        self._task_context_resolver = task_context_resolver
        self._intent_ledger = intent_ledger
        self._boundary_injector = boundary_injector
        self._profile_coordinator = profile_coordinator

    async def admit_and_execute(self, request: ActionRequest, executor: Executor) -> dict[str, Any]:
        effective = self._policy.effective_policy(request.policy)
        action_class, effective_approved, pre_denial = _validate_grant_and_action_class(request)

        task_denial: str | None = None
        if pre_denial is None:
            snapshot: TaskAdmissionSnapshot | None = None
            if self._task_context_resolver is not None:
                try:
                    snapshot = self._task_context_resolver.resolve_task_context(request)
                except Exception:
                    task_denial = "Task lifecycle context resolution failed; invocation denied."
            elif request.task_id is not None and request.task_state is not None:
                snapshot = TaskAdmissionSnapshot(
                    task_id=request.task_id,
                    state=request.task_state,
                    current_epoch=request.epoch or 0,
                    epoch_status="active" if request.epoch else None,
                    epoch_worker_id=request.worker_id,
                    lease_expired=False,
                )
            if task_denial is None:
                task_denial = _validate_task_state_and_epoch(request, action_class, snapshot)

        if pre_denial is not None:
            decision = AdmissionDecision(False, pre_denial, False, action_class)
        elif task_denial is not None:
            decision = AdmissionDecision(False, task_denial, False, action_class)
        else:
            try:
                raw_decision = self._policy.authorize(
                    request.tool_name, request.args, effective, approved=effective_approved
                )
                decision = AdmissionDecision(
                    bool(raw_decision.allowed),
                    str(raw_decision.reason or ""),
                    bool(raw_decision.requires_approval),
                    action_class,
                    getattr(raw_decision, "error_code", None),
                )
            except Exception:
                # Policy evaluation errors are not permission to execute.
                decision = AdmissionDecision(
                    False,
                    "Authorization policy evaluation failed; invocation denied.",
                    False,
                    action_class,
                )

        if request.additional_denial:
            decision = AdmissionDecision(
                False,
                request.additional_denial,
                False,
                action_class,
            )

        profile_outcome: ProfileAdmissionOutcome | None = None
        profile_handle: Any = None
        profile_released = False
        if decision.allowed and self._profile_coordinator is not None:
            try:
                profile_outcome = self._profile_coordinator.admit_profile(
                    request,
                    effective_policy=effective,
                    action_class=action_class,
                )
            except Exception:
                profile_outcome = ProfileAdmissionOutcome(
                    allowed=False,
                    reason="Execution profile admission failed; invocation denied.",
                    error_code="admission_failed",
                )
            if not profile_outcome.allowed:
                decision = AdmissionDecision(
                    False,
                    profile_outcome.reason or "Execution profile denied invocation.",
                    decision.requires_approval,
                    action_class,
                    profile_outcome.error_code,
                )
            else:
                profile_handle = profile_outcome.handle

        try:
            if decision.allowed:
                failure_injection.check_action_boundary(
                    "before_intent",
                    tool_name=request.tool_name,
                    action_id=str(request.action_id or ""),
                    task_id=str(request.task_id or request.session_id or ""),
                    step_id=request.step_id,
                    injector=self._boundary_injector,
                )

            explicit_approval = bool(effective_approved and decision.requires_approval)
            event_id = self._ledger.start(
                request.session_id, request.tool_name, effective, explicit_approval, request.args
            )
            started = time.perf_counter()

            intent_decision: IntentBeginDecision | None = None
            if self._intent_ledger is not None:
                try:
                    intent_decision = self._intent_ledger.begin(
                        request,
                        effective_policy=effective,
                        action_class=action_class,
                        allowed=decision.allowed,
                        explicit_approval=explicit_approval,
                    )
                except Exception as intent_exc:
                    # Fail closed: if durable intent cannot be committed before execution,
                    # the consequential executor must NEVER run.
                    intent_fail: dict[str, Any] = {
                        "ok": False,
                        "output": f"Durable intent persistence failed for `{request.tool_name}`: {intent_exc}",
                        "diff": "",
                        "elapsed_ms": round((time.perf_counter() - started) * 1000),
                    }
                    try:
                        self._ledger.finish(event_id, intent_fail, intent_fail["elapsed_ms"], status="failed")
                    except Exception:
                        pass
                    raise

            if not decision.allowed:
                result: dict[str, Any] = {
                    "ok": False,
                    "output": f"Denied: {decision.reason}",
                    "diff": "",
                    "elapsed_ms": 1,
                    "action_class": action_class,
                }
                if decision.error_code:
                    result["error_code"] = decision.error_code
                if profile_outcome is not None:
                    if profile_outcome.profile is not None:
                        result["execution_profile"] = profile_outcome.profile
                    if profile_outcome.conflict_denied:
                        result["conflict_denied"] = True
                        result["conflicting_barriers"] = list(profile_outcome.conflicting_barriers)
                        result["exhausted_resources"] = list(profile_outcome.exhausted_resources)
                if intent_decision is not None:
                    result["action_id"] = intent_decision.action_id
                    result["attempt"] = intent_decision.attempt
                    result["attempt_id"] = intent_decision.attempt_id
                    result["ledger_status"] = intent_decision.status
                    result["replay_policy"] = intent_decision.replay_policy
                try:
                    self._ledger.finish(event_id, result, 1, status="denied")
                except Exception:
                    result["audit_warning"] = "Denial could not be finalized in the local audit log."
                if request.denial_as_exception:
                    raise PermissionError(result["output"])
                return result

            if intent_decision is not None and not intent_decision.proceed:
                if intent_decision.reconciled and intent_decision.already_committed:
                    reconciled_res: dict[str, Any] = {
                        "ok": True,
                        "output": (
                            intent_decision.reason
                            or f"Reconciled `{request.tool_name}` (`{intent_decision.action_id}`): effect already committed."
                        ),
                        "diff": "",
                        "elapsed_ms": 1,
                        "action_class": action_class,
                        "action_id": intent_decision.action_id,
                        "attempt": intent_decision.attempt,
                        "attempt_id": intent_decision.attempt_id,
                        "ledger_status": intent_decision.status,
                        "replay_policy": intent_decision.replay_policy,
                        "reconciled": True,
                    }
                    try:
                        self._ledger.finish(event_id, reconciled_res, 1, status="completed")
                    except Exception:
                        reconciled_res["audit_warning"] = "Reconciliation could not be finalized in the local audit log."
                    return reconciled_res

                blocked_res: dict[str, Any] = {
                    "ok": False,
                    "output": (
                        intent_decision.reason
                        or f"Replay blocked for `{request.tool_name}` (`{intent_decision.action_id}`)."
                    ),
                    "diff": "",
                    "elapsed_ms": 1,
                    "action_class": action_class,
                    "action_id": intent_decision.action_id,
                    "attempt": intent_decision.attempt,
                    "attempt_id": intent_decision.attempt_id,
                    "ledger_status": intent_decision.status,
                    "replay_policy": intent_decision.replay_policy,
                    "replay_blocked": True,
                }
                if intent_decision.status == "uncertain":
                    blocked_res["uncertain"] = True
                if intent_decision.already_committed:
                    blocked_res["already_committed"] = True
                try:
                    self._ledger.finish(event_id, blocked_res, 1, status="denied")
                except Exception:
                    blocked_res["audit_warning"] = "Replay denial could not be finalized in the local audit log."
                if request.denial_as_exception:
                    if intent_decision.error is not None:
                        raise intent_decision.error
                    raise PermissionError(blocked_res["output"])
                return blocked_res

            if self._pre_execute_guard is not None:
                try:
                    self._pre_execute_guard()
                except Exception as guard_exc:
                    guard_ms = round((time.perf_counter() - started) * 1000)
                    if intent_decision is not None and self._intent_ledger is not None:
                        try:
                            self._intent_ledger.mark_never_started(
                                intent_decision.action_id,
                                error_code=type(guard_exc).__name__,
                            )
                        except Exception:
                            pass
                    guard_fail: dict[str, Any] = {
                        "ok": False,
                        "output": f"Tool `{request.tool_name}` blocked before start: {guard_exc}",
                        "diff": "",
                        "elapsed_ms": guard_ms,
                    }
                    try:
                        self._ledger.finish(event_id, guard_fail, guard_ms, status="failed")
                    except Exception:
                        pass
                    raise

            resolved_action_id = intent_decision.action_id if intent_decision is not None else str(request.action_id or "")
            resolved_task_key = str(request.task_id or request.session_id or "")
            failure_injection.check_action_boundary(
                "after_intent_before_effect",
                tool_name=request.tool_name,
                action_id=resolved_action_id,
                task_id=resolved_task_key,
                step_id=request.step_id,
                injector=self._boundary_injector,
            )

            scope = ActiveAdmissionScope(
                tool_name=request.tool_name,
                action_class=action_class,
                policy=effective,
                session_id=request.session_id,
                event_id=event_id,
                grant_source=str(request.grant_source or "unspecified"),
                task_id=request.task_id,
                epoch=request.epoch,
                worker_id=request.worker_id,
                action_id=(intent_decision.action_id if intent_decision is not None else ""),
                attempt=(intent_decision.attempt if intent_decision is not None else 1),
                attempt_id=(intent_decision.attempt_id if intent_decision is not None else ""),
                replay_policy=(intent_decision.replay_policy if intent_decision is not None else "non_idempotent"),
                lease_id=(profile_outcome.lease_id if profile_outcome is not None else None),
                footprint_scope=(profile_outcome.footprint_scope if profile_outcome is not None else ""),
                barriers=(profile_outcome.barriers if profile_outcome is not None else ()),
            )
            try:
                scope_token = _ACTIVE_ADMISSION_SCOPE.set(scope)
                try:
                    result = await executor()
                finally:
                    _ACTIVE_ADMISSION_SCOPE.reset(scope_token)
            except failure_injection.InjectedBoundaryCrashError:
                if profile_handle is not None and self._profile_coordinator is not None:
                    profile_released = True
                    abort_fn = getattr(self._profile_coordinator, "abort_on_interrupt", None)
                    try:
                        if callable(abort_fn):
                            abort_fn(profile_handle, action_id=resolved_action_id, reason="boundary_crash")
                        else:
                            self._profile_coordinator.release_only(profile_handle)
                    except Exception:
                        pass
                raise
            except asyncio.CancelledError as cancel_exc:
                if profile_handle is not None and self._profile_coordinator is not None:
                    profile_released = True
                    abort_fn = getattr(self._profile_coordinator, "abort_on_interrupt", None)
                    try:
                        if callable(abort_fn):
                            abort_fn(profile_handle, action_id=resolved_action_id, reason="cancelled_in_flight")
                        else:
                            self._profile_coordinator.release_only(profile_handle)
                    except Exception:
                        pass
                cancel_ms = round((time.perf_counter() - started) * 1000)
                cancel_status = "uncertain" if is_consequential_action_class(action_class) else "failed"
                if intent_decision is not None and self._intent_ledger is not None:
                    try:
                        cancel_status = self._intent_ledger.record_exception(
                            intent_decision.action_id, cancel_exc, cancel_ms
                        )
                    except Exception:
                        pass
                try:
                    self._ledger.finish(
                        event_id,
                        {
                            "ok": False,
                            "uncertain": cancel_status == "uncertain",
                            "output": f"Tool `{request.tool_name}` cancelled in flight.",
                            "diff": "",
                            "elapsed_ms": cancel_ms,
                        },
                        cancel_ms,
                        status="uncertain" if cancel_status == "uncertain" else "failed",
                    )
                except Exception:
                    pass
                raise
            except Exception as exc:
                if profile_handle is not None and self._profile_coordinator is not None:
                    profile_released = True
                    try:
                        self._profile_coordinator.reconcile_and_release(
                            profile_handle,
                            None,
                            action_id=resolved_action_id,
                            exc=exc,
                        )
                    except Exception:
                        try:
                            self._profile_coordinator.release_only(profile_handle)
                        except Exception:
                            pass
                err_ms = round((time.perf_counter() - started) * 1000)
                err_ledger_status = "failed"
                if intent_decision is not None and self._intent_ledger is not None:
                    try:
                        err_ledger_status = self._intent_ledger.record_exception(
                            intent_decision.action_id, exc, err_ms
                        )
                    except Exception:
                        err_ledger_status = "uncertain"
                failure: dict[str, Any] = {
                    "ok": False,
                    "output": f"Tool `{request.tool_name}` failed: {exc}",
                    "diff": "",
                    "elapsed_ms": err_ms,
                }
                audit_err_status = "uncertain" if err_ledger_status == "uncertain" else "failed"
                try:
                    self._ledger.finish(event_id, failure, err_ms, status=audit_err_status)
                except Exception:
                    pass  # The durable started row still proves that execution was attempted.
                raise

            failure_injection.check_action_boundary(
                "after_effect_before_result_commit",
                tool_name=request.tool_name,
                action_id=resolved_action_id,
                task_id=resolved_task_key,
                step_id=request.step_id,
                injector=self._boundary_injector,
            )

            if profile_handle is not None and self._profile_coordinator is not None:
                profile_released = True
                try:
                    reconciled_result = self._profile_coordinator.reconcile_and_release(
                        profile_handle,
                        result,
                        action_id=resolved_action_id,
                        exc=None,
                    )
                    if reconciled_result is not None:
                        result = reconciled_result
                except Exception as rec_exc:
                    try:
                        self._profile_coordinator.release_only(profile_handle)
                    except Exception:
                        pass
                    result = {
                        **result,
                        "ok": False,
                        "uncertain": True,
                        "error_code": "footprint_reconciliation_failed",
                        "output": (
                            f"Footprint reconciliation failed for `{request.tool_name}` ({rec_exc}); "
                            + str(result.get("output") or "")
                        ),
                    }
            elapsed = int(result.get("elapsed_ms") or round((time.perf_counter() - started) * 1000))
            if intent_decision is not None and self._intent_ledger is not None:
                try:
                    final_status = self._intent_ledger.complete(intent_decision.action_id, result, elapsed)
                    result = {
                        **result,
                        "action_id": intent_decision.action_id,
                        "attempt": intent_decision.attempt,
                        "attempt_id": intent_decision.attempt_id,
                        "ledger_status": final_status,
                    }
                except Exception:
                    result = {
                        **result,
                        "action_id": intent_decision.action_id,
                        "attempt": intent_decision.attempt,
                        "attempt_id": intent_decision.attempt_id,
                        "ledger_status": "in_flight",
                        "audit_warning": "Tool result could not be finalized in the durable action ledger.",
                    }
            try:
                if bool(result.get("uncertain")):
                    self._ledger.finish(event_id, result, elapsed, status="uncertain")
                else:
                    self._ledger.finish(event_id, result, elapsed)
            except Exception:
                # The durable `started` event still records the action attempt; don't erase its outcome in memory.
                result = {**result, "audit_warning": "Tool result could not be finalized in the local audit log."}
            return result
        finally:
            if profile_handle is not None and not profile_released and self._profile_coordinator is not None:
                try:
                    abort_fn = getattr(self._profile_coordinator, "abort_on_interrupt", None)
                    if (
                        callable(abort_fn)
                        and intent_decision is not None
                        and intent_decision.proceed
                    ):
                        abort_fn(
                            profile_handle,
                            action_id=intent_decision.action_id,
                            reason="interrupted_in_flight",
                        )
                    else:
                        self._profile_coordinator.release_only(profile_handle)
                except Exception:
                    pass

execution_spine = sys.modules[__name__]

"""Durable, cursor-addressable task event stream for harness sessions (M5-P1-07).

The runtime already writes one append-only JSONL log per harness session under
``.harnesses/sessions/<session_id>.jsonl``. That log is the source the UI
re-renders after a reload, so it has to behave like a durable event stream
rather than a debug trace:

* **Monotonic, gap-detectable sequence numbers.** Every record carries a ``seq``
  that strictly increases per session. A reader that remembers ``seq = N`` can
  ask for ``> N`` and can *prove* whether it missed anything: a pruned history,
  a counter rollback after a restore, or a crash between counter allocation and
  append all show up as a discontinuity instead of silently vanishing.
* **At-most-once terminal records.** Terminal turn outcomes and approval
  decisions can be appended with a ``dedupe_key``. Re-appending the same key
  returns the record that is already durable instead of writing a second one, so
  a retried or concurrently resumed turn cannot emit two "turn completed" or two
  "approval decided" records.
* **Bounded storage.** Logs are pruned to a byte budget, keeping the newest
  events. Pruning is visible to readers through ``retained_from_seq`` so an old
  cursor is answered with ``snapshot_required`` instead of a half history.
* **Explicit truncation.** A torn or non-JSON line is skipped and counted; it is
  never invented or repaired into a fake event.

Durability contract: appends use ``O_APPEND`` + ``fsync`` of the record, and the
sequence sidecar (``<session>.seq``) is replaced atomically. The store assumes a
single application process owns a session at a time, which matches the runtime's
own worker-lease model; concurrent appends from separate processes are not
supported and are not claimed to be.

This module is standard-library only and does no I/O outside the store directory
it is given. It never invents events, never deletes a session directory, and
never mutates a record after it is written.
"""


import json
import os
import threading
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable

TASK_EVENT_STREAM_VERSION = 1

DEFAULT_READ_LIMIT = 200
MAX_READ_LIMIT = 1000
#: Roll the log over once it grows past this size, keeping the newest events.
DEFAULT_MAX_LOG_BYTES = 8 * 1024 * 1024
DEFAULT_RETAIN_EVENTS = 4000
#: How often a live stream emits a heartbeat frame while idle.
STREAM_HEARTBEAT_SECONDS = 10.0

#: Turn outcomes that end a turn; the newest one decides the reconstructed state.
TERMINAL_TURN_EVENTS = frozenset({"turn/end"})
#: Turn-end states that mean the turn reached a final outcome.
TERMINAL_TURN_STATES = frozenset({"completed", "cancelled", "failed"})

_APPEND_LOCK = threading.Lock()
_DEDUPE_CACHE: dict[str, dict[str, dict[str, Any]]] = {}
_DEDUPE_CACHE_SESSIONS: dict[str, str] = {}


class TaskEventError(Exception):
    """Raised when a session id or cursor cannot address the event store safely."""


def _safe_session_id(session_id: str) -> str:
    """Return a store-safe session id or raise.

    Session ids become file names, so anything that can escape the store
    directory is rejected rather than sanitized (a sanitized id would silently
    point at a different session).
    """
    sid = (session_id or "").strip()
    if not sid or len(sid) > 128:
        raise TaskEventError("Task event session id must be 1-128 characters.")
    if ".." in sid or "/" in sid or "\\" in sid:
        raise TaskEventError(f"Unsafe task event session id: {session_id!r}")
    if not all(ch.isalnum() or ch in "-_." for ch in sid):
        raise TaskEventError(f"Unsafe task event session id: {session_id!r}")
    return sid


@dataclass(frozen=True)
class TaskEventSnapshot:
    """Event-derived view of a session, used for reload reconstruction."""

    session_id: str
    latest_seq: int
    retained_from_seq: int
    event_count: int
    turns_started: int
    turns_completed: int
    last_turn_state: str
    terminal: bool
    undecided_approvals: tuple[str, ...]
    approval_decisions: tuple[tuple[str, str], ...]
    last_event_type: str
    last_event_ts: float
    skipped_records: int

    def to_dict(self) -> dict[str, Any]:
        return {
            "session_id": self.session_id,
            "stream_version": TASK_EVENT_STREAM_VERSION,
            "latest_seq": self.latest_seq,
            "retained_from_seq": self.retained_from_seq,
            "event_count": self.event_count,
            "turns_started": self.turns_started,
            "turns_completed": self.turns_completed,
            "last_turn_state": self.last_turn_state,
            "terminal": self.terminal,
            "undecided_approvals": list(self.undecided_approvals),
            "approval_decisions": [
                {"approval_id": aid, "decision": decision} for aid, decision in self.approval_decisions
            ],
            "last_event_type": self.last_event_type,
            "last_event_ts": self.last_event_ts,
            "skipped_records": self.skipped_records,
        }


@dataclass(frozen=True)
class TaskEventPage:
    """One cursor read over a session's event log."""

    session_id: str
    events: tuple[dict[str, Any], ...]
    next_cursor: int
    latest_seq: int
    retained_from_seq: int
    has_more: bool
    truncated: bool
    snapshot_required: bool
    resync_reason: str
    missing_ranges: tuple[tuple[int, int], ...]

    def to_dict(self) -> dict[str, Any]:
        return {
            "session_id": self.session_id,
            "stream_version": TASK_EVENT_STREAM_VERSION,
            "events": list(self.events),
            "next_cursor": self.next_cursor,
            "latest_seq": self.latest_seq,
            "retained_from_seq": self.retained_from_seq,
            "has_more": self.has_more,
            "truncated": self.truncated,
            "snapshot_required": self.snapshot_required,
            "resync_reason": self.resync_reason,
            "missing_ranges": [{"from_seq": start, "to_seq": end} for start, end in self.missing_ranges],
        }


def _valid_record(record: Any) -> bool:
    return (
        isinstance(record, dict)
        and isinstance(record.get("seq"), int)
        and not isinstance(record.get("seq"), bool)
        and int(record["seq"]) > 0
        and isinstance(record.get("type"), str)
    )


class TaskEventLog:
    """Append-only per-session event log with cursors, dedupe, and pruning."""

    def __init__(
        self,
        store_dir: Path,
        *,
        max_log_bytes: int = DEFAULT_MAX_LOG_BYTES,
        retain_events: int = DEFAULT_RETAIN_EVENTS,
    ) -> None:
        self.store_dir = Path(store_dir)
        self.max_log_bytes = max(64 * 1024, int(max_log_bytes))
        self.retain_events = max(16, int(retain_events))

    # -- paths ------------------------------------------------------------

    def log_path(self, session_id: str) -> Path:
        return self.store_dir / f"{_safe_session_id(session_id)}.jsonl"

    def cursor_path(self, session_id: str) -> Path:
        return self.store_dir / f"{_safe_session_id(session_id)}.seq"

    # -- reading ----------------------------------------------------------

    def load(self, session_id: str) -> tuple[list[dict[str, Any]], int]:
        """Return ``(valid_records, skipped_line_count)`` in file order."""
        path = self.log_path(session_id)
        if not path.exists():
            return [], 0
        try:
            text = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return [], 0
        records: list[dict[str, Any]] = []
        skipped = 0
        for line in text.splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                parsed = json.loads(line)
            except json.JSONDecodeError:
                skipped += 1
                continue
            if _valid_record(parsed):
                records.append(parsed)
            else:
                skipped += 1
        return records, skipped

    def all_events(self, session_id: str) -> list[dict[str, Any]]:
        """Every retained event, in sequence order (backward-compatible list view)."""
        records, _ = self.load(session_id)
        return sorted(records, key=lambda rec: int(rec["seq"]))

    def latest_seq(self, session_id: str) -> int:
        records, _ = self.load(session_id)
        if not records:
            return 0
        return max(int(rec["seq"]) for rec in records)

    def retained_from_seq(self, session_id: str) -> int:
        records, _ = self.load(session_id)
        if not records:
            return 0
        return min(int(rec["seq"]) for rec in records)

    def read(self, session_id: str, *, cursor: int = 0, limit: int = DEFAULT_READ_LIMIT) -> TaskEventPage:
        """Return the events after ``cursor`` plus an explicit resync verdict."""
        safe_start = max(0, int(cursor))
        safe_limit = max(1, min(int(limit), MAX_READ_LIMIT))
        records, _ = self.load(session_id)
        records.sort(key=lambda rec: int(rec["seq"]))
        latest = int(records[-1]["seq"]) if records else 0
        retained = int(records[0]["seq"]) if records else 0

        truncated = bool(records) and retained > 1

        def _empty(reason: str, missing: tuple[tuple[int, int], ...] = ()) -> TaskEventPage:
            return TaskEventPage(
                session_id=session_id,
                events=(),
                next_cursor=safe_start,
                latest_seq=latest,
                retained_from_seq=retained,
                has_more=False,
                truncated=truncated,
                snapshot_required=bool(reason),
                resync_reason=reason,
                missing_ranges=missing,
            )

        if safe_start > latest:
            # The reader is ahead of the store: a different database, a restored
            # backup, or a brand-new store. Only a snapshot can re-anchor it.
            return _empty("cursor_ahead")
        if safe_start > 0 and records and safe_start + 1 < retained:
            # A reader that had already applied events is missing pruned history:
            # never let it continue as if the log were complete. A reader at
            # cursor 0 has no prior state to contradict, so it gets the retained
            # tail (with `truncated` set) instead of a refusal.
            return _empty("events_pruned", ((safe_start + 1, retained - 1),))

        selected = [rec for rec in records if int(rec["seq"]) > safe_start][:safe_limit]
        missing: list[tuple[int, int]] = []
        # A fresh reader (cursor 0) starts at the oldest retained event: history
        # pruned before that is `truncated`, not an unrecoverable gap in what the
        # reader was promised. Gaps after that point are real.
        expected = safe_start + 1 if safe_start > 0 else (retained or 1)
        for rec in selected:
            seq = int(rec["seq"])
            if seq > expected:
                missing.append((expected, seq - 1))
            expected = seq + 1
        if not selected and safe_start < latest:
            missing.append((safe_start + 1, latest))
        next_cursor = int(selected[-1]["seq"]) if selected else safe_start
        return TaskEventPage(
            session_id=session_id,
            events=tuple(selected),
            next_cursor=next_cursor,
            latest_seq=latest,
            retained_from_seq=retained,
            has_more=bool(selected) and next_cursor < latest,
            truncated=truncated,
            snapshot_required=bool(missing),
            resync_reason="sequence_gap" if missing else "",
            missing_ranges=tuple(missing),
        )

    # -- writing ----------------------------------------------------------

    def _next_seq(self, session_id: str, records: Iterable[dict[str, Any]]) -> int:
        """Allocate the next sequence number, durably and monotonically."""
        cursor_file = self.cursor_path(session_id)
        recorded = 0
        if cursor_file.exists():
            try:
                recorded = int(cursor_file.read_text(encoding="utf-8").strip() or "0")
            except (OSError, ValueError):
                recorded = 0
        existing = max((int(rec["seq"]) for rec in records), default=0)
        return max(recorded, existing) + 1

    def _write_cursor(self, session_id: str, seq: int) -> None:
        cursor_file = self.cursor_path(session_id)
        tmp = cursor_file.with_name(cursor_file.name + ".tmp")
        tmp.write_text(str(seq), encoding="utf-8")
        try:
            tmp.chmod(0o600)
        except OSError:
            pass
        os.replace(tmp, cursor_file)

    def _dedupe_index(self, session_id: str, records: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
        key = str(self.log_path(session_id).resolve())
        cached = _DEDUPE_CACHE.get(key)
        if cached is None or _DEDUPE_CACHE_SESSIONS.get(key) != session_id:
            cached = {}
            for rec in records:
                dedupe_key = rec.get("dedupe_key")
                if isinstance(dedupe_key, str) and dedupe_key and dedupe_key not in cached:
                    cached[dedupe_key] = rec
            _DEDUPE_CACHE[key] = cached
            _DEDUPE_CACHE_SESSIONS[key] = session_id
        return cached

    def find_by_dedupe_key(self, session_id: str, dedupe_key: str) -> dict[str, Any] | None:
        if not dedupe_key:
            return None
        records, _ = self.load(session_id)
        return self._dedupe_index(session_id, records).get(dedupe_key)

    def append(
        self,
        session_id: str,
        event_type: str,
        payload: dict[str, Any] | None = None,
        *,
        dedupe_key: str | None = None,
        ts: float | None = None,
    ) -> dict[str, Any]:
        """Append one event and return the durable record.

        With a ``dedupe_key`` the append is idempotent: if a record with that key
        is already retained, it is returned unchanged and nothing is written.
        """
        safe_id = _safe_session_id(session_id)
        if not isinstance(event_type, str) or not event_type.strip():
            raise TaskEventError("Task event type must be a non-empty string.")
        body = dict(payload or {})
        body.pop("seq", None)
        body.pop("ts", None)
        body.pop("type", None)
        body.pop("dedupe_key", None)
        with _APPEND_LOCK:
            self.store_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
            records, _ = self.load(safe_id)
            if dedupe_key:
                existing = self._dedupe_index(safe_id, records).get(dedupe_key)
                if existing is not None:
                    return dict(existing)
            seq = self._next_seq(safe_id, records)
            record: dict[str, Any] = {**body, "seq": seq, "ts": round(time.time() if ts is None else ts, 3), "type": event_type}
            if dedupe_key:
                record["dedupe_key"] = dedupe_key
            self._write_cursor(safe_id, seq)
            line = json.dumps(record, ensure_ascii=False) + "\n"
            fd = os.open(self.log_path(safe_id), os.O_APPEND | os.O_CREAT | os.O_WRONLY, 0o600)
            try:
                os.write(fd, line.encode("utf-8"))
                os.fsync(fd)
            finally:
                os.close(fd)
            if dedupe_key:
                self._dedupe_index(safe_id, records)[dedupe_key] = record
            self._maybe_prune(safe_id)
            return record

    def _maybe_prune(self, session_id: str) -> None:
        path = self.log_path(session_id)
        try:
            size = path.stat().st_size
        except OSError:
            return
        if size <= self.max_log_bytes:
            return
        self.prune(session_id, retain=self.retain_events)

    def prune(self, session_id: str, *, retain: int = DEFAULT_RETAIN_EVENTS) -> int:
        """Keep the newest ``retain`` events; return how many were dropped."""
        safe_id = _safe_session_id(session_id)
        records, _ = self.load(safe_id)
        keep = max(1, int(retain))
        if len(records) <= keep:
            return 0
        dropped = records[: -keep]
        kept = records[-keep:]
        path = self.log_path(safe_id)
        tmp = path.with_name(path.name + ".tmp")
        tmp.write_text(
            "".join(json.dumps(rec, ensure_ascii=False) + "\n" for rec in kept),
            encoding="utf-8",
        )
        try:
            tmp.chmod(0o600)
        except OSError:
            pass
        os.replace(tmp, path)
        # The dedupe index must forget pruned keys; rebuild it from kept records.
        _DEDUPE_CACHE.pop(str(path.resolve()), None)
        _DEDUPE_CACHE_SESSIONS.pop(str(path.resolve()), None)
        self._dedupe_index(safe_id, kept)
        return len(dropped)

    # -- reconstruction ---------------------------------------------------

    def reconstruct(self, session_id: str) -> TaskEventSnapshot:
        """Recompute session facts from the durable log alone."""
        safe_id = _safe_session_id(session_id)
        records, skipped = self.load(safe_id)
        records.sort(key=lambda rec: int(rec["seq"]))
        latest = int(records[-1]["seq"]) if records else 0
        retained = int(records[0]["seq"]) if records else 0
        turns_started = 0
        turns_completed = 0
        last_turn_state = ""
        undecided: list[str] = []
        decisions: dict[str, str] = {}
        for rec in records:
            event_type = rec.get("type")
            if event_type == "turn/start":
                turns_started += 1
            elif event_type == "turn/end":
                state = str(rec.get("state") or "")
                if state:
                    last_turn_state = state
                if state == "completed":
                    turns_completed += 1
            elif event_type == "approval/request":
                approval_id = rec.get("approval_id")
                if isinstance(approval_id, str) and approval_id and approval_id not in decisions:
                    if approval_id not in undecided:
                        undecided.append(approval_id)
            elif event_type == "approval/decision":
                approval_id = rec.get("approval_id")
                if isinstance(approval_id, str) and approval_id:
                    decisions[approval_id] = str(rec.get("decision") or "")
                    if approval_id in undecided:
                        undecided.remove(approval_id)
        return TaskEventSnapshot(
            session_id=safe_id,
            latest_seq=latest,
            retained_from_seq=retained,
            event_count=len(records),
            turns_started=turns_started,
            turns_completed=turns_completed,
            last_turn_state=last_turn_state,
            terminal=last_turn_state in TERMINAL_TURN_STATES,
            undecided_approvals=tuple(undecided),
            approval_decisions=tuple(decisions.items()),
            last_event_type=str(records[-1].get("type") or "") if records else "",
            last_event_ts=float(records[-1].get("ts") or 0.0) if records else 0.0,
            skipped_records=skipped,
        )

    def approval_decision(self, session_id: str, approval_id: str) -> str:
        """Return the durable decision for an approval id, or ``""`` if undecided."""
        if not approval_id:
            return ""
        for approval, decision in self.reconstruct(session_id).approval_decisions:
            if approval == approval_id:
                return decision
        return ""


def parse_cursor(value: Any, *, default: int = 0) -> int:
    """Parse a cursor from a query string, header, or JSON value without raising."""
    try:
        parsed = int(str(value).strip())
    except (TypeError, ValueError):
        return default
    return parsed if parsed >= 0 else default


__all__ = [
    "DEFAULT_MAX_LOG_BYTES",
    "DEFAULT_READ_LIMIT",
    "DEFAULT_RETAIN_EVENTS",
    "MAX_READ_LIMIT",
    "STREAM_HEARTBEAT_SECONDS",
    "TASK_EVENT_STREAM_VERSION",
    "TaskEventError",
    "TaskEventLog",
    "TaskEventPage",
    "TaskEventSnapshot",
    "parse_cursor",
]

task_events = sys.modules[__name__]

"""Filesystem confinement and container isolation policy primitives."""


import os
import shlex
import uuid
from pathlib import Path


class SandboxBoundaryError(ValueError):
    """Raised when a workspace or execution request crosses the boundary."""


SECRET_NAMES = frozenset({
    ".env",
    ".netrc",
    "id_rsa",
    "id_ed25519",
    "credentials.json",
    "token",
    "api-token",
})


def confined_path(root: Path, raw_path: str) -> Path:
    """Resolve a path and reject traversal, sibling-prefix, and symlink escapes."""
    if not isinstance(raw_path, str) or not raw_path.strip() or "\x00" in raw_path:
        raise SandboxBoundaryError("path must be a non-empty string without NUL characters.")
    workspace = root.expanduser().resolve()
    lexical = Path(raw_path)
    if not lexical.is_absolute():
        current = workspace
        for part in lexical.parts:
            if part in ("", "."):
                continue
            if part == "..":
                current = current.parent
                continue
            current = current / part
            if current.is_symlink():
                resolved = current.resolve()
                try:
                    resolved.relative_to(workspace)
                except ValueError as exc:
                    raise SandboxBoundaryError("symlink escapes the workspace boundary.") from exc
    candidate = (workspace / raw_path).resolve()
    try:
        candidate.relative_to(workspace)
    except ValueError as exc:
        raise SandboxBoundaryError("path escapes the workspace boundary.") from exc
    return candidate


def validate_workspace(root: Path, *, max_entries: int = 100_000) -> Path:
    """Validate a real directory and reject known secret-bearing names."""
    workspace = root.expanduser()
    if workspace.is_symlink() or not workspace.is_dir():
        raise SandboxBoundaryError("workspace must be a real directory.")
    resolved = workspace.resolve()
    if resolved == Path(resolved.anchor) or resolved == Path.home().resolve():
        raise SandboxBoundaryError("workspace is too broad for sandbox execution.")
    entries = 0
    for directory, directories, files in os.walk(resolved, followlinks=False):
        entries += len(directories) + len(files)
        if entries > max_entries:
            raise SandboxBoundaryError("workspace exceeds the entry scan budget.")
        for name in (*directories, *files):
            if name.lower() in SECRET_NAMES:
                raise SandboxBoundaryError("workspace contains a known secret-bearing filename.")
    return resolved


def sandbox_command(
    workspace: Path,
    command: str,
    *,
    image: str,
    runtime: str = "docker",
    container_name: str | None = None,
) -> list[str]:
    """Build a defense-in-depth command without enabling network or privileges."""
    if not command.strip() or not image.strip():
        raise SandboxBoundaryError("command and image must be non-empty.")
    if runtime not in {"docker", "podman"}:
        raise SandboxBoundaryError("runtime must be docker or podman.")
    root = validate_workspace(workspace)
    args = [
        runtime,
        "run",
        "--rm",
        "--network=none",
        "--read-only",
        "--cap-drop=ALL",
        "--security-opt=no-new-privileges",
        "--pids-limit=128",
        "--memory=2g",
        "--cpus=2",
    ]
    if container_name:
        if not container_name.replace("-", "").replace("_", "").isalnum():
            raise SandboxBoundaryError("container_name contains unsafe characters.")
        args.extend(["--name", container_name])
    args.extend(["--mount", f"type=bind,src={root},dst=/workspace,rw", "--workdir", "/workspace", image, "sh", "-lc", command])
    return args


def build_container_invocation(
    resolved_workspace: Path,
    command: str,
    *,
    runtime_path: str,
    image: str,
    python_code: bool = False,
    container_name: str | None = None,
) -> list[str]:
    """Construct the canonical least-privilege, no-network container argv for untrusted code."""
    if not resolved_workspace.is_dir():
        raise SandboxBoundaryError("Sandbox workspace must be an existing directory.")
    if "," in str(resolved_workspace):
        raise SandboxBoundaryError("Sandbox workspace paths containing commas are unsupported by Docker --mount syntax.")
    if not image or not image.strip() or image.startswith("-"):
        raise SandboxBoundaryError("STUDIO_SANDBOX_IMAGE must be a configured, trusted image name or digest.")
    if not runtime_path or not runtime_path.strip():
        raise SandboxBoundaryError("Sandbox runtime executable path must be non-empty.")
    name = container_name or f"m5-studio-{uuid.uuid4().hex[:20]}"
    if not name.replace("-", "").replace("_", "").isalnum():
        raise SandboxBoundaryError("container_name contains unsafe characters.")
    argv = [
        runtime_path,
        "run",
        "--rm",
        "--pull=never",
        "--name",
        name,
        "--network=none",
        "--read-only",
        "--cap-drop=ALL",
        "--security-opt=no-new-privileges",
        "--env",
        "HOME=/tmp",
        "--env",
        "TMPDIR=/tmp",
        "--env",
        "PYTHONDONTWRITEBYTECODE=1",
        "--pids-limit=128",
        "--memory=2g",
        "--cpus=2",
        "--ipc=private",
        "--ulimit",
        "nofile=1024:1024",
        "--tmpfs",
        "/tmp:rw,noexec,nosuid,nodev,size=256m",
        "--mount",
        f"type=bind,source={resolved_workspace},target=/workspace",
        "--workdir",
        "/workspace",
        "--entrypoint",
        "/bin/sh",
    ]
    if os.name == "posix" and hasattr(os, "getuid") and hasattr(os, "getgid"):
        argv.extend(["--user", f"{os.getuid()}:{os.getgid()}"])
    argv.append(image)
    shell_command = f"exec python3 -c {shlex.quote(command)}" if python_code else command
    argv.extend(["-lc", shell_command])
    return argv

sandbox_boundary = sys.modules[__name__]

"""Version-aware managed edits: durable edit transactions and observed versions (M5-P2-02).

A managed edit is a compare-and-swap on file *content*, not on a path. Two facts
have to be durable for that to be true:

1. **What the agent saw.** ``read_file`` hands the agent a version of a file. If
   the user edits the file afterwards, the agent's reasoning is about bytes that
   no longer exist, and applying "replace ``old_text`` with ``new_text``" would
   silently revert the user's change. ``ObservedVersionIndex`` records the SHA-256
   of the bytes handed to the agent per session and path, durably (it survives a
   restart, because the transcript does too).
2. **What the edit actually did.** ``EditTransactionLedger`` appends one durable
   record per applied edit: pre-edit digest (or "the file did not exist"),
   post-edit digest, the expected/observed digests the decision was based on, the
   tool, mode, size, session/task/snapshot ids and a monotonic ``seq``. A later
   reader — recovery, reconciliation, an operator audit — can therefore explain
   every byte the runtime wrote, without trusting an in-memory claim.

Both stores live under the harness store directory (``edits/`` beside
``sessions/``), are owner-only (``0700`` directories, ``0600`` files), append with
``O_APPEND`` + ``fsync`` (ledger) or replace atomically (observed index), and keep
a bounded history so a long session cannot grow them without limit.

The module is standard-library only, does no I/O outside the store directory it
is given, never invents a record, and never rewrites a durable record after it is
written.
"""


import json
import os
import re
import threading
import time
import uuid
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable

EDIT_LEDGER_VERSION = 1

#: Default number of transactions returned by a history read.
DEFAULT_READ_LIMIT = 50
MAX_READ_LIMIT = 500
#: Rotate a session ledger beyond this size, keeping the newest records.
DEFAULT_MAX_LEDGER_BYTES = 4 * 1024 * 1024
DEFAULT_RETAIN_TRANSACTIONS = 2000
#: How many observed versions are remembered per session before the oldest go.
MAX_OBSERVED_ENTRIES = 2048
MAX_REL_PATH_LENGTH = 1024

_SHA256_RE = re.compile(r"^(?:sha256:)?([0-9a-fA-F]{64})$")
_SAFE_SESSION_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$")

_LEDGER_LOCK = threading.Lock()
_OBSERVED_LOCK = threading.Lock()
_SEQ_CACHE: dict[str, int] = {}


class EditVersionError(ValueError):
    """Raised for a malformed expected hash, session id, or workspace path."""


def parse_expected_sha256(raw: Any) -> str | None:
    """Validate a caller-supplied expected content hash and normalize it to lowercase hex.

    Accepts ``None``/``""`` (no expectation), a bare 64-character hex digest, or a
    ``sha256:``-prefixed digest, case-insensitively. Anything else — a truncated
    hash, a git blob id from another algorithm, a path, a dict — raises instead of
    being ignored: a silently dropped expectation would be a promise the runtime
    did not keep.
    """
    if raw is None:
        return None
    if not isinstance(raw, str):
        raise EditVersionError("expected_sha256 must be a string containing a SHA-256 digest.")
    text = raw.strip()
    if not text:
        return None
    match = _SHA256_RE.match(text)
    if match is None:
        raise EditVersionError(
            "expected_sha256 must be 64 hexadecimal characters (optionally prefixed with 'sha256:'), "
            f"got {text[:80]!r}."
        )
    return match.group(1).lower()


def _safe_session_id(session_id: str) -> str:
    """Return a store-safe session id or raise (never sanitize into a different session)."""
    sid = (session_id or "").strip()
    if not sid:
        raise EditVersionError("Edit ledger session id must not be empty.")
    if not _SAFE_SESSION_RE.match(sid):
        raise EditVersionError(f"Unsafe edit ledger session id: {session_id!r}")
    return sid


def _safe_rel_path(rel_path: str) -> str:
    """Validate a workspace-relative path for recording; never normalize it into another file."""
    raw = (rel_path or "").strip().replace("\\", "/")
    if not raw:
        raise EditVersionError("Edit ledger path must not be empty.")
    if len(raw) > MAX_REL_PATH_LENGTH:
        raise EditVersionError("Edit ledger path is too long to record.")
    if raw.startswith("/") or re.match(r"^[A-Za-z]:", raw):
        raise EditVersionError(f"Edit ledger path must be workspace-relative, got {rel_path!r}.")
    parts = [part for part in raw.split("/") if part not in ("", ".")]
    if not parts or any(part == ".." for part in parts):
        raise EditVersionError(f"Edit ledger path must stay inside the workspace, got {rel_path!r}.")
    return "/".join(parts)


def _now() -> float:
    return round(time.time(), 6)


def _restrict_file(path: Path) -> None:
    """Best-effort owner-only permissions on a file we just created."""
    try:
        os.chmod(path, 0o600)
    except OSError:
        pass


def _ensure_private_dir(path: Path) -> Path:
    path.mkdir(parents=True, exist_ok=True)
    try:
        os.chmod(path, 0o700)
    except OSError:
        pass
    return path


@dataclass(frozen=True, slots=True)
class EditTransaction:
    """One applied managed edit, with the hashes that justify it."""

    edit_id: str
    seq: int
    session_id: str
    rel_path: str
    tool: str
    pre_sha256: str | None
    post_sha256: str
    pre_existed: bool
    expected_sha256: str | None
    observed_sha256: str | None
    mode: int | None
    bytes_written: int
    recorded_at: float
    task_id: str = ""
    snapshot_id: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": EDIT_LEDGER_VERSION,
            "edit_id": self.edit_id,
            "seq": self.seq,
            "session_id": self.session_id,
            "rel_path": self.rel_path,
            "tool": self.tool,
            "pre_sha256": self.pre_sha256,
            "post_sha256": self.post_sha256,
            "pre_existed": self.pre_existed,
            "expected_sha256": self.expected_sha256,
            "observed_sha256": self.observed_sha256,
            "mode": self.mode,
            "bytes_written": self.bytes_written,
            "recorded_at": self.recorded_at,
            "task_id": self.task_id,
            "snapshot_id": self.snapshot_id,
        }

    @classmethod
    def from_dict(cls, raw: dict[str, Any]) -> "EditTransaction":
        return cls(
            edit_id=str(raw["edit_id"]),
            seq=int(raw["seq"]),
            session_id=str(raw["session_id"]),
            rel_path=str(raw["rel_path"]),
            tool=str(raw.get("tool") or ""),
            pre_sha256=str(raw["pre_sha256"]) if raw.get("pre_sha256") else None,
            post_sha256=str(raw["post_sha256"]),
            pre_existed=bool(raw.get("pre_existed")),
            expected_sha256=str(raw["expected_sha256"]) if raw.get("expected_sha256") else None,
            observed_sha256=str(raw["observed_sha256"]) if raw.get("observed_sha256") else None,
            mode=int(raw["mode"]) if raw.get("mode") is not None else None,
            bytes_written=int(raw.get("bytes_written") or 0),
            recorded_at=float(raw.get("recorded_at") or 0.0),
            task_id=str(raw.get("task_id") or ""),
            snapshot_id=str(raw.get("snapshot_id") or ""),
        )


class EditTransactionLedger:
    """Append-only, durable record of the edits this runtime applied."""

    def __init__(
        self,
        store_root: Path,
        *,
        max_ledger_bytes: int = DEFAULT_MAX_LEDGER_BYTES,
        retain_transactions: int = DEFAULT_RETAIN_TRANSACTIONS,
    ) -> None:
        self.store_root = Path(store_root)
        self.max_ledger_bytes = max(0, int(max_ledger_bytes))
        self.retain_transactions = max(1, int(retain_transactions))

    # -- paths -----------------------------------------------------------

    def ledger_dir(self) -> Path:
        return self.store_root / "edits"

    def ledger_path(self, session_id: str) -> Path:
        return self.ledger_dir() / f"{_safe_session_id(session_id)}.jsonl"

    # -- writing ---------------------------------------------------------

    def record(
        self,
        *,
        session_id: str,
        rel_path: str,
        tool: str,
        post_sha256: str,
        pre_sha256: str | None = None,
        expected_sha256: str | None = None,
        observed_sha256: str | None = None,
        mode: int | None = None,
        bytes_written: int = 0,
        task_id: str = "",
        snapshot_id: str = "",
    ) -> EditTransaction:
        """Append one transaction and return it as recorded (durable before return)."""
        sid = _safe_session_id(session_id)
        rel = _safe_rel_path(rel_path)
        post = parse_expected_sha256(post_sha256)
        if post is None:
            raise EditVersionError("An edit transaction requires the SHA-256 of the bytes written.")
        pre = parse_expected_sha256(pre_sha256)
        expected = parse_expected_sha256(expected_sha256)
        observed = parse_expected_sha256(observed_sha256)
        path = self.ledger_path(sid)
        _ensure_private_dir(path.parent)
        with _LEDGER_LOCK:
            seq = _next_seq(path)
            transaction = EditTransaction(
                edit_id=f"ed-{uuid.uuid4().hex[:16]}",
                seq=seq,
                session_id=sid,
                rel_path=rel,
                tool=str(tool or "")[:40],
                pre_sha256=pre,
                post_sha256=post,
                pre_existed=pre is not None,
                expected_sha256=expected,
                observed_sha256=observed,
                mode=int(mode) if mode is not None else None,
                bytes_written=max(0, int(bytes_written)),
                recorded_at=_now(),
                task_id=str(task_id or "")[:128],
                snapshot_id=str(snapshot_id or "")[:128],
            )
            payload = json.dumps(transaction.to_dict(), sort_keys=True, ensure_ascii=False)
            fd = os.open(path, os.O_APPEND | os.O_CREAT | os.O_WRONLY | getattr(os, "O_CLOEXEC", 0), 0o600)
            try:
                _restrict_file(path)
                os.write(fd, (payload + "\n").encode("utf-8"))
                os.fsync(fd)
            finally:
                os.close(fd)
            _rotate_if_needed(path, self.max_ledger_bytes, self.retain_transactions)
        return transaction

    # -- reading ---------------------------------------------------------

    def _read_records(self, path: Path) -> tuple[list[EditTransaction], int]:
        """Read valid transactions plus the count of unreadable (torn) lines."""
        records: list[EditTransaction] = []
        skipped = 0
        try:
            raw = path.read_text(encoding="utf-8")
        except FileNotFoundError:
            return records, skipped
        except OSError as exc:
            raise EditVersionError(f"Cannot read the edit ledger at {path}: {exc}") from exc
        for line in raw.splitlines():
            if not line.strip():
                continue
            try:
                records.append(EditTransaction.from_dict(json.loads(line)))
            except (json.JSONDecodeError, KeyError, TypeError, ValueError):
                # A torn append is reported, never repaired into a plausible record.
                skipped += 1
        return records, skipped

    def list_transactions(self, session_id: str, *, limit: int = DEFAULT_READ_LIMIT) -> list[EditTransaction]:
        """Newest-first transactions for a session."""
        path = self.ledger_path(session_id)
        records, _skipped = self._read_records(path)
        records.sort(key=lambda record: record.seq, reverse=True)
        return records[: max(1, min(int(limit), MAX_READ_LIMIT))]

    def latest_for_path(self, session_id: str, rel_path: str) -> EditTransaction | None:
        """Most recent transaction for one workspace path, if any."""
        target = _safe_rel_path(rel_path)
        for record in self.list_transactions(session_id, limit=MAX_READ_LIMIT):
            if record.rel_path == target:
                return record
        return None

    def count_unreadable_lines(self, session_id: str) -> int:
        """Number of lines that could not be parsed (torn appends), for diagnostics."""
        _records, skipped = self._read_records(self.ledger_path(session_id))
        return skipped


def _next_seq(path: Path) -> int:
    """Next sequence number for a ledger file, seeded from its last record."""
    key = str(path)
    cached = _SEQ_CACHE.get(key)
    if cached is not None:
        _SEQ_CACHE[key] = cached + 1
        return cached + 1
    last = 0
    try:
        with path.open("rb") as stream:
            for line in stream:
                line = line.strip()
                if not line:
                    continue
                try:
                    last = max(last, int(json.loads(line).get("seq") or 0))
                except (json.JSONDecodeError, TypeError, ValueError, AttributeError):
                    continue
    except FileNotFoundError:
        last = 0
    _SEQ_CACHE[key] = last + 1
    return last + 1


def _rotate_if_needed(path: Path, max_bytes: int, retain: int) -> None:
    """Keep the ledger bounded by rewriting the newest records atomically."""
    if max_bytes <= 0:
        return
    try:
        if path.stat().st_size <= max_bytes:
            return
    except OSError:
        return
    try:
        raw = path.read_text(encoding="utf-8")
    except OSError:
        return
    kept = [line for line in raw.splitlines() if line.strip()][-retain:]
    tmp = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0), 0o600)
    try:
        os.write(fd, ("\n".join(kept) + "\n").encode("utf-8") if kept else b"")
        os.fsync(fd)
    finally:
        os.close(fd)
    os.replace(tmp, path)
    _SEQ_CACHE.pop(str(path), None)


class ObservedVersionIndex:
    """Durable record of the content version handed to the agent for a path."""

    def __init__(self, store_root: Path, *, max_entries: int = MAX_OBSERVED_ENTRIES) -> None:
        self.store_root = Path(store_root)
        self.max_entries = max(1, int(max_entries))

    def index_dir(self) -> Path:
        return self.store_root / "edits"

    def index_path(self, session_id: str) -> Path:
        return self.index_dir() / f"{_safe_session_id(session_id)}.observed.json"

    def _load(self, session_id: str) -> dict[str, dict[str, Any]]:
        path = self.index_path(session_id)
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            return {}
        except (OSError, json.JSONDecodeError):
            # A corrupt index must not be trusted as "the agent has no version":
            # callers treat a failed lookup as unknown and fall back to their own read.
            raise EditVersionError(f"Observed-version index at {path} is unreadable.")
        entries = raw.get("entries")
        if not isinstance(entries, dict):
            raise EditVersionError(f"Observed-version index at {path} is malformed.")
        cleaned: dict[str, dict[str, Any]] = {}
        for key, value in entries.items():
            if isinstance(key, str) and isinstance(value, dict) and isinstance(value.get("sha256"), str):
                cleaned[key] = {"sha256": value["sha256"], "recorded_at": float(value.get("recorded_at") or 0.0)}
        return cleaned

    def _save(self, session_id: str, entries: dict[str, dict[str, Any]]) -> None:
        path = self.index_path(session_id)
        _ensure_private_dir(path.parent)
        payload = json.dumps(
            {"schema_version": EDIT_LEDGER_VERSION, "session_id": _safe_session_id(session_id), "entries": entries},
            sort_keys=True,
            ensure_ascii=False,
        )
        tmp = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0), 0o600)
        try:
            os.write(fd, payload.encode("utf-8"))
            os.fsync(fd)
        finally:
            os.close(fd)
        os.replace(tmp, path)
        _restrict_file(path)

    def mark_observed(self, session_id: str, rel_path: str, sha256_hex: str) -> None:
        """Record that the agent currently holds the bytes with this digest."""
        rel = _safe_rel_path(rel_path)
        digest = parse_expected_sha256(sha256_hex)
        if digest is None:
            raise EditVersionError("Observed version requires a SHA-256 digest.")
        with _OBSERVED_LOCK:
            entries = self._load(session_id)
            entries[rel] = {"sha256": digest, "recorded_at": _now()}
            if len(entries) > self.max_entries:
                ordered = sorted(entries.items(), key=lambda item: item[1]["recorded_at"], reverse=True)
                entries = dict(ordered[: self.max_entries])
            self._save(session_id, entries)

    def expected_for(self, session_id: str, rel_path: str) -> str | None:
        """Digest the agent last saw for a path, or None when nothing was observed."""
        rel = _safe_rel_path(rel_path)
        with _OBSERVED_LOCK:
            entry = self._load(session_id).get(rel)
        if entry is None:
            return None
        return parse_expected_sha256(entry["sha256"])

    def forget(self, session_id: str, rel_path: str) -> None:
        """Drop the recorded version for a path (used when the runtime deletes it)."""
        rel = _safe_rel_path(rel_path)
        with _OBSERVED_LOCK:
            entries = self._load(session_id)
            if entries.pop(rel, None) is not None:
                self._save(session_id, entries)

    def entries(self, session_id: str) -> dict[str, str]:
        """All recorded path → digest pairs for a session."""
        with _OBSERVED_LOCK:
            entries = self._load(session_id)
        return {path: entry["sha256"] for path, entry in entries.items()}

    def clear(self, session_id: str) -> None:
        """Forget every recorded version for a session."""
        with _OBSERVED_LOCK:
            try:
                self.index_path(session_id).unlink()
            except FileNotFoundError:
                pass


def describe_history(transactions: Iterable[EditTransaction], *, limit: int = 20) -> list[dict[str, Any]]:
    """Compact newest-first history rows for display or tests."""
    rows: list[dict[str, Any]] = []
    for record in list(transactions)[:limit]:
        rows.append(
            {
                "edit_id": record.edit_id,
                "seq": record.seq,
                "path": record.rel_path,
                "tool": record.tool,
                "pre_sha256": record.pre_sha256,
                "post_sha256": record.post_sha256,
                "recorded_at": record.recorded_at,
            }
        )
    return rows


__all__ = [
    "DEFAULT_READ_LIMIT",
    "EDIT_LEDGER_VERSION",
    "MAX_OBSERVED_ENTRIES",
    "MAX_READ_LIMIT",
    "EditTransaction",
    "EditTransactionLedger",
    "EditVersionError",
    "ObservedVersionIndex",
    "describe_history",
    "parse_expected_sha256",
]

edit_transactions = sys.modules[__name__]

"""Pre-edit Git baseline capture, selective CAS user snapshots, and non-destructive restore (M5-P2-01).

This stdlib-only module preserves user work before autonomous edits:

1. **Git baseline & dirty-state capture** (`capture_baseline`):
   - Records `HEAD` commit, `HEAD^{tree}`, symbolic branch, staged index changes
     (`git diff-index --cached` or unborn index entries), unstaged working-tree
     modifications/deletions (`git diff-files`), and relevant untracked user files
     (`git ls-files --others --exclude-standard`) using strictly read-only,
     fixed-argv Git plumbing (`shell=False`).
2. **Selective content-addressed storage** (`ContentAddressedBlobStore`):
   - Snapshots only necessary bytes (dirty staged/unstaged/untracked user files
     at baseline, plus clean target files lazily via `capture_target_before_edit`
     immediately before an edit mutates them) into owner-only (`0600`) SHA-256
     content-addressed blobs written via temp-file + `os.fsync` + `os.replace`.
3. **Ignored & sensitive file preservation without indiscriminate copying**:
   - Skips heavy build/cache trees (`node_modules`, `.venv`, `.git`, `.harnesses`,
     etc.) and **never** copies secret/sensitive files (`.env`, `.secrets`,
     private keys, credentials, tokens) or Git-ignored config files into CAS;
     instead records non-secret in-place metadata + streaming SHA-256 digests so
     sensitive files remain untouched in place and are verified intact on restore.
4. **Disk-full safe pause** (`SnapshotDiskFullError`):
   - Preflights free bytes and catches `ENOSPC` / `EDQUOT` across CAS and manifest
     writes, cleaning up temporary files and surfacing a structured signal so
     callers transition tasks into a safe `paused` state without partial edits.
5. **Verified non-destructive restore** (`restore_snapshot` / `verify_snapshot_state`):
   - Restores working-tree files atomically via directory-fd `O_NOFOLLOW` writes
     and reconciles `.git/index` entries via `git hash-object -w` +
     `git update-index` — **never** invoking `git reset --hard`, `git clean`, or
     `git checkout --force`.
"""

import errno
import hashlib
import json
import os
import re
import shutil
import stat
import subprocess
import tempfile
import time
import uuid
from collections.abc import Mapping, Sequence
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any


SNAPSHOT_SCHEMA_VERSION = 1
DEFAULT_MIN_FREE_BYTES = 2 * 1024 * 1024  # 2 MiB safety floor before CAS/manifest writes
DEFAULT_MAX_SNAPSHOT_FILE_BYTES = 16 * 1024 * 1024  # 16 MiB per snapshotted user file
DEFAULT_MAX_SCAN_ENTRIES = 25_000

_WSNAP_HEX64_RE = re.compile(r"^[0-9a-f]{64}$")
_WSNAP_SAFE_ID_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$")
_WSNAP_DISK_FULL_ERRNOS: frozenset[int] = frozenset(
    code
    for code in (
        errno.ENOSPC,
        getattr(errno, "EDQUOT", errno.ENOSPC),
    )
)

SENSITIVE_EXEMPT_NAMES: frozenset[str] = frozenset(
    {
        ".env.example",
        ".env.sample",
        ".env.template",
        ".env.dist",
        ".env.test.example",
    }
)

SENSITIVE_EXACT_NAMES: frozenset[str] = frozenset(
    set(sandbox_boundary.SECRET_NAMES)
    | {
        ".secrets",
        ".npmrc",
        ".pypirc",
        ".git-credentials",
        ".dockerconfigjson",
        "application_default_credentials.json",
        "id_ecdsa",
        "id_dsa",
    }
)

SENSITIVE_DIR_NAMES: frozenset[str] = frozenset({".ssh", ".gnupg", ".aws"})
SENSITIVE_SUFFIXES: tuple[str, ...] = (".pem", ".key", ".p12", ".pfx", ".keystore", ".jks")

HEAVY_SKIP_DIRS: frozenset[str] = frozenset(
    {
        ".git",
        ".harnesses",
        ".sdlc",
        ".planning",
        "node_modules",
        ".venv",
        "venv",
        "__pycache__",
        ".mypy_cache",
        ".pytest_cache",
        ".ruff_cache",
        "dist",
        "build",
        "target",
        ".tox",
        ".nox",
        ".next",
        ".nuxt",
        ".parcel-cache",
        ".turbo",
        "coverage",
    }
)

# Shell command segments that wipe uncommitted user work destructively.
_WSNAP_SEGMENT_SPLIT_RE = re.compile(r"(?:&&|\|\||;|\||\n|\r)+")
_WSNAP_ENV_ASSIGN_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=\S*$")


class WorkspaceSnapshotError(RuntimeError):
    """Base fail-closed error for workspace baseline and snapshot operations."""


class SnapshotDiskFullError(WorkspaceSnapshotError):
    """Raised when disk space or quota is exhausted during snapshot or edit preflight."""

    def __init__(
        self,
        message: str,
        *,
        operation: str = "snapshot",
        target_path: str = "",
        errno_code: int = errno.ENOSPC,
    ) -> None:
        super().__init__(message)
        self.operation = operation
        self.target_path = target_path
        self.errno_code = errno_code


class SnapshotIntegrityError(WorkspaceSnapshotError):
    """Raised when a snapshot manifest or CAS blob fails integrity verification."""


class SnapshotConflictError(WorkspaceSnapshotError):
    """Raised when an operation would overwrite concurrent user work or sensitive files."""


class DestructiveGitOperationError(WorkspaceSnapshotError):
    """Raised when a destructive Git reset/clean/checkout operation is attempted."""


def is_disk_full_os_error(exc: BaseException) -> bool:
    """Return True when ``exc`` represents disk-space or quota exhaustion."""
    if isinstance(exc, SnapshotDiskFullError):
        return True
    if isinstance(exc, OSError) and exc.errno in _WSNAP_DISK_FULL_FULL_SET():
        return True
    return False


def _WSNAP_DISK_FULL_FULL_SET() -> frozenset[int]:
    return _WSNAP_DISK_FULL_ERRNOS


def is_sensitive_filename(name: str) -> bool:
    """Return True if a single path component denotes a secret-bearing file."""
    low = (name or "").strip().lower()
    if not low or low in SENSITIVE_EXEMPT_NAMES:
        return False
    if low in SENSITIVE_EXACT_NAMES:
        return True
    if low.startswith(".env.") or low.startswith("credentials."):
        return True
    if low.endswith(SENSITIVE_SUFFIXES):
        return True
    return False


def is_sensitive_rel_path(rel_path: str) -> bool:
    """Return True if any directory or filename component in ``rel_path`` is sensitive."""
    raw = (rel_path or "").replace("\\", "/").strip("/")
    if not raw:
        return False
    parts = [p for p in raw.split("/") if p and p != "."]
    if not parts:
        return False
    for part in parts[:-1]:
        if part.lower() in SENSITIVE_DIR_NAMES or is_sensitive_filename(part):
            return True
    return is_sensitive_filename(parts[-1])


def detect_destructive_git_command(command: str) -> str | None:
    """Detect destructive workspace-wiping Git shell commands; return reason or None.

    Allows safe read-only or dry-run invocations (e.g., ``git clean -n``,
    ``git status``, ``git diff``, ``git checkout -b feature``) while blocking
    commands that discard uncommitted user work (``git reset --hard``,
    ``git reset --merge``, ``git clean -f``, ``git checkout --force``,
    ``git checkout -- .``, ``git restore .``).
    """
    text = (command or "").strip()
    if not text or "git" not in text:
        return None
    for raw_seg in _WSNAP_SEGMENT_SPLIT_RE.split(text):
        seg = raw_seg.strip().lstrip("(").rstrip(")")
        if not seg:
            continue
        tokens = [tok.strip("\"'") for tok in seg.split() if tok.strip("\"'")]
        while tokens and (
            _WSNAP_ENV_ASSIGN_RE.match(tokens[0])
            or tokens[0] in {"sudo", "env", "command"}
        ):
            tokens.pop(0)
        if not tokens:
            continue
        exe = os.path.basename(tokens[0])
        if exe != "git":
            continue
        # Skip global git flags such as -C <dir>, --git-dir=..., -c k=v
        idx = 1
        while idx < len(tokens):
            tok = tokens[idx]
            if tok in {"-C", "-c", "--git-dir", "--work-tree"}:
                idx += 2
                continue
            if tok.startswith(("--git-dir=", "--work-tree=", "-C", "-c")):
                idx += 1
                continue
            if tok.startswith("-"):
                idx += 1
                continue
            break
        if idx >= len(tokens):
            continue
        sub = tokens[idx]
        rest = tokens[idx + 1 :]
        if sub == "reset":
            for arg in rest:
                if arg in {"--hard", "--merge"}:
                    return f"Blocked destructive Git command `git reset {arg}`; use non-destructive workspace snapshots instead."
        elif sub == "clean":
            has_dry_run = any(
                arg in {"-n", "--dry-run"}
                or (arg.startswith("-") and not arg.startswith("--") and "n" in arg[1:])
                for arg in rest
            )
            has_force = any(
                arg == "--force"
                or (arg.startswith("-") and not arg.startswith("--") and "f" in arg[1:])
                for arg in rest
            )
            if has_force and not has_dry_run:
                return "Blocked destructive Git command `git clean -f`; untracked and ignored user files must be preserved."
        elif sub == "checkout":
            if any(arg in {"-f", "--force"} for arg in rest):
                return "Blocked destructive Git command `git checkout --force`; uncommitted user changes must not be discarded."
            if "--" in rest:
                dd_idx = rest.index("--")
                targets = rest[dd_idx + 1 :]
                if any(t in {".", "./", "*"} for t in targets):
                    return "Blocked blanket `git checkout -- .`; restore individual paths via workspace snapshots instead."
            elif rest == ["."]:
                return "Blocked blanket `git checkout .`; restore individual paths via workspace snapshots instead."
        elif sub == "restore":
            has_staged_only = "--staged" in rest and "--worktree" not in rest and "-W" not in rest
            if not has_staged_only and any(t in {".", "./", "*"} for t in rest if not t.startswith("-")):
                return "Blocked blanket `git restore .` on working tree; use verified workspace snapshot restore instead."
    return None


def assert_non_destructive_git_argv(argv: Sequence[str]) -> None:
    """Fail closed if an internal subprocess argv ever attempts destructive Git reset/clean."""
    if not argv:
        return
    reason = detect_destructive_git_command(" ".join(argv))
    if reason is not None:
        raise DestructiveGitOperationError(reason)


def _wsnap_validate_identifier(value: str, label: str) -> str:
    clean = (value or "").strip()
    if not _WSNAP_SAFE_ID_RE.match(clean) or ".." in clean:
        raise WorkspaceSnapshotError(f"Invalid {label}: {value!r}")
    return clean


def _wsnap_normalize_rel_path(root: Path, raw_path: str) -> tuple[str, tuple[str, ...]]:
    """Validate confinement under ``root`` via ``sandbox_boundary.confined_path`` and return POSIX rel path."""
    cleaned = (raw_path or "").replace("\\", "/").strip()
    if not cleaned or cleaned == ".":
        raise WorkspaceSnapshotError("Snapshot file path must reference a file inside the workspace, not root.")
    try:
        confined = sandbox_boundary.confined_path(root, cleaned)
        root_resolved = root.expanduser().resolve(strict=True)
        rel = confined.relative_to(root_resolved)
    except (sandbox_boundary.SandboxBoundaryError, ValueError, OSError) as exc:
        raise SnapshotConflictError(f"Path {raw_path!r} escapes workspace boundary: {exc}") from exc
    parts = tuple(p for p in rel.parts if p not in ("", "."))
    if not parts:
        raise WorkspaceSnapshotError(f"Path {raw_path!r} resolves to workspace root.")
    return "/".join(parts), parts


def _wsnap_lexical_parts(raw_path: str) -> tuple[str, ...]:
    """Split a workspace-relative path lexically, refusing absolute and escaping inputs.

    Deliberately does not resolve symlinks: callers that hash a target need the
    components the caller actually named, so a link can be refused rather than
    followed into a different file.
    """
    cleaned = (raw_path or "").replace("\\", "/").strip()
    if not cleaned or cleaned == ".":
        raise SnapshotConflictError("A managed edit needs a file path inside the workspace.")
    if cleaned.startswith("/") or re.match(r"^[A-Za-z]:", cleaned):
        raise SnapshotConflictError(f"Path {raw_path!r} is absolute; managed edits require workspace-relative paths.")
    parts: list[str] = []
    for part in cleaned.split("/"):
        if part in ("", "."):
            continue
        if part == "..":
            raise SnapshotConflictError(f"Path {raw_path!r} escapes the workspace boundary.")
        parts.append(part)
    if not parts or parts[-1] in ("", "."):
        raise SnapshotConflictError(f"Path {raw_path!r} does not name a file inside the workspace.")
    return tuple(parts)


def _wsnap_open_root_fd(root: Path) -> int:
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    directory = getattr(os, "O_DIRECTORY", 0)
    canonical = root.expanduser().resolve(strict=True)
    flags = os.O_RDONLY | directory | nofollow | getattr(os, "O_CLOEXEC", 0)
    current_fd = os.open(os.sep, flags)
    try:
        for part in canonical.parts[1:]:
            next_fd = os.open(part, flags, dir_fd=current_fd)
            os.close(current_fd)
            current_fd = next_fd
        return current_fd
    except Exception:
        os.close(current_fd)
        raise


def _wsnap_read_confined_bytes(
    root: Path,
    rel_parts: tuple[str, ...],
    *,
    max_bytes: int = DEFAULT_MAX_SNAPSHOT_FILE_BYTES,
) -> tuple[bytes, os.stat_result]:
    """Read regular file bytes under ``root`` via directory-anchored ``O_NOFOLLOW`` descriptors."""
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    directory = getattr(os, "O_DIRECTORY", 0)
    dir_flags = os.O_RDONLY | directory | nofollow | getattr(os, "O_CLOEXEC", 0)
    current_fd = _wsnap_open_root_fd(root)
    file_fd: int | None = None
    try:
        for part in rel_parts[:-1]:
            next_fd = os.open(part, dir_flags, dir_fd=current_fd)
            os.close(current_fd)
            current_fd = next_fd
        file_flags = os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0)
        file_fd = os.open(rel_parts[-1], file_flags, dir_fd=current_fd)
        os.close(current_fd)
        current_fd = -1
        info = os.fstat(file_fd)
        if not stat.S_ISREG(info.st_mode):
            raise IsADirectoryError("/".join(rel_parts))
        if info.st_size > max_bytes:
            raise WorkspaceSnapshotError(
                f"Workspace file {'/'.join(rel_parts)!r} ({info.st_size} bytes) exceeds snapshot limit ({max_bytes} bytes)."
            )
        with os.fdopen(file_fd, "rb") as fh:
            file_fd = None
            data = fh.read(max_bytes + 1)
        if len(data) > max_bytes:
            raise WorkspaceSnapshotError(
                f"Workspace file {'/'.join(rel_parts)!r} grew beyond snapshot limit ({max_bytes} bytes)."
            )
        return data, info
    finally:
        if file_fd is not None:
            os.close(file_fd)
        if current_fd >= 0:
            os.close(current_fd)


def _wsnap_hash_confined_file_in_place(root: Path, rel_parts: tuple[str, ...]) -> tuple[str, os.stat_result] | None:
    """Compute streaming SHA-256 of a regular file in-place without persisting its bytes anywhere.

    Returns ``None`` if the path does not exist or is a symlink/non-regular entry.
    """
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    directory = getattr(os, "O_DIRECTORY", 0)
    dir_flags = os.O_RDONLY | directory | nofollow | getattr(os, "O_CLOEXEC", 0)
    current_fd = _wsnap_open_root_fd(root)
    file_fd: int | None = None
    try:
        for part in rel_parts[:-1]:
            try:
                next_fd = os.open(part, dir_flags, dir_fd=current_fd)
            except OSError:
                return None
            os.close(current_fd)
            current_fd = next_fd
        try:
            file_fd = os.open(rel_parts[-1], os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0), dir_fd=current_fd)
        except OSError:
            return None
        os.close(current_fd)
        current_fd = -1
        info = os.fstat(file_fd)
        if not stat.S_ISREG(info.st_mode):
            return None
        hasher = hashlib.sha256()
        with os.fdopen(file_fd, "rb") as fh:
            file_fd = None
            while True:
                chunk = fh.read(65536)
                if not chunk:
                    break
                hasher.update(chunk)
        return hasher.hexdigest(), info
    finally:
        if file_fd is not None:
            os.close(file_fd)
        if current_fd >= 0:
            os.close(current_fd)


def hash_confined_child(parent_fd: int, leaf: str) -> str | None:
    """SHA-256 of a regular file directly under an open directory fd, or ``None`` if absent.

    Opened relative to the caller's directory descriptor with ``O_NOFOLLOW``, so the
    hash describes the entry the caller is about to replace even if a symlink was
    swapped in, and the read cannot be redirected outside the workspace.
    """
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    file_fd: int | None = None
    try:
        file_fd = os.open(leaf, os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0), dir_fd=parent_fd)
    except (FileNotFoundError, NotADirectoryError):
        return None
    except OSError as exc:
        if exc.errno == errno.ELOOP:
            raise SnapshotConflictError(f"Refusing to read symlink at {leaf!r}.") from exc
        raise
    try:
        info = os.fstat(file_fd)
        if not stat.S_ISREG(info.st_mode):
            return None
        hasher = hashlib.sha256()
        with os.fdopen(file_fd, "rb") as fh:
            file_fd = None
            while True:
                chunk = fh.read(65536)
                if not chunk:
                    break
                hasher.update(chunk)
        return hasher.hexdigest()
    finally:
        if file_fd is not None:
            os.close(file_fd)


def read_confined_target(root: Path, raw_rel_path: str, *, max_bytes: int = DEFAULT_MAX_SNAPSHOT_FILE_BYTES) -> bytes | None:
    """Exact bytes of a confined regular file, or ``None`` when it does not exist.

    Used to keep the bytes an edit is about to replace (for inverse patching).
    Symlinks are refused rather than followed, and the read is anchored on a
    directory descriptor with ``O_NOFOLLOW``, so the bytes returned are the bytes
    at the path the caller named.
    """
    root_res = Path(root).expanduser().resolve(strict=True)
    rel_parts = _wsnap_lexical_parts(raw_rel_path)
    parent = root_res
    for part in rel_parts[:-1]:
        parent = parent / part
        if parent.is_symlink():
            raise SnapshotConflictError(f"Refusing to read through symlinked directory {str(parent)!r}.")
        if not parent.is_dir():
            return None
    leaf = root_res.joinpath(*rel_parts)
    try:
        entry_st = os.lstat(leaf)
    except FileNotFoundError:
        return None
    if stat.S_ISLNK(entry_st.st_mode):
        raise SnapshotConflictError(f"Refusing to follow symlink at {'/'.join(rel_parts)!r}.")
    if not stat.S_ISREG(entry_st.st_mode):
        raise SnapshotConflictError(f"{'/'.join(rel_parts)!r} is not a regular file.")
    data, _info = _wsnap_read_confined_bytes(root_res, rel_parts, max_bytes=max_bytes)
    return data


def hash_target_in_place(root: Path, raw_rel_path: str) -> tuple[str, int, int] | None:
    """``(sha256, size_bytes, mode)`` for a confined regular file, or ``None`` when it does not exist.

    The digest is streamed, so a large target can still be version-checked (the
    snapshot size cap applies to *copying* bytes, not to reading a digest).
    Symlinks are never followed: a managed edit must not be redirectable by a
    link that appeared after the path was validated.
    """
    root_res = Path(root).expanduser().resolve(strict=True)
    # Walk the *lexical* path first so a symlink component is refused instead of
    # being resolved into a different file that the caller never named.
    rel_parts = _wsnap_lexical_parts(raw_rel_path)
    rel_posix = "/".join(rel_parts)
    current = root_res
    for part in rel_parts[:-1]:
        current = current / part
        if current.is_symlink():
            raise SnapshotConflictError(f"Refusing to write through symlinked directory {str(current)!r}.")
        if not current.is_dir():
            return None
    leaf = root_res.joinpath(*rel_parts)
    try:
        entry_st = os.lstat(leaf)
    except FileNotFoundError:
        return None
    if stat.S_ISLNK(entry_st.st_mode):
        raise SnapshotConflictError(f"Refusing to follow symlink at {rel_posix!r}.")
    if not stat.S_ISREG(entry_st.st_mode):
        raise SnapshotConflictError(f"{rel_posix!r} is not a regular file and cannot be edited.")
    hashed = _wsnap_hash_confined_file_in_place(root_res, rel_parts)
    if hashed is None:
        return None
    digest, info = hashed
    return digest, int(info.st_size), stat.S_IMODE(info.st_mode)


def atomic_write_confined_bytes(
    root: Path,
    raw_rel_path: str,
    data: bytes,
    *,
    mode: int | None = None,
    min_free_bytes: int = DEFAULT_MIN_FREE_BYTES,
    expected_sha256: str | None = None,
) -> str:
    """Atomically write ``data`` to a confined workspace path via anchored ``O_NOFOLLOW`` temp file + fsync.

    With ``expected_sha256`` the write is a compare-and-swap: the current bytes are
    re-hashed through the same directory descriptor immediately before the rename,
    and the write is refused with :class:`SnapshotConflictError` when they differ
    (including when the file is missing). The temporary file is unlinked, so a
    refused write leaves the workspace exactly as it was.
    """
    rel_posix, rel_parts = _wsnap_normalize_rel_path(root, raw_rel_path)
    if expected_sha256 is not None and not _WSNAP_HEX64_RE.match(str(expected_sha256)):
        raise WorkspaceSnapshotError("expected_sha256 must be 64 lowercase hexadecimal characters.")
    _wsnap_preflight_disk_space(root, needed_bytes=len(data), min_free_bytes=min_free_bytes, operation="workspace_write")
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    directory = getattr(os, "O_DIRECTORY", 0)
    dir_flags = os.O_RDONLY | directory | nofollow | getattr(os, "O_CLOEXEC", 0)
    parent_fd = _wsnap_open_root_fd(root)
    try:
        for part in rel_parts[:-1]:
            try:
                next_fd = os.open(part, dir_flags, dir_fd=parent_fd)
            except FileNotFoundError:
                try:
                    os.mkdir(part, 0o777, dir_fd=parent_fd)
                except FileExistsError:
                    pass
                except OSError as exc:
                    if is_disk_full_os_error(exc):
                        raise SnapshotDiskFullError(
                            f"Disk full creating parent directory for {rel_posix!r}: {exc}",
                            operation="workspace_mkdir",
                            target_path=rel_posix,
                            errno_code=int(exc.errno or errno.ENOSPC),
                        ) from exc
                    raise
                next_fd = os.open(part, dir_flags, dir_fd=parent_fd)
            os.close(parent_fd)
            parent_fd = next_fd

        leaf = rel_parts[-1]
        try:
            existing_st = os.stat(leaf, dir_fd=parent_fd, follow_symlinks=False)
            if stat.S_ISLNK(existing_st.st_mode):
                raise SnapshotConflictError(f"Refusing to overwrite symlink at {rel_posix!r}.")
            if stat.S_ISDIR(existing_st.st_mode):
                raise SnapshotConflictError(f"Refusing to overwrite directory at {rel_posix!r} with a file.")
        except FileNotFoundError:
            pass

        tmp_name = f".m5-wsnap-{uuid.uuid4().hex}.tmp"
        tmp_fd: int | None = None
        try:
            open_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | nofollow | getattr(os, "O_CLOEXEC", 0)
            tmp_fd = os.open(tmp_name, open_flags, mode if mode is not None else 0o666, dir_fd=parent_fd)
            if mode is not None:
                os.fchmod(tmp_fd, mode)
            view = memoryview(data)
            while view:
                written = os.write(tmp_fd, view)
                if written <= 0:
                    raise OSError(errno.EIO, f"Short write on {rel_posix!r}")
                view = view[written:]
            os.fsync(tmp_fd)
            os.close(tmp_fd)
            tmp_fd = None
            if expected_sha256 is not None:
                current = hash_confined_child(parent_fd, leaf)
                if current != expected_sha256:
                    raise SnapshotConflictError(
                        "Refusing to overwrite "
                        f"{rel_posix!r}: expected content {expected_sha256} but found "
                        f"{current if current is not None else 'no file'}. Nothing was written."
                    )
            os.rename(tmp_name, leaf, src_dir_fd=parent_fd, dst_dir_fd=parent_fd)
            try:
                os.fsync(parent_fd)
            except OSError:
                pass
        except OSError as exc:
            if is_disk_full_os_error(exc):
                raise SnapshotDiskFullError(
                    f"Disk full while writing workspace file {rel_posix!r}: {exc}",
                    operation="workspace_write",
                    target_path=rel_posix,
                    errno_code=int(exc.errno or errno.ENOSPC),
                ) from exc
            raise
        finally:
            if tmp_fd is not None:
                os.close(tmp_fd)
            try:
                os.unlink(tmp_name, dir_fd=parent_fd)
            except FileNotFoundError:
                pass
        return hashlib.sha256(data).hexdigest()
    finally:
        os.close(parent_fd)


def remove_confined_target(root: Path, raw_rel_path: str) -> bool:
    """Remove one confined regular file (never a symlink or directory); True if removed.

    Used by rollback to undo a file the runtime created. The leaf is unlinked
    through an anchored parent descriptor after an ``O_NOFOLLOW`` ``lstat``
    confirms it is a regular file, so a link swapped in at the last moment is
    refused instead of followed.
    """
    root_res = Path(root).expanduser().resolve(strict=True)
    rel_parts = _wsnap_lexical_parts(raw_rel_path)
    parent = root_res
    for part in rel_parts[:-1]:
        parent = parent / part
        if parent.is_symlink() or not parent.is_dir():
            return False
    leaf = root_res.joinpath(*rel_parts)
    try:
        entry_st = os.lstat(leaf)
    except FileNotFoundError:
        return False
    if not stat.S_ISREG(entry_st.st_mode):
        raise SnapshotConflictError(f"Refusing to remove non-regular file {'/'.join(rel_parts)!r}.")
    return _wsnap_unlink_confined_file(root_res, raw_rel_path)


def _wsnap_unlink_confined_file(root: Path, raw_rel_path: str) -> bool:
    """Unlink a single regular file under ``root`` via anchored ``O_NOFOLLOW`` parent fd."""
    rel_posix, rel_parts = _wsnap_normalize_rel_path(root, raw_rel_path)
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    directory = getattr(os, "O_DIRECTORY", 0)
    dir_flags = os.O_RDONLY | directory | nofollow | getattr(os, "O_CLOEXEC", 0)
    parent_fd = _wsnap_open_root_fd(root)
    try:
        for part in rel_parts[:-1]:
            try:
                next_fd = os.open(part, dir_flags, dir_fd=parent_fd)
            except FileNotFoundError:
                return False
            os.close(parent_fd)
            parent_fd = next_fd
        leaf = rel_parts[-1]
        try:
            st = os.stat(leaf, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            return False
        if not stat.S_ISREG(st.st_mode):
            raise SnapshotConflictError(f"Refusing to unlink non-regular entry at {rel_posix!r}.")
        os.unlink(leaf, dir_fd=parent_fd)
        return True
    finally:
        os.close(parent_fd)


def _wsnap_query_free_bytes(target_dir: Path) -> int:
    probe = target_dir
    while not probe.exists() and probe.parent != probe:
        probe = probe.parent
    usage = shutil.disk_usage(probe)
    return int(usage.free)


def _wsnap_preflight_disk_space(
    target_dir: Path,
    *,
    needed_bytes: int,
    min_free_bytes: int,
    operation: str,
) -> None:
    if min_free_bytes <= 0 and needed_bytes <= 0:
        return
    try:
        free_bytes = _wsnap_query_free_bytes(target_dir)
    except OSError as exc:
        if is_disk_full_os_error(exc):
            raise SnapshotDiskFullError(
                f"Disk full probing free space for {operation}: {exc}",
                operation=operation,
                target_path=str(target_dir),
                errno_code=int(exc.errno or errno.ENOSPC),
            ) from exc
        raise
    required = max(0, needed_bytes) + max(0, min_free_bytes)
    if free_bytes < required:
        raise SnapshotDiskFullError(
            f"Insufficient free disk space for {operation}: {free_bytes} bytes free < {required} bytes required.",
            operation=operation,
            target_path=str(target_dir),
            errno_code=errno.ENOSPC,
        )


def _wsnap_atomic_write_private_bytes(
    target_path: Path,
    payload: bytes,
    *,
    min_free_bytes: int,
    operation: str,
) -> None:
    """Atomically write ``0600`` bytes to ``target_path`` with temp-file + fsync + os.replace."""
    parent = target_path.parent
    try:
        parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    except OSError as exc:
        if is_disk_full_os_error(exc):
            raise SnapshotDiskFullError(
                f"Disk full creating snapshot directory {parent}: {exc}",
                operation=operation,
                target_path=str(target_path),
                errno_code=int(exc.errno or errno.ENOSPC),
            ) from exc
        raise
    _wsnap_preflight_disk_space(parent, needed_bytes=len(payload), min_free_bytes=min_free_bytes, operation=operation)
    fd: int | None = None
    tmp_path: Path | None = None
    try:
        fd, raw_tmp = tempfile.mkstemp(prefix=f".{target_path.name}.", suffix=".tmp", dir=str(parent))
        tmp_path = Path(raw_tmp)
        os.fchmod(fd, 0o600)
        view = memoryview(payload)
        while view:
            written = os.write(fd, view)
            if written <= 0:
                raise OSError(errno.EIO, f"Short write on {target_path}")
            view = view[written:]
        os.fsync(fd)
        os.close(fd)
        fd = None
        os.replace(tmp_path, target_path)
        tmp_path = None
        try:
            dir_fd = os.open(str(parent), os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        except OSError:
            pass
    except SnapshotDiskFullError:
        raise
    except OSError as exc:
        if is_disk_full_os_error(exc):
            raise SnapshotDiskFullError(
                f"Disk full during {operation} ({target_path}): {exc}",
                operation=operation,
                target_path=str(target_path),
                errno_code=int(exc.errno or errno.ENOSPC),
            ) from exc
        raise WorkspaceSnapshotError(f"Failed writing {target_path}: {exc}") from exc
    finally:
        if fd is not None:
            os.close(fd)
        if tmp_path is not None:
            try:
                tmp_path.unlink(missing_ok=True)
            except OSError:
                pass


class ContentAddressedBlobStore:
    """Owner-only (`0600`) SHA-256 content-addressed blob store with read-back verification."""

    def __init__(self, cas_root: Path, *, min_free_bytes: int = DEFAULT_MIN_FREE_BYTES) -> None:
        self.cas_root = cas_root
        self.min_free_bytes = min_free_bytes

    def _blob_path(self, sha256_hex: str) -> Path:
        digest = (sha256_hex or "").strip().lower()
        if not _WSNAP_HEX64_RE.match(digest):
            raise SnapshotIntegrityError(f"Invalid CAS SHA-256 digest: {sha256_hex!r}")
        return self.cas_root / digest[:2] / f"{digest}.blob"

    def has_blob(self, sha256_hex: str) -> bool:
        try:
            path = self._blob_path(sha256_hex)
        except SnapshotIntegrityError:
            return False
        if not path.is_file() or path.is_symlink():
            return False
        try:
            actual = hashlib.sha256(path.read_bytes()).hexdigest()
        except OSError:
            return False
        return actual == sha256_hex.strip().lower()

    def put_bytes(self, data: bytes) -> tuple[str, bool]:
        """Store ``data`` under its SHA-256 digest; returns ``(sha256_hex, newly_written)``."""
        digest = hashlib.sha256(data).hexdigest()
        blob_path = self._blob_path(digest)
        if self.has_blob(digest):
            return digest, False
        _wsnap_atomic_write_private_bytes(
            blob_path,
            data,
            min_free_bytes=self.min_free_bytes,
            operation="cas_put_blob",
        )
        return digest, True

    def get_bytes(self, sha256_hex: str) -> bytes:
        """Read and verify a blob from CAS; raises ``SnapshotIntegrityError`` on corruption or absence."""
        digest = (sha256_hex or "").strip().lower()
        blob_path = self._blob_path(digest)
        if not blob_path.is_file() or blob_path.is_symlink():
            raise SnapshotIntegrityError(f"Missing CAS blob {digest}.")
        try:
            payload = blob_path.read_bytes()
        except OSError as exc:
            raise SnapshotIntegrityError(f"Unreadable CAS blob {digest}: {exc}") from exc
        actual = hashlib.sha256(payload).hexdigest()
        if actual != digest:
            raise SnapshotIntegrityError(f"CAS blob {digest} failed SHA-256 verification (got {actual}).")
        return payload


@dataclass(frozen=True, slots=True)
class GitBaselineInfo:
    is_git: bool
    git_toplevel: str = ""
    workspace_rel_prefix: str = "."
    has_head: bool = False
    head_commit: str = ""
    head_tree: str = ""
    branch: str = ""
    clean_at_capture: bool = True

    def to_dict(self) -> dict[str, Any]:
        return {
            "is_git": self.is_git,
            "git_toplevel": self.git_toplevel,
            "workspace_rel_prefix": self.workspace_rel_prefix,
            "has_head": self.has_head,
            "head_commit": self.head_commit,
            "head_tree": self.head_tree,
            "branch": self.branch,
            "clean_at_capture": self.clean_at_capture,
        }

    @classmethod
    def from_dict(cls, raw: Mapping[str, Any]) -> GitBaselineInfo:
        return cls(
            is_git=bool(raw.get("is_git", False)),
            git_toplevel=str(raw.get("git_toplevel") or ""),
            workspace_rel_prefix=str(raw.get("workspace_rel_prefix") or "."),
            has_head=bool(raw.get("has_head", False)),
            head_commit=str(raw.get("head_commit") or ""),
            head_tree=str(raw.get("head_tree") or ""),
            branch=str(raw.get("branch") or ""),
            clean_at_capture=bool(raw.get("clean_at_capture", True)),
        )


