@dataclass(frozen=True, slots=True)
class PreservedFileEntry:
    """Metadata-only record for ignored or sensitive files (bytes are NEVER stored in CAS)."""

    rel_path: str
    reason: str  # "ignored_sensitive", "sensitive_unignored", "git_ignored"
    size_bytes: int
    mode: int
    in_place_sha256: str
